package com.xemantic.typescript.compiler

import kotlin.math.pow

/**
 * MVP type checker providing the three resolver methods needed by the Transformer:
 * - [isReferencedAliasDeclaration] — import elision
 * - [getEnumMemberValue] — const enum inlining
 * - [isValueAliasDeclaration] — export assignment elision
 *
 * The checker merges symbol tables from all source files, computes enum member
 * values (including cross-file references), and tracks which imports are used
 * in value positions vs. type-only positions.
 */
class Checker(
    private val options: CompilerOptions,
    private val binderResults: List<BinderResult>,
    /** True when the source had @Filename directives (multi-file test input). */
    private val isMultiFileSource: Boolean = false,
    /** When true, only run targeted checks (TS1210 etc.) — used for emitDeclarationOnly. */
    private val declarationOnly: Boolean = false,
    /**
     * When non-null, only report diagnostics for files in this set (round-robin
     * file assignment for parallel checking via [CheckerPool]). The checker still
     * merges globals and resolves types for ALL files, but diagnostic output is
     * filtered to the assigned subset.
     */
    private val assignedFileNames: Set<String>? = null,
) {
    /** Merged symbol tables from all files (global scope). */
    private val globals: SymbolTable = symbolTable()

    /** Per-file binder results for lookup. */
    private val fileResults: Map<String, BinderResult> =
        binderResults.associateBy { it.sourceFile.fileName }

    // -----------------------------------------------------------------------
    // Per-checker mutable state — grouped for parallel-checking readiness.
    // When N Checker instances run concurrently (Phase 4 item 9c), each
    // owns its own CheckerState. Shared immutable data (AST, binder results,
    // compiler options) stays on Checker.
    // -----------------------------------------------------------------------

    /**
     * All mutable state that is per-checker-instance: diagnostics, caches,
     * relation tables, and recursion-depth counters. In a future parallel
     * checking model ([CheckerPool]), each checker gets its own instance.
     */
    private class CheckerState {
        /** Checker-produced diagnostics. */
        val diagnostics: MutableList<Diagnostic> = mutableListOf()
        /** Import symbols that are referenced in value positions. */
        val referencedAliases: MutableSet<Int> = mutableSetOf()
        /** Computed enum member values: enum symbol ID → (member name → value). */
        val enumValues: MutableMap<Int, MutableMap<String, ConstantValue>> = mutableMapOf()
        /**
         * Per-file-per-name count of TS2552 spelling suggestions emitted.
         * TypeScript limits spelling suggestions to 10 per unique name per file.
         * Key = "$fileName:$missingName".
         */
        val spellingSuggestionCounts: MutableMap<String, Int> = mutableMapOf()
        // Type resolution caches (checker-local — NOT on AST nodes)
        /** Cache of TypeNode → resolved Type. */
        val nodeTypes = HashMap<TypeNode, Type>()
        /** Cache of symbol ID → resolved type of that symbol. */
        val symbolTypes = HashMap<Int, Type>()
        /** Cache of symbol ID → declared type (for classes/interfaces). */
        val declaredTypes = HashMap<Int, Type>()
        // Type relation instances
        val subtypeRelation = Relation()
        val assignableRelation = Relation()
        val comparableRelation = Relation()
        val identityRelation = Relation()
        // Recursion depth counters
        var checkDepth = 0
        var relationDepth = 0
        /** Tracks (source.id, target.id) pairs currently being compared to detect recursive types.
         *  When a pair is already on the stack, we assume compatibility (TypeScript's approach). */
        val relationComparisonStack = HashSet<Long>()
        /** Tracks whether the current comparison used any cycle-break assumptions. */
        var relationUsedCycleBreak = false
        /** Track pairs already being elaborated to prevent infinite recursion in recursive types. */
        val elaborationStack = HashSet<Long>()
        var argCountDepth = 0
        var callTypeCheckDepth = 0
        var arithmeticCheckDepth = 0
        // LinkStore: checker-local side map for import alias targets.
        // In TypeScript/tsgo, symbol.target is set by the checker — storing it
        // here instead keeps binder output immutable for parallel checking.
        val symbolTargets = HashMap<Int, Symbol>()
    }

    private val state = CheckerState()

    // -----------------------------------------------------------------------
    // Delegating properties — allow all existing code to work unchanged
    // while mutable state is clearly grouped in CheckerState.
    // -----------------------------------------------------------------------
    @get:JvmName("diagnostics_") private val diagnostics get() = state.diagnostics
    private val referencedAliases get() = state.referencedAliases
    private val enumValues get() = state.enumValues
    private val spellingSuggestionCounts get() = state.spellingSuggestionCounts
    private val nodeTypes get() = state.nodeTypes
    private val symbolTypes get() = state.symbolTypes
    private val declaredTypes get() = state.declaredTypes
    private val subtypeRelation get() = state.subtypeRelation
    private val assignableRelation get() = state.assignableRelation
    private val comparableRelation get() = state.comparableRelation
    private val identityRelation get() = state.identityRelation
    private var checkDepth: Int
        get() = state.checkDepth
        set(value) { state.checkDepth = value }
    private var relationDepth: Int
        get() = state.relationDepth
        set(value) { state.relationDepth = value }
    private var relationUsedCycleBreak: Boolean
        get() = state.relationUsedCycleBreak
        set(value) { state.relationUsedCycleBreak = value }
    private var argCountDepth: Int
        get() = state.argCountDepth
        set(value) { state.argCountDepth = value }
    private var callTypeCheckDepth: Int
        get() = state.callTypeCheckDepth
        set(value) { state.callTypeCheckDepth = value }
    private var arithmeticCheckDepth: Int
        get() = state.arithmeticCheckDepth
        set(value) { state.arithmeticCheckDepth = value }

    /** Tracks whether we're inside a static class method/accessor for TS2339 `this` checking. */
    private var inStaticClassMethod = false

    // -----------------------------------------------------------------------
    // LinkStore helpers — checker-local side map for symbol targets.
    // Keeps binder output immutable; each parallel checker resolves independently.
    // -----------------------------------------------------------------------

    /** Get the resolved alias target for a symbol (checker-local, then binder fallback). */
    private fun getSymbolTarget(symbol: Symbol): Symbol? =
        state.symbolTargets[symbol.id] ?: symbol.target

    /** Set the resolved alias target for a symbol in the checker-local side map. */
    private fun setSymbolTarget(symbol: Symbol, target: Symbol) {
        state.symbolTargets[symbol.id] = target
    }

    /** Local variable types populated during TS2322 checking — enables getTypeOfIdentifier
     *  to resolve function-scoped variable types from their type annotations. */
    private var currentLocalTypes: MutableMap<String, Type> = mutableMapOf()

    /** Current function's parameters — set during implicit-return checking to enable exhaustive
     *  switch detection for literal-type parameters (e.g., `bar: "a" | "b"`). */
    private var currentFunctionParams: List<Parameter> = emptyList()

    /** File-level symbol table for the file currently being checked. Set by checker passes
     *  so that getTypeOfIdentifier can resolve file-level declarations (functions, classes,
     *  variables) without going through globals (which may have merge conflicts). */
    private var currentFileLocals: SymbolTable? = null

    /** The file name currently being checked — used to look up file-level type maps. */
    private var currentCheckFileName: String? = null

    /** Pre-built per-file type maps: fileName → (name → Type). Built once during init,
     *  contains types for all file-level annotated declarations. Used by getTypeOfIdentifier
     *  to resolve file-level identifiers across all checker passes. */
    private val fileLocalTypeMaps = HashMap<String, Map<String, Type>>()

    /** Contextual type for function expressions — set when evaluating an initializer whose
     *  target has call signatures (e.g., `var f: (x: number) => void = (x) => { ... }`).
     *  Used by getTypeOfArrowFunction/getTypeOfFunctionExpression to infer parameter types. */
    private var contextualType: Type? = null

    /** 16.0: Class/interface type parameter scope for member type resolution.
     *  Set by resolveReferenceMembers / getTypeOfVariableOrProperty when resolving member
     *  types that reference enclosing class type parameters (e.g. `get foo(): T` inside
     *  `class C<T>`). getTypeFromTypeReference consults this before falling back to globals. */
    private var currentTypeParamScope: Map<String, Type.TypeParam>? = null

    /** Global Array interface — used as target for `Type.Reference` in array types.
     *  Initialized from built-in lib during init; falls back to empty interface if not found. */
    private var globalArrayType: Type.Interface = Type.Interface().also {
        it.symbol = Symbol(SymbolFlags.Interface, "Array")
    }

    /** Maximum recursion depth for AST walking to prevent StackOverflow. */
    private val maxCheckDepth = 200
    private val maxRelationDepth = 100

    /** Tracks the first missing required property found during structural comparison.
     *  Set by propertiesRelatedTo, consumed by TS2322 emission to produce TS2741 instead.
     *  Reset before each top-level comparison. */
    private var lastMissingPropertyName: String? = null
    private var lastMissingPropertySymbol: Symbol? = null

    /** Tracks when structural comparison fails due to target having an index signature
     *  that the source (a named class/interface) lacks. Consumed by TS2322 elaboration
     *  to produce "Index signature for type 'string|number' is missing in type 'X'." */
    private var lastMissingIndexSigKind: String? = null

    /** Check if a file is a declaration file (.d.ts/.d.mts/.d.cts). */
    private fun isDtsFile(fileName: String): Boolean =
        fileName.endsWith(".d.ts") || fileName.endsWith(".d.mts") || fileName.endsWith(".d.cts")

    // Whether strict null checks are enabled (null/undefined not assignable to other types)
    // MUST be declared before init {} to avoid Kotlin property initialization order issue
    private val strictNullChecks: Boolean = !options.strictExplicitlyFalse && !options.strictNullChecksExplicitlyFalse

    // Built-in generic type names — skip TS2315/TS2344 checks for these
    // MUST be declared before init {} to avoid Kotlin property initialization order issue
    private val BUILTIN_GENERICS = setOf("Array", "ReadonlyArray", "Promise", "Map", "Set",
        "WeakMap", "WeakSet", "Record", "Partial", "Required", "Readonly",
        "Pick", "Omit", "Exclude", "Extract", "NonNullable", "ReturnType",
        "InstanceType", "ConstructorParameters", "Parameters", "ThisParameterType",
        "OmitThisParameter", "ThisType", "Awaited")

    // -----------------------------------------------------------------------
    // Built-in type declarations (minimal lib.d.ts stubs)
    // Parsed and bound once at Checker init, merged into globals before user files.
    // This provides apparent types for primitives (String, Number, Boolean)
    // so that property access on primitives resolves correctly.
    // -----------------------------------------------------------------------

    /** Cached apparent types for primitive wrappers — resolved lazily from globals. */
    private var stringWrapperType: Type? = null
    private var numberWrapperType: Type? = null
    private var booleanWrapperType: Type? = null

    /**
     * Parsed source file for the built-in type declarations — retained so that
     * TS2728 "declared here" related info can look up positions inside lib stubs.
     * TypeScript baselines render these as `lib.es5.d.ts:--:--` regardless of the
     * actual lib file (different lib.*.d.ts are concatenated by the TS build).
     */
    private var builtinLibSourceFile: SourceFile? = null

    /**
     * Parse and bind the built-in type declarations, returning the symbol table.
     * These are merged into globals BEFORE user files so that user declarations
     * can augment/override them (matching TypeScript's behavior).
     */
    private fun parseBuiltinLib(): SymbolTable {
        val source = BUILTIN_LIB_SOURCE
        val ast = Parser(source, "lib.es5.d.ts").parse()
        builtinLibSourceFile = ast
        return Binder(options).bind(ast).locals
    }

    init {
        // 0. Merge built-in type declarations into globals (before user files)
        mergeSymbolTable(globals, parseBuiltinLib())
        // 0b. Wire globalArrayType from built-in lib (if Array was parsed)
        globals["Array"]?.let { arraySym ->
            if (arraySym.flags.hasAny(SymbolFlags.Interface)) {
                val arrayType = getDeclaredTypeOfClassOrInterface(arraySym)
                globalArrayType = arrayType
            }
        }
        // 1. Merge file-level symbols into globals
        for (result in binderResults) {
            mergeSymbolTable(globals, result.locals)
        }
        // 1b. Merge module augmentation exports into target module symbols
        mergeModuleAugmentations()
        // 2. Compute all enum member values
        computeAllEnumValues()
        // 3. Track import references across all files
        trackAllImportReferences()
        // 3b. Build per-file type maps for file-level declarations
        buildFileLocalTypeMaps()

        // For declarationOnly mode, only run class strict-mode checks (TS1210)
        if (declarationOnly) {
            checkClassStrictModeIdentifiers()
        }

        if (!declarationOnly) {
        // 4. Check for unused declarations (TS6133/TS6196)
        if (options.noUnusedLocals || options.noUnusedParameters) {
            checkUnusedDeclarations()
        }
        // 4b. Check for unused parameter properties (TS6138)
        // Property declared via constructor parameter but never accessed as this.prop
        if (options.noUnusedLocals || options.noUnusedParameters) {
            checkUnusedParameterProperties()
        }
        // 5. Check for variables used before assignment (TS2454)
        // Requires strictNullChecks (either via strict: true or strictNullChecks: true).
        // Suppressed when strict is explicitly false OR strictNullChecks is explicitly false.
        val shouldCheckDefiniteAssignment = !options.strictExplicitlyFalse && !options.strictNullChecksExplicitlyFalse
        if (shouldCheckDefiniteAssignment) {
            checkDefiniteAssignment()
        }
        // 6. Check for class properties without initializer (TS2564)
        // Suppressed when strict=false, or when strictPropertyInitialization=false explicitly set
        if (!options.strictExplicitlyFalse && !options.strictPropertyInitializationExplicitlyFalse) {
            checkPropertyInitialization()
        }
        // 7. Check for implicit any parameters (TS7006)
        if (options.noImplicitAny || options.strict) {
            checkImplicitAnyParameters()
        }
        // 7b. TS7019: Rest parameter implicitly has 'any[]' type — fires by default unless strict=false
        // This fires even without noImplicitAny (same behavior as TS7006 for parameter properties).
        if (!options.strictExplicitlyFalse) {
            checkImplicitAnyRestParameters()
        }
        // 7b'. TS2370: A rest parameter must be of an array type — fires unconditionally
        // (syntactic type-shape error, not an implicit-any diagnostic).
        checkNonArrayRestParameters()
        // 7b''. TS7033: Abstract get accessor with no return type annotation → implicit any.
        // Gated on noImplicitAny/strict.
        if (options.noImplicitAny || options.strict) {
            checkAbstractAccessorReturnTypes()
        }
        // 7b'''. TS18045: 'accessor' modifier requires target ES2015+.
        checkAccessorModifierTarget()
        // 7b'''. TS2669: `declare global { ... }` nested inside a regular namespace.
        checkInvalidGlobalAugmentations()
        // 7c. TS7005: Variable implicitly has 'any' type — fires unconditionally for:
        //   - ambient declarations (declare var/let/const without type annotation)
        //   - const/let without type AND without initializer (uninitialized block-scoped vars)
        // Both fire regardless of noImplicitAny flag.
        if (!options.strictExplicitlyFalse) {
            checkImplicitAnyVariables()
        }
        // 8. Check for unresolved names (TS2304)
        checkUnresolvedNames()
        // 9. Check JSX elements for missing type definitions (TS7026)
        // TS7026 is an implicit-any diagnostic, so only fire when noImplicitAny/strict is on.
        // With @strict: false or @noImplicitAny: false, implicit any is allowed → no TS7026.
        if (options.jsx != null && (options.noImplicitAny || options.strict) && !options.strictExplicitlyFalse) {
            checkJsxImplicitAny()
        }
        // 10. Check for duplicate identifiers (TS2300)
        checkDuplicateIdentifiers()
        // 10b. Check catch clause redeclaration (TS2492)
        checkCatchClauseRedeclarations()
        // 11. Check export assignment conflicts (TS2309)
        checkExportAssignmentConflicts()
        // 12. Check strict mode identifier restrictions (TS1100)
        // Runs unconditionally — per-file strict mode detection inside
        checkStrictModeIdentifiers()
        // 12b. Check class body strict mode (TS1210) — class bodies are always strict
        checkClassStrictModeIdentifiers()
        // 12c. Check access modifiers on object literal members (TS1042)
        checkObjectLiteralModifiers()
        // 12d. Check 'arguments' in class field initializers / static blocks (TS2815)
        checkArgumentsInClassFieldInitializers()
        // 13. Check export= in ES module files (TS1203)
        checkExportAssignmentInEsModule()
        // 14. Check unresolved module specifiers (TS2307)
        checkUnresolvedModules()
        // 14a'. Check relative imports/exports inside `declare module "X"` augmentations (TS2439)
        checkRelativeImportsInAmbientModules()
        // 14a. Check invalid module augmentations (TS2664)
        checkAmbientModuleAugmentations()
        // 14aa. Check .d.ts top-level declarations for 'declare'/'export' modifier (TS1046)
        checkDtsTopLevelDeclarations()
        // 14b. Check default imports from modules without default export (TS1192)
        checkDefaultImports()
        // 14c. Check named imports/re-exports for non-existent module members (TS2305)
        checkNamedImportExistence()
        // 15. Check break/continue crossing function boundaries (TS1107)
        checkJumpTargets()
        // 16. Check call expression argument counts (TS2554)
        checkArgumentCounts()
        // 17. Check missing function implementations (TS2391)
        checkMissingImplementations()
        // 18. Check unreachable code (TS7027)
        if (options.allowUnreachableCode == false) {
            checkUnreachableCode()
        }
        // 18b. Check unused labels (TS7028)
        if (options.allowUnusedLabels == false) {
            checkUnusedLabels()
        }
        // 18c. Check fallthrough cases in switch (TS7029)
        if (options.noFallthroughCasesInSwitch) {
            checkFallthroughCases()
        }
        // 18d. Check not all code paths return a value (TS7030/TS2355/TS2366).
        // Always run (not gated by noImplicitReturns) because TS2355 fires for functions with
        // explicit non-void return type and no return statements, regardless of noImplicitReturns.
        // When noImplicitReturns is true, TS2366 is emitted instead of TS7030/TS2355 for non-async
        // functions with definitely-non-nullable return types.
        checkImplicitReturns()
        // 19. Check type used as value (TS2693)
        checkTypeUsedAsValue()
        // 20. Check always-truthy expressions (TS2872)
        checkAlwaysTruthy()
        // 20b. Check comma operator left side unused (TS2695)
        checkCommaOperatorUnused()
        // 21. Check null/undefined used in invalid positions (TS18050)
        checkNullUndefinedUsage()
        // 22. Check for implicit this (TS2683)
        if (options.noImplicitThis || options.strict) {
            checkImplicitThis()
        }
        // 23. Check duplicate object literal properties (TS1117)
        checkDuplicateObjectLiteralProperties()
        // 24. Check super called before this in derived constructors (TS17009)
        checkSuperBeforeThis()
        // 25. Check assignment to const variables (TS2540)
        checkConstAssignment()
        // 25b. Check delete operator (TS1102/TS2703)
        checkDeleteOperator()
        // 26. Check parameter properties outside constructor (TS2369)
        checkParameterProperties()
        // 27. Check super in non-derived class (TS2335)
        checkSuperInNonDerived()
        // 28. Check const without initializer (TS1155)
        checkConstWithoutInitializer()
        // 29. Check reserved words in wrong context (TS1359)
        checkReservedWordIdentifiers()
        // 30. Check outFile with non-AMD/System module (TS6131)
        checkOutFileModuleConflict()
        // 31. Check for merge conflict markers (TS1185)
        checkConflictMarkers()
        // 32. Check module=none with imports/exports (TS1148)
        checkModuleNoneConflict()
        // 33. Check export= in system modules (TS1218)
        checkExportAssignmentInSystem()
        // 34. Check reserved name collisions in modules (TS2441)
        checkReservedModuleNames()
        // 34b. Check __esModule reserved export (TS1216)
        checkEsModuleReservedExport()
        // 35. Check block-scoped function declarations in ES5 strict mode (TS1250)
        if (options.target < ScriptTarget.ES2015) {
            checkBlockScopedFunctionDeclarations()
        }
        // 35b. Check private identifiers targeting ES5 (TS18028)
        if (options.target <= ScriptTarget.ES5) {
            checkPrivateIdentifiersTarget()
        }
        // 36. Check import declarations with modifiers (TS1191)
        checkImportModifiers()
        // 37. Check block-scoped variable use before declaration (TS2448)
        checkUseBeforeDeclaration()
        // 38. Check setter parameter count (TS1049)
        checkSetterParameterCount()
        // 39. Check duplicate modifiers (TS1030)
        checkDuplicateModifiers()
        // 40. Check rest parameter is last (TS1014)
        checkRestParameterLast()
        // 40b. Check rest element with property name in binding patterns (TS2566)
        checkRestElementPropertyNames()
        // 41. Check implementation in ambient context (TS1183)
        checkAmbientImplementation()
        // 41b. Check ambient module declarations with relative names (TS2436)
        checkAmbientRelativeModuleNames()
        // 42. Check arguments collision with rest params (TS2396)
        // TS2396 only fires at target < ES2015 (no arguments object concern with arrow functions)
        // But TS1215 fires for module files regardless of target
        // Run checkArgumentsCollision if either: target < ES2015 (for TS2396) OR there are module files (for TS1215)
        val hasModuleFiles = binderResults.any { isModuleFile(it.sourceFile.statements) && !isDtsFile(it.sourceFile.fileName) }
        if (options.target < ScriptTarget.ES2015 || hasModuleFiles) {
            checkArgumentsCollision()
        }
        // 43. Check initializers in ambient contexts (TS1039)
        checkAmbientInitializers()
        // 44. Check multiple defaults in switch (TS1113)
        checkMultipleDefaults()
        // 45. Check interface property initializers (TS1246)
        checkInterfacePropertyInitializers()
        // 46. Check await in non-async context (TS1308)
        checkAwaitContext()
        // 47. Check declaration name conflicts with built-in global (TS2397)
        checkBuiltinGlobalConflict()
        // 48. Check parameter question mark with initializer (TS1015)
        checkOptionalParamWithInitializer()
        // 49. Check set accessor parameter initializer (TS1052)
        checkSetAccessorInitializer()
        // 49b. Check set accessor rest parameter (TS1053)
        checkSetAccessorRestParameter()
        // 49c. Check for-in left-hand side type annotation (TS2404)
        checkForInLhsTypeAnnotation()
        // 50. Check statements in ambient contexts (TS1036)
        checkAmbientStatements()
        // 51. Check parameter initializer in non-implementation context (TS2371)
        checkParameterInitializerInNonImpl()
        // 52. Check strict mode reserved words as identifiers (TS1212)
        checkStrictModeReservedWords()
        // 53. Check class/interface named 'undefined' (TS2414/TS2427)
        checkUndefinedClassInterfaceName()
        // 54. Check multiple default exports (TS2528)
        checkMultipleDefaultExports()
        // 55. Check derived class constructor must contain super call (TS2377)
        checkDerivedConstructorSuper()
        // 56. Check circular import alias definitions (TS2303)
        checkCircularImportAlias()
        // 57. Check return statement outside function body (TS1108)
        checkReturnOutsideFunction()
        // 57b. Check with statements (TS1101 in strict mode, TS2410 always)
        checkWithStatements()
        // 58. Check duplicate labels (TS1114)
        checkDuplicateLabels()
        // 59. Check empty type argument list (TS1099)
        checkEmptyTypeArguments()
        // 60. Check TS2354: importHelpers without tslib
        checkImportHelpersWithoutTslib()
        // 60b. Check TS2343: syntax requires helper not in tslib
        checkMissingTslibHelpers()
        // 61. Check bodyless function declarations without return type (TS7010)
        // Fires by default (like TS2454/TS2564), suppressed only when @strict: false explicitly set.
        if (!options.strictExplicitlyFalse || options.noImplicitAny) {
            checkBodylessFunctionReturnTypesMissing()
        }
        // 62. Check block-scoped declarations outside blocks (TS1156)
        checkBlockScopedDeclarationsInSingleBody()
        // 62b. Check var shadowing outer block-scoped name (TS2481)
        checkOuterScopeVarShadowing()
        // 63. Check class member initializers referencing constructor params/vars (TS2301)
        checkConstructorParamInInitializers()
        // 64. Check type assignability (TS2322) — basic primitive type mismatches
        checkTypeAssignability()
        // 64b. Check property access on known types (TS2339)
        checkPropertyAccess()
        // 64c. Check call expression argument types (TS2345)
        checkCallExpressionTypes()
        // 64d. Check arithmetic operator types (TS2362/TS2363)
        checkArithmeticOperandTypes()
        // 64e. Check class implements interface (TS2420)
        checkClassImplementsInterface()
        // 64e2. Check property type incompatible with base type (TS2416)
        checkPropertyOverride()
        // 64f. Check type argument constraints (TS2344)
        checkTypeArgumentConstraints()
        // 64f2. Check interface extends interface (TS2430)
        checkInterfaceExtendsInterface()
        // 64f3. Check circular base class references (TS2506)
        checkCircularBaseClasses()
        // 64f3a. Check circular interface extends cycles (TS2310)
        checkCircularInterfaceBases()
        // 64f3b. Check non-constructor extends (TS2507)
        checkNonConstructorExtends()
        // 64f5. Check interface multi-base property conflicts (TS2320)
        checkInterfaceMultiBaseConflicts()
        // 64f4. Check index signature property type compatibility (TS2411)
        checkIndexSignatureProperties()
        // 64g. Check abstract class instantiation (TS2511)
        checkAbstractClassInstantiation()
        // 64h. Check overload signature compatibility (TS2394)
        checkOverloadSignatureCompatibility()
        // 64i. Check static members referencing class type parameters (TS2302)
        checkStaticMembersReferenceTypeParams()
        // 65. Check invalid assignment targets (TS2364)
        checkInvalidAssignmentTargets()
        // 65a. Check for-in LHS type (TS2405: must be 'string' or 'any')
        checkForInLhsTypes()
        // 65b. Check subsequent var declaration type mismatch (TS2403)
        checkSubsequentVarTypes()
        // 66. Check TypeScript syntax in JavaScript files (TS8xxx)
        checkTsSyntaxInJsFiles()
        // 67. Check export specifiers for non-local declarations (TS2661)
        checkExportSpecifierLocality()
        // 68. Check import declaration conflicts with local (TS2440)
        checkImportConflictsWithLocal()
        // 69. Check namespace used as type (TS2709)
        checkNamespaceUsedAsType()
        // 70. Check property used before initialization (TS2729)
        checkPropertyUseBeforeInit()
        // 71. Check downlevelIteration requirement (TS2802)
        if (options.target < ScriptTarget.ES2015 && !options.downlevelIteration) {
            checkDownlevelIteration()
        }
        // 71b. Check BigInt literals at targets lower than ES2020 (TS2737)
        if (options.target < ScriptTarget.ES2020) {
            checkBigIntLiterals()
        }
        // 72. Check call/new expression type argument count (TS2558)
        checkCallTypeArgCount()
        // 73. Check cross-file duplicate function implementation (TS2393)
        if (binderResults.size > 1) {
            checkCrossFileDuplicateFunction()
        }
        // 73b. Check cross-file block-scoped variable redeclarations (TS2451)
        if (binderResults.size > 1) {
            checkCrossFileBlockScopedDuplicates()
        }
        // 74. Check module hidden by local declaration (TS2437)
        checkModuleHiddenByLocal()
        // 75. Check export assignment expressions in ambient contexts (TS2714)
        checkAmbientExportAssignmentExpressions()
        // 76. Check for multiple AMD module name directives (TS2458)
        if (options.effectiveModule == ModuleKind.AMD) {
            checkMultipleAmdModuleNames()
        }
        // 77. Check class named 'Object' with CJS/AMD/System/UMD module (TS2725)
        checkObjectClassNameConflict()
        } // end if (!declarationOnly)
    }

    // -----------------------------------------------------------------------
    // Public API
    // -----------------------------------------------------------------------

    /** Returns diagnostics produced by the checker, filtered to assigned files if set. */
    fun getDiagnostics(): List<Diagnostic> {
        if (assignedFileNames == null) return diagnostics.toList()
        return diagnostics.filter { it.fileName == null || it.fileName in assignedFileNames }
    }

    // -----------------------------------------------------------------------
    // Public API — called by Transformer
    // -----------------------------------------------------------------------

    /**
     * Check if an import/export alias is referenced in value positions.
     * If not referenced, the import can be elided from JS output.
     */
    fun isReferencedAliasDeclaration(node: Node): Boolean {
        val key = nodeKey(node)
        for (result in binderResults) {
            val symbol = result.nodeToSymbol[key]
            if (symbol != null) {
                // Check if this specific symbol is referenced
                if (symbol.id in referencedAliases) return true
                // For ImportDeclarations with named imports, check if ANY specifier is referenced
                if (node is ImportDeclaration) {
                    val clause = node.importClause ?: return false
                    val bindings = clause.namedBindings
                    if (bindings is NamedImports) {
                        return bindings.elements.any { spec ->
                            val specSymbol = result.nodeToSymbol[nodeKey(spec)]
                            specSymbol != null && specSymbol.id in referencedAliases
                        }
                    }
                    // Default import or namespace import
                    return false
                }
                return false
            }
        }
        return true // safe default: keep the import
    }

    /**
     * Check if an export assignment refers to a value (not just a type).
     */
    fun isValueAliasDeclaration(node: Node): Boolean {
        if (node !is ExportAssignment) return true
        val expr = node.expression
        if (expr is Identifier) {
            val symbol = resolveIdentifierInFile(expr.text, node)
            if (symbol != null) {
                return symbol.flags.hasAny(SymbolFlags.Value)
            }
        }
        return true // expressions are always values
    }

    /**
     * Check if a re-exported name from a module specifier is a value (not type-only).
     * Used for `export { name } from "module"` — elide specifiers that are type-only
     * (interfaces, type aliases, non-instantiated namespaces).
     */
    fun isValueExport(name: String, moduleSpecifier: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return true
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return true
        val targetResult = fileResults[targetFile] ?: return true
        val symbol = targetResult.locals[name] ?: return true // safe default: keep
        val resolved = resolveAlias(symbol)
        // Const enums without preserveConstEnums are type-only (inlined at use sites)
        if (!options.preserveConstEnums && !options.isolatedModules && !options.verbatimModuleSyntax &&
            resolved.flags.hasAny(SymbolFlags.ConstEnum)) return false
        // Check if the symbol has value flags
        if (resolved.flags.hasAny(SymbolFlags.Value)) return true
        // Non-instantiated namespaces (no value content) are type-only
        if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
            // Check module instance state from binder
            for (br in binderResults) {
                for (decl in resolved.declarations) {
                    if (decl is ModuleDeclaration) {
                        val state = br.moduleInstanceStates[nodeKey(decl)]
                        if (state == ModuleInstanceState.Instantiated) return true
                    }
                }
            }
            return false // non-instantiated namespace
        }
        return false
    }

    /**
     * Get the constant value of an enum member node.
     */
    fun getEnumMemberValue(memberNode: Node): ConstantValue? {
        val key = nodeKey(memberNode)
        for (result in binderResults) {
            val symbol = result.nodeToSymbol[key]
            if (symbol != null) {
                val enumSymbol = symbol.parent ?: return null
                return enumValues[enumSymbol.id]?.get(symbol.name)
            }
        }
        return null
    }

    /**
     * Check if an import=require() resolves to a type-only module (only interfaces/types).
     * Used by CJS transform to elide require() for type-only imports.
     */
    /**
     * Returns true if a symbol is purely type-only based on its declaration nodes.
     * This avoids using symbol.flags which may be polluted by cross-file merging.
     * - InterfaceDeclaration / TypeAliasDeclaration → always type-only
     * - ModuleDeclaration with NonInstantiated state → type-only
     * - VariableDeclaration, FunctionDeclaration, ClassDeclaration, EnumDeclaration → value
     * - ImportSpecifier with Alias flags → check underlying if resolvable, otherwise conservative
     */
    private fun isSymbolTypeOnly(symbol: Symbol): Boolean {
        var hasValueDecl = false
        var hasTypeOnlyDecl = false
        for (decl in symbol.declarations) {
            when (decl) {
                is InterfaceDeclaration, is TypeAliasDeclaration -> hasTypeOnlyDecl = true
                is ModuleDeclaration -> {
                    // Module is type-only only if NonInstantiated (no runtime IIFE)
                    val state = binderResults.firstNotNullOfOrNull { br ->
                        br.moduleInstanceStates[nodeKey(decl)]
                    }
                    if (state == ModuleInstanceState.Instantiated || state == null) {
                        hasValueDecl = true
                    } else {
                        // Even a NonInstantiated namespace can be a value if it has value exports
                        // (e.g. `declare namespace a { export const x: number }; export = a`)
                        val hasValueExports = symbol.exports?.values?.any { it.flags.hasAny(SymbolFlags.Value) } == true
                        if (hasValueExports) {
                            hasValueDecl = true
                        } else {
                            hasTypeOnlyDecl = true
                        }
                    }
                }
                is VariableDeclaration, is FunctionDeclaration,
                is ClassDeclaration, is EnumDeclaration -> hasValueDecl = true
                else -> {} // ImportSpecifier, BindingElement, etc. - ignore for now
            }
        }
        if (hasValueDecl) return false
        return hasTypeOnlyDecl
    }

    fun isTypeOnlyImportRequire(moduleSpecifier: String, sourceFileName: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null)
        if (targetFile != null) {
            val targetResult = fileResults[targetFile] ?: return false
            // Check all exports from the target file
            for (stmt in targetResult.sourceFile.statements) {
                when (stmt) {
                    is ExportAssignment -> {
                        if (stmt.isExportEquals) {
                            val expr = stmt.expression
                            if (expr is Identifier) {
                                val symbol = targetResult.locals[expr.text]
                                if (symbol != null) {
                                    // Note: symbol.flags may have been polluted by cross-file merging
                                    // (e.g. Interface|Alias when another file imports this name).
                                    // Use the node-level declaration kind to determine the original type.
                                    return isSymbolTypeOnly(symbol)
                                }
                            }
                            return false // expression export = always value
                        }
                    }
                    else -> {}
                }
            }
            return false
        }
        // File-based resolution failed — check ambient external modules (declare module "X").
        // Look through all files for `declare module "specifier"` blocks whose exports are type-only.
        return isAmbientModuleTypeOnly(moduleSpecifier)
    }

    /**
     * Check if an ambient external module (declare module "X") exports only types.
     * Searches all files for matching `declare module` blocks and checks their exports.
     */
    private fun isAmbientModuleTypeOnly(moduleName: String): Boolean {
        for (result in binderResults) {
            // Skip files that are themselves modules (have imports/exports).
            // In module files, `declare module "X"` is an augmentation, not a definition.
            // Only script files can define ambient external modules.
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode
                    && (stmt.name as StringLiteralNode).text == moduleName) {
                    // Found the ambient module definition. Analyze the body AST directly.
                    // Cannot rely on result.locals[moduleName] because an import alias
                    // with the same name (import x = require("x")) may overwrite the symbol.
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        return isModuleBlockTypeOnly(body)
                    }
                    // No body — treat as type-only (empty ambient module)
                    return true
                }
            }
        }
        return false
    }

    /**
     * Check if a ModuleBlock contains only type declarations (interfaces, type aliases,
     * non-instantiated namespaces). Analyzes AST directly without symbol lookup.
     */
    private fun isModuleBlockTypeOnly(block: ModuleBlock): Boolean {
        for (stmt in block.statements) {
            when (stmt) {
                is ExportAssignment -> {
                    if (stmt.isExportEquals) {
                        val expr = stmt.expression
                        if (expr is Identifier) {
                            // Look for the exported name among the block's own declarations
                            return isNameTypeOnlyInBlock(expr.text, block)
                        }
                        return false // expression export = always value
                    }
                    // export default — check expression type
                }
                is VariableStatement -> return false // variables are values
                is FunctionDeclaration -> return false
                is ClassDeclaration -> return false
                is EnumDeclaration -> return false
                is InterfaceDeclaration -> { /* type-only, continue */ }
                is TypeAliasDeclaration -> { /* type-only, continue */ }
                is ModuleDeclaration -> {
                    // Nested namespace — check if instantiated
                    val br = binderResults.firstOrNull() ?: return false
                    val state = br.moduleInstanceStates[nodeKey(stmt)]
                    if (state == ModuleInstanceState.Instantiated) return false
                }
                is ExportDeclaration -> { /* re-export — skip for now */ }
                is ImportDeclaration -> { /* import — skip */ }
                is ImportEqualsDeclaration -> { /* import — skip */ }
                else -> { /* other statements */ }
            }
        }
        return true // all statements are type-only
    }

    /**
     * Check if a name declared within a ModuleBlock is type-only.
     * Used for `export = Name` resolution in ambient modules.
     */
    private fun isNameTypeOnlyInBlock(name: String, block: ModuleBlock): Boolean {
        var hasValueDecl = false
        var hasTypeOnlyDecl = false
        for (stmt in block.statements) {
            when (stmt) {
                is InterfaceDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is EnumDeclaration -> if (stmt.name.text == name) hasValueDecl = true
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        if (d.name is Identifier && (d.name as Identifier).text == name) {
                            hasValueDecl = true
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val modName = when (val n = stmt.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> null
                    }
                    if (modName == name) {
                        // Check if the namespace has value exports
                        val br = binderResults.firstOrNull() ?: continue
                        val state = br.moduleInstanceStates[nodeKey(stmt)]
                        if (state == ModuleInstanceState.Instantiated) {
                            hasValueDecl = true
                        } else {
                            hasTypeOnlyDecl = true
                        }
                    }
                }
                else -> {}
            }
        }
        if (hasValueDecl) return false
        return hasTypeOnlyDecl
    }

    /**
     * Check if a name resolves to a type-only declaration across all files.
     * Used for `export { X }` (no from) to decide if void 0 hoist is needed.
     * Returns true if the name is a type-only symbol (interface, type alias,
     * non-instantiated namespace). Returns false if it's a value or unknown.
     */
    fun isTypeOnlyGlobalName(name: String): Boolean {
        // Check globals first
        val globalSymbol = globals[name]
        if (globalSymbol != null) {
            val resolved = resolveAlias(globalSymbol)
            if (resolved.flags.hasAny(SymbolFlags.Value)) return false
            if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
                // If the namespace exports any value members, it's not type-only
                // (e.g. `declare namespace NS { export var foo }` has a runtime value shape)
                val exports = resolved.exports
                if (exports != null && exports.values.any { it.flags.hasAny(SymbolFlags.Value) }) return false
                for (br in binderResults) {
                    for (decl in resolved.declarations) {
                        if (decl is ModuleDeclaration) {
                            val state = br.moduleInstanceStates[nodeKey(decl)]
                            if (state == ModuleInstanceState.Instantiated) return false
                        }
                    }
                }
                return true
            }
            return resolved.flags.hasAny(SymbolFlags.Type) && !resolved.flags.hasAny(SymbolFlags.Value)
        }
        // Check all file locals
        for (result in binderResults) {
            val symbol = result.locals[name]
            if (symbol != null) {
                val resolved = resolveAlias(symbol)
                if (resolved.flags.hasAny(SymbolFlags.Value)) return false
                if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
                    // If the namespace exports any value members, it's not type-only
                    val exports = resolved.exports
                    if (exports != null && exports.values.any { it.flags.hasAny(SymbolFlags.Value) }) return false
                    for (br in binderResults) {
                        for (decl in resolved.declarations) {
                            if (decl is ModuleDeclaration) {
                                val state = br.moduleInstanceStates[nodeKey(decl)]
                                if (state == ModuleInstanceState.Instantiated) return false
                            }
                        }
                    }
                    return true
                }
                return resolved.flags.hasAny(SymbolFlags.Type) && !resolved.flags.hasAny(SymbolFlags.Value)
            }
        }
        return false // unknown name — conservative, keep the export
    }

    /**
     * Resolve a const enum member access like `E.A` to its constant value.
     * Returns null if `enumName` is not a const enum or `memberName` is not found.
     */
    fun resolveConstEnumMemberAccess(
        enumName: String,
        memberName: String,
        sourceFileName: String,
    ): ConstantValue? {
        val result = fileResults[sourceFileName] ?: return null
        val symbol = resolveNamePath(enumName, result) ?: return null
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.ConstEnum)) return null
        return enumValues[target.id]?.get(memberName)
    }

    /**
     * Check if a name resolves to a const enum (directly or through alias chains).
     * Used for eliding import aliases to const enums after inlining.
     */
    fun isConstEnumAlias(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name] ?: return false
        val target = resolveAlias(symbol)
        return target.flags.hasAny(SymbolFlags.ConstEnum)
    }

    /**
     * Check if a name resolves to a numeric enum type.
     * Used for decorator metadata serialization: numeric enums serialize as `Number`.
     * Returns false for string enums, non-enums, or unknown names.
     */
    fun isNumericEnumType(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name] ?: return false
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return false
        // A numeric enum has all NumberValue (or no values computed, which means all auto-number)
        val values = enumValues[target.id] ?: return true // no values means all auto-numeric
        return values.values.none { it is ConstantValue.StringValue }
    }

    /**
     * Check if a name resolves to a class symbol (directly or through alias chains).
     * Used for decorator metadata: type-only class imports serialize as `Function`.
     */
    fun isClassType(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name] ?: return false
        val target = resolveAlias(symbol)
        return target.flags.hasAny(SymbolFlags.Class)
    }

    /**
     * Returns true if [name] is exported from [moduleSpecifier] ONLY via `export type { Name }`
     * (i.e., the export declaration has `isTypeOnly = true`). This indicates the import is effectively
     * type-only even without an explicit `import type { ... }`.
     */
    fun isTypeOnlyExportName(name: String, moduleSpecifier: String, sourceFileName: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        // Scan export declarations in the target file to find if `name` is exported type-only
        var hasTypeOnlyExport = false
        var hasValueExport = false
        for (stmt in targetResult.sourceFile.statements) {
            if (stmt !is ExportDeclaration) continue
            val clause = stmt.exportClause as? NamedExports ?: continue
            for (spec in clause.elements) {
                val exportedName = spec.name.text
                if (exportedName != name) continue
                if (stmt.isTypeOnly || spec.isTypeOnly) {
                    hasTypeOnlyExport = true
                } else {
                    hasValueExport = true
                }
            }
        }
        // Only type-only if exported via `export type { X }` and NOT also via plain `export { X }`
        return hasTypeOnlyExport && !hasValueExport
    }

    /**
     * Resolve an enum member value through import aliases.
     * Works for both const and non-const enums. Returns the numeric value or null.
     */
    fun resolveEnumMemberValue(
        enumName: String,
        memberName: String,
        sourceFileName: String,
    ): Long? {
        val result = fileResults[sourceFileName] ?: return null
        val symbol = resolveNamePath(enumName, result) ?: return null
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
        val value = enumValues[target.id]?.get(memberName)
        return when (value) {
            is ConstantValue.NumberValue -> value.value.toLong()
            else -> null
        }
    }

    /**
     * Get the module instance state for a module/namespace declaration.
     */
    fun getModuleInstanceState(node: ModuleDeclaration): ModuleInstanceState {
        val key = nodeKey(node)
        for (result in binderResults) {
            val state = result.moduleInstanceStates[key]
            if (state != null) return state
        }
        return ModuleInstanceState.Instantiated // safe default
    }

    /**
     * Returns true if [name] is declared as a plain `var` in any file that comes
     * BEFORE [currentFileName] in the compilation order.
     *
     * Used in script-mode (non-module) files to decide whether to erase `import x = NS`
     * when NS is a non-instantiated namespace: if an earlier file already declares `x`
     * as a plain var, the import alias in the current file is redundant and should be erased.
     */
    fun hasVarDeclarationInEarlierFile(name: String, currentFileName: String): Boolean {
        val currentIdx = binderResults.indexOfFirst { it.sourceFile.fileName == currentFileName }
        if (currentIdx <= 0) return false
        for (i in 0 until currentIdx) {
            val result = binderResults[i]
            val symbol = result.locals[name] ?: continue
            for (decl in symbol.declarations) {
                if (decl is VariableDeclaration) return true
            }
        }
        return false
    }

    /**
     * Returns true if a plain `var` declaration for [name] exists in any file that comes
     * AFTER [currentFileName] in the compilation order.
     *
     * Used symmetrically with [hasVarDeclarationInEarlierFile]: when a later file will declare
     * `var x`, the current file's `import x = NS` must be kept so that the merged var binding
     * is observable at runtime (`var x = NS` in current + `var x` in later = two var declarations
     * for the same name, which is legal in script mode).
     */
    fun hasVarDeclarationInLaterFile(name: String, currentFileName: String): Boolean {
        val currentIdx = binderResults.indexOfFirst { it.sourceFile.fileName == currentFileName }
        if (currentIdx < 0) return false
        for (i in currentIdx + 1 until binderResults.size) {
            val result = binderResults[i]
            val symbol = result.locals[name] ?: continue
            for (decl in symbol.declarations) {
                if (decl is VariableDeclaration) return true
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Symbol table merging
    // -----------------------------------------------------------------------

    private fun mergeSymbolTable(target: SymbolTable, source: SymbolTable) {
        for ((name, symbol) in source) {
            val existing = target[name]
            if (existing != null) {
                // Merge: combine flags and declarations
                existing.flags = existing.flags or symbol.flags
                existing.declarations.addAll(symbol.declarations)
                if (existing.valueDeclaration == null && symbol.valueDeclaration != null) {
                    existing.valueDeclaration = symbol.valueDeclaration
                }
                // Merge enum exports
                if (symbol.exports != null) {
                    if (existing.exports == null) existing.exports = symbolTable()
                    mergeSymbolTable(existing.exports!!, symbol.exports!!)
                }
            } else {
                target[name] = symbol
            }
        }
    }

    /**
     * Merge module augmentation exports into target module symbols.
     *
     * When `declare module "./foo" { namespace Bar { ... } }` augments a file-based module,
     * the binder creates a module symbol keyed by the specifier string (e.g., "./foo") in
     * globals. The actual target symbols (e.g., class Bar) are in globals under their own
     * names. This method resolves the augmentation specifiers and merges augmented exports
     * (namespaces, interfaces, etc.) into the corresponding global symbols.
     */
    private fun mergeModuleAugmentations() {
        val processedSpecifiers = mutableSetOf<String>()
        for (result in binderResults) {
            collectModuleAugmentations(result.sourceFile.statements, processedSpecifiers)
        }
    }

    private fun collectModuleAugmentations(statements: List<Statement>, processedSpecifiers: MutableSet<String>) {
        for (stmt in statements) {
            if (stmt !is ModuleDeclaration) continue
            val name = stmt.name as? StringLiteralNode ?: continue
            val specifier = name.text

            // Recursively process nested module declarations inside this one
            // (e.g. `declare module "D" { module "a" { interface A { ... } } }`)
            val body = stmt.body
            if (body is ModuleBlock) {
                collectModuleAugmentations(body.statements, processedSpecifiers)
            }

            if (!processedSpecifiers.add(specifier)) continue

            // Find the augmentation module symbol in globals
            val augModule = globals[specifier] ?: continue
            val augExports = augModule.exports ?: continue

            // Resolve the specifier to a target file
            val targetFile = resolveModuleSpecifier(specifier, stmt)

            // Merge each augmented export into the corresponding global symbol.
            for ((exportName, augSymbol) in augExports) {
                val globalSymbol = globals[exportName]
                if (globalSymbol != null) {
                    if (augSymbol.exports != null) {
                        if (globalSymbol.exports == null) globalSymbol.exports = symbolTable()
                        mergeSymbolTable(globalSymbol.exports!!, augSymbol.exports!!)
                        globalSymbol.flags = globalSymbol.flags or (augSymbol.flags and SymbolFlags.Module)
                    }
                    if (augSymbol.declarations.isNotEmpty()) {
                        for (decl in augSymbol.declarations) {
                            if (decl !in globalSymbol.declarations) {
                                globalSymbol.declarations.add(decl)
                            }
                        }
                    }
                } else {
                    // New export not yet in globals — add it
                    globals[exportName] = augSymbol
                }
            }

            // Also merge augmented exports into the target file's binder result locals
            if (targetFile != null) {
                val targetResult = fileResults[targetFile]
                if (targetResult != null) {
                    for ((exportName, augSymbol) in augExports) {
                        val localSymbol = targetResult.locals[exportName]
                        if (localSymbol != null) {
                            if (augSymbol.exports != null) {
                                if (localSymbol.exports == null) localSymbol.exports = symbolTable()
                                mergeSymbolTable(localSymbol.exports!!, augSymbol.exports!!)
                                localSymbol.flags = localSymbol.flags or (augSymbol.flags and SymbolFlags.Module)
                            }
                            if (augSymbol.declarations.isNotEmpty()) {
                                for (decl in augSymbol.declarations) {
                                    if (decl !in localSymbol.declarations) {
                                        localSymbol.declarations.add(decl)
                                    }
                                }
                            }
                        } else {
                            // New export — add to target file's locals
                            targetResult.locals[exportName] = augSymbol
                        }
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Enum value computation
    // -----------------------------------------------------------------------

    private fun computeAllEnumValues() {
        for (result in binderResults) {
            for ((_, symbol) in result.locals) {
                computeEnumValuesRecursive(symbol)
            }
        }
    }

    private fun computeEnumValuesRecursive(symbol: Symbol) {
        if (symbol.flags.hasAny(SymbolFlags.Enum)) {
            computeEnumSymbolValues(symbol)
        }
        // Recurse into namespace exports to find nested enums
        if (symbol.flags.hasAny(SymbolFlags.Module)) {
            symbol.exports?.values?.forEach { computeEnumValuesRecursive(it) }
        }
    }

    private fun computeEnumSymbolValues(symbol: Symbol) {
        if (enumValues.containsKey(symbol.id)) return
        val values = mutableMapOf<String, ConstantValue>()
        enumValues[symbol.id] = values

        for (decl in symbol.declarations) {
            if (decl !is EnumDeclaration) continue
            var autoValue = 0.0
            for (member in decl.members) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> continue
                }
                if (member.initializer != null) {
                    val computed = evaluateEnumInitializer(member.initializer, values, symbol)
                    if (computed != null) {
                        values[name] = computed
                        if (computed is ConstantValue.NumberValue) {
                            autoValue = computed.value + 1
                        }
                    } else {
                        // Cannot evaluate — auto-increment is broken
                        autoValue = Double.NaN
                    }
                } else {
                    if (!autoValue.isNaN()) {
                        values[name] = ConstantValue.NumberValue(autoValue)
                        autoValue++
                    }
                }
            }
        }
    }

    private fun evaluateEnumInitializer(
        expr: Expression,
        currentValues: Map<String, ConstantValue>,
        currentEnum: Symbol,
    ): ConstantValue? {
        return when (expr) {
            is NumericLiteralNode -> {
                val value = expr.text.toDoubleOrNull() ?: return null
                ConstantValue.NumberValue(value)
            }
            is StringLiteralNode -> ConstantValue.StringValue(expr.text)
            is PrefixUnaryExpression -> {
                val operand = evaluateEnumInitializer(expr.operand, currentValues, currentEnum)
                    ?: return null
                if (operand !is ConstantValue.NumberValue) return null
                when (expr.operator) {
                    SyntaxKind.Plus -> operand
                    SyntaxKind.Minus -> ConstantValue.NumberValue(-operand.value)
                    SyntaxKind.Tilde -> ConstantValue.NumberValue(
                        operand.value.toLong().inv().toDouble()
                    )
                    else -> null
                }
            }
            is BinaryExpression -> {
                val left = evaluateEnumInitializer(expr.left, currentValues, currentEnum)
                    ?: return null
                val right = evaluateEnumInitializer(expr.right, currentValues, currentEnum)
                    ?: return null
                if (left is ConstantValue.NumberValue && right is ConstantValue.NumberValue) {
                    evaluateNumericBinary(left.value, expr.operator, right.value)
                } else if (left is ConstantValue.StringValue && right is ConstantValue.StringValue
                    && expr.operator == SyntaxKind.Plus) {
                    ConstantValue.StringValue(left.value + right.value)
                } else null
            }
            is ParenthesizedExpression -> {
                evaluateEnumInitializer(expr.expression, currentValues, currentEnum)
            }
            is Identifier -> {
                // Reference to another member in the same enum
                currentValues[expr.text]
            }
            is PropertyAccessExpression -> {
                // Reference to another enum's member: E.A or A.B.C.E.V1
                val memberName = expr.name.text
                val targetEnum = resolveEnumExpression(expr.expression, currentEnum.name)
                if (targetEnum != null) {
                    if (targetEnum.name == currentEnum.name && targetEnum.id == currentEnum.id) {
                        currentValues[memberName]
                    } else {
                        if (!targetEnum.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(targetEnum) // ensure computed
                        enumValues[targetEnum.id]?.get(memberName)
                    }
                } else {
                    // Simple case: Identifier.member
                    val objName = (expr.expression as? Identifier)?.text ?: return null
                    if (objName == currentEnum.name) {
                        currentValues[memberName]
                    } else {
                        val symbol = globals[objName] ?: return null
                        val target = resolveAlias(symbol)
                        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(target)
                        enumValues[target.id]?.get(memberName)
                    }
                }
            }
            is ElementAccessExpression -> {
                // E["member"] or E[`member`] — element access to enum member
                val keyStr = when (val k = expr.argumentExpression) {
                    is StringLiteralNode -> k.text
                    is NoSubstitutionTemplateLiteralNode -> k.text
                    else -> return null
                }
                val objName = (expr.expression as? Identifier)?.text
                if (objName != null) {
                    if (objName == currentEnum.name) {
                        currentValues[keyStr]
                    } else {
                        val symbol = globals[objName] ?: return null
                        val target = resolveAlias(symbol)
                        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(target)
                        enumValues[target.id]?.get(keyStr)
                    }
                } else {
                    // Nested: A.B.C.E["V2"]
                    val targetEnum = resolveEnumExpression(expr.expression, currentEnum.name)
                        ?: return null
                    if (targetEnum.name == currentEnum.name && targetEnum.id == currentEnum.id) {
                        currentValues[keyStr]
                    } else {
                        if (!targetEnum.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(targetEnum)
                        enumValues[targetEnum.id]?.get(keyStr)
                    }
                }
            }
            is NoSubstitutionTemplateLiteralNode -> {
                ConstantValue.StringValue(expr.text)
            }
            is TemplateExpression -> {
                // Template literal: `prefix${expr}suffix`
                val sb = StringBuilder(expr.head.text)
                for (span in expr.templateSpans) {
                    val spanValue = evaluateEnumInitializer(span.expression, currentValues, currentEnum)
                        ?: return null
                    sb.append(
                        when (spanValue) {
                            is ConstantValue.StringValue -> spanValue.value
                            is ConstantValue.NumberValue -> spanValue.toString()
                        }
                    )
                    // The literal part is a StringLiteralNode (template middle/tail)
                    val literalText = (span.literal as? StringLiteralNode)?.text
                        ?: (span.literal as? NoSubstitutionTemplateLiteralNode)?.text
                        ?: ""
                    sb.append(literalText)
                }
                ConstantValue.StringValue(sb.toString())
            }
            else -> null
        }
    }

    private fun evaluateNumericBinary(
        left: Double,
        operator: SyntaxKind,
        right: Double,
    ): ConstantValue? {
        val result = when (operator) {
            SyntaxKind.Plus -> left + right
            SyntaxKind.Minus -> left - right
            SyntaxKind.Asterisk -> left * right
            SyntaxKind.Slash -> left / right
            SyntaxKind.Percent -> left % right
            SyntaxKind.AsteriskAsterisk -> left.pow(right)
            SyntaxKind.Bar -> (left.toLong() or right.toLong()).toDouble()
            SyntaxKind.Ampersand -> (left.toLong() and right.toLong()).toDouble()
            SyntaxKind.Caret -> (left.toLong() xor right.toLong()).toDouble()
            SyntaxKind.LessThanLessThan -> (left.toLong() shl right.toInt()).toDouble()
            SyntaxKind.GreaterThanGreaterThan -> (left.toLong() shr right.toInt()).toDouble()
            SyntaxKind.GreaterThanGreaterThanGreaterThan ->
                (left.toLong().toInt().ushr(right.toInt())).toDouble()
            else -> return null
        }
        return ConstantValue.NumberValue(result)
    }

    // -----------------------------------------------------------------------
    // Import reference tracking
    // -----------------------------------------------------------------------

    private fun trackAllImportReferences() {
        for (result in binderResults) {
            trackReferencesInStatements(result.sourceFile.statements, result)
        }
    }

    /**
     * Build per-file type maps containing types for all file-level declarations.
     * These maps enable getTypeOfIdentifier to resolve file-level names across all
     * checker passes, not just during the TS2322 walk.
     */
    private fun buildFileLocalTypeMaps() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val typeMap = mutableMapOf<String, Type>()
            for ((name, symbol) in result.locals) {
                // Only resolve types for symbols that are NOT simple variables
                // (variable inference via getTypeOfExpression can be expensive on stress tests)
                if (symbol.flags.hasAny(SymbolFlags.Function or SymbolFlags.Class or
                        SymbolFlags.Interface or SymbolFlags.Enum or SymbolFlags.TypeAlias or
                        SymbolFlags.Alias)) {
                    try {
                        val type = getTypeOfSymbol(symbol)
                        if (type !== anyType && type !== errorType) {
                            typeMap[name] = type
                        }
                    } catch (_: StackOverflowError) {
                        // Circular type resolution — skip
                    }
                } else if (symbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
                    // For variables, only resolve if they have a type annotation (cheap)
                    val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
                    val hasAnnotation = when (decl) {
                        is VariableDeclaration -> decl.type != null
                        is Parameter -> decl.type != null
                        is PropertyDeclaration -> decl.type != null
                        else -> false
                    }
                    if (hasAnnotation) {
                        try {
                            val type = getTypeOfSymbol(symbol)
                            if (type !== anyType && type !== errorType) {
                                typeMap[name] = type
                            }
                        } catch (_: StackOverflowError) {}
                    }
                }
            }
            if (typeMap.isNotEmpty()) {
                fileLocalTypeMaps[fileName] = typeMap
            }
        }
    }

    private fun trackReferencesInStatements(statements: List<Statement>, result: BinderResult) {
        for (stmt in statements) {
            trackReferencesInStatement(stmt, result)
        }
    }

    private fun trackReferencesInStatement(stmt: Statement, result: BinderResult) {
        when (stmt) {
            // Skip type-only declarations (no value references inside)
            is InterfaceDeclaration -> return
            is TypeAliasDeclaration -> return
            // Skip declare statements (ambient — no runtime)
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Walk body for value references
                stmt.body?.let { trackReferencesInStatements(it.statements, result) }
                // Walk parameter initializers
                for (param in stmt.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                    // Decorators are value references
                    param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                }
                // Decorators on the function itself are irrelevant (only classes/methods have them)
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // extends clause is a value reference
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (type in clause.types) {
                            trackReferencesInExpression(type.expression, result)
                        }
                    }
                    // implements clause is type-only — skip
                }
                // Decorators are value references
                stmt.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                // Walk class members
                for (member in stmt.members) {
                    trackReferencesInClassElement(member, result)
                }
            }
            is EnumDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Enum member initializers are value references
                for (member in stmt.members) {
                    member.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                when (val body = stmt.body) {
                    is ModuleBlock -> trackReferencesInStatements(body.statements, result)
                    is ModuleDeclaration -> trackReferencesInStatement(body, result)
                    else -> {}
                }
            }
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ExpressionStatement -> {
                trackReferencesInExpression(stmt.expression, result)
            }
            is ReturnStatement -> {
                stmt.expression?.let { trackReferencesInExpression(it, result) }
            }
            is IfStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.thenStatement, result)
                stmt.elseStatement?.let { trackReferencesInStatement(it, result) }
            }
            is Block -> trackReferencesInStatements(stmt.statements, result)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { trackReferencesInExpression(it, result) }
                        }
                    }
                    is Expression -> trackReferencesInExpression(init, result)
                    else -> {}
                }
                stmt.condition?.let { trackReferencesInExpression(it, result) }
                stmt.incrementor?.let { trackReferencesInExpression(it, result) }
                trackReferencesInStatement(stmt.statement, result)
            }
            is ForInStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is ForOfStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is WhileStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is DoStatement -> {
                trackReferencesInStatement(stmt.statement, result)
                trackReferencesInExpression(stmt.expression, result)
            }
            is SwitchStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            trackReferencesInExpression(clause.expression, result)
                            trackReferencesInStatements(clause.statements, result)
                        }
                        is DefaultClause -> {
                            trackReferencesInStatements(clause.statements, result)
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> {
                stmt.expression?.let { trackReferencesInExpression(it, result) }
            }
            is TryStatement -> {
                trackReferencesInStatements(stmt.tryBlock.statements, result)
                stmt.catchClause?.let {
                    trackReferencesInStatements(it.block.statements, result)
                }
                stmt.finallyBlock?.let {
                    trackReferencesInStatements(it.statements, result)
                }
            }
            is LabeledStatement -> {
                trackReferencesInStatement(stmt.statement, result)
            }
            is WithStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is ExportDeclaration -> {
                // export { X } — X is a value reference if not type-only
                if (!stmt.isTypeOnly) {
                    when (val clause = stmt.exportClause) {
                        is NamedExports -> {
                            for (spec in clause.elements) {
                                if (!spec.isTypeOnly) {
                                    val name = spec.propertyName?.text ?: spec.name.text
                                    markAliasReferenced(name, result)
                                }
                            }
                        }
                        else -> {}
                    }
                }
            }
            is ExportAssignment -> {
                trackReferencesInExpression(stmt.expression, result)
            }
            is ImportDeclaration -> { /* imports don't create value references */ }
            is ImportEqualsDeclaration -> { /* handled separately */ }
            else -> { /* other statements */ }
        }
    }

    private fun trackReferencesInClassElement(element: ClassElement, result: BinderResult) {
        when (element) {
            is PropertyDeclaration -> {
                if (ModifierFlag.Declare !in element.modifiers) {
                    element.initializer?.let { trackReferencesInExpression(it, result) }
                }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is MethodDeclaration -> {
                if (ModifierFlag.Declare !in element.modifiers) {
                    element.body?.let { trackReferencesInStatements(it.statements, result) }
                    for (param in element.parameters) {
                        param.initializer?.let { trackReferencesInExpression(it, result) }
                        param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                    }
                }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is Constructor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                for (param in element.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                    param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                }
            }
            is GetAccessor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is SetAccessor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is ClassStaticBlockDeclaration -> {
                trackReferencesInStatements(element.body.statements, result)
            }
            else -> { /* IndexSignature, SemicolonClassElement — no value refs */ }
        }
    }

    private fun trackReferencesInExpression(expr: Expression, result: BinderResult) {
        when (expr) {
            is Identifier -> {
                markAliasReferenced(expr.text, result)
            }
            is PropertyAccessExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is ElementAccessExpression -> {
                trackReferencesInExpression(expr.expression, result)
                trackReferencesInExpression(expr.argumentExpression, result)
            }
            is CallExpression -> {
                trackReferencesInExpression(expr.expression, result)
                for (arg in expr.arguments) {
                    trackReferencesInExpression(arg, result)
                }
            }
            is NewExpression -> {
                trackReferencesInExpression(expr.expression, result)
                expr.arguments?.forEach { trackReferencesInExpression(it, result) }
            }
            is BinaryExpression -> {
                // Iterative traversal to avoid StackOverflow on deeply nested binaries
                var current: Expression = expr
                while (current is BinaryExpression) {
                    trackReferencesInExpression(current.right, result)
                    current = current.left
                }
                trackReferencesInExpression(current, result)
            }
            is ConditionalExpression -> {
                trackReferencesInExpression(expr.condition, result)
                trackReferencesInExpression(expr.whenTrue, result)
                trackReferencesInExpression(expr.whenFalse, result)
            }
            is PrefixUnaryExpression -> {
                trackReferencesInExpression(expr.operand, result)
            }
            is PostfixUnaryExpression -> {
                trackReferencesInExpression(expr.operand, result)
            }
            is ParenthesizedExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is ArrayLiteralExpression -> {
                for (element in expr.elements) {
                    trackReferencesInExpression(element, result)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            trackReferencesInExpression(prop.initializer, result)
                            val propName = prop.name
                            if (propName is ComputedPropertyName) {
                                trackReferencesInExpression(propName.expression, result)
                            }
                        }
                        is ShorthandPropertyAssignment -> {
                            markAliasReferenced(prop.name.text, result)
                        }
                        is SpreadAssignment -> {
                            trackReferencesInExpression(prop.expression, result)
                        }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> trackReferencesInStatements(body.statements, result)
                    is Expression -> trackReferencesInExpression(body, result)
                    else -> {}
                }
                for (param in expr.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is FunctionExpression -> {
                trackReferencesInStatements(expr.body.statements, result)
                for (param in expr.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ClassExpression -> {
                expr.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (type in clause.types) {
                            trackReferencesInExpression(type.expression, result)
                        }
                    }
                }
                for (member in expr.members) {
                    trackReferencesInClassElement(member, result)
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    trackReferencesInExpression(span.expression, result)
                }
            }
            is TaggedTemplateExpression -> {
                trackReferencesInExpression(expr.tag, result)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        for (span in template.templateSpans) {
                            trackReferencesInExpression(span.expression, result)
                        }
                    }
                    else -> {}
                }
            }
            is SpreadElement -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is AwaitExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is YieldExpression -> {
                expr.expression?.let { trackReferencesInExpression(it, result) }
            }
            is DeleteExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is TypeOfExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is VoidExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is AsExpression -> {
                // The expression part is a value reference, but the type part is not
                trackReferencesInExpression(expr.expression, result)
            }
            is SatisfiesExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is NonNullExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is TypeAssertionExpression -> {
                // <Type>expr — expr is a value reference
                trackReferencesInExpression(expr.expression, result)
            }
            is CommaListExpression -> {
                for (e in expr.elements) {
                    trackReferencesInExpression(e, result)
                }
            }
            is MetaProperty -> { /* import.meta, new.target — no named references */ }
            // Literals — no references
            is StringLiteralNode -> {}
            is NumericLiteralNode -> {}
            is BigIntLiteralNode -> {}
            is RegularExpressionLiteralNode -> {}
            is NoSubstitutionTemplateLiteralNode -> {}
            is OmittedExpression -> {}
            // Binding patterns (in destructuring expressions)
            is ObjectBindingPattern -> {}
            is ArrayBindingPattern -> {}
            is ComputedPropertyName -> {
                trackReferencesInExpression(expr.expression, result)
            }
            // JSX expressions
            is JsxElement -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                trackReferencesInExpression(expr.openingElement.tagName, result)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { trackReferencesInExpression(it, result) }
                    } else if (child is Expression) {
                        trackReferencesInExpression(child, result)
                    }
                }
            }
            is JsxSelfClosingElement -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                trackReferencesInExpression(expr.tagName, result)
                for (attr in expr.attributes) {
                    when (attr) {
                        is JsxAttribute -> {
                            val v = attr.value
                            if (v is JsxExpressionContainer) {
                                v.expression?.let { trackReferencesInExpression(it, result) }
                            } else if (v is Expression) {
                                trackReferencesInExpression(v, result)
                            }
                        }
                        is JsxSpreadAttribute -> trackReferencesInExpression(attr.expression, result)
                        else -> {}
                    }
                }
            }
            is JsxFragment -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { trackReferencesInExpression(it, result) }
                    } else if (child is Expression) {
                        trackReferencesInExpression(child, result)
                    }
                }
            }
        }
    }

    /**
     * Mark an alias symbol as referenced if the given name resolves to an import.
     */
    private fun markAliasReferenced(name: String, result: BinderResult) {
        val symbol = result.locals[name] ?: return
        if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            referencedAliases.add(symbol.id)
        }
    }

    /**
     * Mark the JSX factory namespace import as referenced.
     * When a file uses JSX elements, the JSX factory namespace (default: "React") is
     * implicitly used at runtime, so its import must not be elided.
     * This applies for all JSX modes including "preserve".
     */
    private fun markJsxFactoryReferenced(result: BinderResult) {
        if (options.jsx == null) return
        // Determine the factory namespace: first dotted segment of jsxFactory, or reactNamespace, or "React"
        val factoryNamespace = when {
            options.jsxFactory != null -> options.jsxFactory!!.substringBefore('.')
            options.reactNamespace != null -> options.reactNamespace!!
            else -> "React"
        }
        markAliasReferenced(factoryNamespace, result)
    }

    // -----------------------------------------------------------------------
    // Symbol resolution helpers
    // -----------------------------------------------------------------------

    private fun resolveIdentifierInFile(name: String, contextNode: Node): Symbol? {
        for (result in binderResults) {
            val symbol = result.locals[name]
            if (symbol != null) return symbol
        }
        return globals[name]
    }

    private fun resolveAlias(symbol: Symbol, visited: MutableSet<Int> = mutableSetOf()): Symbol {
        if (!visited.add(symbol.id)) return symbol // cycle detected
        getSymbolTarget(symbol)?.let { return resolveAlias(it, visited) }
        // For import aliases, try to resolve the target
        if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            for (decl in symbol.declarations) {
                when (decl) {
                    is ImportEqualsDeclaration -> {
                        val ref = decl.moduleReference
                        when (ref) {
                            is QualifiedName -> {
                                val target = resolveQualifiedName(ref) ?: continue
                                setSymbolTarget(symbol, target)
                                return resolveAlias(target, visited)
                            }
                            is Identifier -> {
                                val target = globals[ref.text] ?: continue
                                setSymbolTarget(symbol, target)
                                return resolveAlias(target, visited)
                            }
                            is ExternalModuleReference -> {
                                // import A = require("mod") — resolve module then its export
                                val specifier = (ref.expression as? StringLiteralNode)?.text ?: continue
                                val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                                val targetResult = fileResults[targetFile] ?: continue
                                // Look for export = X in the target module
                                val exportTarget = resolveModuleExportAssignment(targetResult, visited)
                                if (exportTarget != null) {
                                    setSymbolTarget(symbol, exportTarget)
                                    return resolveAlias(exportTarget, visited)
                                }
                                // No export = found — create module symbol
                                val moduleSymbol = createModuleSymbol(symbol.name, targetResult)
                                setSymbolTarget(symbol, moduleSymbol)
                                return moduleSymbol
                            }
                            else -> {}
                        }
                    }
                    is ImportDeclaration -> {
                        val specifier = (decl.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                        val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                        val targetResult = fileResults[targetFile] ?: continue

                        // Namespace import: import * as Foo from "mod"
                        val namedBindings = decl.importClause?.namedBindings
                        if (namedBindings is NamespaceImport) {
                            val moduleSymbol = createModuleSymbol(symbol.name, targetResult)
                            setSymbolTarget(symbol, moduleSymbol)
                            return moduleSymbol
                        }

                        // Default import: import Foo from "mod"
                        if (decl.importClause?.name != null &&
                            symbol.name == decl.importClause?.name?.text) {
                            // Look for "default" export in target — first check locals["default"]
                            val defaultSymbol = targetResult.locals["default"]
                            if (defaultSymbol != null) {
                                setSymbolTarget(symbol, defaultSymbol)
                                return resolveAlias(defaultSymbol, visited)
                            }
                            // Scan for `export default X` (ExportAssignment without isExportEquals)
                            for (stmt in targetResult.sourceFile.statements) {
                                if (stmt is ExportAssignment && !stmt.isExportEquals) {
                                    val resolved = resolveExpressionToSymbol(stmt.expression, targetResult, visited)
                                    if (resolved != null) {
                                        setSymbolTarget(symbol, resolved)
                                        return resolveAlias(resolved, visited)
                                    }
                                }
                            }
                            // Scan for `export { X as default } from "mod"` re-exports
                            for (stmt in targetResult.sourceFile.statements) {
                                if (stmt is ExportDeclaration) {
                                    val clause = stmt.exportClause
                                    if (clause is NamedExports) {
                                        val defaultSpec = clause.elements.find { it.name.text == "default" }
                                        if (defaultSpec != null) {
                                            val originalName = defaultSpec.propertyName?.text ?: "default"
                                            val fromSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                                            val resolvedTarget: Symbol? = if (fromSpec != null) {
                                                val fromFile = resolveModuleSpecifier(fromSpec, stmt)
                                                val fromResult = fromFile?.let { fileResults[it] }
                                                fromResult?.locals?.get(originalName)
                                            } else {
                                                targetResult.locals[originalName]
                                            }
                                            if (resolvedTarget != null) {
                                                setSymbolTarget(symbol, resolvedTarget)
                                                return resolveAlias(resolvedTarget, visited)
                                            }
                                        }
                                    }
                                }
                            }
                            continue
                        }

                        // Named import: import { X } from "mod"
                        val target = targetResult.locals[symbol.name] ?: continue
                        setSymbolTarget(symbol, target)
                        return resolveAlias(target, visited)
                    }
                    is ImportSpecifier -> {
                        // Named import — the original name to look up
                        val originalName = decl.propertyName?.text ?: decl.name.text
                        // Find the ImportDeclaration parent for this specifier
                        // Since we don't have parent pointers, search all files
                        for (result in binderResults) {
                            for (stmt in result.sourceFile.statements) {
                                if (stmt is ImportDeclaration) {
                                    val bindings = stmt.importClause?.namedBindings
                                    if (bindings is NamedImports && decl in bindings.elements) {
                                        val specifier2 = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                                            ?: continue
                                        val targetFile2 = resolveModuleSpecifier(specifier2, stmt) ?: continue
                                        val targetResult2 = fileResults[targetFile2] ?: continue
                                        val target = targetResult2.locals[originalName] ?: continue
                                        setSymbolTarget(symbol, target)
                                        return resolveAlias(target, visited)
                                    }
                                }
                            }
                        }
                    }
                    else -> {}
                }
            }
        }
        return symbol
    }

    /**
     * Resolve a module's export assignment (`export = expr`) to a symbol.
     * Returns null if no export assignment exists.
     */
    private fun resolveModuleExportAssignment(result: BinderResult, visited: MutableSet<Int> = mutableSetOf()): Symbol? {
        for (stmt in result.sourceFile.statements) {
            if (stmt is ExportAssignment && stmt.isExportEquals) {
                return resolveExpressionToSymbol(stmt.expression, result, visited)
            }
        }
        return null
    }

    /**
     * Resolve an expression to a symbol (for export assignment resolution).
     */
    private fun resolveExpressionToSymbol(expr: Expression, result: BinderResult, visited: MutableSet<Int> = mutableSetOf()): Symbol? {
        return when (expr) {
            is Identifier -> {
                val symbol = result.locals[expr.text] ?: globals[expr.text] ?: return null
                resolveAlias(symbol, visited)
            }
            is PropertyAccessExpression -> {
                val parent = resolveExpressionToSymbol(expr.expression, result, visited) ?: return null
                val child = parent.exports?.get(expr.name.text) ?: return null
                resolveAlias(child, visited)
            }
            else -> null
        }
    }

    /**
     * Create a synthetic module symbol whose exports are the target file's effective exports.
     * For `.d.ts` files with ambient module declarations (`declare module "foo" {...}`), the
     * exports come from the inner ambient module, not from file-level locals.
     * For regular `.ts` files, uses the file-level locals directly.
     */
    private fun createModuleSymbol(name: String, targetResult: BinderResult): Symbol {
        val moduleSymbol = Symbol(
            name = name,
            flags = SymbolFlags.Module,
        )
        // For .d.ts files, check if there's a single ambient module declaration.
        // If so, use its exports rather than the file-level locals.
        val targetFile = targetResult.sourceFile.fileName
        if (targetFile.endsWith(".d.ts")) {
            val ambientModules = targetResult.sourceFile.statements
                .filterIsInstance<ModuleDeclaration>()
                .filter { ModifierFlag.Declare in it.modifiers }
            if (ambientModules.size == 1) {
                val ambientSymbol = targetResult.locals[when (val n = ambientModules[0].name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> ""
                }]
                if (ambientSymbol != null && ambientSymbol.exports != null) {
                    moduleSymbol.exports = ambientSymbol.exports
                    return moduleSymbol
                }
            }
        }
        moduleSymbol.exports = targetResult.locals
        return moduleSymbol
    }

    /**
     * Resolve a QualifiedName (e.g., A.B.C.E) to a symbol by walking the namespace chain.
     */
    /**
     * Resolve an expression to an enum symbol for enum member access.
     * Handles nested namespace access like A.B.C.E → the symbol for enum E.
     */
    private fun resolveEnumExpression(expr: Expression, currentEnumName: String): Symbol? {
        return when (expr) {
            is Identifier -> {
                val symbol = globals[expr.text] ?: return null
                resolveAlias(symbol)
            }
            is PropertyAccessExpression -> {
                val parent = resolveEnumExpression(expr.expression, currentEnumName) ?: return null
                val child = parent.exports?.get(expr.name.text) ?: return null
                resolveAlias(child)
            }
            else -> null
        }
    }

    /**
     * Resolve a dotted name path (e.g., "A.B.C.E") to a symbol by walking the namespace chain.
     */
    private fun resolveNamePath(path: String, result: BinderResult): Symbol? {
        val parts = path.split(".")
        // First look in file-level locals, then globals
        var current = result.locals[parts[0]] ?: globals[parts[0]]
        // If not found at file level, search all namespace scopes across all files
        if (current == null && parts.size > 1) {
            current = findSymbolInAllNamespaceScopes(parts[0]) ?: return null
        }
        if (current == null) return null
        for (i in 1 until parts.size) {
            current = resolveAlias(current!!)
            current = current.exports?.get(parts[i]) ?: return null
        }
        return current
    }

    /**
     * Search all namespace export scopes in all binder results for a symbol with the given name.
     * Used when a name is only in a namespace scope (e.g., import alias inside a namespace body).
     */
    private fun findSymbolInAllNamespaceScopes(name: String): Symbol? {
        for (br in binderResults) {
            val found = findSymbolInExports(name, br.locals)
            if (found != null) return found
        }
        return null
    }

    private fun findSymbolInExports(name: String, scope: SymbolTable): Symbol? {
        // Check this scope directly
        val direct = scope[name]
        if (direct != null) return direct
        // Recurse into namespace exports
        for ((_, sym) in scope) {
            if (sym.flags.hasAny(SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)) {
                val found = sym.exports?.let { findSymbolInExports(name, it) }
                if (found != null) return found
            }
        }
        return null
    }

    private fun resolveQualifiedName(qn: QualifiedName): Symbol? {
        val left = when (val l = qn.left) {
            is Identifier -> globals[l.text]
            is QualifiedName -> resolveQualifiedName(l)
            else -> null
        } ?: return null
        val resolved = resolveAlias(left)
        return resolved.exports?.get(qn.right.text)
    }

    /**
     * Simple module specifier resolution: strip leading `./` and append `.ts` / try `.ts`.
     * This is a simplified version for the test suite where module specifiers
     * are relative paths within the same test compilation unit.
     * Also supports baseUrl-relative non-relative specifiers (e.g., "defs/cc" with baseUrl "/proj").
     */
    private fun resolveModuleSpecifier(specifier: String, contextNode: Node? = null): String? {
        val isRelative = specifier.startsWith("./") || specifier.startsWith("../")
        val baseName = specifier.removePrefix("./").removePrefix("../")
        // Try exact match first, then with extensions
        val candidates = mutableListOf(
            baseName,
            "$baseName.ts",
            "$baseName.tsx",
            "./$baseName",
            "./$baseName.ts",
            "./$baseName.tsx",
        )
        // Only try .d.ts for relative specifiers (./X or ../X) to avoid matching ambient module
        // declarations in non-relative imports like "foo" → "foo.d.ts" (which may have augmentations
        // from other files that we can't account for).
        if (isRelative) {
            candidates.add("$baseName.d.ts")
            candidates.add("./$baseName.d.ts")
        }
        // For non-relative specifiers, also try baseUrl-prefixed paths
        if (!isRelative && options.baseUrl != null) {
            val baseUrl = options.baseUrl.trimEnd('/')
            candidates.add("$baseUrl/$baseName")
            candidates.add("$baseUrl/$baseName.ts")
            candidates.add("$baseUrl/$baseName.tsx")
        }
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        // Try matching by base filename (strips common path prefix)
        for (fileName in fileResults.keys) {
            // Only strip .d.ts for relative specifiers (./X); skip .d.ts files for non-relative
            val fileBase = if (isRelative) {
                fileName.removePrefix("./").removeSuffix(".d.ts").removeSuffix(".ts").removeSuffix(".tsx")
            } else {
                fileName.removePrefix("./").removeSuffix(".ts").removeSuffix(".tsx")
            }
            if (fileBase == baseName) return fileName
            // For non-relative specifiers: check if file ends with /baseName
            if (!isRelative && (fileBase.endsWith("/$baseName") || fileBase == baseName)) return fileName
            // For relative specifiers in flat-directory absolute-path test layouts (e.g. @Filename: /foo.ts):
            // fileBase = "/foo", baseName = "foo" → fileBase == "/$baseName"
            if (isRelative && fileBase == "/$baseName") return fileName
        }
        return null
    }

    /**
     * Resolve a module specifier relative to the given context file's directory.
     * For `folder/bar.ts` importing `./foo`, resolves to `folder/foo.ts`.
     * Falls back to [resolveModuleSpecifier] if directory-relative resolution fails.
     */
    private fun resolveModuleSpecifierRelative(specifier: String, contextFileName: String): String? {
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) {
            // Non-relative: use normal resolution
            return resolveModuleSpecifier(specifier)
        }
        // Get directory of the context file
        val dir = contextFileName.substringBeforeLast('/', "")
        val resolved = if (dir.isEmpty()) specifier else "$dir/${specifier.removePrefix("./")}"
        // Normalize `..` segments
        val normalized = normalizePath(resolved)
        val candidates = listOf(
            normalized,
            "$normalized.ts",
            "$normalized.tsx",
            "$normalized.d.ts",
        )
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        // Also strip leading "./" if present for lookup
        val candidatesNoPrefix = candidates.map { it.removePrefix("./") }
        for (candidate in candidatesNoPrefix) {
            if (candidate in fileResults) return candidate
        }
        return resolveModuleSpecifier(specifier)
    }

    /**
     * Resolve a relative module specifier strictly relative to the context file's directory,
     * WITHOUT falling back to global (non-directory-aware) resolution.
     * Used for TS2307/TS2792 checks where directory context must be respected.
     */
    private fun resolveModuleSpecifierStrictRelative(specifier: String, contextFileName: String): String? {
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) return null
        val dir = contextFileName.substringBeforeLast('/', "")
        val basePath = if (dir.isEmpty()) specifier else "$dir/${specifier.removePrefix("./")}"
        val normalized = normalizePath(basePath)
        // Strip .js/.jsx extensions to allow TypeScript to resolve .ts/.tsx instead
        val withoutJs = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            else -> null
        }
        val candidates = buildList {
            add(normalized)
            add("$normalized.ts")
            add("$normalized.tsx")
            add("$normalized.d.ts")
            if (withoutJs != null) {
                add(withoutJs)
                add("$withoutJs.ts")
                add("$withoutJs.tsx")
                add("$withoutJs.d.ts")
            }
            add(normalized.removePrefix("./"))
            add("${normalized.removePrefix("./")}.ts")
            add("${normalized.removePrefix("./")}.tsx")
        }
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        return null
    }

    /** Normalize a path by resolving `..` and `.` segments. */
    private fun normalizePath(path: String): String {
        val parts = path.split('/')
        val result = mutableListOf<String>()
        for (part in parts) {
            when (part) {
                "." -> {}
                ".." -> if (result.isNotEmpty() && result.last() != "..") result.removeLast() else result.add(part)
                else -> result.add(part)
            }
        }
        return result.joinToString("/")
    }

    // -----------------------------------------------------------------------
    // Unused declaration checking (TS6133/TS6196)
    // -----------------------------------------------------------------------

    /**
     * Tracks declarations and references within a scope for unused checking.
     */
    private class UnusedScope {
        /** All declarations in this scope: name → list of (declaration node, name node, kind). */
        val declarations = mutableListOf<UnusedDecl>()
        /** Names referenced in this scope or any nested scope. */
        val referencedNames = mutableSetOf<String>()
    }

    private data class UnusedDecl(
        val name: String,
        val nameNode: Node,       // Node whose pos gives the error position
        val declNode: Node,       // The full declaration node
        val spanLength: Int = 0,  // Explicit squiggle length (0 = use name.length)
        val isExported: Boolean,
        val isParameter: Boolean,
        val isTypeOnly: Boolean,  // interface, type alias
        val stmtIndex: Int = -1,  // index in parent statement list (for self-reference detection)
        val parentVarStmt: VariableStatement? = null, // parent statement for TS6199 grouping
        val parentBindingPattern: Node? = null, // parent ObjectBindingPattern/ArrayBindingPattern for TS6198 grouping
        val bindingElementCount: Int = 0, // total binding elements in parentBindingPattern
        val parentImportDecl: ImportDeclaration? = null, // parent import for TS6192 grouping
    )

    /**
     * Check for parameter properties declared in constructors but never accessed as `this.prop`.
     * Emits TS6138: "Property 'X' is declared but its value is never read."
     */
    private fun checkUnusedParameterProperties() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ClassDeclaration) checkUnusedParamPropsInClass(stmt, source, fileName)
            }
        }
    }

    private fun checkUnusedParamPropsInClass(classDecl: ClassDeclaration, source: String, fileName: String) {
        // Find the constructor
        val ctor = classDecl.members.filterIsInstance<Constructor>().firstOrNull() ?: return
        // Collect parameter properties (constructor params with access modifiers)
        val paramProps = ctor.parameters.filter { param ->
            param.modifiers.any { isParameterPropertyModifier(it) }
        }
        if (paramProps.isEmpty()) return

        // Collect names of parameter properties
        val paramPropNames = paramProps.mapNotNull { (it.name as? Identifier)?.text }.toSet()
        if (paramPropNames.isEmpty()) return

        // Find all `this.propName` accesses in ALL class members (including constructor body)
        val accessedViaThis = mutableSetOf<String>()
        for (member in classDecl.members) {
            when (member) {
                is MethodDeclaration -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is Constructor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is GetAccessor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is SetAccessor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is PropertyDeclaration -> member.initializer?.let { collectThisAccessInExpr(it, accessedViaThis) }
                else -> {}
            }
        }

        // Emit TS6138 for parameter properties never accessed as this.prop
        for (param in paramProps) {
            val name = param.name as? Identifier ?: continue
            val propName = name.text
            if (propName.isEmpty()) continue
            if (propName in accessedViaThis) continue
            // Never accessed as this.propName → TS6138
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6138,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = propName.length,
            ))
        }
    }

    private fun collectThisPropertyAccesses(statements: List<Statement>, result: MutableSet<String>) {
        for (stmt in statements) {
            when (stmt) {
                is ExpressionStatement -> collectThisAccessInExpr(stmt.expression, result)
                is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectThisAccessInExpr(it, result) }
                }
                is ReturnStatement -> stmt.expression?.let { collectThisAccessInExpr(it, result) }
                is IfStatement -> {
                    collectThisAccessInExpr(stmt.expression, result)
                    collectThisPropertyAccesses(listOf(stmt.thenStatement), result)
                    stmt.elseStatement?.let { collectThisPropertyAccesses(listOf(it), result) }
                }
                is Block -> collectThisPropertyAccesses(stmt.statements, result)
                is ForStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                        it.initializer?.let { init -> collectThisAccessInExpr(init, result) }
                    }
                    stmt.condition?.let { collectThisAccessInExpr(it, result) }
                    stmt.incrementor?.let { collectThisAccessInExpr(it, result) }
                    collectThisPropertyAccesses(listOf(stmt.statement), result)
                }
                is WhileStatement -> {
                    collectThisAccessInExpr(stmt.expression, result)
                    collectThisPropertyAccesses(listOf(stmt.statement), result)
                }
                else -> {}
            }
        }
    }

    private fun collectThisAccessInExpr(expr: Expression, result: MutableSet<String>) {
        when (expr) {
            is PropertyAccessExpression -> {
                val obj = expr.expression
                if (obj is Identifier && obj.text == "this") {
                    // this.propName — collect the property name
                    result.add(expr.name.text)
                } else {
                    collectThisAccessInExpr(obj, result)
                }
            }
            is CallExpression -> {
                collectThisAccessInExpr(expr.expression, result)
                expr.arguments.forEach { collectThisAccessInExpr(it, result) }
            }
            is BinaryExpression -> {
                collectThisAccessInExpr(expr.left, result)
                collectThisAccessInExpr(expr.right, result)
            }
            is NewExpression -> {
                collectThisAccessInExpr(expr.expression, result)
                expr.arguments?.forEach { collectThisAccessInExpr(it, result) }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> collectThisPropertyAccesses(body.statements, result)
                is Expression -> collectThisAccessInExpr(body, result)
                else -> {}
            }
            is FunctionExpression -> collectThisPropertyAccesses(expr.body.statements, result)
            is ParenthesizedExpression -> collectThisAccessInExpr(expr.expression, result)
            else -> {}
        }
    }

    private fun checkUnusedDeclarations() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val isModule = isModuleFile(result.sourceFile.statements)
            checkUnusedInStatements(
                result.sourceFile.statements,
                source,
                result.sourceFile.fileName,
                isTopLevel = true,
                isModuleScope = isModule,
            )
        }
    }

    /**
     * Check if a file is a module (has import/export statements).
     * Non-module files' top-level declarations are global and not checked for unused.
     */
    private fun isModuleFile(statements: List<Statement>): Boolean {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return true
                is ImportEqualsDeclaration -> return true
                is ExportDeclaration -> return true
                is ExportAssignment -> return true
                // VariableStatement is not a Declaration but can have export modifier
                is VariableStatement -> if (ModifierFlag.Export in stmt.modifiers) return true
                else -> {
                    if (stmt is Declaration) {
                        val modifiers = when (stmt) {
                            is FunctionDeclaration -> stmt.modifiers
                            is ClassDeclaration -> stmt.modifiers
                            is EnumDeclaration -> stmt.modifiers
                            is InterfaceDeclaration -> stmt.modifiers
                            is TypeAliasDeclaration -> stmt.modifiers
                            is ModuleDeclaration -> stmt.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Export in modifiers) return true
                    }
                }
            }
        }
        return false
    }

    /**
     * Check if a file is an ES module (has actual ES import/export statements).
     * Unlike [isModuleFile], this does NOT count `import x = namespace` declarations
     * as module-making — those are legacy TypeScript namespace aliases.
     * Used for TS2694 namespace name qualification in module files.
     */
    private fun isEsModuleFile(statements: List<Statement>): Boolean {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return true   // import { x } from "..."
                // ImportEqualsDeclaration: import x = namespace is NOT ES module
                is ExportDeclaration -> return true   // export { x } or export * from
                is ExportAssignment -> return true    // export default or export =
                else -> {
                    if (stmt is Declaration) {
                        val modifiers = when (stmt) {
                            is FunctionDeclaration -> stmt.modifiers
                            is ClassDeclaration -> stmt.modifiers
                            is VariableStatement -> stmt.modifiers
                            is EnumDeclaration -> stmt.modifiers
                            is InterfaceDeclaration -> stmt.modifiers
                            is TypeAliasDeclaration -> stmt.modifiers
                            is ModuleDeclaration -> stmt.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Export in modifiers) return true
                    }
                }
            }
        }
        return false
    }

    private fun checkUnusedInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isTopLevel: Boolean,
        isModuleScope: Boolean = false,
    ) {
        // Skip file-level declarations in non-module files (they're global)
        if (isTopLevel && !isModuleScope) {
            // Still recurse into nested scopes (namespace bodies, function bodies)
            for (stmt in statements) {
                checkUnusedInNestedScopes(stmt, source, fileName, siblingStatements = statements)
            }
            return
        }

        val scope = UnusedScope()

        // 1. Collect declarations (with statement index for self-reference detection)
        for ((idx, stmt) in statements.withIndex()) {
            collectUnusedDeclarations(stmt, scope, isTopLevel, stmtIndex = idx)
        }

        // 2. Collect references per statement (for self-reference detection)
        val refsPerStmt = Array(statements.size) { mutableSetOf<String>() }
        for ((idx, stmt) in statements.withIndex()) {
            val stmtScope = UnusedScope()
            collectUnusedReferences(stmt, stmtScope)
            refsPerStmt[idx] = stmtScope.referencedNames
            scope.referencedNames.addAll(stmtScope.referencedNames)
        }

        // 3. Report unreferenced declarations
        // A declaration is considered unused if:
        // - It's not referenced at all, OR
        // - It's only referenced from within its own declaration (self-reference)
        val unusedDecls = mutableListOf<UnusedDecl>()
        for (decl in scope.declarations) {
            val isExternallyReferenced = if (decl.stmtIndex >= 0) {
                refsPerStmt.withIndex().any { (idx, refs) ->
                    idx != decl.stmtIndex && decl.name in refs
                }
            } else {
                decl.name in scope.referencedNames
            }
            if (isExternallyReferenced) continue
            // Shorthand underscore elements in ObjectBindingPattern still contribute to TS6198
            val isShorthandUnderscore = decl.name.startsWith("_") &&
                decl.parentBindingPattern is ObjectBindingPattern &&
                (decl.declNode as? BindingElement)?.propertyName == null
            if (decl.name.startsWith("_") && !isShorthandUnderscore) continue
            if (decl.isExported) continue

            if (decl.isParameter) {
                if (!options.noUnusedParameters) continue
            } else {
                if (!options.noUnusedLocals) continue
            }

            unusedDecls.add(decl)
        }

        // Check for TS6199: if ALL declarations from a VariableStatement are unused,
        // emit a single "All variables are unused" instead of individual TS6133
        val ts6199Stmts = mutableSetOf<VariableStatement>()
        val declsByVarStmt = unusedDecls.filter { it.parentVarStmt != null }
            .groupBy { it.parentVarStmt!! }
        for ((varStmt, decls) in declsByVarStmt) {
            val totalDeclCount = varStmt.declarationList.declarations.size
            if (decls.size == totalDeclCount && totalDeclCount > 1) {
                ts6199Stmts.add(varStmt)
                // Emit TS6199 for the entire statement
                // Span covers from `var` keyword to the end of the statement line (including `;`)
                val stmtStart = varStmt.pos
                val lineEnd = source.indexOf('\n', stmtStart).let { if (it < 0) source.length else it }
                val spanLength = source.substring(stmtStart, lineEnd).trimEnd().length
                val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                diagnostics.add(Diagnostic(
                    message = "All variables are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6199,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = stmtStart,
                    length = spanLength,
                ))
            }
        }

        // Check for TS6198: if ALL elements from a destructuring pattern are unused,
        // emit a single "All destructured elements are unused" instead of individual TS6133
        // TS6198 only fires for ObjectBindingPattern, not ArrayBindingPattern
        val ts6198Patterns = mutableSetOf<Node>()
        val declsByPattern = unusedDecls.filter { it.parentBindingPattern is ObjectBindingPattern }
            .groupBy { it.parentBindingPattern!! }
        for ((pattern, decls) in declsByPattern) {
            val totalCount = decls.first().bindingElementCount
            // Shorthand underscore-prefixed elements (e.g., `{ _a1 }` not `{ a: _a1 }`)
            // are already included in `decls` (not skipped at the filter above), so no
            // separate counting is needed — just compare decls.size with totalCount.
            if (decls.size == totalCount && totalCount > 1) {
                ts6198Patterns.add(pattern)
                val patStart = pattern.pos
                val spanLength = computeBindingPatternSpan(source, patStart, pattern)
                val (line, character) = getLineAndCharacterOfPosition(source, patStart)
                diagnostics.add(Diagnostic(
                    message = "All destructured elements are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6198,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = patStart,
                    length = spanLength,
                ))
            }
        }

        // Check for TS6192: if ALL bindings from an import declaration are unused,
        // emit a single "All imports in import declaration are unused." instead of individual TS6133.
        val ts6192Imports = mutableSetOf<ImportDeclaration>()
        val declsByImport = unusedDecls.filter { it.parentImportDecl != null }
            .groupBy { it.parentImportDecl!! }
        for ((importDecl, decls) in declsByImport) {
            val clause = importDecl.importClause ?: continue
            // Count total non-type-only bindings
            var totalBindings = 0
            if (clause.name != null) totalBindings++ // default import
            when (val nb = clause.namedBindings) {
                is NamedImports -> totalBindings += nb.elements.count { !it.isTypeOnly }
                is NamespaceImport -> totalBindings++
                else -> {}
            }
            if (totalBindings > 1 && decls.size == totalBindings) {
                ts6192Imports.add(importDecl)
                // Emit TS6192 for the entire import statement
                val stmtStart = importDecl.pos
                val stmtLineEnd = source.indexOf('\n', stmtStart).let { if (it < 0) source.length else it }
                val spanLength = source.substring(stmtStart, stmtLineEnd).trimEnd().length
                val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                diagnostics.add(Diagnostic(
                    message = "All imports in import declaration are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6192,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = stmtStart,
                    length = spanLength,
                ))
            }
        }

        for (decl in unusedDecls) {
            // Skip declarations already handled by TS6199
            if (decl.parentVarStmt != null && decl.parentVarStmt in ts6199Stmts) continue
            // Skip declarations already handled by TS6198
            if (decl.parentBindingPattern != null && decl.parentBindingPattern in ts6198Patterns) continue
            // Skip declarations already handled by TS6192
            if (decl.parentImportDecl != null && decl.parentImportDecl in ts6192Imports) continue
            // Underscore-prefixed names that made it through for TS6198 grouping: skip individual TS6133
            if (decl.name.startsWith("_")) continue

            val nameNode = decl.nameNode
            // For single-element destructuring, use the pattern span instead of the name
            val usePatternSpan = decl.parentBindingPattern is ObjectBindingPattern && decl.bindingElementCount == 1
            // For import specifiers with aliases (e.g. `test2 as t2`), point to the local name `t2`
            val start = when {
                usePatternSpan -> decl.parentBindingPattern!!.pos
                nameNode is ImportSpecifier && nameNode.propertyName != null -> nameNode.name.pos
                else -> nameNode.pos
            }
            // Compute squiggle length: for imports using whole-statement node,
            // measure the line text; otherwise use identifier text length
            val length = when {
                usePatternSpan -> computeBindingPatternSpan(source, start, decl.parentBindingPattern!!)
                decl.spanLength > 0 -> decl.spanLength
                nameNode is ImportDeclaration -> {
                    // Squiggle covers the import statement up to semicolon (excluding comments)
                    val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
                    var endPos = start
                    var idx = start
                    while (idx < lineEnd) {
                        val ch = source[idx]
                        if (ch == ';') { endPos = idx + 1; break }
                        if (ch == '/' && idx + 1 < lineEnd && (source[idx + 1] == '/' || source[idx + 1] == '*')) {
                            while (endPos > start && source[endPos - 1].let { it == ' ' || it == '\t' }) endPos--
                            break
                        }
                        endPos = idx + 1
                        idx++
                    }
                    if (endPos <= start) endPos = start + 1
                    endPos - start
                }
                else -> decl.name.length
            }
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            // Classes, interfaces, type aliases, enums use TS6196 "declared but never used"
            // Variables, functions, parameters use TS6133 "declared but its value is never read"
            val isTypeDecl = decl.declNode is ClassDeclaration || decl.declNode is InterfaceDeclaration
                    || decl.declNode is TypeAliasDeclaration || decl.declNode is EnumDeclaration
            val code = if (isTypeDecl) 6196 else 6133
            val message = if (isTypeDecl) {
                "'${decl.name}' is declared but never used."
            } else {
                "'${decl.name}' is declared but its value is never read."
            }

            diagnostics.add(Diagnostic(
                message = message,
                category = DiagnosticCategory.Error,
                code = code,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }

        // 4. Recurse into nested scopes (function bodies, class bodies, etc.)
        for (stmt in statements) {
            checkUnusedInNestedScopes(stmt, source, fileName, siblingStatements = statements)
        }
    }

    private fun collectUnusedDeclarations(
        stmt: Statement,
        scope: UnusedScope,
        isTopLevel: Boolean,
        stmtIndex: Int = -1,
    ) {
        when (stmt) {
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                for (decl in stmt.declarationList.declarations) {
                    collectVarDeclNames(decl.name, decl, isExported, scope, stmtIndex, parentVarStmt = stmt)
                }
            }
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val name = stmt.name ?: return
                val isExported = ModifierFlag.Export in stmt.modifiers ||
                    ModifierFlag.Default in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val name = stmt.name ?: return
                val isExported = ModifierFlag.Export in stmt.modifiers ||
                    ModifierFlag.Default in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is InterfaceDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = true,
                    stmtIndex = stmtIndex,
                ))
            }
            is TypeAliasDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = true,
                    stmtIndex = stmtIndex,
                ))
            }
            is EnumDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameNode = stmt.name
                if (nameNode is Identifier) {
                    val isExported = ModifierFlag.Export in stmt.modifiers
                    scope.declarations.add(UnusedDecl(
                        name = nameNode.text,
                        nameNode = nameNode,
                        declNode = stmt,
                        isExported = isExported,
                        isParameter = false,
                        isTypeOnly = false,
                        stmtIndex = stmtIndex,
                    ))
                }
            }
            is ImportDeclaration -> {
                if (stmt.importClause?.isTypeOnly == true) return
                val clause = stmt.importClause ?: return
                val bindings = clause.namedBindings
                // Count total non-type-only bindings to determine nameNode strategy:
                // - 1 binding: use whole import statement for TS6133 (whole-statement squiggle)
                // - 2+ bindings: use individual binding names for TS6133 (per-binding squiggle)
                //   (when all unused, TS6192 will replace individual TS6133s)
                var totalBindingCount = 0
                if (clause.name != null) totalBindingCount++
                when (bindings) {
                    is NamedImports -> totalBindingCount += bindings.elements.count { !it.isTypeOnly }
                    is NamespaceImport -> totalBindingCount++
                    else -> {}
                }
                val useStatementAsNameNode = totalBindingCount <= 1
                when (bindings) {
                    is NamedImports -> {
                        for (spec in bindings.elements) {
                            if (spec.isTypeOnly) continue
                            scope.declarations.add(UnusedDecl(
                                name = spec.name.text,
                                nameNode = if (useStatementAsNameNode) stmt else spec,
                                declNode = stmt,
                                isExported = false,
                                isParameter = false,
                                isTypeOnly = false,
                                stmtIndex = stmtIndex,
                                parentImportDecl = stmt,
                            ))
                        }
                    }
                    is NamespaceImport -> {
                        scope.declarations.add(UnusedDecl(
                            name = bindings.name.text,
                            nameNode = if (useStatementAsNameNode) stmt else bindings.name,
                            declNode = stmt,
                            isExported = false,
                            isParameter = false,
                            isTypeOnly = false,
                            stmtIndex = stmtIndex,
                            parentImportDecl = stmt,
                        ))
                    }
                    else -> {}
                }
                // Default import
                if (clause.name != null) {
                    scope.declarations.add(UnusedDecl(
                        name = clause.name.text,
                        nameNode = if (useStatementAsNameNode) stmt else clause.name,
                        declNode = stmt,
                        isExported = false,
                        isParameter = false,
                        isTypeOnly = false,
                        stmtIndex = stmtIndex,
                        parentImportDecl = stmt,
                    ))
                }
            }
            is ImportEqualsDeclaration -> {
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            else -> {}
        }
    }

    private fun collectVarDeclNames(
        name: Expression,
        declNode: Node,
        isExported: Boolean,
        scope: UnusedScope,
        stmtIndex: Int = -1,
        parentVarStmt: VariableStatement? = null,
        parentBindingPattern: Node? = null,
        bindingElementCount: Int = 0,
    ) {
        when (name) {
            is Identifier -> {
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = declNode,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                    parentVarStmt = parentVarStmt,
                    parentBindingPattern = parentBindingPattern,
                    bindingElementCount = bindingElementCount,
                ))
            }
            is ObjectBindingPattern -> {
                // When a rest element exists, non-rest siblings are intentional
                // extractions and should not be flagged as unused
                val hasRest = name.elements.any { it.dotDotDotToken }
                val count = if (hasRest) name.elements.count { it.dotDotDotToken } else name.elements.size
                for (element in name.elements) {
                    if (hasRest && !element.dotDotDotToken) continue // skip extraction vars
                    // Rest elements get identifier span (no parentBindingPattern), non-rest get pattern span
                    collectVarDeclNames(element.name, element, isExported, scope, stmtIndex, parentVarStmt,
                        parentBindingPattern = if (element.dotDotDotToken) null else name,
                        bindingElementCount = if (element.dotDotDotToken) 0 else count)
                }
            }
            is ArrayBindingPattern -> {
                val hasRest = name.elements.any { it is BindingElement && it.dotDotDotToken }
                val count = if (hasRest) name.elements.count { it is BindingElement && it.dotDotDotToken }
                    else name.elements.count { it is BindingElement }
                for (element in name.elements) {
                    if (element is BindingElement) {
                        if (hasRest && !element.dotDotDotToken) continue // skip extraction vars
                        collectVarDeclNames(element.name, element, isExported, scope, stmtIndex, parentVarStmt,
                            parentBindingPattern = name, bindingElementCount = count)
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Collect destructuring parameter binding element names for unused checking.
     * For `([a])`, collects `a` with span covering the binding pattern.
     */
    private fun collectDestructuringParamNames(
        pattern: Expression,
        param: Parameter,
        scope: UnusedScope,
    ) {
        // For destructuring parameters, the squiggle behavior depends on how many elements
        // are unused: single-element → pattern span, all unused → TS6198 pattern span,
        // some unused → individual name span.
        when (pattern) {
            is ArrayBindingPattern -> {
                val count = pattern.elements.count { it is BindingElement && !it.dotDotDotToken }
                for (element in pattern.elements) {
                    if (element is BindingElement) {
                        val name = element.name
                        if (name is Identifier) {
                            scope.declarations.add(UnusedDecl(
                                name = name.text,
                                nameNode = name,
                                declNode = param,
                                isExported = false,
                                isParameter = true,
                                isTypeOnly = false,
                                parentBindingPattern = pattern,
                                bindingElementCount = count,
                            ))
                        }
                    }
                }
            }
            is ObjectBindingPattern -> {
                val count = pattern.elements.count { !it.dotDotDotToken }
                for (element in pattern.elements) {
                    val name = element.name
                    if (name is Identifier) {
                        scope.declarations.add(UnusedDecl(
                            name = name.text,
                            nameNode = name,
                            declNode = param,
                            isExported = false,
                            isParameter = true,
                            isTypeOnly = false,
                            parentBindingPattern = pattern,
                            bindingElementCount = count,
                        ))
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Collect all name references from a statement (including nested expressions).
     * This is used for unused declaration checking — it marks names as "referenced"
     * when they appear in value or type positions.
     */
    private fun collectUnusedReferences(stmt: Statement, scope: UnusedScope) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectRefsFromExpr(it, scope) }
                    decl.type?.let { collectRefsFromType(it, scope) }
                }
            }
            is ExpressionStatement -> collectRefsFromExpr(stmt.expression, scope)
            is ReturnStatement -> stmt.expression?.let { collectRefsFromExpr(it, scope) }
            is IfStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.thenStatement, scope)
                stmt.elseStatement?.let { collectUnusedReferences(it, scope) }
            }
            is Block -> stmt.statements.forEach { collectUnusedReferences(it, scope) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { collectRefsFromExpr(it, scope) }
                        }
                    }
                    is Expression -> collectRefsFromExpr(init, scope)
                    else -> {}
                }
                stmt.condition?.let { collectRefsFromExpr(it, scope) }
                stmt.incrementor?.let { collectRefsFromExpr(it, scope) }
                collectUnusedReferences(stmt.statement, scope)
            }
            is ForInStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is ForOfStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is WhileStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is DoStatement -> {
                collectUnusedReferences(stmt.statement, scope)
                collectRefsFromExpr(stmt.expression, scope)
            }
            is SwitchStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            collectRefsFromExpr(clause.expression, scope)
                            clause.statements.forEach { collectUnusedReferences(it, scope) }
                        }
                        is DefaultClause -> {
                            clause.statements.forEach { collectUnusedReferences(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { collectRefsFromExpr(it, scope) }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectUnusedReferences(it, scope) }
                stmt.catchClause?.block?.statements?.forEach { collectUnusedReferences(it, scope) }
                stmt.finallyBlock?.statements?.forEach { collectUnusedReferences(it, scope) }
            }
            is LabeledStatement -> collectUnusedReferences(stmt.statement, scope)
            is WithStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is FunctionDeclaration -> {
                // References inside function bodies count as usage of outer scope names
                // Type parameters shadow outer names, so collect into inner scope first
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.body?.statements?.forEach { collectUnusedReferences(it, innerScope) }
                for (param in stmt.parameters) {
                    param.initializer?.let { collectRefsFromExpr(it, innerScope) }
                    param.type?.let { collectRefsFromType(it, innerScope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, innerScope) }
                }
                stmt.type?.let { collectRefsFromType(it, innerScope) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is ClassDeclaration -> {
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, innerScope)
                        type.typeArguments?.forEach { collectRefsFromType(it, innerScope) }
                    }
                }
                stmt.decorators?.forEach { collectRefsFromExpr(it.expression, innerScope) }
                for (member in stmt.members) {
                    collectRefsFromClassElement(member, innerScope)
                }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is InterfaceDeclaration -> {
                // Collect references from extends clause and members
                // Type parameters shadow outer names
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, innerScope)
                        type.typeArguments?.forEach { collectRefsFromType(it, innerScope) }
                    }
                }
                for (member in stmt.members) {
                    collectRefsFromClassElement(member, innerScope)
                }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is TypeAliasDeclaration -> {
                // Type parameters shadow outer names
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.type.let { collectRefsFromType(it, innerScope) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is EnumDeclaration -> {
                for (member in stmt.members) {
                    member.initializer?.let { collectRefsFromExpr(it, scope) }
                }
            }
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> body.statements.forEach { collectUnusedReferences(it, scope) }
                    is ModuleDeclaration -> collectUnusedReferences(body, scope)
                    else -> {}
                }
            }
            is ExportDeclaration -> {
                // export { X } — X is a reference
                when (val clause = stmt.exportClause) {
                    is NamedExports -> {
                        for (spec in clause.elements) {
                            val name = spec.propertyName?.text ?: spec.name.text
                            scope.referencedNames.add(name)
                        }
                    }
                    else -> {}
                }
            }
            is ExportAssignment -> {
                collectRefsFromExpr(stmt.expression, scope)
            }
            else -> {}
        }
    }

    private fun collectRefsFromExpr(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is Identifier -> scope.referencedNames.add(expr.text)
            is PropertyAccessExpression -> {
                collectRefsFromExpr(expr.expression, scope)
            }
            is ElementAccessExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromExpr(expr.argumentExpression, scope)
            }
            is CallExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                expr.arguments.forEach { collectRefsFromExpr(it, scope) }
                expr.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is NewExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                expr.arguments?.forEach { collectRefsFromExpr(it, scope) }
                expr.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Simple assignment: left side is write-only (not a read)
                    collectRefsFromExpr(expr.right, scope)
                    collectWriteTargetRefs(expr.left, scope)
                } else {
                    // Non-assignment or compound assignment: iterative traversal
                    var current: Expression = expr
                    while (current is BinaryExpression) {
                        collectRefsFromExpr(current.right, scope)
                        current = current.left
                    }
                    collectRefsFromExpr(current, scope)
                }
            }
            is ConditionalExpression -> {
                collectRefsFromExpr(expr.condition, scope)
                collectRefsFromExpr(expr.whenTrue, scope)
                collectRefsFromExpr(expr.whenFalse, scope)
            }
            is PrefixUnaryExpression -> collectRefsFromExpr(expr.operand, scope)
            is PostfixUnaryExpression -> collectRefsFromExpr(expr.operand, scope)
            is ParenthesizedExpression -> collectRefsFromExpr(expr.expression, scope)
            is ArrayLiteralExpression -> {
                expr.elements.forEach { collectRefsFromExpr(it, scope) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            collectRefsFromExpr(prop.initializer, scope)
                            val propName = prop.name
                            if (propName is ComputedPropertyName) {
                                collectRefsFromExpr(propName.expression, scope)
                            }
                        }
                        is ShorthandPropertyAssignment -> {
                            scope.referencedNames.add(prop.name.text)
                        }
                        is SpreadAssignment -> collectRefsFromExpr(prop.expression, scope)
                        is MethodDeclaration -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                            prop.parameters.forEach { param ->
                                param.initializer?.let { collectRefsFromExpr(it, scope) }
                            }
                        }
                        is GetAccessor -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                        }
                        is SetAccessor -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> body.statements.forEach { collectUnusedReferences(it, scope) }
                    is Expression -> collectRefsFromExpr(body, scope)
                    else -> {}
                }
                expr.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                expr.type?.let { collectRefsFromType(it, scope) }
            }
            is FunctionExpression -> {
                expr.body.statements.forEach { collectUnusedReferences(it, scope) }
                expr.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                expr.type?.let { collectRefsFromType(it, scope) }
            }
            is ClassExpression -> {
                expr.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, scope)
                        type.typeArguments?.forEach { collectRefsFromType(it, scope) }
                    }
                }
                for (member in expr.members) {
                    collectRefsFromClassElement(member, scope)
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is TaggedTemplateExpression -> {
                collectRefsFromExpr(expr.tag, scope)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        template.templateSpans.forEach { collectRefsFromExpr(it.expression, scope) }
                    }
                    else -> {}
                }
            }
            is SpreadElement -> collectRefsFromExpr(expr.expression, scope)
            is AwaitExpression -> collectRefsFromExpr(expr.expression, scope)
            is YieldExpression -> expr.expression?.let { collectRefsFromExpr(it, scope) }
            is DeleteExpression -> collectRefsFromExpr(expr.expression, scope)
            is TypeOfExpression -> collectRefsFromExpr(expr.expression, scope)
            is VoidExpression -> collectRefsFromExpr(expr.expression, scope)
            is AsExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is SatisfiesExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is NonNullExpression -> collectRefsFromExpr(expr.expression, scope)
            is TypeAssertionExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is CommaListExpression -> expr.elements.forEach { collectRefsFromExpr(it, scope) }
            is JsxElement -> {
                collectRefsFromExpr(expr.openingElement.tagName, scope)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { collectRefsFromExpr(it, scope) }
                    } else if (child is Expression) {
                        collectRefsFromExpr(child, scope)
                    }
                }
            }
            is JsxSelfClosingElement -> {
                collectRefsFromExpr(expr.tagName, scope)
                for (attr in expr.attributes) {
                    when (attr) {
                        is JsxAttribute -> {
                            val v = attr.value
                            if (v is JsxExpressionContainer) {
                                v.expression?.let { collectRefsFromExpr(it, scope) }
                            } else if (v is Expression) {
                                collectRefsFromExpr(v, scope)
                            }
                        }
                        is JsxSpreadAttribute -> collectRefsFromExpr(attr.expression, scope)
                        else -> {}
                    }
                }
            }
            is JsxFragment -> {
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { collectRefsFromExpr(it, scope) }
                    } else if (child is Expression) {
                        collectRefsFromExpr(child, scope)
                    }
                }
            }
            else -> {} // literals, omitted expressions, binding patterns, etc.
        }
    }

    /**
     * For write-only targets (left side of `=`), only collect references from
     * property access bases and element access arguments, not the target identifier itself.
     */
    private fun collectWriteTargetRefs(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is Identifier -> {} // Don't add — this is a write target, not a read
            is PropertyAccessExpression -> {
                // obj.prop = value — obj IS read
                collectRefsFromExpr(expr.expression, scope)
            }
            is ElementAccessExpression -> {
                // obj[key] = value — both obj and key are read
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromExpr(expr.argumentExpression, scope)
            }
            is ArrayLiteralExpression -> {
                // [x, y] = [1, 2] — destructuring write: elements are write targets
                for (element in expr.elements) {
                    when (element) {
                        is SpreadElement -> collectWriteTargetRefs(element.expression, scope)
                        is BinaryExpression -> {
                            // [x = default] — x is write target, default IS a read
                            if (element.operator == SyntaxKind.Equals) {
                                collectWriteTargetRefs(element.left, scope)
                                collectRefsFromExpr(element.right, scope)
                            } else {
                                collectRefsFromExpr(element, scope)
                            }
                        }
                        is OmittedExpression -> {} // skip holes
                        is Expression -> collectWriteTargetRefs(element, scope)
                        else -> {}
                    }
                }
            }
            is ObjectLiteralExpression -> {
                // { x, y } = { x: 1, y: 2 } — destructuring write: properties are write targets
                for (prop in expr.properties) {
                    when (prop) {
                        is ShorthandPropertyAssignment -> {
                            // { x } = obj — x is a write target
                            if (prop.objectAssignmentInitializer != null) {
                                // { x = default } = obj — x is write target, default IS a read
                                collectRefsFromExpr(prop.objectAssignmentInitializer!!, scope)
                            }
                            // Don't add prop.name to referencedNames
                        }
                        is PropertyAssignment -> {
                            // { key: target } = obj — key is a read (if computed), target is write
                            if (prop.name is ComputedPropertyName) {
                                collectRefsFromExpr((prop.name as ComputedPropertyName).expression, scope)
                            }
                            collectWriteTargetRefs(prop.initializer, scope)
                        }
                        is SpreadAssignment -> collectWriteTargetRefs(prop.expression, scope)
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> collectWriteTargetRefs(expr.expression, scope)
            else -> collectRefsFromExpr(expr, scope) // fallback: treat as read
        }
    }

    private fun collectRefsFromClassElement(element: ClassElement, scope: UnusedScope) {
        when (element) {
            is PropertyDeclaration -> {
                element.initializer?.let { collectRefsFromExpr(it, scope) }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is MethodDeclaration -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                element.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, scope) }
                }
            }
            is Constructor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                }
            }
            is GetAccessor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is SetAccessor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is ClassStaticBlockDeclaration -> {
                element.body.statements.forEach { collectUnusedReferences(it, scope) }
            }
            else -> {}
        }
    }

    /**
     * Collect name references from type nodes. Type references count as usage
     * for unused declaration checking — `let x: MyType` counts as using `MyType`.
     */
    private fun collectRefsFromType(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeReference -> {
                when (val name = type.typeName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        // For A.B.C, only the leftmost name is a scope reference
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
                type.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is ArrayType -> collectRefsFromType(type.elementType, scope)
            is TupleType -> type.elements.forEach { collectRefsFromType(it, scope) }
            is UnionType -> type.types.forEach { collectRefsFromType(it, scope) }
            is IntersectionType -> type.types.forEach { collectRefsFromType(it, scope) }
            is ParenthesizedType -> collectRefsFromType(type.type, scope)
            is FunctionType -> {
                type.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                collectRefsFromType(type.type, scope)
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, scope) }
                    tp.default?.let { collectRefsFromType(it, scope) }
                }
            }
            is ConstructorType -> {
                type.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                collectRefsFromType(type.type, scope)
            }
            is TypeQuery -> {
                when (val name = type.exprName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        is MethodDeclaration -> {
                            member.parameters.forEach { param ->
                                param.type?.let { collectRefsFromType(it, scope) }
                            }
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        is IndexSignature -> {
                            member.parameters.forEach { param ->
                                param.type?.let { collectRefsFromType(it, scope) }
                            }
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectRefsFromType(type.checkType, scope)
                collectRefsFromType(type.extendsType, scope)
                collectRefsFromType(type.trueType, scope)
                collectRefsFromType(type.falseType, scope)
            }
            is MappedType -> {
                type.type?.let { collectRefsFromType(it, scope) }
                type.nameType?.let { collectRefsFromType(it, scope) }
                type.typeParameter.constraint?.let { collectRefsFromType(it, scope) }
            }
            is IndexedAccessType -> {
                collectRefsFromType(type.objectType, scope)
                collectRefsFromType(type.indexType, scope)
            }
            is TypeOperator -> collectRefsFromType(type.type, scope)
            is InferType -> {} // infer T — doesn't reference existing names
            is TemplateLiteralType -> {
                type.templateSpans.forEach { span ->
                    collectRefsFromType(span.type, scope)
                }
            }
            is RestType -> collectRefsFromType(type.type, scope)
            is NamedTupleMember -> collectRefsFromType(type.type, scope)
            is OptionalType -> collectRefsFromType(type.type, scope)
            is ImportType -> {
                type.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            else -> {} // keyword types, literal types, this type, etc.
        }
    }

    /**
     * Recurse into nested scopes to check for unused declarations within them.
     */
    private fun checkUnusedInNestedScopes(stmt: Statement, source: String, fileName: String, siblingStatements: List<Statement>? = null) {
        when (stmt) {
            is FunctionDeclaration -> {
                stmt.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, stmt.parameters, source, fileName,
                        typeParameters = stmt.typeParameters,
                        returnType = stmt.type,
                    )
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    checkUnusedInClassElement(member, source, fileName)
                }
                // Check class-level type parameters
                checkUnusedClassTypeParams(stmt, source, fileName, siblingStatements)
                // Check unused private members
                checkUnusedPrivateMembers(stmt.members, source, fileName)
            }
            is InterfaceDeclaration -> {
                checkUnusedInterfaceTypeParams(stmt, source, fileName, siblingStatements)
            }
            is TypeAliasDeclaration -> {
                checkUnusedTypeAliasTypeParams(stmt, source, fileName)
            }
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> checkUnusedInStatements(
                        body.statements, source, fileName, isTopLevel = false,
                    )
                    is ModuleDeclaration -> checkUnusedInNestedScopes(
                        body, source, fileName,
                    )
                    else -> {}
                }
            }
            is VariableStatement -> {
                // Check initializer expressions for nested function-likes
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkUnusedInExpr(it, source, fileName) }
                    // Check unused type params in type annotations (ConstructorType, FunctionType, TypeLiteral)
                    decl.type?.let { checkUnusedTypeParamsInType(it, source, fileName) }
                }
            }
            is ExpressionStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let { checkUnusedInExpr(it, source, fileName) }
            }
            is Block -> checkUnusedInStatements(
                stmt.statements, source, fileName, isTopLevel = false,
            )
            is IfStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
                checkUnusedInNestedScopes(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkUnusedInNestedScopes(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        // Check for unused variables declared in the for-initializer
                        checkForStatementVariable(init, stmt, source, fileName)
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkUnusedInExpr(it, source, fileName) }
                        }
                    }
                    is Expression -> checkUnusedInExpr(init, source, fileName)
                    else -> {}
                }
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkForLoopVariable(stmt.initializer, stmt.statement, source, fileName)
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkForLoopVariable(stmt.initializer, stmt.statement, source, fileName)
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is WhileStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            is DoStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            is SwitchStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Check unused declarations within each case/default clause
                    checkUnusedInStatements(clauseStmts, source, fileName, isTopLevel = false)
                    clauseStmts.forEach { checkUnusedInNestedScopes(it, source, fileName) }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
                stmt.catchClause?.block?.statements?.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
                stmt.finallyBlock?.statements?.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
            }
            is LabeledStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            else -> {}
        }
    }

    /**
     * Check for unused declarations inside expression-level function-likes
     * (function expressions, arrow functions, class expressions).
     */
    private fun checkUnusedInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> {
                checkUnusedInFunctionLike(
                    expr.body.statements, expr.parameters, source, fileName,
                    typeParameters = expr.typeParameters,
                    returnType = expr.type,
                )
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkUnusedInFunctionLike(
                        body.statements, expr.parameters, source, fileName,
                        typeParameters = expr.typeParameters,
                        returnType = expr.type,
                    )
                    is Expression -> {
                        // Arrow with expression body — still check parameters
                        if (options.noUnusedParameters) {
                            val scope = UnusedScope()
                            for (param in expr.parameters) {
                                val name = param.name
                                if (name is Identifier && !name.text.startsWith("_")) {
                                    scope.declarations.add(UnusedDecl(
                                        name = name.text,
                                        nameNode = name,
                                        declNode = param,
                                        isExported = false,
                                        isParameter = true,
                                        isTypeOnly = false,
                                    ))
                                }
                            }
                            collectRefsFromExpr(body, scope)
                            for (decl in scope.declarations) {
                                if (decl.name in scope.referencedNames) continue
                                val start = decl.nameNode.pos
                                val length = decl.name.length
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "'${decl.name}' is declared but its value is never read.",
                                    category = DiagnosticCategory.Error,
                                    code = 6133,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                        checkUnusedInExpr(body, source, fileName)
                    }
                    else -> {}
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    checkUnusedInClassElement(member, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                    typeParameters = prop.typeParameters,
                                    returnType = prop.type,
                                )
                            }
                        }
                        is GetAccessor -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                )
                            }
                        }
                        is SetAccessor -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                )
                            }
                        }
                        is PropertyAssignment -> {
                            checkUnusedInExpr(prop.initializer, source, fileName)
                        }
                        is SpreadAssignment -> {
                            checkUnusedInExpr(prop.expression, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUnusedInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkUnusedInExpr(current, source, fileName)
            }
            is ConditionalExpression -> {
                checkUnusedInExpr(expr.condition, source, fileName)
                checkUnusedInExpr(expr.whenTrue, source, fileName)
                checkUnusedInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is NewExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is AsExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is PropertyAccessExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                checkUnusedInExpr(expr.argumentExpression, source, fileName)
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { checkUnusedInExpr(it.expression, source, fileName) }
            }
            is TaggedTemplateExpression -> {
                checkUnusedInExpr(expr.tag, source, fileName)
            }
            is AwaitExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkUnusedInExpr(it, source, fileName) }
            is SpreadElement -> checkUnusedInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkUnusedInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkUnusedInExpr(expr.operand, source, fileName)
            else -> {} // Literals, identifiers, etc. — no nested function-likes
        }
    }

    /**
     * Check for unused for-in/for-of loop variables.
     */
    /**
     * Check for unused variables declared in a C-style for-loop initializer:
     * `for(var i = 0; condition; increment) { body }`
     * Collects references from condition, incrementor, and body.
     */
    private fun checkForStatementVariable(
        declList: VariableDeclarationList,
        forStmt: ForStatement,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return
        val scope = UnusedScope()
        for (decl in declList.declarations) {
            collectVarDeclNames(decl.name, decl, isExported = false, scope)
        }
        // Collect references from condition, incrementor, and body
        forStmt.condition?.let { collectRefsFromExpr(it, scope) }
        forStmt.incrementor?.let { collectRefsFromExpr(it, scope) }
        collectUnusedReferences(forStmt.statement, scope)
        // Report unused
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            if (decl.name.startsWith("_")) continue
            val start = decl.nameNode.pos
            val length = decl.name.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun checkForLoopVariable(
        initializer: Node?,
        body: Statement,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return
        val declList = initializer as? VariableDeclarationList ?: return
        val scope = UnusedScope()
        for (decl in declList.declarations) {
            collectVarDeclNames(decl.name, decl, isExported = false, scope)
        }
        // Collect references from the body
        collectUnusedReferences(body, scope)
        // Report unused
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            if (decl.name.startsWith("_")) continue
            val start = decl.nameNode.pos
            val length = decl.name.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun checkUnusedInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
    ) {
        when (element) {
            is MethodDeclaration -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                        typeParameters = element.typeParameters,
                        returnType = element.type,
                    )
                }
            }
            is Constructor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is GetAccessor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is SetAccessor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is ClassStaticBlockDeclaration -> {
                checkUnusedInStatements(
                    element.body.statements, source, fileName, isTopLevel = false,
                )
            }
            is PropertyDeclaration -> {
                element.initializer?.let { checkUnusedInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    /**
     * Check for unused type parameters on a class declaration.
     */
    /**
     * Check for unused private class members (TS6133).
     * Private properties and methods that are never accessed within the class are unused.
     */
    private fun checkUnusedPrivateMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return

        // Collect private members
        data class PrivateMember(val name: String, val nameNode: Node)
        val privateMembers = mutableListOf<PrivateMember>()
        val getterSetterNames = mutableSetOf<String>() // track getter/setter pairs

        for (member in members) {
            val isPrivate = when (member) {
                is PropertyDeclaration -> ModifierFlag.Private in member.modifiers
                is MethodDeclaration -> ModifierFlag.Private in member.modifiers
                is GetAccessor -> ModifierFlag.Private in member.modifiers
                is SetAccessor -> ModifierFlag.Private in member.modifiers
                else -> false
            }
            if (!isPrivate) continue

            val name = when (member) {
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                else -> null
            } ?: continue

            val nameNode = when (member) {
                is PropertyDeclaration -> member.name
                is MethodDeclaration -> member.name
                is GetAccessor -> member.name
                is SetAccessor -> member.name
                else -> continue
            }

            // Track getter/setter pairs — don't duplicate
            if (member is GetAccessor || member is SetAccessor) {
                if (name in getterSetterNames) continue
                getterSetterNames.add(name)
            }

            privateMembers.add(PrivateMember(name, nameNode))
        }

        if (privateMembers.isEmpty()) return

        // Collect property access names per member (for self-reference detection)
        val privateMemberNames = privateMembers.map { it.name }.toSet()
        data class MemberRefs(val memberName: String?, val refs: MutableSet<String>)
        val refsPerMember = mutableListOf<MemberRefs>()
        for (member in members) {
            val memberName = when (member) {
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                is Constructor -> null
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                else -> null
            }
            val refs = mutableSetOf<String>()
            // Build param name → string literal values map for this[param] resolution
            val paramLiterals = buildParamLiteralMap(member)
            when (member) {
                is MethodDeclaration -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is Constructor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is GetAccessor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is SetAccessor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is PropertyDeclaration -> member.initializer?.let { collectPropertyAccessNamesInExpr(it, refs) }
                else -> {}
            }
            refsPerMember.add(MemberRefs(memberName, refs))
        }

        // Report unused private members
        // A member is unused if it's only accessed from its own body (self-reference)
        for (pm in privateMembers) {
            val isExternallyAccessed = refsPerMember.any { mr ->
                mr.memberName != pm.name && pm.name in mr.refs
            }
            if (isExternallyAccessed) continue
            val start = pm.nameNode.pos
            val length = pm.name.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${pm.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun collectPropertyAccessNames(block: Block, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        for (stmt in block.statements) {
            collectPropertyAccessNamesInStmt(stmt, names, paramLiterals)
        }
    }

    private fun collectPropertyAccessNamesInStmt(stmt: Statement, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        when (stmt) {
            is ExpressionStatement -> collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is IfStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                collectPropertyAccessNamesInStmt(stmt.thenStatement, names, paramLiterals)
                stmt.elseStatement?.let { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is Block -> stmt.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> collectPropertyAccessNamesInExpr(init, names, paramLiterals)
                    else -> {}
                }
                stmt.condition?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                stmt.incrementor?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
            }
            is WhileStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
            }
            is DoStatement -> {
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
            }
            is SwitchStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            collectPropertyAccessNamesInExpr(clause.expression, names, paramLiterals)
                            clause.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                        }
                        is DefaultClause -> clause.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                stmt.catchClause?.block?.statements?.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                stmt.finallyBlock?.statements?.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is ThrowStatement -> stmt.expression?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            else -> {}
        }
    }

    private fun collectPropertyAccessNamesInExpr(expr: Expression, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        when (expr) {
            is PropertyAccessExpression -> {
                names.add(expr.name.text)
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            }
            is CallExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                expr.arguments.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Simple assignment: left side is write-only, don't count as read
                    // But still recurse into sub-expressions of the left side
                    // (e.g. for `this.a[this.b] = 0`, this.b IS a read)
                    val left = expr.left
                    val right = expr.right
                    if (left is ObjectLiteralExpression && right is Identifier && right.text == "this") {
                        // Destructuring from this: ({ x, y } = this) reads this.x, this.y
                        for (prop in left.properties) {
                            when (prop) {
                                is ShorthandPropertyAssignment -> names.add(prop.name.text)
                                is PropertyAssignment -> {
                                    val propName = prop.name
                                    if (propName is Identifier) names.add(propName.text)
                                }
                                else -> {}
                            }
                        }
                    } else if (left is PropertyAccessExpression) {
                        // this.x = ... → only recurse into the base (this), not the property name
                        collectPropertyAccessNamesInExpr(left.expression, names, paramLiterals)
                    } else {
                        collectPropertyAccessNamesInExpr(left, names, paramLiterals)
                    }
                } else {
                    collectPropertyAccessNamesInExpr(expr.left, names, paramLiterals)
                }
                collectPropertyAccessNamesInExpr(expr.right, names, paramLiterals)
            }
            is PrefixUnaryExpression -> collectPropertyAccessNamesInExpr(expr.operand, names, paramLiterals)
            is PostfixUnaryExpression -> collectPropertyAccessNamesInExpr(expr.operand, names, paramLiterals)
            is ParenthesizedExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is ConditionalExpression -> {
                collectPropertyAccessNamesInExpr(expr.condition, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.whenTrue, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.whenFalse, names, paramLiterals)
            }
            is NewExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                expr.arguments?.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            }
            is ElementAccessExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.argumentExpression, names, paramLiterals)
                // String literal element access like obj["name"] counts as accessing "name"
                val arg = expr.argumentExpression
                if (arg is StringLiteralNode) {
                    names.add(arg.text)
                } else if (arg is Identifier && paramLiterals.isNotEmpty()) {
                    // this[param] where param has string literal union type
                    paramLiterals[arg.text]?.let { names.addAll(it) }
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { collectPropertyAccessNamesInExpr(it.expression, names, paramLiterals) }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> body.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                    is Expression -> collectPropertyAccessNamesInExpr(body, names, paramLiterals)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is ArrayLiteralExpression -> expr.elements.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> collectPropertyAccessNamesInExpr(prop.initializer, names, paramLiterals)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> collectPropertyAccessNamesInExpr(prop.expression, names, paramLiterals)
                        else -> {}
                    }
                }
            }
            is AsExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is NonNullExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is TypeAssertionExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is AwaitExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is SpreadElement -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is DeleteExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is VoidExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is TypeOfExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is CommaListExpression -> expr.elements.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            else -> {}
        }
    }

    /**
     * Build a map of parameter name → string literal values from type annotations.
     * Used to resolve `this[param]` as reads of the named properties.
     */
    private fun buildParamLiteralMap(member: ClassElement): Map<String, Set<String>> {
        val params = when (member) {
            is MethodDeclaration -> member.parameters
            is Constructor -> member.parameters
            is GetAccessor -> member.parameters
            is SetAccessor -> member.parameters
            else -> return emptyMap()
        }
        val result = mutableMapOf<String, Set<String>>()
        for (param in params) {
            val paramName = (param.name as? Identifier)?.text ?: continue
            val type = param.type ?: continue
            val literals = extractStringLiteralsFromType(type)
            if (literals.isNotEmpty()) result[paramName] = literals
        }
        return result
    }

    private fun extractStringLiteralsFromType(type: TypeNode): Set<String> {
        return when (type) {
            is LiteralType -> {
                val lit = type.literal
                if (lit is StringLiteralNode) setOf(lit.text) else emptySet()
            }
            is UnionType -> type.types.flatMapTo(mutableSetOf()) { extractStringLiteralsFromType(it) }
            is ParenthesizedType -> extractStringLiteralsFromType(type.type)
            else -> emptySet()
        }
    }

    private fun checkUnusedClassTypeParams(
        cls: ClassDeclaration,
        source: String,
        fileName: String,
        siblingStatements: List<Statement>? = null,
    ) {
        val typeParams = cls.typeParameters
        // Class type params are only checked with noUnusedParameters (not noUnusedLocals alone)
        if (typeParams.isNullOrEmpty() || !options.noUnusedParameters) return
        // Skip if another declaration merges with this class (interface/namespace) — same file
        val className = cls.name?.text
        if (className != null && siblingStatements != null) {
            val hasMerge = siblingStatements.any { stmt ->
                stmt !== cls && when (stmt) {
                    is InterfaceDeclaration -> stmt.name.text == className
                    is ModuleDeclaration -> {
                        val n = stmt.name
                        n is Identifier && n.text == className
                    }
                    else -> false
                }
            }
            if (hasMerge) return
        }
        // Skip if another declaration merges with this class across files (via globals)
        if (className != null) {
            val globalSymbol = globals[className]
            if (globalSymbol != null && globalSymbol.declarations.any { it.kind == SyntaxKind.InterfaceDeclaration || it.kind == SyntaxKind.ModuleDeclaration }) return
        }

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text,
                    nameNode = tp.name,
                    declNode = tp,
                    isExported = false,
                    isParameter = false,
                    isTypeOnly = true,
                ))
            }
        }

        // Collect type refs from: heritage clauses, member types, constructor params
        cls.heritageClauses?.forEach { clause ->
            for (type in clause.types) {
                type.typeArguments?.forEach { collectTypeRefs(it, tpScope) }
                // The extends expression itself might reference a type param
                if (type.expression is Identifier) {
                    tpScope.referencedNames.add((type.expression as Identifier).text)
                }
            }
        }
        for (member in cls.members) {
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                    member.body?.let { body ->
                        for (stmt in body.statements) collectTypeRefsInStatement(stmt, tpScope)
                    }
                }
                is Constructor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.body?.let { body ->
                        for (stmt in body.statements) collectTypeRefsInStatement(stmt, tpScope)
                    }
                }
                is GetAccessor -> member.type?.let { collectTypeRefs(it, tpScope) }
                is SetAccessor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                is IndexSignature -> member.type?.let { collectTypeRefs(it, tpScope) }
                else -> {}
            }
        }

        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    /** Check if a class declaration uses any of the named type parameters in its members. */
    private fun classUsesTypeParams(cls: ClassDeclaration, typeParamNames: Set<String>): Boolean {
        val tpScope = UnusedScope()
        // Add all type param names as "declarations" — we just want to see which ones are referenced
        for (name in typeParamNames) {
            tpScope.declarations.add(UnusedDecl(name = name, nameNode = Identifier(text = name), declNode = Identifier(text = name), isExported = false, isParameter = false, isTypeOnly = true))
        }
        for (member in cls.members) {
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                }
                is Constructor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                is GetAccessor -> member.type?.let { collectTypeRefs(it, tpScope) }
                is SetAccessor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                else -> {}
            }
        }
        return tpScope.referencedNames.any { it in typeParamNames }
    }

    private fun checkUnusedInterfaceTypeParams(
        iface: InterfaceDeclaration,
        source: String,
        fileName: String,
        siblingStatements: List<Statement>? = null,
    ) {
        val typeParams = iface.typeParameters
        if (typeParams.isNullOrEmpty() || !(options.noUnusedLocals || options.noUnusedParameters)) return
        val ifaceName = iface.name.text
        // Same-file merge check: if class/interface/namespace with same name in same file, skip
        if (siblingStatements != null) {
            val hasMerge = siblingStatements.any { stmt ->
                stmt !== iface && when (stmt) {
                    is InterfaceDeclaration -> stmt.name.text == ifaceName
                    is ClassDeclaration -> stmt.name?.text == ifaceName
                    is ModuleDeclaration -> {
                        val n = stmt.name
                        n is Identifier && n.text == ifaceName
                    }
                    else -> false
                }
            }
            if (hasMerge) return
        }
        // Cross-file merge check
        val globalSymbol = globals[ifaceName]
        if (globalSymbol != null) {
            // Skip if multiple interface/namespace declarations (normal interface merging)
            val nonClassDecls = globalSymbol.declarations.count {
                it.kind == SyntaxKind.InterfaceDeclaration || it.kind == SyntaxKind.ModuleDeclaration
            }
            if (nonClassDecls > 1) return
            // For class+interface cross-file merge: skip if the class uses any of the type params
            val typeParamNames = typeParams.map { it.name.text }.toSet()
            val classDecls = globalSymbol.declarations.filterIsInstance<ClassDeclaration>()
            for (classDecl in classDecls) {
                if (classUsesTypeParams(classDecl, typeParamNames)) return
            }
        }

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text, nameNode = tp.name, declNode = tp,
                    isExported = false, isParameter = false, isTypeOnly = true,
                ))
            }
        }

        // Collect refs from heritage clauses and members
        iface.heritageClauses?.forEach { clause ->
            for (type in clause.types) {
                type.typeArguments?.forEach { collectTypeRefs(it, tpScope) }
            }
        }
        for (member in iface.members) {
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                }
                is IndexSignature -> member.type?.let { collectTypeRefs(it, tpScope) }
                else -> {}
            }
        }

        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    private fun checkUnusedTypeAliasTypeParams(
        alias: TypeAliasDeclaration,
        source: String,
        fileName: String,
    ) {
        val typeParams = alias.typeParameters
        if (typeParams.isNullOrEmpty() || !(options.noUnusedLocals || options.noUnusedParameters)) return

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text, nameNode = tp.name, declNode = tp,
                    isExported = false, isParameter = false, isTypeOnly = true,
                ))
            }
        }

        collectTypeRefs(alias.type, tpScope)
        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    private fun reportUnusedTypeParams(
        scope: UnusedScope,
        typeParams: List<TypeParameter>,
        source: String,
        fileName: String,
    ) {
        val allUnused = scope.declarations.none { it.name in scope.referencedNames }
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            val tp = decl.declNode as TypeParameter
            val start: Int
            val length: Int
            if (allUnused && scope.declarations.size == 1 && typeParams.size == 1) {
                start = tp.pos - 1
                length = decl.name.length + 2
            } else {
                start = tp.name.pos
                length = decl.name.length
            }
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun checkUnusedInFunctionLike(
        bodyStatements: List<Statement>,
        parameters: List<Parameter>,
        source: String,
        fileName: String,
        typeParameters: List<TypeParameter>? = null,
        returnType: TypeNode? = null,
    ) {
        // Check parameters (if noUnusedParameters is enabled)
        if (options.noUnusedParameters) {
            val scope = UnusedScope()
            // Collect parameter declarations
            for (param in parameters) {
                if (param.isCommentPlaceholder) continue
                val name = param.name
                if (name is Identifier) {
                    // Skip if underscore-prefixed or if it has access modifiers (constructor params)
                    if (!name.text.startsWith("_") &&
                        ModifierFlag.Public !in param.modifiers &&
                        ModifierFlag.Protected !in param.modifiers &&
                        ModifierFlag.Private !in param.modifiers) {
                        scope.declarations.add(UnusedDecl(
                            name = name.text,
                            nameNode = name,
                            declNode = param,
                            isExported = false,
                            isParameter = true,
                            isTypeOnly = false,
                        ))
                    }
                } else {
                    // Destructuring parameters: collect individual binding element names
                    collectDestructuringParamNames(name, param, scope)
                }
            }
            // Collect references from body
            for (stmt in bodyStatements) {
                collectUnusedReferences(stmt, scope)
            }
            // Also collect references from parameter defaults and types.
            // For VALUE param scope, type annotations only contribute `typeof X` refs
            // (value namespace) — bare `T` in type position is a TYPE namespace ref and
            // does NOT count as a use of a value param with the same name.
            for (param in parameters) {
                param.initializer?.let { collectRefsFromExpr(it, scope) }
                param.type?.let { collectTypeQueryValueRefs(it, scope) }
            }
            // Scan return type for typeof references
            returnType?.let { collectTypeQueryValueRefs(it, scope) }
            // Report unused parameters
            // First check for TS6198: if ALL elements from a destructuring pattern are unused,
            // emit a single "All destructured elements are unused" instead of individual TS6133
            val unusedParams = scope.declarations.filter { it.name !in scope.referencedNames }
            val paramTs6198Patterns = mutableSetOf<Node>()
            val paramDeclsByPattern = unusedParams.filter { it.parentBindingPattern is ObjectBindingPattern }
                .groupBy { it.parentBindingPattern!! }
            for ((pattern, decls) in paramDeclsByPattern) {
                val totalCount = decls.first().bindingElementCount
                if (decls.size == totalCount && totalCount > 1) {
                    paramTs6198Patterns.add(pattern)
                    val patStart = pattern.pos
                    val spanLength = computeBindingPatternSpan(source, patStart, pattern)
                    val (line, character) = getLineAndCharacterOfPosition(source, patStart)
                    diagnostics.add(Diagnostic(
                        message = "All destructured elements are unused.",
                        category = DiagnosticCategory.Error,
                        code = 6198,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = patStart,
                        length = spanLength,
                    ))
                }
            }
            for (decl in unusedParams) {
                if (decl.parentBindingPattern != null && decl.parentBindingPattern in paramTs6198Patterns) continue
                // Underscore-prefixed names don't get individual TS6133 (only TS6198 above)
                if (decl.name.startsWith("_")) continue
                val nameNode = decl.nameNode
                // Single-element destructuring parameter: use pattern span for both { } and [ ]
                val usePatternSpan = decl.parentBindingPattern != null && decl.bindingElementCount == 1
                val start = if (usePatternSpan) decl.parentBindingPattern!!.pos else nameNode.pos
                val length = if (usePatternSpan) computeBindingPatternSpan(source, start, decl.parentBindingPattern!!)
                    else if (decl.spanLength > 0) decl.spanLength else decl.name.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "'${decl.name}' is declared but its value is never read.",
                    category = DiagnosticCategory.Error,
                    code = 6133,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }

        // Check unused type parameters (TS6133)
        if (typeParameters != null && typeParameters.isNotEmpty() && (options.noUnusedLocals || options.noUnusedParameters)) {
            val tpScope = UnusedScope()
            for (tp in typeParameters) {
                if (!tp.name.text.startsWith("_")) {
                    tpScope.declarations.add(UnusedDecl(
                        name = tp.name.text,
                        nameNode = tp.name,
                        declNode = tp,
                        isExported = false,
                        isParameter = false,
                        isTypeOnly = true,
                    ))
                }
            }
            // Collect type references from: type param constraints, parameter types,
            // return type, and body statements (types in variable declarations etc.)
            for (tp in typeParameters) {
                tp.constraint?.let { collectTypeRefs(it, tpScope) }
                tp.default?.let { collectTypeRefs(it, tpScope) }
            }
            for (param in parameters) {
                param.type?.let { collectTypeRefs(it, tpScope) }
            }
            returnType?.let { collectTypeRefs(it, tpScope) }
            for (stmt in bodyStatements) {
                collectTypeRefsInStatement(stmt, tpScope)
            }
            reportUnusedTypeParams(tpScope, typeParameters, source, fileName)
        }

        // Check local declarations in the body
        checkUnusedInStatements(bodyStatements, source, fileName, isTopLevel = false)
    }

    /**
     * Check for unused type parameters defined within type annotations.
     * Handles: ConstructorType `new <T,U>(a:T)=>void`, FunctionType `<T,U>(a:T)=>void`,
     * and TypeLiteral members with ConstructSignature/CallSignature.
     */
    private fun checkUnusedTypeParamsInType(type: TypeNode, source: String, fileName: String) {
        if (!options.noUnusedLocals && !options.noUnusedParameters) return
        when (type) {
            is ConstructorType -> {
                checkTypeParamsInSignature(type.typeParameters, type.parameters, type.type, source, fileName)
            }
            is FunctionType -> {
                checkTypeParamsInSignature(type.typeParameters, type.parameters, type.type, source, fileName)
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            // Call signatures (name=""), construct signatures (name="new"), and methods
                            checkTypeParamsInSignature(member.typeParameters, member.parameters, member.type, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is UnionType -> type.types.forEach { checkUnusedTypeParamsInType(it, source, fileName) }
            is IntersectionType -> type.types.forEach { checkUnusedTypeParamsInType(it, source, fileName) }
            is ParenthesizedType -> checkUnusedTypeParamsInType(type.type, source, fileName)
            else -> {}
        }
    }

    /** Check unused type params for a single signature (construct/call/method). */
    private fun checkTypeParamsInSignature(
        typeParameters: List<TypeParameter>?,
        parameters: List<Parameter>,
        returnType: TypeNode?,
        source: String,
        fileName: String,
    ) {
        if (typeParameters.isNullOrEmpty()) return
        val scope = UnusedScope()
        for (tp in typeParameters) {
            if (!tp.name.text.startsWith("_")) {
                scope.declarations.add(UnusedDecl(
                    name = tp.name.text,
                    nameNode = tp.name,
                    declNode = tp,
                    isExported = false,
                    isParameter = false,
                    isTypeOnly = true,
                ))
            }
        }
        // Collect refs from constraints, param types, return type
        for (tp in typeParameters) {
            tp.constraint?.let { collectTypeRefs(it, scope) }
            tp.default?.let { collectTypeRefs(it, scope) }
        }
        for (param in parameters) {
            param.type?.let { collectTypeRefs(it, scope) }
        }
        returnType?.let { collectTypeRefs(it, scope) }
        reportUnusedTypeParams(scope, typeParameters, source, fileName)
    }

    /** Collect type identifier references from a type node. */
    private fun collectTypeRefs(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeReference -> {
                val name = type.typeName
                if (name is Identifier) scope.referencedNames.add(name.text)
                type.typeArguments?.forEach { collectTypeRefs(it, scope) }
            }
            is KeywordTypeNode -> {} // any, number, string, etc. — no references
            is ArrayType -> collectTypeRefs(type.elementType, scope)
            is TupleType -> type.elements.forEach {
                when (it) {
                    is TypeNode -> collectTypeRefs(it, scope)
                    else -> {}
                }
            }
            is UnionType -> type.types.forEach { collectTypeRefs(it, scope) }
            is IntersectionType -> type.types.forEach { collectTypeRefs(it, scope) }
            is ParenthesizedType -> collectTypeRefs(type.type, scope)
            is FunctionType -> {
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                type.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                type.type?.let { collectTypeRefs(it, scope) }
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                type.type?.let { collectTypeRefs(it, scope) }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, scope) }
                        is MethodDeclaration -> {
                            member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                            member.type?.let { collectTypeRefs(it, scope) }
                        }
                        is IndexSignature -> member.type?.let { collectTypeRefs(it, scope) }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectTypeRefs(type.checkType, scope)
                collectTypeRefs(type.extendsType, scope)
                collectTypeRefs(type.trueType, scope)
                collectTypeRefs(type.falseType, scope)
            }
            is MappedType -> {
                type.type?.let { collectTypeRefs(it, scope) }
            }
            is TypeQuery -> {
                val name = type.exprName
                if (name is Identifier) scope.referencedNames.add(name.text)
            }
            is IndexedAccessType -> {
                collectTypeRefs(type.objectType, scope)
                collectTypeRefs(type.indexType, scope)
            }
            is TypeOperator -> collectTypeRefs(type.type, scope)
            is RestType -> collectTypeRefs(type.type, scope)
            is OptionalType -> collectTypeRefs(type.type, scope)
            is InferType -> {} // infer T — declares, doesn't reference
            is LiteralType -> {} // string/number literals
            is TemplateLiteralType -> {
                type.templateSpans.forEach { span ->
                    collectTypeRefs(span.type, scope)
                }
            }
            else -> {}
        }
    }

    /**
     * Collect ONLY `typeof X` references from within a TypeNode tree. Unlike [collectTypeRefs],
     * bare TypeReference identifiers are NOT added — they belong to the TYPE namespace and do
     * not count as value-param uses for TS6133 purposes. Needed for cases like
     * `function f<T>(T: T)` where the second `T` in type position references the type param,
     * not the value param of the same name.
     */
    private fun collectTypeQueryValueRefs(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeQuery -> {
                when (val name = type.exprName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
            }
            is ArrayType -> collectTypeQueryValueRefs(type.elementType, scope)
            is TupleType -> type.elements.forEach {
                if (it is TypeNode) collectTypeQueryValueRefs(it, scope)
            }
            is UnionType -> type.types.forEach { collectTypeQueryValueRefs(it, scope) }
            is IntersectionType -> type.types.forEach { collectTypeQueryValueRefs(it, scope) }
            is ParenthesizedType -> collectTypeQueryValueRefs(type.type, scope)
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                type.type?.let { collectTypeQueryValueRefs(it, scope) }
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                type.type?.let { collectTypeQueryValueRefs(it, scope) }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        is MethodDeclaration -> {
                            member.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                            member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        }
                        is IndexSignature -> member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectTypeQueryValueRefs(type.checkType, scope)
                collectTypeQueryValueRefs(type.extendsType, scope)
                collectTypeQueryValueRefs(type.trueType, scope)
                collectTypeQueryValueRefs(type.falseType, scope)
            }
            is MappedType -> type.type?.let { collectTypeQueryValueRefs(it, scope) }
            is IndexedAccessType -> {
                collectTypeQueryValueRefs(type.objectType, scope)
                collectTypeQueryValueRefs(type.indexType, scope)
            }
            is TypeOperator -> collectTypeQueryValueRefs(type.type, scope)
            is RestType -> collectTypeQueryValueRefs(type.type, scope)
            is OptionalType -> collectTypeQueryValueRefs(type.type, scope)
            is TypeReference -> {
                // Bare type reference is TYPE namespace, not value; skip.
                // But type arguments can still contain nested TypeQuery.
                type.typeArguments?.forEach { collectTypeQueryValueRefs(it, scope) }
            }
            is TemplateLiteralType -> type.templateSpans.forEach { span ->
                collectTypeQueryValueRefs(span.type, scope)
            }
            else -> {}
        }
    }

    /** Recursively collect type refs from statements (for unused type param detection). */
    private fun collectTypeRefsInStatement(stmt: Statement, scope: UnusedScope) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.type?.let { collectTypeRefs(it, scope) }
                    decl.initializer?.let { collectTypeRefsInExpr(it, scope) }
                }
            }
            is ExpressionStatement -> collectTypeRefsInExpr(stmt.expression, scope)
            is ReturnStatement -> stmt.expression?.let { collectTypeRefsInExpr(it, scope) }
            is IfStatement -> {
                collectTypeRefsInExpr(stmt.expression, scope)
                collectTypeRefsInStatement(stmt.thenStatement, scope)
                stmt.elseStatement?.let { collectTypeRefsInStatement(it, scope) }
            }
            is Block -> stmt.statements.forEach { collectTypeRefsInStatement(it, scope) }
            is ForStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is ForInStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is ForOfStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is WhileStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is DoStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectTypeRefsInStatement(it, scope) }
                stmt.catchClause?.block?.statements?.forEach { collectTypeRefsInStatement(it, scope) }
                stmt.finallyBlock?.statements?.forEach { collectTypeRefsInStatement(it, scope) }
            }
            else -> {}
        }
    }

    /** Collect type refs from expressions (type assertions, as expressions, etc.). */
    private fun collectTypeRefsInExpr(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is AsExpression -> {
                collectTypeRefs(expr.type, scope)
                collectTypeRefsInExpr(expr.expression, scope)
            }
            is TypeAssertionExpression -> {
                collectTypeRefs(expr.type, scope)
                collectTypeRefsInExpr(expr.expression, scope)
            }
            is CallExpression -> {
                expr.typeArguments?.forEach { collectTypeRefs(it, scope) }
                collectTypeRefsInExpr(expr.expression, scope)
                expr.arguments.forEach { collectTypeRefsInExpr(it, scope) }
            }
            is NewExpression -> {
                expr.typeArguments?.forEach { collectTypeRefs(it, scope) }
            }
            is ParenthesizedExpression -> collectTypeRefsInExpr(expr.expression, scope)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    collectTypeRefsInExpr(current.right, scope)
                    current = current.left
                }
                collectTypeRefsInExpr(current, scope)
            }
            is ConditionalExpression -> {
                collectTypeRefsInExpr(expr.condition, scope)
                collectTypeRefsInExpr(expr.whenTrue, scope)
                collectTypeRefsInExpr(expr.whenFalse, scope)
            }
            is ArrowFunction -> {
                expr.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                expr.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                expr.type?.let { collectTypeRefs(it, scope) }
            }
            is FunctionExpression -> {
                expr.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                expr.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                expr.type?.let { collectTypeRefs(it, scope) }
            }
            else -> {}
        }
    }

    /**
     * Compute 1-based line and character for a position in source text.
     */
    private fun getLineAndCharacterOfPosition(source: String, position: Int): Pair<Int, Int> {
        var line = 1
        var lineStart = 0
        for (i in 0 until position.coerceAtMost(source.length)) {
            if (source[i] == '\n') {
                line++
                lineStart = i + 1
            }
        }
        return line to (position - lineStart + 1)
    }

    /**
     * Compute the span length for a binding pattern by finding the closing
     * brace/bracket in the source. Our parser's `end` position is set after
     * nextToken() so it extends past the closing delimiter.
     */
    private fun computeBindingPatternSpan(source: String, start: Int, pattern: Node): Int {
        val closeChar = if (pattern is ObjectBindingPattern) '}' else ']'
        var depth = 0
        var i = start
        while (i < source.length) {
            val ch = source[i]
            if (ch == '{' || ch == '[') depth++
            else if (ch == '}' || ch == ']') {
                depth--
                if (depth == 0 && ch == closeChar) return i - start + 1
            }
            i++
        }
        return pattern.end - start
    }

    // -----------------------------------------------------------------------
    // Definite assignment checking (TS2454)
    // -----------------------------------------------------------------------

    /**
     * Check for variables used before being definitively assigned.
     * Emits TS2454 "Variable 'X' is used before being assigned."
     */
    private fun checkDefiniteAssignment() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkDefiniteAssignmentInStatements(
                result.sourceFile.statements, source, fileName,
                fileLocals = result.locals,
            )
        }
    }

    /**
     * Walk statements tracking which variables are uninitialized.
     * When a reference to an uninitialized variable is found, emit TS2454.
     */
    private fun checkDefiniteAssignmentInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        preInitialized: Set<String> = emptySet(),
        fileLocals: SymbolTable? = null,
    ) {
        // Track variables declared with type but no initializer
        val uninitialized = mutableSetOf<String>()

        for (stmt in statements) {
            // 1. Collect variable declarations that are uninitialized
            // (but skip any names that are pre-initialized via function parameters)
            collectUninitializedVars(stmt, uninitialized, preInitialized, fileLocals)

            // 2. Check for uses of uninitialized variables in this statement
            if (uninitialized.isNotEmpty()) {
                checkUsesOfUninitialized(stmt, uninitialized, source, fileName)
            }

            // 3. Mark variables as assigned if they appear on left side of assignment
            markAssignments(stmt, uninitialized)

            // 4. Recurse into nested scopes
            checkDefiniteAssignmentInNestedScopes(stmt, source, fileName)
        }
    }

    private fun collectUninitializedVars(
        stmt: Statement,
        uninitialized: MutableSet<String>,
        preInitialized: Set<String> = emptySet(),
        fileLocals: SymbolTable? = null,
    ) {
        when (stmt) {
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    // Only flag variables with type annotation but no initializer
                    // Skip definite assignment assertions (var x!: Type)
                    if (decl.type != null && decl.initializer == null && !decl.exclamationToken) {
                        // Skip `var x: any` — `any` includes undefined, no assignment needed
                        if (isAnyType(decl.type)) continue
                        // Skip if type annotation is a bare generic reference (TS2314 error type)
                        if (isUnresolvedGenericType(decl.type)) continue
                        // Skip import types (e.g. `import('./b').B`) — we can't resolve them
                        if (typeContainsImportType(decl.type)) continue
                        // Skip types that include undefined — variable is implicitly initialized to undefined
                        if (typeIncludesUndefined(decl.type)) continue
                        // Skip if the type annotation is a reference to a namespace symbol.
                        // Namespace-typed vars (var a: A where A is a namespace) get TS2709 but NOT TS2454.
                        if (fileLocals != null && isNamespaceTypeRef(decl.type, fileLocals)) continue
                        val name = decl.name
                        if (name is Identifier) {
                            // Skip if name matches a function parameter (var redeclaration of param)
                            if (name.text !in preInitialized) {
                                uninitialized.add(name.text)
                            }
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Returns true if the type annotation is a TypeReference directly to a namespace symbol.
     * Used to suppress TS2454 for vars typed as plain namespace names (e.g. `var a: SomeNamespace`).
     * TypeScript flags TS2709 (cannot use namespace as type) for such declarations instead of TS2454.
     * Note: qualified types like `var x: A.B` are NOT suppressed, since A.B may be a valid class/interface.
     */
    private fun isNamespaceTypeRef(type: TypeNode?, locals: SymbolTable): Boolean {
        if (type !is TypeReference) return false
        val typeName = type.typeName
        // Only check simple identifiers — `var a: A` where A is a namespace
        val name = (typeName as? Identifier)?.text ?: return false
        val symbol = locals[name] ?: return false
        // If the name resolves to any kind of module/namespace, TypeScript flags TS2709 not TS2454
        return symbol.flags.hasAny(SymbolFlags.Module)
    }

    private fun isAnyType(type: Node?): Boolean {
        if (type == null) return false
        // Check for keyword type nodes like `any` and `unknown`
        // Both are top types — a variable typed `unknown` can hold any value including undefined
        return type.kind == SyntaxKind.AnyKeyword || type.kind == SyntaxKind.UnknownKeyword
    }

    /**
     * Returns true if the type annotation contains an import type (e.g. `import('./b').B`).
     * We can't resolve import types, so we skip TS2564 checking for properties with such types.
     */
    private fun typeContainsImportType(type: Node?): Boolean {
        if (type == null) return false
        if (type is ImportType) return true
        // Check nested: QualifiedName inside TypeReference, or union/intersection members
        return when (type) {
            is TypeReference -> typeContainsImportType(type.typeName)
            is UnionType -> type.types.any { typeContainsImportType(it) }
            is IntersectionType -> type.types.any { typeContainsImportType(it) }
            is ArrayType -> typeContainsImportType(type.elementType)
            is QualifiedName -> typeContainsImportType(type.left) || typeContainsImportType(type.right)
            else -> false
        }
    }

    /**
     * Returns true if the type syntactically includes `undefined`.
     * Variables typed as `T | undefined` start with undefined as a valid value,
     * so they don't need definite assignment (no TS2454).
     * Note: `null` alone does NOT satisfy definite assignment — only `undefined` does.
     */
    private fun typeIncludesUndefined(type: Node?): Boolean {
        if (type == null) return false
        return when (type) {
            is UnionType -> type.types.any { member ->
                member.kind == SyntaxKind.UndefinedKeyword ||
                    typeIncludesUndefined(member)
            }
            else -> type.kind == SyntaxKind.UndefinedKeyword
        }
    }

    /**
     * Check expression trees for references to uninitialized variables.
     * When found, emit TS2454 and remove from uninitialized set (report only first use).
     */
    private fun checkUsesOfUninitialized(
        stmt: Statement,
        uninitialized: MutableSet<String>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        findUninitializedRefs(it, uninitialized, source, fileName)
                    }
                }
            }
            is ExpressionStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let {
                    findUninitializedRefs(it, uninitialized, source, fileName)
                }
            }
            is IfStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
                // Recurse into else-if chains to check their conditions,
                // but NOT into body blocks (they may have type-narrowed variables
                // that our simplified checker can't track via control flow analysis)
                val elseStmt = stmt.elseStatement
                if (elseStmt is IfStatement) {
                    checkUsesOfUninitialized(elseStmt, uninitialized, source, fileName)
                }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> {
                        findUninitializedRefs(init, uninitialized, source, fileName)
                        markAssignmentsInExpr(init, uninitialized)
                    }
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let {
                                findUninitializedRefs(it, uninitialized, source, fileName)
                            }
                            // Variable with initializer is assigned
                            if (decl.initializer != null) {
                                val name = decl.name
                                if (name is Identifier) uninitialized.remove(name.text)
                            }
                        }
                    }
                    else -> {}
                }
                stmt.condition?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is ForInStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ForOfStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is WhileStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ThrowStatement -> {
                stmt.expression?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is SwitchStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ClassDeclaration -> {
                // Check heritage clause expressions (extends/implements) for TS2454
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        findUninitializedRefs(type.expression, uninitialized, source, fileName)
                    }
                }
            }
            is Block -> {
                for (s in stmt.statements) {
                    checkUsesOfUninitialized(s, uninitialized, source, fileName)
                    markAssignments(s, uninitialized)
                }
            }
            is DoStatement -> {
                checkUsesOfUninitialized(stmt.statement, uninitialized, source, fileName)
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) {
                    checkUsesOfUninitialized(s, uninitialized, source, fileName)
                    markAssignments(s, uninitialized)
                }
            }
            is LabeledStatement -> {
                checkUsesOfUninitialized(stmt.statement, uninitialized, source, fileName)
            }
            is ExportAssignment -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Walk an expression tree to find references to uninitialized variables.
     * Emits TS2454 diagnostic at the usage site.
     */
    private fun findUninitializedRefs(
        expr: Expression,
        uninitialized: MutableSet<String>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text in uninitialized) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Variable '${expr.text}' is used before being assigned.",
                        category = DiagnosticCategory.Error,
                        code = 2454,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is PropertyAccessExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            }
            is ElementAccessExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                findUninitializedRefs(expr.argumentExpression, uninitialized, source, fileName)
            }
            is CallExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                expr.arguments.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is NewExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                expr.arguments?.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Assignment — right side may use uninitialized, left side is a write
                    findUninitializedRefs(expr.right, uninitialized, source, fileName)
                    // Mark the left side as assigned (so subsequent uses are not flagged)
                    // But for property/element access (d.x = v, d[i] = v), the base object is READ
                    val left = expr.left
                    when (left) {
                        is Identifier -> uninitialized.remove(left.text)
                        is PropertyAccessExpression -> findUninitializedRefs(left.expression, uninitialized, source, fileName)
                        is ElementAccessExpression -> {
                            findUninitializedRefs(left.expression, uninitialized, source, fileName)
                            findUninitializedRefs(left.argumentExpression, uninitialized, source, fileName)
                        }
                        is ObjectLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        is ArrayLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        else -> {}
                    }
                } else if (expr.operator == SyntaxKind.Comma) {
                    // Comma operator: evaluate left first, mark assignments, then evaluate right.
                    // This correctly handles `t0 = t1, t1 = t0` where t0 is assigned before t1 uses it.
                    findUninitializedRefs(expr.left, uninitialized, source, fileName)
                    // Left side is done; now right side can benefit from its assignments
                    findUninitializedRefs(expr.right, uninitialized, source, fileName)
                } else {
                    // Iterative left spine to avoid StackOverflow
                    var current: Expression = expr
                    while (current is BinaryExpression && current.operator != SyntaxKind.Equals &&
                           current.operator != SyntaxKind.Comma) {
                        findUninitializedRefs(current.right, uninitialized, source, fileName)
                        current = current.left
                    }
                    if (current is BinaryExpression) {
                        findUninitializedRefs(current.right, uninitialized, source, fileName)
                    } else {
                        findUninitializedRefs(current, uninitialized, source, fileName)
                    }
                }
            }
            is ConditionalExpression -> {
                findUninitializedRefs(expr.condition, uninitialized, source, fileName)
                findUninitializedRefs(expr.whenTrue, uninitialized, source, fileName)
                findUninitializedRefs(expr.whenFalse, uninitialized, source, fileName)
            }
            is PrefixUnaryExpression -> {
                findUninitializedRefs(expr.operand, uninitialized, source, fileName)
            }
            is PostfixUnaryExpression -> {
                findUninitializedRefs(expr.operand, uninitialized, source, fileName)
            }
            is ParenthesizedExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            // Check computed property names: { [t]: 0 } reads t
                            val name = prop.name
                            if (name is ComputedPropertyName) {
                                findUninitializedRefs(name.expression, uninitialized, source, fileName)
                            }
                            findUninitializedRefs(prop.initializer, uninitialized, source, fileName)
                        }
                        is ShorthandPropertyAssignment -> {
                            findUninitializedRefs(prop.name, uninitialized, source, fileName)
                        }
                        is SpreadAssignment -> {
                            findUninitializedRefs(prop.expression, uninitialized, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach {
                    findUninitializedRefs(it.expression, uninitialized, source, fileName)
                }
            }
            is TaggedTemplateExpression -> {
                findUninitializedRefs(expr.tag, uninitialized, source, fileName)
            }
            is SpreadElement -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is AwaitExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is YieldExpression -> expr.expression?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            is AsExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is NonNullExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is TypeOfExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is DeleteExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is VoidExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is TypeAssertionExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is SatisfiesExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is CommaListExpression -> {
                expr.elements.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            else -> {} // Literals, arrow functions, etc. — no direct references
        }
    }

    /**
     * Mark variables as assigned when they appear on the left side of assignments.
     */
    private fun markAssignments(stmt: Statement, uninitialized: MutableSet<String>) {
        when (stmt) {
            is ExpressionStatement -> {
                markAssignmentsInExpr(stmt.expression, uninitialized)
            }
            is VariableStatement -> {
                // Variable with initializer — it's assigned
                for (decl in stmt.declarationList.declarations) {
                    if (decl.initializer != null) {
                        val name = decl.name
                        if (name is Identifier) {
                            uninitialized.remove(name.text)
                        }
                    }
                }
            }
            is IfStatement -> {
                // Assignments in if/else branches — scan both branches
                markAssignmentsInStmt(stmt.thenStatement, uninitialized)
                stmt.elseStatement?.let { markAssignmentsInStmt(it, uninitialized) }
            }
            is SwitchStatement -> {
                // Assignments in switch cases — scan all case bodies
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    for (s in clauseStmts) markAssignmentsInStmt(s, uninitialized)
                }
            }
            is Block -> {
                for (s in stmt.statements) markAssignments(s, uninitialized)
            }
            else -> {}
        }
    }

    private fun markAssignmentsInStmt(stmt: Statement, uninitialized: MutableSet<String>) {
        when (stmt) {
            is ExpressionStatement -> markAssignmentsInExpr(stmt.expression, uninitialized)
            is Block -> stmt.statements.forEach { markAssignmentsInStmt(it, uninitialized) }
            is IfStatement -> {
                markAssignmentsInStmt(stmt.thenStatement, uninitialized)
                stmt.elseStatement?.let { markAssignmentsInStmt(it, uninitialized) }
            }
            else -> {}
        }
    }

    private fun markAssignmentsInExpr(expr: Expression, uninitialized: MutableSet<String>) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    val left = expr.left
                    when (left) {
                        is Identifier -> uninitialized.remove(left.text)
                        is ObjectLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        is ArrayLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        else -> {}
                    }
                }
                // Iterative left spine to avoid StackOverflow
                var current: Expression = expr
                while (current is BinaryExpression) {
                    markAssignmentsInExpr(current.right, uninitialized)
                    if (current.operator == SyntaxKind.Equals) {
                        val left = current.left
                        when (left) {
                            is Identifier -> uninitialized.remove(left.text)
                            is ObjectLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                            is ArrayLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                            else -> {}
                        }
                    }
                    current = current.left
                }
                markAssignmentsInExpr(current, uninitialized)
            }
            is CommaListExpression -> {
                expr.elements.forEach { markAssignmentsInExpr(it, uninitialized) }
            }
            is ParenthesizedExpression -> markAssignmentsInExpr(expr.expression, uninitialized)
            else -> {}
        }
    }

    /** Extract assigned variable names from destructuring assignment targets. */
    private fun collectDestructuringTargets(expr: Expression, uninitialized: MutableSet<String>) {
        when (expr) {
            is Identifier -> uninitialized.remove(expr.text)
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is ShorthandPropertyAssignment -> uninitialized.remove(prop.name.text)
                        is PropertyAssignment -> collectDestructuringTargets(prop.initializer, uninitialized)
                        is SpreadAssignment -> collectDestructuringTargets(prop.expression, uninitialized)
                        else -> {}
                    }
                }
            }
            is ArrayLiteralExpression -> {
                for (elem in expr.elements) {
                    when (elem) {
                        is SpreadElement -> collectDestructuringTargets(elem.expression, uninitialized)
                        is OmittedExpression -> {} // skip holes
                        else -> collectDestructuringTargets(elem, uninitialized)
                    }
                }
            }
            is BinaryExpression -> {
                // Default value: `x = defaultVal` — the target is `x`
                if (expr.operator == SyntaxKind.Equals) {
                    collectDestructuringTargets(expr.left, uninitialized)
                }
            }
            else -> {}
        }
    }

    /**
     * Collect identifier names from a parameter list (for pre-initializing TS2454 scope).
     * Parameters are always assigned when the function body executes.
     */
    private fun collectParamNames(parameters: List<Parameter>): Set<String> {
        val names = mutableSetOf<String>()
        for (param in parameters) {
            val name = param.name
            if (name is Identifier && name.text != "this") {
                names.add(name.text)
            }
        }
        return names
    }

    /**
     * Recurse into function bodies and other nested scopes for TS2454 checking.
     */
    private fun checkDefiniteAssignmentInNestedScopes(
        stmt: Statement,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                stmt.body?.let {
                    checkDefiniteAssignmentInStatements(
                        it.statements, source, fileName,
                        preInitialized = collectParamNames(stmt.parameters),
                    )
                }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is Constructor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is GetAccessor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is SetAccessor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return // skip ambient
                when (val body = stmt.body) {
                    is ModuleBlock -> checkDefiniteAssignmentInStatements(
                        body.statements, source, fileName,
                    )
                    is ModuleDeclaration -> checkDefiniteAssignmentInNestedScopes(
                        body, source, fileName,
                    )
                    else -> {}
                }
            }
            is Block -> checkDefiniteAssignmentInStatements(
                stmt.statements, source, fileName,
            )
            is IfStatement -> {
                checkDefiniteAssignmentInNestedScopes(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkDefiniteAssignmentInNestedScopes(it, source, fileName) }
            }
            is ForStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is ForInStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is ForOfStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is WhileStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is DoStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach {
                            checkDefiniteAssignmentInNestedScopes(it, source, fileName)
                        }
                        is DefaultClause -> clause.statements.forEach {
                            checkDefiniteAssignmentInNestedScopes(it, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach {
                    checkDefiniteAssignmentInNestedScopes(it, source, fileName)
                }
                stmt.catchClause?.block?.statements?.forEach {
                    checkDefiniteAssignmentInNestedScopes(it, source, fileName)
                }
                stmt.finallyBlock?.statements?.forEach {
                    checkDefiniteAssignmentInNestedScopes(it, source, fileName)
                }
            }
            is LabeledStatement -> checkDefiniteAssignmentInNestedScopes(stmt.statement, source, fileName)
            is VariableStatement -> {
                // Recurse into class/function expressions in variable initializers
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkDefiniteAssignmentInExprContext(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkDefiniteAssignmentInExprContext(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkDefiniteAssignmentInExprContext(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Walk an expression for nested function/class expressions, recursing into
     * their bodies to check for TS2454.
     */
    private fun checkDefiniteAssignmentInExprContext(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ClassExpression -> {
                for (member in expr.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is Constructor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is GetAccessor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is SetAccessor -> member.body?.let {
                            checkDefiniteAssignmentInStatements(
                                it.statements, source, fileName,
                                preInitialized = collectParamNames(member.parameters),
                            )
                        }
                        is PropertyDeclaration -> member.initializer?.let {
                            checkDefiniteAssignmentInExprContext(it, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is FunctionExpression -> expr.body.let {
                checkDefiniteAssignmentInStatements(
                    it.statements, source, fileName,
                    preInitialized = collectParamNames(expr.parameters),
                )
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkDefiniteAssignmentInStatements(
                        body.statements, source, fileName,
                        preInitialized = collectParamNames(expr.parameters),
                    )
                    is Expression -> checkDefiniteAssignmentInExprContext(body, source, fileName)
                    else -> {}
                }
            }
            is CallExpression -> {
                checkDefiniteAssignmentInExprContext(expr.expression, source, fileName)
                expr.arguments.forEach { checkDefiniteAssignmentInExprContext(it, source, fileName) }
            }
            is NewExpression -> {
                checkDefiniteAssignmentInExprContext(expr.expression, source, fileName)
                expr.arguments?.forEach { checkDefiniteAssignmentInExprContext(it, source, fileName) }
            }
            is BinaryExpression -> {
                // Iterative left-spine walk to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkDefiniteAssignmentInExprContext(current.right, source, fileName)
                    current = current.left
                }
                checkDefiniteAssignmentInExprContext(current, source, fileName)
            }
            is ParenthesizedExpression -> checkDefiniteAssignmentInExprContext(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkDefiniteAssignmentInExprContext(expr.condition, source, fileName)
                checkDefiniteAssignmentInExprContext(expr.whenTrue, source, fileName)
                checkDefiniteAssignmentInExprContext(expr.whenFalse, source, fileName)
            }
            else -> {}
        }
    }


    // -----------------------------------------------------------------------
    // Property initialization checking (TS2564)
    // -----------------------------------------------------------------------

    /**
     * Check for class properties without initializer and not definitely assigned
     * in the constructor. Emits TS2564.
     */
    private fun checkPropertyInitialization() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkPropertyInitInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkPropertyInitInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    // Abstract classes still need TS2564 for non-abstract properties
                    checkClassPropertyInit(stmt.members, source, fileName)
                }
                is ModuleDeclaration -> {
                    // Skip declare (ambient) namespaces — classes inside are ambient
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkPropertyInitInStatements(
                            body.statements, source, fileName,
                        )
                        else -> {}
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    stmt.body?.let {
                        checkPropertyInitInStatements(it.statements, source, fileName)
                    }
                }
                is Block -> checkPropertyInitInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let {
                        checkPropertyInitInStatements(listOf(it), source, fileName)
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkPropertyInitInExpr(decl.initializer, source, fileName)
                    }
                }
                is ExpressionStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is ReturnStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                else -> {}
            }
        }
    }

    private fun checkPropertyInitInExpr(expr: Expression?, source: String, fileName: String) {
        when (expr) {
            is ClassExpression -> {
                if (ModifierFlag.Abstract !in expr.modifiers) {
                    checkClassPropertyInit(expr.members, source, fileName)
                }
            }
            is ParenthesizedExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    private fun checkClassPropertyInit(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Find the constructor and collect assigned properties
        val constructorAssigned = mutableSetOf<String>()
        // Collect all class member names (for typeof-reference check below)
        val classMemberNames = mutableSetOf<String>()
        for (member in members) {
            if (member is Constructor) {
                member.body?.let { body ->
                    collectConstructorAssignments(body.statements, constructorAssigned)
                }
                // Constructor parameters with access modifiers (public/private/protected)
                // are automatically assigned
                for (param in member.parameters) {
                    if (ModifierFlag.Public in param.modifiers ||
                        ModifierFlag.Protected in param.modifiers ||
                        ModifierFlag.Private in param.modifiers) {
                        val name = param.name
                        if (name is Identifier) {
                            constructorAssigned.add(name.text)
                        }
                    }
                }
            }
            // Collect member names for typeof-reference detection
            val memberName = when (val n = (member as? PropertyDeclaration)?.name
                ?: (member as? MethodDeclaration)?.name) {
                is Identifier -> n.text
                else -> null
            }
            if (memberName != null) classMemberNames.add(memberName)
        }

        // Check each property
        for (member in members) {
            if (member !is PropertyDeclaration) continue
            // Skip if has initializer, optional, declare, static, abstract, or definite assignment
            if (member.initializer != null) continue
            if (member.questionToken) continue
            if (member.exclamationToken) continue
            if (ModifierFlag.Declare in member.modifiers) continue
            if (ModifierFlag.Static in member.modifiers) continue
            if (ModifierFlag.Abstract in member.modifiers) continue
            // Must have type annotation (no type = any, which is always ok)
            if (member.type == null) continue
            // Skip `any` type — no assignment needed for any
            if (isAnyType(member.type)) continue
            // Skip if type annotation is a bare generic reference (would trigger TS2314)
            // TypeScript doesn't flag TS2564 on error types
            if (isUnresolvedGenericType(member.type)) continue
            // Skip import types (e.g. `import('./b').B`) — we can't resolve them
            if (typeContainsImportType(member.type)) continue
            // Skip `typeof X` where X is a class member or unresolved name — TypeScript resolves
            // these as error types and suppresses TS2564. Only check `typeof X` when X is
            // definitely NOT a class member (TypeScript would resolve it as a valid type).
            if (member.type is TypeQuery) {
                val queryExpr = (member.type as TypeQuery).exprName
                if (queryExpr is Identifier && queryExpr.text in classMemberNames) continue
                // If the typeof target is NOT a class member, fall through to check TS2564
                // (e.g., `typeof GlobalFoo` where GlobalFoo is a declared external var)
            }

            // Get property name — only identifier-named and computed properties get TS2564
            // String/numeric literal names are excluded (TypeScript doesn't check those)
            val propName = when (val name = member.name) {
                is Identifier -> name.text
                is ComputedPropertyName -> {
                    // Computed property name — handles Symbol.X, NS.x, and simple identifiers
                    when (val expr = name.expression) {
                        is PropertyAccessExpression -> {
                            // Build the full dotted name for display (e.g. "[Symbol.iterator]", "[NS.x]")
                            fun buildDottedName(e: Expression): String? = when (e) {
                                is Identifier -> e.text
                                is PropertyAccessExpression -> {
                                    val baseName = buildDottedName(e.expression) ?: return@buildDottedName null
                                    "$baseName.${e.name.text}"
                                }
                                else -> null
                            }
                            buildDottedName(expr)?.let { "[$it]" }
                        }
                        is Identifier -> "[${expr.text}]"
                        else -> null
                    }
                }
                else -> null
            } ?: continue

            // Check if assigned in constructor
            if (propName in constructorAssigned) continue

            // Emit TS2564
            val nameNode = member.name
            val start = nameNode.pos
            val length = propName.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            diagnostics.add(Diagnostic(
                message = "Property '$propName' has no initializer and is not definitely assigned in the constructor.",
                category = DiagnosticCategory.Error,
                code = 2564,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }

        // Recurse into nested class elements for inner classes
        for (member in members) {
            when (member) {
                is MethodDeclaration -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is Constructor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is GetAccessor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is SetAccessor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is ClassStaticBlockDeclaration -> {
                    checkPropertyInitInStatements(member.body.statements, source, fileName)
                }
                else -> {}
            }
        }
    }

    /**
     * Collect property names assigned in constructor body via `this.propName = ...`
     */
    private fun collectConstructorAssignments(
        statements: List<Statement>,
        assigned: MutableSet<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ExpressionStatement -> {
                    collectThisAssignment(stmt.expression, assigned)
                }
                is IfStatement -> {
                    // Only if BOTH branches assign, consider it assigned
                    // For simplicity, check both branches but don't require both
                    collectConstructorAssignments(
                        listOf(stmt.thenStatement), assigned,
                    )
                    stmt.elseStatement?.let {
                        collectConstructorAssignments(listOf(it), assigned)
                    }
                }
                is Block -> collectConstructorAssignments(stmt.statements, assigned)
                else -> {}
            }
        }
    }

    private fun collectThisAssignment(expr: Expression, assigned: MutableSet<String>) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    val left = expr.left
                    if (left is PropertyAccessExpression) {
                        val base = left.expression
                        if (base is Identifier && base.text == "this") {
                            assigned.add(left.name.text)
                        }
                    }
                }
            }
            is CommaListExpression -> {
                expr.elements.forEach { collectThisAssignment(it, assigned) }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Constructor parameter references in class member initializers (TS2301)
    // -----------------------------------------------------------------------

    /**
     * Checks that instance member variable initializers do not reference identifiers
     * declared in the constructor (parameters or var declarations in the constructor body).
     * Emits TS2301 when such a reference is found.
     *
     * TypeScript fires this because field initializers run before the constructor body,
     * yet in the emitted JS they appear inside the constructor — so a reference that
     * looks like it refers to an outer-scope variable would silently bind to the
     * constructor parameter instead.
     */
    private fun checkConstructorParamInInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkConstructorParamInInitializersInStatements(
                result.sourceFile.statements, source, fileName
            )
        }
    }

    private fun checkConstructorParamInInitializersInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    checkConstructorParamInClassMembers(stmt.members, source, fileName)
                }
                is ModuleDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkConstructorParamInInitializersInStatements(
                            body.statements, source, fileName
                        )
                        else -> {}
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    stmt.body?.let {
                        checkConstructorParamInInitializersInStatements(it.statements, source, fileName)
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkConstructorParamInInitializersInExpr(decl.initializer, source, fileName)
                    }
                }
                is ExpressionStatement ->
                    checkConstructorParamInInitializersInExpr(stmt.expression, source, fileName)
                is ReturnStatement ->
                    checkConstructorParamInInitializersInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkConstructorParamInInitializersInExpr(
        expr: Expression?,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is ClassExpression -> {
                if (ModifierFlag.Declare !in expr.modifiers) {
                    checkConstructorParamInClassMembers(expr.members, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun checkConstructorParamInClassMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Collect names declared in the constructor (params + var declarations in body)
        val ctorDeclaredNames = mutableSetOf<String>()
        val constructor = members.filterIsInstance<Constructor>().firstOrNull()
        if (constructor != null) {
            // Collect parameter names (including binding patterns)
            for (param in constructor.parameters) {
                collectParamDeclaredNames(param.name, ctorDeclaredNames)
            }
            // Collect var declarations from constructor body
            constructor.body?.let { body ->
                collectVarDeclaredNamesInBlock(body.statements, ctorDeclaredNames)
            }
        }
        if (ctorDeclaredNames.isEmpty()) return

        // Check each non-static instance property initializer
        for (member in members) {
            if (member !is PropertyDeclaration) continue
            if (ModifierFlag.Static in member.modifiers) continue // static fields are OK
            val initializer = member.initializer ?: continue
            val memberName = (member.name as? Identifier)?.text ?: continue

            // Walk the initializer expression to find identifiers matching ctor-declared names
            checkExprForCtorParamRefs(initializer, memberName, ctorDeclaredNames, source, fileName)
        }
    }

    /** Collect declared names from a parameter binding pattern. */
    private fun collectParamDeclaredNames(name: Node, result: MutableSet<String>) {
        when (name) {
            is Identifier -> if (name.text != "this") result.add(name.text)
            is ObjectBindingPattern -> name.elements.forEach { elem ->
                collectParamDeclaredNames(elem.name, result)
            }
            is ArrayBindingPattern -> name.elements.forEach { elem ->
                if (elem is BindingElement) collectParamDeclaredNames(elem.name, result)
            }
            else -> {}
        }
    }

    /** Collect var-declared names from constructor body statements (hoisted vars). */
    private fun collectVarDeclaredNamesInBlock(
        statements: List<Statement>,
        result: MutableSet<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags != VarKeyword) continue // only var (not let/const)
                    for (decl in stmt.declarationList.declarations) {
                        collectParamDeclaredNames(decl.name, result)
                    }
                }
                is Block -> collectVarDeclaredNamesInBlock(stmt.statements, result)
                is IfStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.thenStatement), result)
                    stmt.elseStatement?.let { collectVarDeclaredNamesInBlock(listOf(it), result) }
                }
                is ForStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == VarKeyword) {
                        for (decl in init.declarations) collectParamDeclaredNames(decl.name, result)
                    }
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is ForInStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is ForOfStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is WhileStatement -> collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                is DoStatement -> collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                is TryStatement -> {
                    collectVarDeclaredNamesInBlock(stmt.tryBlock.statements, result)
                    stmt.catchClause?.block?.statements?.let { collectVarDeclaredNamesInBlock(it, result) }
                    stmt.finallyBlock?.statements?.let { collectVarDeclaredNamesInBlock(it, result) }
                }
                else -> {}
            }
        }
    }

    /**
     * Walk [expr] recursively to find any [Identifier] references matching [ctorNames].
     * When found, emit TS2301 pointing at the identifier position.
     * [memberName] is the class field name used in the diagnostic message.
     */
    private fun checkExprForCtorParamRefs(
        expr: Expression,
        memberName: String,
        ctorNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text in ctorNames) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Initializer of instance member variable '$memberName' cannot reference identifier '${expr.text}' declared in the constructor.",
                        category = DiagnosticCategory.Error,
                        code = 2301,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is BinaryExpression -> {
                checkExprForCtorParamRefs(expr.left, memberName, ctorNames, source, fileName)
                checkExprForCtorParamRefs(expr.right, memberName, ctorNames, source, fileName)
            }
            is CallExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
                expr.arguments.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            }
            is NewExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
                expr.arguments?.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            }
            is PropertyAccessExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is ElementAccessExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
                checkExprForCtorParamRefs(expr.argumentExpression, memberName, ctorNames, source, fileName)
            }
            is ParenthesizedExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is PrefixUnaryExpression ->
                checkExprForCtorParamRefs(expr.operand, memberName, ctorNames, source, fileName)
            is PostfixUnaryExpression ->
                checkExprForCtorParamRefs(expr.operand, memberName, ctorNames, source, fileName)
            is ConditionalExpression -> {
                checkExprForCtorParamRefs(expr.condition, memberName, ctorNames, source, fileName)
                checkExprForCtorParamRefs(expr.whenTrue, memberName, ctorNames, source, fileName)
                checkExprForCtorParamRefs(expr.whenFalse, memberName, ctorNames, source, fileName)
            }
            is ArrayLiteralExpression ->
                expr.elements.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            is ObjectLiteralExpression ->
                expr.properties.forEach { prop ->
                    when (prop) {
                        is PropertyAssignment ->
                            checkExprForCtorParamRefs(prop.initializer, memberName, ctorNames, source, fileName)
                        is ShorthandPropertyAssignment ->
                            if (prop.name.text in ctorNames) {
                                val start = prop.name.pos
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Initializer of instance member variable '$memberName' cannot reference identifier '${prop.name.text}' declared in the constructor.",
                                    category = DiagnosticCategory.Error,
                                    code = 2301,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = prop.name.text.length,
                                ))
                            }
                        is SpreadAssignment ->
                            checkExprForCtorParamRefs(prop.expression, memberName, ctorNames, source, fileName)
                        else -> {}
                    }
                }
            is ArrowFunction -> {
                // Arrow function: walk the body (recurse into inner lambdas too)
                // Local var declarations inside the body shadow outer constructor params — exclude them.
                val body = expr.body
                if (body is Block) {
                    val localVars = mutableSetOf<String>()
                    collectVarDeclaredNamesInBlock(body.statements, localVars)
                    // Also collect parameter names (they shadow ctor params in nested functions)
                    for (param in expr.parameters) collectParamDeclaredNames(param.name, localVars)
                    val innerCtorNames = if (localVars.isEmpty()) ctorNames else ctorNames - localVars
                    body.statements.forEach { stmt ->
                        checkExprForCtorParamRefsInStmt(stmt, memberName, innerCtorNames, source, fileName)
                    }
                } else if (body is Expression) {
                    checkExprForCtorParamRefs(body, memberName, ctorNames, source, fileName)
                }
            }
            is FunctionExpression -> {
                // Function expression body — walk it
                // Local var declarations inside the body shadow outer constructor params — exclude them.
                val bodyBlock = expr.body
                if (bodyBlock != null) {
                    val localVars = mutableSetOf<String>()
                    collectVarDeclaredNamesInBlock(bodyBlock.statements, localVars)
                    // Also collect parameter names
                    for (param in expr.parameters) collectParamDeclaredNames(param.name, localVars)
                    val innerCtorNames = if (localVars.isEmpty()) ctorNames else ctorNames - localVars
                    bodyBlock.statements.forEach { stmt ->
                        checkExprForCtorParamRefsInStmt(stmt, memberName, innerCtorNames, source, fileName)
                    }
                }
            }
            is TemplateExpression ->
                expr.templateSpans.forEach { span ->
                    checkExprForCtorParamRefs(span.expression, memberName, ctorNames, source, fileName)
                }
            is SpreadElement ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is TypeAssertionExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is AsExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is NonNullExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is TaggedTemplateExpression -> {
                checkExprForCtorParamRefs(expr.tag, memberName, ctorNames, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { span ->
                        checkExprForCtorParamRefs(span.expression, memberName, ctorNames, source, fileName)
                    }
                    else -> {}
                }
            }
            is AwaitExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is YieldExpression ->
                expr.expression?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            is DeleteExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is VoidExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is TypeOfExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, source, fileName)
            is CommaListExpression ->
                expr.elements.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            // Literals, ThisExpression, SuperExpression — no identifiers
            else -> {}
        }
    }

    /** Walk a statement recursively to check for constructor param references. */
    private fun checkExprForCtorParamRefsInStmt(
        stmt: Statement,
        memberName: String,
        ctorNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is ExpressionStatement ->
                checkExprForCtorParamRefs(stmt.expression, memberName, ctorNames, source, fileName)
            is ReturnStatement ->
                stmt.expression?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
            is VariableStatement ->
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, source, fileName) }
                }
            is IfStatement -> {
                checkExprForCtorParamRefs(stmt.expression, memberName, ctorNames, source, fileName)
                checkExprForCtorParamRefsInStmt(stmt.thenStatement, memberName, ctorNames, source, fileName)
                stmt.elseStatement?.let { checkExprForCtorParamRefsInStmt(it, memberName, ctorNames, source, fileName) }
            }
            is Block -> stmt.statements.forEach { checkExprForCtorParamRefsInStmt(it, memberName, ctorNames, source, fileName) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Implicit any checking (TS7006)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method parameters without type annotations when
     * noImplicitAny is enabled. Emits TS7006.
     */
    private fun checkImplicitAnyParameters() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                checkImplicitAnyInStatements(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    /**
     * Check for rest parameters without type annotations. Emits TS7019.
     * Fires by default (unlike TS7006 which requires noImplicitAny/strict),
     * unless strict is explicitly false. Mirrors the TS7006 behavior for
     * parameter properties in checkParamPropsInParams.
     *
     * Note: if noImplicitAny/strict is on, checkParamsForImplicitAny (called from
     * checkImplicitAnyParameters) already emits TS7019 for rest params. To avoid
     * double-emission, skip if checkImplicitAnyParameters already ran.
     */
    private fun checkImplicitAnyRestParameters() {
        // Skip if checkImplicitAnyParameters already handled everything (avoids double-emission)
        if (options.noImplicitAny || options.strict) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            // Skip JS files — TypeScript does not check implicit any in JS files
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")) continue
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkRestParamsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkRestParamsInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    checkRestParamsForImplicitAny(stmt.parameters, source, fileName)
                    stmt.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> checkRestParamsForImplicitAny(member.parameters, source, fileName)
                            is Constructor -> checkRestParamsForImplicitAny(member.parameters, source, fileName)
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) checkRestParamsForImplicitAny(member.parameters, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkRestParamsInStatements(body.statements, source, fileName)
                        else -> {}
                    }
                }
                is Block -> checkRestParamsInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkRestParamsInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkRestParamsInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkRestParamsInStatements(listOf(stmt.statement), source, fileName)
                is ReturnStatement -> stmt.expression?.let { checkRestParamsInExpr(it, source, fileName) }
                is ExpressionStatement -> checkRestParamsInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkRestParamsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkRestParamsForImplicitAny(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkRestParamsInStatements(body.statements, source, fileName)
                    is Expression -> checkRestParamsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkRestParamsForImplicitAny(expr.parameters, source, fileName)
                checkRestParamsInStatements(expr.body.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkRestParamsForImplicitAny(parameters: List<Parameter>, source: String, fileName: String) {
        // First pass: find untyped rest parameters and emit TS7019
        var hasUntypedRest = false
        for (param in parameters) {
            if (!param.dotDotDotToken) continue
            if (param.isCommentPlaceholder) continue
            if (param.type != null) continue  // has type annotation — no TS7019
            val name = param.name
            if (name !is Identifier) continue
            hasUntypedRest = true
            val displayName = if (name.text.isEmpty()) "(Missing)" else name.text
            // Span covers `...name` (3 chars for `...` + name length)
            val start = name.pos - 3  // position of `...`
            val length = 3 + name.text.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Rest parameter '$displayName' implicitly has an 'any[]' type.",
                category = DiagnosticCategory.Error,
                code = 7019,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
        // Second pass: when there's an untyped rest param in the list, also emit TS7006
        // for any untyped regular params (e.g. `function f(...x, y)` — y gets TS7006 too).
        // This matches TypeScript's behavior when parameter syntax errors are present.
        if (hasUntypedRest) {
            for (param in parameters) {
                if (param.dotDotDotToken) continue  // already handled above
                if (param.isCommentPlaceholder) continue
                if (param.type != null) continue
                if (param.initializer != null) continue
                val name = param.name
                if (name !is Identifier || name.text.isEmpty() || name.text == "this") continue
                if (param.modifiers.any { isParameterPropertyModifier(it) }) continue  // handled separately
                val start = name.pos
                val length = if (param.questionToken) name.text.length + 1 else name.text.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Parameter '${name.text}' implicitly has an 'any' type.",
                    category = DiagnosticCategory.Error,
                    code = 7006,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    /**
     * TS2370: A rest parameter must be of an array type.
     *
     * Fires for a rest parameter whose type annotation is clearly not array-like
     * (primitive keyword types: number, string, boolean, bigint, symbol, void,
     * never, null, undefined). Conservative — does not resolve TypeReferences
     * (which could be array-like via type aliases).
     *
     * Unlike TS7019, fires regardless of strict/noImplicitAny — it's a syntactic
     * error about the type shape, not an implicit-any diagnostic.
     */
    private fun checkNonArrayRestParameters() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            checkNonArrayRestInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkNonArrayRestInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    checkNonArrayRestParams(stmt.parameters, source, fileName)
                    stmt.body?.let { checkNonArrayRestInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                checkNonArrayRestParams(member.parameters, source, fileName)
                                member.body?.let { checkNonArrayRestInStatements(it.statements, source, fileName) }
                            }
                            is Constructor -> {
                                checkNonArrayRestParams(member.parameters, source, fileName)
                                member.body?.let { checkNonArrayRestInStatements(it.statements, source, fileName) }
                            }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) checkNonArrayRestParams(member.parameters, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkNonArrayRestInStatements(body.statements, source, fileName)
                        else -> {}
                    }
                }
                is Block -> checkNonArrayRestInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkNonArrayRestInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkNonArrayRestInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkNonArrayRestInStatements(listOf(stmt.statement), source, fileName)
                is ReturnStatement -> stmt.expression?.let { checkNonArrayRestInExpr(it, source, fileName) }
                is ExpressionStatement -> checkNonArrayRestInExpr(stmt.expression, source, fileName)
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { checkNonArrayRestInExpr(it, source, fileName) }
                    }
                }
                else -> {}
            }
        }
    }

    private fun checkNonArrayRestInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkNonArrayRestParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkNonArrayRestInStatements(body.statements, source, fileName)
                    is Expression -> checkNonArrayRestInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkNonArrayRestParams(expr.parameters, source, fileName)
                checkNonArrayRestInStatements(expr.body.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkNonArrayRestParams(parameters: List<Parameter>, source: String, fileName: String) {
        for (param in parameters) {
            if (!param.dotDotDotToken) continue
            if (param.isCommentPlaceholder) continue
            val typeNode = param.type ?: continue
            val keywordText = nonArrayKeywordText(typeNode) ?: continue
            val name = param.name
            if (name !is Identifier) continue
            val start = name.pos - 3  // position of `...`
            val length = (typeNode.pos + keywordText.length) - start
            if (length <= 0) continue
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "A rest parameter must be of an array type.",
                category = DiagnosticCategory.Error,
                code = 2370,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * TS7033: Property 'X' implicitly has type 'any', because its get accessor lacks
     * a return type annotation.
     *
     * Conservative: only fires for bodyless get accessors (abstract/interface form)
     * with no return type annotation. Full TS7033 coverage for getters with bodies
     * requires body return-type inference (not yet implemented).
     */
    private fun checkAbstractAccessorReturnTypes() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            checkAbstractAccessorInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkAbstractAccessorInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (m in stmt.members) {
                        if (m is GetAccessor && m.body == null && m.type == null) {
                            val nameNode = m.name as? Identifier ?: continue
                            val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                            diagnostics.add(Diagnostic(
                                message = "Property '${nameNode.text}' implicitly has type 'any', because its get accessor lacks a return type annotation.",
                                category = DiagnosticCategory.Error,
                                code = 7033,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = nameNode.pos,
                                length = nameNode.text.length,
                            ))
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAbstractAccessorInStatements(it.statements, source, fileName) }
                is Block -> checkAbstractAccessorInStatements(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    /**
     * TS18045: Properties with the 'accessor' modifier require target ES2015+.
     * Only fires in non-ambient contexts (ambient classes / declare namespaces suppress it).
     */
    private fun checkAccessorModifierTarget() {
        if (options.target >= ScriptTarget.ES2015) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAccessorModifierInStatements(result.sourceFile.statements, source, fileName, inAmbient = false)
        }
    }

    private fun checkAccessorModifierInStatements(stmts: List<Statement>, source: String, fileName: String, inAmbient: Boolean) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val classAmbient = inAmbient || ModifierFlag.Declare in stmt.modifiers
                    if (classAmbient) continue
                    for (m in stmt.members) {
                        if (m is PropertyDeclaration && ModifierFlag.Accessor in m.modifiers) {
                            val nameNode = m.name as? Identifier ?: continue
                            val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                            diagnostics.add(Diagnostic(
                                message = "Properties with the 'accessor' modifier are only available when targeting ECMAScript 2015 and higher.",
                                category = DiagnosticCategory.Error,
                                code = 18045,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = nameNode.pos,
                                length = nameNode.text.length,
                            ))
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val modAmbient = inAmbient || ModifierFlag.Declare in stmt.modifiers
                    (stmt.body as? ModuleBlock)?.let { checkAccessorModifierInStatements(it.statements, source, fileName, modAmbient) }
                }
                is Block -> checkAccessorModifierInStatements(stmt.statements, source, fileName, inAmbient)
                else -> {}
            }
        }
    }

    /**
     * TS2669: Augmentations for the global scope can only be directly nested in
     * external modules or ambient module declarations.
     *
     * Fires for `declare global { ... }` (or `global { ... }`) nested inside a
     * regular namespace — i.e. a ModuleDeclaration with Identifier name, not
     * `declare module "X"` (StringLiteralNode name).
     */
    private fun checkInvalidGlobalAugmentations() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            checkGlobalAugNested(result.sourceFile.statements, source, fileName, insideRegularNamespace = false)
        }
    }

    private fun checkGlobalAugNested(
        stmts: List<Statement>, source: String, fileName: String,
        insideRegularNamespace: Boolean,
    ) {
        for (stmt in stmts) {
            if (stmt is ModuleDeclaration) {
                val nameNode = stmt.name
                val isGlobalBlock = nameNode is Identifier && nameNode.text == "global"
                if (isGlobalBlock && insideRegularNamespace) {
                    val start = nameNode.pos
                    val length = 6  // "global"
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Augmentations for the global scope can only be directly nested in external modules or ambient module declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2669,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                    // TS2670 also fires when `global {}` lacks a `declare` modifier.
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        diagnostics.add(Diagnostic(
                            message = "Augmentations for the global scope should have 'declare' modifier unless they appear in already ambient context.",
                            category = DiagnosticCategory.Error,
                            code = 2670,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
                // Recurse into body; mark nested context.
                // A ModuleDeclaration is a "regular namespace" if its name is an Identifier
                // (not a StringLiteralNode for `declare module "X"`).
                val nowInsideRegular = insideRegularNamespace || (nameNode is Identifier && !isGlobalBlock)
                when (val body = stmt.body) {
                    is ModuleBlock -> checkGlobalAugNested(body.statements, source, fileName, nowInsideRegular)
                    is ModuleDeclaration -> checkGlobalAugNested(listOf(body), source, fileName, nowInsideRegular)
                    else -> {}
                }
            }
        }
    }

    /** Returns the keyword text if the type node is clearly not array-like; null otherwise. */
    private fun nonArrayKeywordText(typeNode: TypeNode): String? {
        if (typeNode !is KeywordTypeNode) return null
        return when (typeNode.kind) {
            SyntaxKind.NumberKeyword -> "number"
            SyntaxKind.StringKeyword -> "string"
            SyntaxKind.BooleanKeyword -> "boolean"
            SyntaxKind.BigIntKeyword -> "bigint"
            SyntaxKind.SymbolKeyword -> "symbol"
            SyntaxKind.VoidKeyword -> "void"
            SyntaxKind.NeverKeyword -> "never"
            SyntaxKind.NullKeyword -> "null"
            SyntaxKind.UndefinedKeyword -> "undefined"
            else -> null
        }
    }

    /**
     * Check for variables that implicitly have 'any' type — fires unconditionally:
     * 1. Ambient declarations (`declare var/let/const x`) without type annotation
     * 2. Block-scoped declarations (`const x` / `let x`) without type AND without initializer
     *    (these can't infer a type, so 'any' is implied).
     *
     * These fire regardless of noImplicitAny, unless strict is explicitly false.
     * Skip if noImplicitAny/strict is on (checkImplicitAnyParameters already handles them).
     */
    private fun checkImplicitAnyVariables() {
        // Skip if checkImplicitAnyParameters already handled these cases (avoids double-emission)
        if (options.noImplicitAny || options.strict) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")) continue
            val source = result.sourceFile.text
            checkImplicitAnyVarsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkImplicitAnyVarsInStatements(
        statements: List<Statement>, source: String, fileName: String
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    val isDeclare = ModifierFlag.Declare in stmt.modifiers
                    val isConst = stmt.declarationList.flags == SyntaxKind.ConstKeyword
                    for (decl in stmt.declarationList.declarations) {
                        if (decl.type != null) continue  // has type annotation — no TS7005
                        if (decl.initializer != null) continue  // initializer provides type inference — no TS7005
                        val name = decl.name as? Identifier ?: continue
                        if (name.text.isEmpty()) continue
                        // Case 1: ambient declaration without type or initializer
                        // Case 2: const without type AND without initializer (can't infer type)
                        // Note: `let x` (no type, no init) does NOT fire TS7005 — only `const`
                        val shouldEmit = isDeclare || isConst
                        if (!shouldEmit) continue
                        val start = name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Variable '${name.text}' implicitly has an 'any' type.",
                            category = DiagnosticCategory.Error,
                            code = 7005,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = name.text.length,
                        ))
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkImplicitAnyVarsInStatements(it.statements, source, fileName) }
                is ClassDeclaration -> {} // class members don't get TS7005
                is ModuleDeclaration -> when (val body = stmt.body) {
                    is ModuleBlock -> checkImplicitAnyVarsInStatements(body.statements, source, fileName)
                    else -> {}
                }
                is Block -> checkImplicitAnyVarsInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkImplicitAnyVarsInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkImplicitAnyVarsInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkImplicitAnyVarsInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkImplicitAnyInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        inAmbientContext: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    // Check params for TS7006 for ALL function declarations (both regular and declare)
                    // TypeScript emits TS7006 for untyped parameters in declare functions too
                    checkParamsForImplicitAny(stmt.parameters, source, fileName)
                    stmt.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
                    // TS7010 for bodyless functions is now in checkBodylessFunctionReturnTypes (unconditional)
                }
                is ClassDeclaration -> {
                    val isAmbientClass = ModifierFlag.Declare in stmt.modifiers || inAmbientContext
                    for (member in stmt.members) {
                        if (isAmbientClass) {
                            when (member) {
                                is MethodDeclaration -> {
                                    // Public method params in ambient classes get TS7006
                                    // Private methods: no TS7006, TypeScript doesn't check them
                                    if (ModifierFlag.Private !in member.modifiers) {
                                        checkParamsForImplicitAny(member.parameters, source, fileName)
                                    }
                                }
                                is PropertyDeclaration -> {
                                    // TS7008: Member without type annotation in ambient class (public only)
                                    if (member.type == null && member.initializer == null
                                        && ModifierFlag.Private !in member.modifiers) {
                                        val name = member.name
                                        if (name is Identifier && name.text.isNotEmpty()) {
                                            val start = name.pos
                                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                                            diagnostics.add(Diagnostic(
                                                message = "Member '${name.text}' implicitly has an 'any' type.",
                                                category = DiagnosticCategory.Error,
                                                code = 7008,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = start,
                                                length = name.text.length,
                                            ))
                                        }
                                    }
                                    // Property with function type gets TS7006 for both public AND private
                                    // e.g. `pub_f10: (x) => string` and `priv_f10: (x) => string`
                                    checkImplicitAnyInTypeAnnotation(member.type, source, fileName)
                                }
                                is Constructor -> {
                                    // Public (or unqualified) ambient constructors get TS7006 for untyped params.
                                    // Private constructors are skipped (TypeScript doesn't check them).
                                    if (ModifierFlag.Private !in member.modifiers) {
                                        checkParamsForImplicitAny(member.parameters, source, fileName)
                                    }
                                }
                                else -> {}
                            }
                        } else {
                            checkImplicitAnyInClassElement(member, source, fileName, stmt.members)
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    // Interface method signatures (and call signatures with empty name) get TS7006
                    // for parameters without type annotations. All methods in interfaces are checked
                    // (interfaces are implicitly ambient).
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> checkParamsForImplicitAny(member.parameters, source, fileName)
                            is PropertyDeclaration -> {
                                if (member.type == null && member.initializer == null) {
                                    // TS7008: Member implicitly has an 'any' type
                                    val name = member.name
                                    if (name is Identifier && name.text.isNotEmpty()) {
                                        val start = name.pos
                                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                                        diagnostics.add(Diagnostic(
                                            message = "Member '${name.text}' implicitly has an 'any' type.",
                                            category = DiagnosticCategory.Error,
                                            code = 7008,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = start,
                                            length = name.text.length,
                                        ))
                                    }
                                }
                                // Property with function type annotation: `f10: (x) => string`
                                // Parameters in function type annotations also get TS7006
                                checkImplicitAnyInTypeAnnotation(member.type, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        // TS7005: Variable implicitly has an 'any' type (ambient/declare declarations only)
                        if (decl.type == null && decl.initializer == null
                            && ModifierFlag.Declare in stmt.modifiers) {
                            val name = decl.name
                            if (name is Identifier && name.text.isNotEmpty()) {
                                val start = name.pos
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Variable '${name.text}' implicitly has an 'any' type.",
                                    category = DiagnosticCategory.Error,
                                    code = 7005,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = name.text.length,
                                ))
                            }
                        }
                        // Check function type annotation: `var f: (x) => string` → TS7006 for `x`
                        checkImplicitAnyInTypeAnnotation(decl.type, source, fileName)
                        decl.initializer?.let { checkImplicitAnyInExpr(it, source, fileName) }
                    }
                }
                is ExpressionStatement -> {
                    checkImplicitAnyInExpr(stmt.expression, source, fileName)
                }
                is ModuleDeclaration -> {
                    val childAmbient = inAmbientContext || ModifierFlag.Declare in stmt.modifiers
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkImplicitAnyInStatements(body.statements, source, fileName, childAmbient)
                        is ModuleDeclaration -> checkImplicitAnyInStatements(listOf(body), source, fileName, childAmbient)
                        else -> {}
                    }
                }
                is Block -> checkImplicitAnyInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkImplicitAnyInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkImplicitAnyInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    checkImplicitAnyInStatements(listOf(stmt.statement), source, fileName)
                }
                is ReturnStatement -> {
                    stmt.expression?.let { checkImplicitAnyInExpr(it, source, fileName) }
                }
                else -> {}
            }
        }
    }

    /**
     * Check function types in type annotations for implicit-any parameters.
     * e.g. `f10: (x) => string` — the `x` has no type annotation → TS7006.
     */
    private fun checkImplicitAnyInTypeAnnotation(type: TypeNode?, source: String, fileName: String) {
        when (type) {
            is FunctionType -> checkParamsForImplicitAny(type.parameters, source, fileName)
            else -> {}
        }
    }

    private fun checkImplicitAnyInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
        siblings: List<ClassElement> = emptyList(),
    ) {
        when (element) {
            is MethodDeclaration -> {
                checkParamsForImplicitAny(element.parameters, source, fileName)
                element.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
            }
            is Constructor -> {
                checkParamsForImplicitAny(element.parameters, source, fileName)
                element.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
            }
            is GetAccessor -> {
                element.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
            }
            is SetAccessor -> {
                // Setter value parameters are contextually typed from the getter return type.
                // Skip TS7006 for them — TypeScript never emits implicit-any for setter params.
                element.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
            }
            is PropertyDeclaration -> {
                // Check function type annotation: `pub_f10: (x) => string` → TS7006 for `x`
                checkImplicitAnyInTypeAnnotation(element.type, source, fileName)
                element.initializer?.let { checkImplicitAnyInExpr(it, source, fileName) }
                // TS7008: Static property without type annotation or initializer has implicit any.
                // Only static — instance properties may be assigned in the constructor, so we can't
                // flag them without flow analysis. Private is also skipped (TypeScript does not
                // emit TS7008 for private members). The caller gates on noImplicitAny.
                if (element.type == null && element.initializer == null
                    && ModifierFlag.Static in element.modifiers
                    && ModifierFlag.Private !in element.modifiers
                    && !element.exclamationToken) {
                    val name = element.name
                    if (name is Identifier && name.text.isNotEmpty()) {
                        // Skip if a static initializer block assigns to this property via `this.<name> = ...`
                        // (flow analysis approximation — any assignment suffices).
                        val assignedInStaticBlock = siblings.any { sib ->
                            sib is ClassStaticBlockDeclaration &&
                                blockAssignsToThisProperty(sib.body.statements, name.text)
                        }
                        if (!assignedInStaticBlock) {
                            val start = name.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Member '${name.text}' implicitly has an 'any' type.",
                                category = DiagnosticCategory.Error,
                                code = 7008,
                                fileName = fileName,
                                line = line, character = character,
                                start = start, length = name.text.length,
                            ))
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Does any statement in [statements] contain a `this.<propName> = ...` or `this.<propName> op= ...`
     * assignment? Used to suppress TS7008 for static class props when a sibling static initializer
     * block performs the assignment.
     */
    private fun blockAssignsToThisProperty(statements: List<Statement>, propName: String): Boolean {
        for (stmt in statements) {
            if (statementAssignsToThisProperty(stmt, propName)) return true
        }
        return false
    }

    private fun statementAssignsToThisProperty(stmt: Statement, propName: String): Boolean {
        return when (stmt) {
            is ExpressionStatement -> exprAssignsToThisProperty(stmt.expression, propName)
            is IfStatement -> statementAssignsToThisProperty(stmt.thenStatement, propName)
                || (stmt.elseStatement?.let { statementAssignsToThisProperty(it, propName) } == true)
            is Block -> blockAssignsToThisProperty(stmt.statements, propName)
            is ForStatement -> statementAssignsToThisProperty(stmt.statement, propName)
            is ForInStatement -> statementAssignsToThisProperty(stmt.statement, propName)
            is ForOfStatement -> statementAssignsToThisProperty(stmt.statement, propName)
            is WhileStatement -> statementAssignsToThisProperty(stmt.statement, propName)
            is DoStatement -> statementAssignsToThisProperty(stmt.statement, propName)
            is TryStatement -> blockAssignsToThisProperty(stmt.tryBlock.statements, propName)
                || (stmt.catchClause?.block?.statements?.let { blockAssignsToThisProperty(it, propName) } == true)
                || (stmt.finallyBlock?.statements?.let { blockAssignsToThisProperty(it, propName) } == true)
            else -> false
        }
    }

    private fun exprAssignsToThisProperty(expr: Expression, propName: String): Boolean {
        if (expr is BinaryExpression) {
            val op = expr.operator
            val isAssign = op == SyntaxKind.Equals
                || op == SyntaxKind.PlusEquals || op == SyntaxKind.MinusEquals
                || op == SyntaxKind.AsteriskEquals || op == SyntaxKind.SlashEquals
                || op == SyntaxKind.PercentEquals
                || op == SyntaxKind.AmpersandEquals || op == SyntaxKind.BarEquals
                || op == SyntaxKind.CaretEquals
                || op == SyntaxKind.LessThanLessThanEquals
                || op == SyntaxKind.GreaterThanGreaterThanEquals
                || op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals
                || op == SyntaxKind.AsteriskAsteriskEquals
                || op == SyntaxKind.AmpersandAmpersandEquals
                || op == SyntaxKind.BarBarEquals
                || op == SyntaxKind.QuestionQuestionEquals
            if (isAssign) {
                val target = expr.left
                if (target is PropertyAccessExpression
                    && target.expression is Identifier
                    && (target.expression as Identifier).text == "this"
                    && target.name is Identifier
                    && (target.name as Identifier).text == propName) {
                    return true
                }
            }
        }
        return false
    }

    /**
     * Cheap resolvability check for a call/new expression callee. Used by
     * checkImplicitAnyInExpr to decide whether to suppress TS7006 on callback
     * parameters. Conservative: when unsure (non-Identifier callee, property
     * access, etc.), return true so TS7006 stays suppressed — the current
     * default. Only a bare Identifier that resolves NOWHERE yields false.
     */
    private fun isCalleeResolvable(callee: Expression): Boolean {
        if (callee !is Identifier) return true
        val name = callee.text
        if (name.isEmpty()) return true
        if (name == "this" || name == "super") return true
        if (name in KEYWORD_IDENTIFIERS) return true
        if (globals.containsKey(name)) return true
        if (currentFileLocals?.containsKey(name) == true) return true
        if (name in KNOWN_GLOBALS) return true
        return false
    }

    private fun checkImplicitAnyInExpr(expr: Expression, source: String, fileName: String, contextuallyTyped: Boolean = false) {
        when (expr) {
            is ArrowFunction -> {
                if (!contextuallyTyped) {
                    checkParamsForImplicitAny(expr.parameters, source, fileName)
                }
                when (val body = expr.body) {
                    is Block -> checkImplicitAnyInStatements(body.statements, source, fileName)
                    is Expression -> checkImplicitAnyInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                if (!contextuallyTyped) {
                    checkParamsForImplicitAny(expr.parameters, source, fileName)
                }
                checkImplicitAnyInStatements(expr.body.statements, source, fileName)
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    checkImplicitAnyInClassElement(member, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            if (!contextuallyTyped) {
                                checkParamsForImplicitAny(prop.parameters, source, fileName)
                            }
                            prop.body?.let { checkImplicitAnyInStatements(it.statements, source, fileName) }
                        }
                        is PropertyAssignment -> {
                            // Propagate contextual typing to property initializers
                            checkImplicitAnyInExpr(prop.initializer, source, fileName, contextuallyTyped)
                        }
                        else -> {}
                    }
                }
            }
            is CallExpression -> {
                // Args get contextual typing from parameter types — BUT only if the
                // callee actually resolves. A call to an unresolved identifier has
                // no contextual signature, so callback params should still get TS7006.
                val ctxProp = isCalleeResolvable(expr.expression)
                for (arg in expr.arguments) {
                    checkImplicitAnyInExpr(arg, source, fileName, contextuallyTyped = ctxProp)
                }
            }
            is NewExpression -> {
                // Same as CallExpression — constructor args get contextual typing
                val ctxProp = isCalleeResolvable(expr.expression)
                for (arg in (expr.arguments ?: emptyList())) {
                    checkImplicitAnyInExpr(arg, source, fileName, contextuallyTyped = ctxProp)
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkImplicitAnyInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkImplicitAnyInExpr(current, source, fileName)
            }
            is ParenthesizedExpression -> checkImplicitAnyInExpr(expr.expression, source, fileName, contextuallyTyped)
            is ConditionalExpression -> {
                checkImplicitAnyInExpr(expr.whenTrue, source, fileName, contextuallyTyped)
                checkImplicitAnyInExpr(expr.whenFalse, source, fileName, contextuallyTyped)
            }
            is ArrayLiteralExpression -> {
                // Do NOT propagate contextual typing through arrays — array element type
                // depends on the array type parameter which may be a union (ambiguous)
                expr.elements.forEach { checkImplicitAnyInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkParamsForImplicitAny(
        parameters: List<Parameter>,
        source: String,
        fileName: String,
    ) {
        for (param in parameters) {
            if (param.isCommentPlaceholder) continue
            // Skip if parameter has type annotation or initializer
            if (param.type != null) continue
            if (param.initializer != null) continue
            // Skip `this` parameter
            val name = param.name
            if (name is Identifier && name.text == "this") continue
            // Skip error-recovery placeholders (empty name) unless it's a rest parameter
            // e.g. `function t1(...) {}` — TS7019 fires with name "(Missing)"
            if (name is Identifier && name.text.isEmpty() && !param.dotDotDotToken) continue
            // Skip destructured parameters (they get separate diagnostics)
            if (name !is Identifier) continue
            // Skip parameter properties (public/private/etc. modifiers) — TS7006 already
            // emitted in checkParamPropsInParams alongside TS2369 for them.
            if (param.modifiers.any { isParameterPropertyModifier(it) }) continue

            if (param.dotDotDotToken) {
                // TS7019: Rest parameter implicitly has an 'any[]' type
                val displayName = if (name is Identifier && name.text.isEmpty()) "(Missing)" else (name as Identifier).text
                // Span covers `...name` (3 chars for `...` + name length)
                val start = name.pos - 3 // position of `...`
                val length = 3 + (if (name is Identifier) name.text.length else 0)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Rest parameter '$displayName' implicitly has an 'any[]' type.",
                    category = DiagnosticCategory.Error,
                    code = 7019,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            } else {
                // TS7006: Parameter implicitly has an 'any' type
                val start = name.pos
                // Include the `?` token in the span if present (e.g., `x?` → length 2)
                val length = if (param.questionToken) name.text.length + 1 else name.text.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Parameter '${name.text}' implicitly has an 'any' type.",
                    category = DiagnosticCategory.Error,
                    code = 7006,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // Unresolved name checking (TS2304)
    // -----------------------------------------------------------------------

    /**
     * Scope for name resolution — tracks names declared at each scope level.
     * Lookup walks up the parent chain.
     */
    private class ClassContext(
        val className: String,
        val staticMembers: Set<String>,
        val instanceMembers: Set<String>,
        val inStaticContext: Boolean = false,
    )

    private class NameScope(
        val parent: NameScope?,
        val names: MutableSet<String> = mutableSetOf(),
        val hasArguments: Boolean = false,
        val classContext: ClassContext? = null,
        /** Names added as type parameters — excluded from TS2552 value-position suggestions. */
        val typeParamNames: MutableSet<String> = mutableSetOf(),
        /** Type-eligible names (classes, interfaces, type aliases, enums) declared in this scope. */
        val typeNames: MutableSet<String> = mutableSetOf(),
    ) {
        fun has(name: String): Boolean =
            name in names || (hasArguments && name == "arguments") || parent?.has(name) == true

        /** Returns true if [name] is a type parameter in this scope or any ancestor scope. */
        fun isTypeParam(name: String): Boolean =
            name in typeParamNames || parent?.isTypeParam(name) == true

        /** Add a type parameter name to both [names] and [typeParamNames]. */
        fun addTypeParam(name: String) {
            names.add(name)
            typeParamNames.add(name)
        }

        /** Add a type-eligible name (class/interface/type-alias/enum) — populates both [names] and [typeNames]. */
        fun addType(name: String) {
            names.add(name)
            typeNames.add(name)
        }

        fun child(
            hasArguments: Boolean = false,
            classContext: ClassContext? = this.classContext,
        ): NameScope = NameScope(parent = this, hasArguments = hasArguments, classContext = classContext)
    }

    /**
     * Check for references to names that cannot be resolved.
     * Emits TS2304: "Cannot find name 'X'."
     */
    private fun checkUnresolvedNames() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files without checkJs — TS2304/TS2552 not applicable
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            // File-level scope: binder locals + globals + known globals.
            // Skip ambient external modules (`declare module "foo"`) — their string-literal names
            // are NOT accessible as identifiers in code. TypeScript reports TS2304 for bare uses.
            val ambientExternalModuleNames = result.sourceFile.statements
                .filterIsInstance<ModuleDeclaration>()
                .filter { it.name is StringLiteralNode }
                .map { (it.name as StringLiteralNode).text }
                .toSet()
            val fileScope = NameScope(null)
            for ((name, _) in result.locals) {
                if (name !in ambientExternalModuleNames) fileScope.names.add(name)
            }
            for ((name, _) in globals) {
                // Don't include ambient external module names from globals — they come from
                // `declare module "foo"` declarations and are not accessible as identifiers.
                if (name !in ambientExternalModuleNames) fileScope.names.add(name)
            }
            fileScope.names.addAll(KNOWN_GLOBALS)

            checkUnresolvedInStatements(
                result.sourceFile.statements,
                fileScope,
                source,
                fileName,
            )
        }
    }

    private fun checkUnresolvedInStatements(
        statements: List<Statement>,
        parentScope: NameScope,
        source: String,
        fileName: String,
    ) {
        if (checkDepth > maxCheckDepth) return
        // Create child scope with declarations from this statement list
        val scope = parentScope.child()
        collectDeclaredNames(statements, scope)

        for (stmt in statements) {
            checkUnresolvedInStatement(stmt, scope, source, fileName)
        }
    }

    /**
     * Collect all names declared at this statement-list level.
     * Includes variables, functions, classes, interfaces, type aliases,
     * enums, namespaces, imports. Also hoists `var` declarations from
     * nested blocks/loops (since `var` is function-scoped, not block-scoped).
     */
    private fun collectDeclaredNames(statements: List<Statement>, scope: NameScope) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        addBindingName(decl.name, scope)
                    }
                }
                is FunctionDeclaration -> stmt.name?.let { scope.names.add(it.text) }
                is ClassDeclaration -> stmt.name?.let { scope.addType(it.text) }
                is InterfaceDeclaration -> scope.addType(stmt.name.text)
                is TypeAliasDeclaration -> scope.addType(stmt.name.text)
                is EnumDeclaration -> scope.addType(stmt.name.text)
                is ModuleDeclaration -> {
                    val name = stmt.name
                    when (name) {
                        is Identifier -> scope.names.add(name.text)
                        // StringLiteralNode = `declare module "foo"` (ambient external module).
                        // These are NOT accessible as identifiers in code — don't add to scope.
                        // TypeScript reports TS2304 for uses of the unquoted name as a value.
                        is StringLiteralNode -> { /* skip */ }
                        is PropertyAccessExpression -> {
                            // Dotted namespace: namespace m1.m2.m3 {} — extract leftmost segment
                            var cur: Expression = name
                            while (cur is PropertyAccessExpression) cur = cur.expression
                            if (cur is Identifier) scope.names.add(cur.text)
                        }
                        else -> {}
                    }
                }
                is ImportDeclaration -> {
                    val clause = stmt.importClause ?: return
                    clause.name?.let { scope.names.add(it.text) }
                    when (val bindings = clause.namedBindings) {
                        is NamedImports -> {
                            for (spec in bindings.elements) {
                                scope.names.add(spec.name.text)
                            }
                        }
                        is NamespaceImport -> scope.names.add(bindings.name.text)
                        else -> {}
                    }
                }
                is ImportEqualsDeclaration -> scope.names.add(stmt.name.text)
                is IfStatement -> {
                    // type/interface in non-block embedded body is function-scoped (hoisted)
                    collectEmbeddedTypeNames(stmt.thenStatement, scope)
                    stmt.elseStatement?.let { collectEmbeddedTypeNames(it, scope) }
                }
                is WhileStatement -> collectEmbeddedTypeNames(stmt.statement, scope)
                is DoStatement -> collectEmbeddedTypeNames(stmt.statement, scope)
                is ForStatement -> collectEmbeddedTypeNames(stmt.statement, scope)
                is ForInStatement -> collectEmbeddedTypeNames(stmt.statement, scope)
                is ForOfStatement -> collectEmbeddedTypeNames(stmt.statement, scope)
                else -> {}
            }
            // Hoist var declarations from nested blocks/loops
            collectHoistedVarNames(stmt, scope)
        }
    }

    /**
     * Collect type/interface names from a non-block embedded single-statement body.
     * When `type T = X` or `interface I {}` appears directly as the body of if/while/for
     * (not inside {}), it is function-scoped (hoisted to the enclosing function scope).
     */
    private fun collectEmbeddedTypeNames(stmt: Statement, scope: NameScope) {
        if (stmt is Block) return  // block-scoped types are handled normally
        var inner: Statement = stmt
        while (inner is LabeledStatement) inner = inner.statement
        when (inner) {
            is TypeAliasDeclaration -> scope.addType(inner.name.text)
            is InterfaceDeclaration -> scope.addType(inner.name.text)
            else -> {}
        }
    }

    /**
     * Recursively find `var` declarations in nested blocks, loops, if/else, etc.
     * Since `var` is function-scoped (not block-scoped), these names are visible
     * in the enclosing function/file scope. Does NOT recurse into functions
     * (which create their own scope).
     */
    private fun collectHoistedVarNames(stmt: Statement, scope: NameScope) {
        when (stmt) {
            is VariableStatement -> {
                if (stmt.declarationList.flags == SyntaxKind.VarKeyword) {
                    for (decl in stmt.declarationList.declarations) {
                        addBindingName(decl.name, scope)
                    }
                }
            }
            is Block -> stmt.statements.forEach { collectHoistedVarNames(it, scope) }
            is IfStatement -> {
                collectHoistedVarNames(stmt.thenStatement, scope)
                stmt.elseStatement?.let { collectHoistedVarNames(it, scope) }
            }
            is ForStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                    for (decl in init.declarations) addBindingName(decl.name, scope)
                }
                collectHoistedVarNames(stmt.statement, scope)
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                    for (decl in init.declarations) addBindingName(decl.name, scope)
                }
                collectHoistedVarNames(stmt.statement, scope)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                    for (decl in init.declarations) addBindingName(decl.name, scope)
                }
                collectHoistedVarNames(stmt.statement, scope)
            }
            is WhileStatement -> collectHoistedVarNames(stmt.statement, scope)
            is DoStatement -> collectHoistedVarNames(stmt.statement, scope)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach { collectHoistedVarNames(it, scope) }
                        is DefaultClause -> clause.statements.forEach { collectHoistedVarNames(it, scope) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectHoistedVarNames(it, scope) }
                stmt.catchClause?.block?.statements?.forEach { collectHoistedVarNames(it, scope) }
                stmt.finallyBlock?.statements?.forEach { collectHoistedVarNames(it, scope) }
            }
            is LabeledStatement -> collectHoistedVarNames(stmt.statement, scope)
            is WithStatement -> collectHoistedVarNames(stmt.statement, scope)
            // Do NOT recurse into functions/classes — they create their own scope
            else -> {}
        }
    }

    private fun addBindingName(name: Node, scope: NameScope) {
        when (name) {
            is Identifier -> scope.names.add(name.text)
            is ObjectBindingPattern -> {
                for (element in name.elements) {
                    addBindingName(element.name, scope)
                }
            }
            is ArrayBindingPattern -> {
                for (element in name.elements) {
                    if (element is BindingElement) {
                        addBindingName(element.name, scope)
                    }
                }
            }
            else -> {}
        }
    }

    private fun checkUnresolvedInStatement(
        stmt: Statement,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try { checkUnresolvedInStatementCore(stmt, scope, source, fileName) }
        finally { checkDepth-- }
    }

    private fun checkUnresolvedInStatementCore(
        stmt: Statement,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkUnresolvedInExpr(it, scope, source, fileName) }
                    decl.type?.let { checkUnresolvedInType(it, scope, source, fileName) }
                }
            }
            is ExpressionStatement -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let { checkUnresolvedInExpr(it, scope, source, fileName) }
            }
            is IfStatement -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
                checkUnresolvedInStatement(stmt.thenStatement, scope, source, fileName)
                stmt.elseStatement?.let { checkUnresolvedInStatement(it, scope, source, fileName) }
            }
            is Block -> {
                checkUnresolvedInStatements(stmt.statements, scope, source, fileName)
            }
            is ForStatement -> {
                val forScope = scope.child()
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            addBindingName(decl.name, forScope)
                            decl.initializer?.let { checkUnresolvedInExpr(it, forScope, source, fileName) }
                            decl.type?.let { checkUnresolvedInType(it, forScope, source, fileName) }
                        }
                    }
                    is Expression -> checkUnresolvedInExpr(init, forScope, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkUnresolvedInExpr(it, forScope, source, fileName) }
                stmt.incrementor?.let { checkUnresolvedInExpr(it, forScope, source, fileName) }
                checkUnresolvedInStatement(stmt.statement, forScope, source, fileName)
            }
            is ForInStatement -> {
                val forScope = scope.child()
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            addBindingName(decl.name, forScope)
                        }
                    }
                    else -> {}
                }
                checkUnresolvedInExpr(stmt.expression, forScope, source, fileName)
                checkUnresolvedInStatement(stmt.statement, forScope, source, fileName)
            }
            is ForOfStatement -> {
                val forScope = scope.child()
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            addBindingName(decl.name, forScope)
                        }
                    }
                    else -> {}
                }
                checkUnresolvedInExpr(stmt.expression, forScope, source, fileName)
                checkUnresolvedInStatement(stmt.statement, forScope, source, fileName)
            }
            is WhileStatement -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
                checkUnresolvedInStatement(stmt.statement, scope, source, fileName)
            }
            is DoStatement -> {
                checkUnresolvedInStatement(stmt.statement, scope, source, fileName)
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
            }
            is SwitchStatement -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkUnresolvedInExpr(clause.expression, scope, source, fileName)
                            checkUnresolvedInStatements(clause.statements, scope, source, fileName)
                        }
                        is DefaultClause -> {
                            checkUnresolvedInStatements(clause.statements, scope, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> {
                stmt.expression?.let { checkUnresolvedInExpr(it, scope, source, fileName) }
            }
            is TryStatement -> {
                checkUnresolvedInStatements(stmt.tryBlock.statements, scope, source, fileName)
                stmt.catchClause?.let { clause ->
                    val catchScope = scope.child()
                    clause.variableDeclaration?.let { decl ->
                        addBindingName(decl.name, catchScope)
                    }
                    checkUnresolvedInStatements(clause.block.statements, catchScope, source, fileName)
                }
                stmt.finallyBlock?.let {
                    checkUnresolvedInStatements(it.statements, scope, source, fileName)
                }
            }
            is LabeledStatement -> {
                checkUnresolvedInStatement(stmt.statement, scope, source, fileName)
            }
            is WithStatement -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
                // Inside with() body, name resolution is dynamic — skip checking
            }
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Regular functions break 'this' binding — clear class context
                val fnScope = scope.child(hasArguments = true, classContext = null)
                stmt.typeParameters?.forEach { fnScope.addTypeParam(it.name.text) }
                // Check type parameter constraints BEFORE adding params to scope:
                // TypeScript evaluates type constraints without function params in scope.
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                }
                addParamsToScope(stmt.parameters, fnScope)
                // For ES5 target, `let`/`const` is downleveled to `var` which is function-scoped
                // and hoisted, making it visible in parameter defaults. Suppress TS2304 for body
                // variables when targeting ES5 (matching TypeScript's behavior).
                if (options.target < ScriptTarget.ES2015) {
                    stmt.body?.let { collectDeclaredNames(it.statements, fnScope) }
                }
                stmt.type?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                for (param in stmt.parameters) {
                    param.type?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                    param.initializer?.let { checkUnresolvedInExpr(it, fnScope, source, fileName) }
                }
                stmt.body?.let {
                    checkUnresolvedInStatements(it.statements, fnScope, source, fileName)
                }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Check class decorators
                stmt.decorators?.forEach { checkUnresolvedInExpr(it.expression, scope, source, fileName) }
                val classCtx = buildClassContext(stmt, scope, fileName)
                val classScope = scope.child(classContext = classCtx)
                stmt.typeParameters?.forEach { classScope.addTypeParam(it.name.text) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, classScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, classScope, source, fileName) }
                }
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        checkUnresolvedInExpr(type.expression, classScope, source, fileName)
                        checkHeritageTypeArgCount(type, classScope, source, fileName)
                        type.typeArguments?.forEach { checkUnresolvedInType(it, classScope, source, fileName) }
                    }
                }
                val ctorParamNames = extractCtorParamNames(stmt.members)
                for (member in stmt.members) {
                    checkUnresolvedInClassElement(member, classScope, source, fileName, ctorParamNames)
                }
            }
            is InterfaceDeclaration -> {
                val ifaceScope = scope.child()
                stmt.typeParameters?.forEach { ifaceScope.addTypeParam(it.name.text) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                }
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        checkUnresolvedInExpr(type.expression, ifaceScope, source, fileName)
                        checkHeritageTypeArgCount(type, ifaceScope, source, fileName)
                        type.typeArguments?.forEach { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                    }
                }
                for (member in stmt.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            // Check computed property name (e.g. [x]: string — x must be in scope)
                            if (member.name is ComputedPropertyName) {
                                checkUnresolvedInExpr((member.name as ComputedPropertyName).expression, ifaceScope, source, fileName)
                            }
                            member.type?.let { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                        }
                        is MethodDeclaration -> {
                            val methodScope = ifaceScope.child()
                            member.typeParameters?.forEach { methodScope.addTypeParam(it.name.text) }
                            member.typeParameters?.forEach { tp ->
                                tp.constraint?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                                tp.default?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                            }
                            addParamsToScope(member.parameters, methodScope)
                            for (param in member.parameters) {
                                param.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                            }
                            member.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                        }
                        is IndexSignature -> {
                            member.type?.let { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                            for (param in member.parameters) {
                                param.type?.let { checkUnresolvedInType(it, ifaceScope, source, fileName) }
                            }
                        }
                        else -> {}
                    }
                }
            }
            is TypeAliasDeclaration -> {
                val typeScope = scope.child()
                stmt.typeParameters?.forEach { typeScope.addTypeParam(it.name.text) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, typeScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, typeScope, source, fileName) }
                }
                checkUnresolvedInType(stmt.type, typeScope, source, fileName)
            }
            is EnumDeclaration -> {
                // Enum member initializers can reference other members and the enum itself
                val enumScope = scope.child()
                // Add members from ALL merged enum declarations (via binder symbol)
                // Only add EnumMember symbols, not namespace exports that merged with the same symbol
                val enumResult = fileResults[fileName]
                val enumSymbol = enumResult?.nodeToSymbol?.get(nodeKey(stmt))
                if (enumSymbol?.exports != null) {
                    for ((exportName, sym) in enumSymbol.exports!!) {
                        if (sym.flags.hasAny(SymbolFlags.EnumMember)) {
                            enumScope.names.add(exportName)
                        }
                    }
                }
                // Also add members from this specific declaration (covers cases without binder symbol)
                for (member in stmt.members) {
                    val memberName = member.name
                    if (memberName is Identifier) enumScope.names.add(memberName.text)
                    else if (memberName is StringLiteralNode) enumScope.names.add(memberName.text)
                }
                for (member in stmt.members) {
                    member.initializer?.let { checkUnresolvedInExpr(it, enumScope, source, fileName) }
                }
            }
            is ModuleDeclaration -> {
                // Build namespace scope that includes merged exports from all declarations
                val nsScope = buildNamespaceScope(stmt, scope, fileName)
                if (ModifierFlag.Declare in stmt.modifiers) {
                    // In declare namespaces, skip TS2304 checks (ambient types expected)
                    // but still check heritage clauses for TS2314 (type argument count)
                    checkHeritageClausesInDeclareNamespace(stmt, nsScope, source, fileName)
                    return
                }
                when (val body = stmt.body) {
                    is ModuleBlock -> checkUnresolvedInStatements(body.statements, nsScope, source, fileName)
                    is ModuleDeclaration -> checkUnresolvedInStatement(body, nsScope, source, fileName)
                    else -> {}
                }
            }
            is ExportDeclaration -> {
                // export { X } — check that X exists
                if (stmt.moduleSpecifier == null) {
                    when (val clause = stmt.exportClause) {
                        is NamedExports -> {
                            for (spec in clause.elements) {
                                val name = spec.propertyName?.text ?: spec.name.text
                                val node = spec.propertyName ?: spec.name
                                checkIdentifierResolved(name, node, scope, source, fileName)
                            }
                        }
                        else -> {}
                    }
                }
            }
            is ExportAssignment -> {
                checkUnresolvedInExpr(stmt.expression, scope, source, fileName)
            }
            is ImportEqualsDeclaration -> {
                // Check the module reference for TS2503 (internal namespace alias)
                // Only for non-external (non-require) references: import a = b or import a = b.c
                val ref = stmt.moduleReference
                if (ref !is ExternalModuleReference) {
                    // Find the leftmost identifier in the module reference
                    val leftmost: Identifier? = when (ref) {
                        is Identifier -> ref
                        is QualifiedName -> {
                            var n: Node = ref
                            while (n is QualifiedName) n = n.left
                            n as? Identifier
                        }
                        else -> null
                    }
                    if (leftmost != null) {
                        val name = leftmost.text
                        // Skip invalid identifier starts (numbers, strings) — parser already emits TS1003
                        // Skip keyword identifiers (null, true, false, this, etc.)
                        val validIdStart = name.isNotEmpty() &&
                            (name[0] in 'A'..'Z' || name[0] in 'a'..'z' || name[0] == '_' || name[0] == '$')
                        // Skip synthetic literal refs produced by parser recovery for `import X = <literal>`
                        // (string literal → rawText starts with quote; `null` → text == "null").
                        val isSyntheticLiteral = name == "null" ||
                            (leftmost.rawText?.let { it.startsWith("\"") || it.startsWith("'") } == true)
                        if (validIdStart && name !in KEYWORD_IDENTIFIERS && !isSyntheticLiteral &&
                            (!scope.has(name) || name in VALUE_ONLY_GLOBALS || name == "undefined")) {
                            emitTS2503(name, leftmost, source, fileName)
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /** Extract constructor parameter names from a list of class members. */
    private fun extractCtorParamNames(members: List<ClassElement>): Set<String> {
        val ctor = members.filterIsInstance<Constructor>().firstOrNull() ?: return emptySet()
        val names = mutableSetOf<String>()
        collectCtorBodyVarNames(ctor, names)
        return names
    }

    /** Collect constructor param names and var-declared body names (for TS2301 scope suppression).
     * Collect constructor param names and var-declared body names (for TS2301 scope suppression). */
    private fun collectCtorBodyVarNames(ctor: Constructor, names: MutableSet<String>) {
        for (param in ctor.parameters) collectParamDeclaredNames(param.name, names)
        ctor.body?.let { collectVarDeclaredNamesInBlock(it.statements, names) }
    }

    private fun checkUnresolvedInClassElement(
        element: ClassElement,
        classScope: NameScope,
        source: String,
        fileName: String,
        ctorParamNames: Set<String> = emptySet(),
    ) {
        // Determine class context with correct static flag for the member
        val isStatic = when (element) {
            is PropertyDeclaration -> ModifierFlag.Static in element.modifiers
            is MethodDeclaration -> ModifierFlag.Static in element.modifiers
            is GetAccessor -> ModifierFlag.Static in element.modifiers
            is SetAccessor -> ModifierFlag.Static in element.modifiers
            is ClassStaticBlockDeclaration -> true
            else -> false
        }
        val memberClassCtx = classScope.classContext?.let {
            if (it.inStaticContext != isStatic) ClassContext(it.className, it.staticMembers, it.instanceMembers, isStatic)
            else it
        }
        when (element) {
            is PropertyDeclaration -> {
                val propScope = classScope.child(classContext = memberClassCtx)
                // Add constructor param names to suppress TS2304/TS2552 for names handled by TS2301
                // (TypeScript knows ctor params are "in scope" conceptually, but TS2301 handles the semantic error)
                if (!isStatic && ctorParamNames.isNotEmpty()) {
                    propScope.names.addAll(ctorParamNames)
                }
                // Check decorators
                element.decorators?.forEach { checkUnresolvedInExpr(it.expression, propScope, source, fileName) }
                // Check computed property name (e.g. [x]: string — x must be in scope)
                if (element.name is ComputedPropertyName) {
                    checkUnresolvedInExpr((element.name as ComputedPropertyName).expression, propScope, source, fileName)
                }
                element.type?.let { checkUnresolvedInType(it, propScope, source, fileName) }
                element.initializer?.let { checkUnresolvedInExpr(it, propScope, source, fileName) }
            }
            is MethodDeclaration -> {
                val methodScope = classScope.child(hasArguments = true, classContext = memberClassCtx)
                // Check decorators
                element.decorators?.forEach { checkUnresolvedInExpr(it.expression, methodScope, source, fileName) }
                element.typeParameters?.forEach { methodScope.addTypeParam(it.name.text) }
                element.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                }
                addParamsToScope(element.parameters, methodScope)
                for (param in element.parameters) {
                    // Check parameter decorators
                    param.decorators?.forEach { checkUnresolvedInExpr(it.expression, methodScope, source, fileName) }
                    param.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                    param.initializer?.let { checkUnresolvedInExpr(it, methodScope, source, fileName) }
                }
                element.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                element.body?.let {
                    checkUnresolvedInStatements(it.statements, methodScope, source, fileName)
                }
            }
            is IndexSignature -> {
                element.type?.let { checkUnresolvedInType(it, classScope, source, fileName) }
                for (param in element.parameters) {
                    param.type?.let { checkUnresolvedInType(it, classScope, source, fileName) }
                }
            }
            is Constructor -> {
                val ctorScope = classScope.child(hasArguments = true, classContext = memberClassCtx)
                addParamsToScope(element.parameters, ctorScope)
                for (param in element.parameters) {
                    // Check parameter decorators
                    param.decorators?.forEach { checkUnresolvedInExpr(it.expression, ctorScope, source, fileName) }
                    param.type?.let { checkUnresolvedInType(it, ctorScope, source, fileName) }
                    param.initializer?.let { checkUnresolvedInExpr(it, ctorScope, source, fileName) }
                }
                element.body?.let {
                    checkUnresolvedInStatements(it.statements, ctorScope, source, fileName)
                }
            }
            is GetAccessor -> {
                val getScope = classScope.child(hasArguments = true, classContext = memberClassCtx)
                element.type?.let { checkUnresolvedInType(it, getScope, source, fileName) }
                element.body?.let {
                    checkUnresolvedInStatements(it.statements, getScope, source, fileName)
                }
            }
            is SetAccessor -> {
                val setScope = classScope.child(hasArguments = true, classContext = memberClassCtx)
                addParamsToScope(element.parameters, setScope)
                for (param in element.parameters) {
                    param.type?.let { checkUnresolvedInType(it, setScope, source, fileName) }
                }
                element.body?.let {
                    checkUnresolvedInStatements(it.statements, setScope, source, fileName)
                }
            }
            is ClassStaticBlockDeclaration -> {
                val staticBlockScope = classScope.child(classContext = memberClassCtx)
                checkUnresolvedInStatements(element.body.statements, staticBlockScope, source, fileName)
            }
            else -> {}
        }
    }

    private fun addParamsToScope(params: List<Parameter>, scope: NameScope) {
        for (param in params) {
            addBindingName(param.name, scope)
        }
    }

    private fun checkUnresolvedInExpr(
        expr: Expression,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try { checkUnresolvedInExprCore(expr, scope, source, fileName) }
        finally { checkDepth-- }
    }

    private fun checkUnresolvedInExprCore(
        expr: Expression,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is Identifier -> {
                checkIdentifierResolved(expr.text, expr, scope, source, fileName)
            }
            is PropertyAccessExpression -> {
                // Only check the object, not the property name
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is ElementAccessExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
                checkUnresolvedInExpr(expr.argumentExpression, scope, source, fileName)
            }
            is CallExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
                expr.arguments.forEach { checkUnresolvedInExpr(it, scope, source, fileName) }
                expr.typeArguments?.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            }
            is NewExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
                expr.arguments?.forEach { checkUnresolvedInExpr(it, scope, source, fileName) }
                expr.typeArguments?.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUnresolvedInExpr(current.right, scope, source, fileName)
                    current = current.left
                }
                checkUnresolvedInExpr(current, scope, source, fileName)
            }
            is PrefixUnaryExpression -> {
                checkUnresolvedInExpr(expr.operand, scope, source, fileName)
            }
            is PostfixUnaryExpression -> {
                checkUnresolvedInExpr(expr.operand, scope, source, fileName)
            }
            is ConditionalExpression -> {
                checkUnresolvedInExpr(expr.condition, scope, source, fileName)
                checkUnresolvedInExpr(expr.whenTrue, scope, source, fileName)
                checkUnresolvedInExpr(expr.whenFalse, scope, source, fileName)
            }
            is ParenthesizedExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is TypeAssertionExpression -> {
                checkUnresolvedInType(expr.type, scope, source, fileName)
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is AsExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
                checkUnresolvedInType(expr.type, scope, source, fileName)
            }
            is NonNullExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is ArrowFunction -> {
                val arrowScope = scope.child(hasArguments = false)
                expr.typeParameters?.forEach { arrowScope.addTypeParam(it.name.text) }
                expr.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, arrowScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, arrowScope, source, fileName) }
                }
                addParamsToScope(expr.parameters, arrowScope)
                // For ES5 target, let/const is downleveled to var (hoisted) — suppress TS2304
                if (options.target < ScriptTarget.ES2015) {
                    if (expr.body is Block) collectDeclaredNames((expr.body as Block).statements, arrowScope)
                }
                for (param in expr.parameters) {
                    param.type?.let { checkUnresolvedInType(it, arrowScope, source, fileName) }
                    param.initializer?.let { checkUnresolvedInExpr(it, arrowScope, source, fileName) }
                }
                expr.type?.let { checkUnresolvedInType(it, arrowScope, source, fileName) }
                when (val body = expr.body) {
                    is Block -> checkUnresolvedInStatements(body.statements, arrowScope, source, fileName)
                    is Expression -> checkUnresolvedInExpr(body, arrowScope, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                // Regular functions break 'this' binding — clear class context
                val fnScope = scope.child(hasArguments = true, classContext = null)
                expr.name?.let { fnScope.names.add(it.text) }
                expr.typeParameters?.forEach { fnScope.addTypeParam(it.name.text) }
                addParamsToScope(expr.parameters, fnScope)
                // For ES5 target, let/const is downleveled to var (hoisted) — suppress TS2304
                if (options.target < ScriptTarget.ES2015) {
                    collectDeclaredNames(expr.body.statements, fnScope)
                }
                for (param in expr.parameters) {
                    param.type?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                    param.initializer?.let { checkUnresolvedInExpr(it, fnScope, source, fileName) }
                }
                expr.type?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                checkUnresolvedInStatements(expr.body.statements, fnScope, source, fileName)
            }
            is ClassExpression -> {
                val classCtx = buildClassContext(expr, scope, fileName)
                val classScope = scope.child(classContext = classCtx)
                // Class expression name is in scope within its own body
                expr.name?.let { classScope.names.add(it.text) }
                expr.typeParameters?.forEach { classScope.addTypeParam(it.name.text) }
                expr.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        checkUnresolvedInExpr(type.expression, classScope, source, fileName)
                        checkHeritageTypeArgCount(type, classScope, source, fileName)
                        type.typeArguments?.forEach { checkUnresolvedInType(it, classScope, source, fileName) }
                    }
                }
                val ctorParamNames = extractCtorParamNames(expr.members)
                for (member in expr.members) {
                    checkUnresolvedInClassElement(member, classScope, source, fileName, ctorParamNames)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            // Check computed property names
                            if (prop.name is ComputedPropertyName) {
                                checkUnresolvedInExpr(
                                    (prop.name as ComputedPropertyName).expression,
                                    scope, source, fileName
                                )
                            }
                            checkUnresolvedInExpr(prop.initializer, scope, source, fileName)
                        }
                        is ShorthandPropertyAssignment -> {
                            checkShorthandPropertyResolved(prop, scope, source, fileName)
                        }
                        is SpreadAssignment -> {
                            checkUnresolvedInExpr(prop.expression, scope, source, fileName)
                        }
                        is MethodDeclaration -> {
                            val methodScope = scope.child(hasArguments = true)
                            prop.typeParameters?.forEach { methodScope.addTypeParam(it.name.text) }
                            addParamsToScope(prop.parameters, methodScope)
                            for (param in prop.parameters) {
                                param.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                                param.initializer?.let { checkUnresolvedInExpr(it, methodScope, source, fileName) }
                            }
                            prop.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                            prop.body?.let {
                                checkUnresolvedInStatements(it.statements, methodScope, source, fileName)
                            }
                        }
                        is GetAccessor -> {
                            prop.body?.let {
                                checkUnresolvedInStatements(it.statements, scope, source, fileName)
                            }
                        }
                        is SetAccessor -> {
                            val setScope = scope.child(hasArguments = true)
                            addParamsToScope(prop.parameters, setScope)
                            prop.body?.let {
                                checkUnresolvedInStatements(it.statements, setScope, source, fileName)
                            }
                        }
                        else -> {}
                    }
                }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkUnresolvedInExpr(it, scope, source, fileName) }
            }
            is SpreadElement -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkUnresolvedInExpr(span.expression, scope, source, fileName)
                }
            }
            is TaggedTemplateExpression -> {
                checkUnresolvedInExpr(expr.tag, scope, source, fileName)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        for (span in template.templateSpans) {
                            checkUnresolvedInExpr(span.expression, scope, source, fileName)
                        }
                    }
                    else -> {}
                }
            }
            is TypeOfExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is VoidExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is DeleteExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is AwaitExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
            }
            is YieldExpression -> {
                expr.expression?.let { checkUnresolvedInExpr(it, scope, source, fileName) }
            }
            is CommaListExpression -> {
                expr.elements.forEach { checkUnresolvedInExpr(it, scope, source, fileName) }
            }
            is SatisfiesExpression -> {
                checkUnresolvedInExpr(expr.expression, scope, source, fileName)
                checkUnresolvedInType(expr.type, scope, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkUnresolvedInType(
        type: TypeNode,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try { checkUnresolvedInTypeCore(type, scope, source, fileName) }
        finally { checkDepth-- }
    }

    private fun checkUnresolvedInTypeCore(
        type: TypeNode,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        when (type) {
            is TypeReference -> {
                // Check the type name (Identifier or QualifiedName)
                checkTypeNameResolved(type.typeName, scope, source, fileName)
                // Check type argument count (TS2314)
                checkTypeArgCount(type, scope, source, fileName)
                // Check TS1099: empty type argument list
                if (type.typeArguments != null && type.typeArguments.isEmpty()) {
                    val ltIdx = source.indexOf("<>", type.typeName.pos)
                    if (ltIdx >= 0 && ltIdx < type.end) emitTS1099(ltIdx, source, fileName)
                }
                type.typeArguments?.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            }
            is ArrayType -> checkUnresolvedInType(type.elementType, scope, source, fileName)
            is TupleType -> type.elements.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            is UnionType -> type.types.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            is IntersectionType -> type.types.forEach { checkUnresolvedInType(it, scope, source, fileName) }
            is ParenthesizedType -> checkUnresolvedInType(type.type, scope, source, fileName)
            is TypeOperator -> checkUnresolvedInType(type.type, scope, source, fileName)
            is IndexedAccessType -> {
                checkUnresolvedInType(type.objectType, scope, source, fileName)
                checkUnresolvedInType(type.indexType, scope, source, fileName)
                checkIndexTypeValidity(type.indexType, source, fileName)
            }
            is MappedType -> {
                val mappedScope = scope.child()
                type.typeParameter?.let { mappedScope.addTypeParam(it.name.text) }
                type.type?.let { checkUnresolvedInType(it, mappedScope, source, fileName) }
                type.nameType?.let { checkUnresolvedInType(it, mappedScope, source, fileName) }
            }
            is ConditionalType -> {
                checkUnresolvedInType(type.checkType, scope, source, fileName)
                checkUnresolvedInType(type.extendsType, scope, source, fileName)
                // infer creates new type names in the true branch
                val trueScope = scope.child()
                collectInferTypeNames(type.extendsType, trueScope)
                checkUnresolvedInType(type.trueType, trueScope, source, fileName)
                checkUnresolvedInType(type.falseType, scope, source, fileName)
            }
            is FunctionType -> {
                val fnScope = scope.child()
                type.typeParameters?.forEach { fnScope.addTypeParam(it.name.text) }
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                }
                addParamsToScope(type.parameters, fnScope)
                for (param in type.parameters) {
                    param.type?.let { checkUnresolvedInType(it, fnScope, source, fileName) }
                }
                checkUnresolvedInType(type.type, fnScope, source, fileName)
            }
            is ConstructorType -> {
                val ctorScope = scope.child()
                type.typeParameters?.forEach { ctorScope.addTypeParam(it.name.text) }
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { checkUnresolvedInType(it, ctorScope, source, fileName) }
                    tp.default?.let { checkUnresolvedInType(it, ctorScope, source, fileName) }
                }
                addParamsToScope(type.parameters, ctorScope)
                for (param in type.parameters) {
                    param.type?.let { checkUnresolvedInType(it, ctorScope, source, fileName) }
                }
                checkUnresolvedInType(type.type, ctorScope, source, fileName)
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            member.type?.let { checkUnresolvedInType(it, scope, source, fileName) }
                        }
                        is MethodDeclaration -> {
                            val methodScope = scope.child()
                            member.typeParameters?.forEach { methodScope.addTypeParam(it.name.text) }
                            member.typeParameters?.forEach { tp ->
                                tp.constraint?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                                tp.default?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                            }
                            addParamsToScope(member.parameters, methodScope)
                            for (param in member.parameters) {
                                param.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                            }
                            member.type?.let { checkUnresolvedInType(it, methodScope, source, fileName) }
                        }
                        is IndexSignature -> {
                            member.type?.let { checkUnresolvedInType(it, scope, source, fileName) }
                            for (param in member.parameters) {
                                param.type?.let { checkUnresolvedInType(it, scope, source, fileName) }
                            }
                        }
                        is Constructor -> {
                            val ctorScope = scope.child()
                            addParamsToScope(member.parameters, ctorScope)
                            for (param in member.parameters) {
                                param.type?.let { checkUnresolvedInType(it, ctorScope, source, fileName) }
                            }
                        }
                        else -> {}
                    }
                }
            }
            is TypeQuery -> {
                // typeof expr — check the expression name
                checkTypeQueryName(type.exprName, scope, source, fileName)
            }
            is TemplateLiteralType -> {
                type.templateSpans.forEach { span ->
                    checkUnresolvedInType(span.type, scope, source, fileName)
                }
            }
            is InferType -> {
                // infer U — U is introduced, not referenced
            }
            is RestType -> {
                checkUnresolvedInType(type.type, scope, source, fileName)
            }
            is OptionalType -> {
                checkUnresolvedInType(type.type, scope, source, fileName)
            }
            is NamedTupleMember -> {
                checkUnresolvedInType(type.type, scope, source, fileName)
            }
            else -> {
                // LiteralType, KeywordType, ThisType, etc. — no name resolution needed
            }
        }
    }

    private fun collectInferTypeNames(type: TypeNode, scope: NameScope) {
        when (type) {
            is InferType -> scope.addTypeParam(type.typeParameter.name.text)
            is UnionType -> type.types.forEach { collectInferTypeNames(it, scope) }
            is IntersectionType -> type.types.forEach { collectInferTypeNames(it, scope) }
            is TypeReference -> type.typeArguments?.forEach { collectInferTypeNames(it, scope) }
            is ArrayType -> collectInferTypeNames(type.elementType, scope)
            is TupleType -> type.elements.forEach { collectInferTypeNames(it, scope) }
            is ParenthesizedType -> collectInferTypeNames(type.type, scope)
            is ConditionalType -> {
                collectInferTypeNames(type.checkType, scope)
                collectInferTypeNames(type.extendsType, scope)
                collectInferTypeNames(type.trueType, scope)
                collectInferTypeNames(type.falseType, scope)
            }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { collectInferTypeNames(it, scope) } }
                collectInferTypeNames(type.type, scope)
            }
            is RestType -> collectInferTypeNames(type.type, scope)
            is TypeOperator -> collectInferTypeNames(type.type, scope)
            is NamedTupleMember -> collectInferTypeNames(type.type, scope)
            is OptionalType -> collectInferTypeNames(type.type, scope)
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> member.type?.let { collectInferTypeNames(it, scope) }
                        is MethodDeclaration -> {
                            member.parameters.forEach { p -> p.type?.let { collectInferTypeNames(it, scope) } }
                            member.type?.let { collectInferTypeNames(it, scope) }
                        }
                        is IndexSignature -> {
                            member.parameters.forEach { p -> p.type?.let { collectInferTypeNames(it, scope) } }
                            member.type?.let { collectInferTypeNames(it, scope) }
                        }
                        is GetAccessor -> member.type?.let { collectInferTypeNames(it, scope) }
                        is SetAccessor -> member.parameters.forEach { p -> p.type?.let { collectInferTypeNames(it, scope) } }
                        else -> {}
                    }
                }
            }
            is MappedType -> {
                type.type?.let { collectInferTypeNames(it, scope) }
                type.nameType?.let { collectInferTypeNames(it, scope) }
            }
            is IndexedAccessType -> {
                collectInferTypeNames(type.objectType, scope)
                collectInferTypeNames(type.indexType, scope)
            }
            is TemplateLiteralType -> {
                type.templateSpans.forEach { collectInferTypeNames(it.type, scope) }
            }
            else -> {}
        }
    }

    /**
     * Check if a type reference name (Identifier or QualifiedName) resolves.
     * For Identifiers, checks scope resolution (TS2304).
     * For QualifiedNames, checks leftmost identifier resolves AND that each
     * segment exists in namespace exports (TS2694).
     */
    private fun checkTypeNameResolved(
        name: Node,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        when (name) {
            is Identifier -> {
                checkIdentifierResolved(name.text, name, scope, source, fileName, inTypePosition = true)
            }
            is QualifiedName -> {
                // Check the leftmost part of A.B.C
                var leftmost: Node = name
                while (leftmost is QualifiedName) leftmost = leftmost.left
                if (leftmost is Identifier) {
                    val lname = leftmost.text
                    // For qualified type references, the leftmost must be a namespace.
                    // If not found → TS2503 "Cannot find namespace 'x'" (not TS2304).
                    // Only emit for valid identifier starts (skip parser recovery artifacts).
                    val validIdStart = lname.isNotEmpty() &&
                        (lname[0] in 'A'..'Z' || lname[0] in 'a'..'z' || lname[0] == '_' || lname[0] == '$')
                    if (validIdStart && lname !in KEYWORD_IDENTIFIERS) {
                        if (!scope.has(lname)) {
                            emitTS2503(lname, leftmost, source, fileName)
                            return
                        }
                        // Leftmost IS in scope. If the resolved symbol is NOT a namespace/module,
                        // look for a similarly-named namespace and emit TS2833.
                        val leftSym = globals[lname] ?: currentFileLocals?.get(lname)
                        if (leftSym != null && !leftSym.flags.hasAny(SymbolFlags.Module)) {
                            val candidates = collectNamespaceNames(fileName)
                            val suggestion = getSpellingSuggestionFromNames(lname, candidates)
                            if (suggestion != null) {
                                emitTS2833(lname, leftmost, suggestion, source, fileName)
                                return
                            }
                        }
                    }
                }
                // Check QualifiedName segments for TS2694
                checkQualifiedNameExports(name, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Check that the index type of an IndexedAccessType is usable as an index.
     * Valid index types: string, number, symbol, their literal subtypes, unions/intersections of
     * valid types, keyof T, type parameters, type references, etc. Invalid at the syntax level:
     * tuple types, object type literals, function/constructor types, array types.
     * Emits TS2538: "Type 'X' cannot be used as an index type."
     */
    private fun checkIndexTypeValidity(indexType: TypeNode, source: String, fileName: String) {
        val invalid = when (indexType) {
            is TupleType -> true
            is TypeLiteral -> true
            is FunctionType -> true
            is ConstructorType -> true
            is ArrayType -> true
            else -> false
        }
        if (!invalid) return
        val display = formatTypeForDisplay(indexType) ?: return
        val start = indexType.pos
        val length = display.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type '$display' cannot be used as an index type.",
            category = DiagnosticCategory.Error,
            code = 2538,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** Collect namespace/module names visible from [fileName] (globals + current file locals). */
    private fun collectNamespaceNames(fileName: String): Set<String> {
        val result = mutableSetOf<String>()
        for ((name, sym) in globals) {
            if (sym.flags.hasAny(SymbolFlags.Module)) result.add(name)
        }
        val fileLocals = fileResults[fileName]?.locals
        if (fileLocals != null) {
            for ((name, sym) in fileLocals) {
                if (sym.flags.hasAny(SymbolFlags.Module)) result.add(name)
            }
        }
        return result
    }

    /** Emit TS2833 "Cannot find namespace 'X'. Did you mean 'Y'?" with TS2728 related info. */
    private fun emitTS2833(
        name: String, node: Node, suggestion: String,
        source: String, fileName: String,
    ) {
        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = findDeclarationRelatedInfo(suggestion, fileName, source)
        diagnostics.add(Diagnostic(
            message = "Cannot find namespace '$name'. Did you mean '$suggestion'?",
            category = DiagnosticCategory.Error,
            code = 2833,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOfNotNull(relatedInfo),
        ))
    }

    /** Emit TS2503: "Cannot find namespace 'X'." */
    private fun emitTS2503(name: String, node: Node, source: String, fileName: String) {
        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Cannot find namespace '$name'.",
            category = DiagnosticCategory.Error,
            code = 2503,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check that each segment of a QualifiedName resolves through namespace exports.
     * Given a root QualifiedName `Root` and a 0-based segment index `segIdx` (0=leftmost
     * Identifier, 1..N=successive `.right` identifiers), return the Identifier node at that
     * index. Used for TS2694 squiggle placement at a specific intermediate segment.
     */
    private fun findQualifiedNameSegment(root: QualifiedName, segIdx: Int): Identifier? {
        // Walk down-left to collect the chain of rights: [innermost Identifier, right1, right2, ..., root.right]
        val chain = mutableListOf<Identifier>()
        var node: Node = root
        while (node is QualifiedName) {
            chain.add(0, node.right)
            node = node.left
        }
        if (node is Identifier) chain.add(0, node) else return null
        return chain.getOrNull(segIdx)
    }

     /**
     * Emits TS2694: "Namespace 'X' has no exported member 'Y'."
     */
    private fun checkQualifiedNameExports(
        qn: QualifiedName,
        source: String,
        fileName: String,
    ) {
        // Build the namespace path segments and resolve through binder symbols
        val segments = mutableListOf<String>()
        val rightId = qn.right

        // Collect all segments from left to right
        fun collectSegments(node: Node) {
            when (node) {
                is Identifier -> segments.add(node.text)
                is QualifiedName -> {
                    collectSegments(node.left)
                    segments.add(node.right.text)
                }
                else -> return
            }
        }
        collectSegments(qn.left)
        // segments now has all path segments except the rightmost

        // Resolve through the namespace chain
        var symbol = globals[segments.firstOrNull() ?: return]
        if (symbol == null) {
            // Also check file-level locals
            for (result in binderResults) {
                symbol = result.locals[segments.first()]
                if (symbol != null) break
            }
        }
        if (symbol == null) return // leftmost doesn't resolve — already flagged by TS2304

        symbol = resolveAlias(symbol)

        // Walk through intermediate segments (skip first, that's the root namespace)
        for (i in 1 until segments.size) {
            val exports = symbol!!.exports ?: return // not a namespace
            val next = exports[segments[i]]
            if (next == null) {
                // Intermediate segment not found — emit TS2694 (or TS2724 with spelling)
                // Use resolved symbol's qualified name, not source-level alias
                val namespacePath = symbolToQualifiedName(symbol!!, fileName)
                emitTS2694(namespacePath, segments[i], rightId, source, fileName, exports = exports)
                return
            }
            // Intermediate segment is present but may not actually be EXPORTED from the
            // namespace (e.g. a local `import inner = ...` inside a regular namespace): the
            // member is in `exports` (how the binder tracks namespace-local symbols) but
            // isn't accessible externally. Emit TS2694 at the inaccessible segment.
            // Sub-namespace symbols (Module flag) are always accessible via dotted access,
            // including implicit-export forms like `namespace A.B.C {}`.
            val isIntermediateAccessible = next.flags.hasAny(SymbolFlags.Module) ||
                isMemberAccessible(next, symbol!!)
            if (!isIntermediateAccessible) {
                val namespacePath = symbolToQualifiedName(symbol!!, fileName)
                // Locate the specific Identifier for segments[i] in the QualifiedName so
                // the squiggle points to that segment, not the rightId.
                val segmentIdent = findQualifiedNameSegment(qn, i) ?: rightId
                emitTS2694(namespacePath, segments[i], segmentIdent, source, fileName)
                return
            }
            symbol = resolveAlias(next)
        }

        // Now check the final segment (rightmost identifier)
        val exports = symbol!!.exports
        if (exports == null) return // not a namespace, can't check
        val member = exports[rightId.text]
        // Use resolved symbol's qualified name, not source-level alias
        val namespacePath = symbolToQualifiedName(symbol!!, fileName)
        if (member == null) {
            // Member doesn't exist at all — try spelling suggestion (TS2724)
            emitTS2694(namespacePath, rightId.text, rightId, source, fileName, exports = exports)
        } else if (!isMemberAccessible(member, symbol!!)) {
            // Member exists but is not exported from a non-declare namespace
            emitTS2694(namespacePath, rightId.text, rightId, source, fileName)
        }
    }

    /**
     * Check if a member symbol is accessible from outside its namespace.
     * In `declare` namespaces, all members are implicitly exported.
     * In regular namespaces, only members with ExportValue flag are accessible.
     */
    private fun isMemberAccessible(member: Symbol, namespace: Symbol): Boolean {
        // If member has explicit export, always accessible
        if (member.flags.hasAny(SymbolFlags.ExportValue)) return true
        // Enum members are always accessible through the enum name (Kind.A)
        if (member.flags.hasAny(SymbolFlags.EnumMember)) return true
        // In declare namespaces (or namespaces inside declare contexts), all members are accessible
        if (isAmbientNamespace(namespace)) return true
        return false
    }

    /** Check if a namespace symbol is in an ambient (declare) context. */
    private fun isAmbientNamespace(symbol: Symbol): Boolean {
        for (decl in symbol.declarations) {
            if (decl is ModuleDeclaration && ModifierFlag.Declare in decl.modifiers) {
                return true
            }
        }
        // Check parent namespace — a namespace inside `declare module` is also ambient
        val parent = symbol.parent
        if (parent != null && parent.declarations.isNotEmpty()) {
            return isAmbientNamespace(parent)
        }
        return false
    }

    /**
     * Build a fully-qualified name for a symbol by walking up the parent chain.
     * For `namespace foo { namespace bar { namespace baz {} } }`, returns "foo.bar.baz".
     * For file-level module symbols (quoted names like '"file"'), returns the symbol name directly.
     *
     * When [fileName] is provided and the symbol is a top-level namespace in a module file,
     * prefixes with the quoted file base name (e.g., `"file".c`).
     */
    private fun symbolToQualifiedName(symbol: Symbol, fileName: String? = null): String {
        val parts = mutableListOf(symbol.name)
        var current = symbol.parent
        while (current != null && current.name.isNotEmpty() && !current.name.startsWith("\"")) {
            parts.add(current.name)
            current = current.parent
        }
        // For module-level symbols, include the quoted module name
        if (current != null && current.name.startsWith("\"")) {
            parts.add(current.name)
        } else if (current == null && fileName != null) {
            // Symbol has no parent — it's file-level.
            // If this file is an ES module (has ES import/export, NOT import=), TypeScript
            // formats it as "basename".nsName. import= declarations are legacy namespace
            // aliases and do NOT make a file a module for this purpose.
            val fileResult = binderResults.firstOrNull { it.sourceFile.fileName == fileName }
            if (fileResult != null && isEsModuleFile(fileResult.sourceFile.statements)) {
                // Build quoted base name: strip known extensions, strip directory prefix
                val baseName = fileName
                    .substringAfterLast("/")
                    .substringAfterLast("\\")
                    .removeSuffix(".d.ts")
                    .removeSuffix(".ts")
                    .removeSuffix(".tsx")
                    .removeSuffix(".mts")
                    .removeSuffix(".cts")
                    .removeSuffix(".js")
                    .removeSuffix(".jsx")
                parts.add("\"$baseName\"")
            }
        }
        parts.reverse()
        return parts.joinToString(".")
    }

    private fun emitTS2694(
        namespacePath: String,
        memberName: String,
        memberNode: Identifier,
        source: String,
        fileName: String,
        exports: Map<String, Symbol>? = null,
    ) {
        val start = memberNode.pos
        val length = memberName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Check for spelling suggestion (TS2724)
        if (exports != null) {
            val suggestion = getSpellingSuggestionFromNames(memberName, exports.keys)
            if (suggestion != null) {
                diagnostics.add(Diagnostic(
                    message = "'$namespacePath' has no exported member named '$memberName'. Did you mean '$suggestion'?",
                    category = DiagnosticCategory.Error,
                    code = 2724,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                return
            }
        }
        diagnostics.add(Diagnostic(
            message = "Namespace '$namespacePath' has no exported member '$memberName'.",
            category = DiagnosticCategory.Error,
            code = 2694,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check typeof expression names (e.g., `typeof x`, `typeof a.b.c`).
     */
    private fun checkTypeQueryName(
        name: Node,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        // typeof X in type position — the identifier is a value reference, so spelling
        // suggestions (TS2552) are allowed, but class-member suggestions (TS2662/TS2663) are not.
        // TypeScript emits plain TS2304 (not TS2663) for `typeof a` in class property types.
        // If X resolves to a TYPE-ONLY symbol (interface, type alias), emit TS2693 instead.
        when (name) {
            is Identifier -> {
                if (isTypeOnlySymbolName(name.text, fileName)) {
                    emitTS2693(name.text, name, source, fileName)
                    return
                }
                checkIdentifierResolved(name.text, name, scope, source, fileName, inTypePosition = false, suppressClassSuggestion = true)
            }
            is QualifiedName -> {
                var leftmost: Node = name
                while (leftmost is QualifiedName) leftmost = leftmost.left
                if (leftmost is Identifier) {
                    checkIdentifierResolved(leftmost.text, leftmost, scope, source, fileName, inTypePosition = false, suppressClassSuggestion = true)
                }
            }
            else -> {}
        }
    }

    /**
     * Returns true when [name] resolves to a symbol that has only a Type flag
     * (interface or type alias) and no Value flag — i.e. using it in a value
     * position (including inside `typeof`) is a TS2693 error.
     */
    private fun isTypeOnlySymbolName(name: String, fileName: String): Boolean {
        val result = fileResults[fileName]
        val sym = result?.locals?.get(name) ?: globals[name] ?: return false
        if (sym.flags.hasAny(SymbolFlags.Value)) return false
        // NamespaceModule with value exports is still usable as a value — skip.
        if (sym.flags.hasAny(SymbolFlags.Module)) {
            val exports = sym.exports
            if (exports != null && exports.values.any { it.flags.hasAny(SymbolFlags.Value) }) return false
        }
        return sym.flags.hasAny(SymbolFlags.Type)
    }

    /**
     * Build a scope for a namespace body that includes all merged exports.
     * This allows `namespace A { export class Foo {} } namespace A { new Foo() }`
     * to resolve `Foo` in the second block.
     */
    private fun buildNamespaceScope(stmt: ModuleDeclaration, parentScope: NameScope, fileName: String): NameScope {
        val result = fileResults[fileName] ?: return parentScope
        // For simple identifier names, look up the binder symbol directly
        val name = stmt.name
        val nsScope = parentScope.child()
        when (name) {
            is Identifier -> {
                // Look up the merged symbol for this namespace via nodeToSymbol
                val symbol = result.nodeToSymbol[nodeKey(stmt)]
                symbol?.exports?.forEach { (exportName, exportSym) ->
                    nsScope.names.add(exportName)
                    if (exportSym.flags.hasAny(SymbolFlags.Type)) nsScope.typeNames.add(exportName)
                }
            }
            is PropertyAccessExpression -> {
                // Dotted namespace A.B.C: collect exports of each ancestor namespace
                // (A, A.B, A.B.C) so names from parent namespaces are in scope.
                val segments = mutableListOf<String>()
                var cur: Expression = name
                while (cur is PropertyAccessExpression) {
                    segments.add(0, cur.name.text)
                    cur = cur.expression
                }
                if (cur is Identifier) segments.add(0, cur.text)
                var sym: Symbol? = null
                for ((i, seg) in segments.withIndex()) {
                    sym = if (i == 0) {
                        result.locals[seg] ?: globals[seg]
                    } else {
                        sym?.exports?.get(seg)
                    }
                    if (sym == null) break
                    // Add exports of each ancestor namespace to scope
                    sym.exports?.forEach { (exportName, exportSym) ->
                        nsScope.names.add(exportName)
                        if (exportSym.flags.hasAny(SymbolFlags.Type)) nsScope.typeNames.add(exportName)
                    }
                }
            }
            else -> {}
        }
        if (nsScope.names.isEmpty()) return parentScope
        return nsScope
    }

    /**
     * Build a ClassContext with static and instance member names for
     * TS2662/TS2663 did-you-mean diagnostics.
     */
    private fun buildClassContext(
        classLike: Node, // ClassDeclaration or ClassExpression
        scope: NameScope,
        fileName: String,
    ): ClassContext? {
        val className: String
        val members: List<ClassElement>
        val heritageClauses: List<HeritageClause>?
        when (classLike) {
            is ClassDeclaration -> {
                className = classLike.name?.text ?: return null
                members = classLike.members
                heritageClauses = classLike.heritageClauses
            }
            is ClassExpression -> {
                className = classLike.name?.text ?: return null
                members = classLike.members
                heritageClauses = classLike.heritageClauses
            }
            else -> return null
        }
        val staticMembers = mutableSetOf<String>()
        val instanceMembers = mutableSetOf<String>()
        collectClassMembers(members, staticMembers, instanceMembers)
        // Collect inherited members from base class if resolvable
        heritageClauses?.forEach { clause ->
            if (clause.token == SyntaxKind.ExtendsKeyword) {
                for (type in clause.types) {
                    val baseName = when (val expr = type.expression) {
                        is Identifier -> expr.text
                        else -> null
                    }
                    if (baseName != null) {
                        collectBaseClassMembers(baseName, scope, fileName, staticMembers, instanceMembers)
                    }
                }
            }
        }
        return ClassContext(className, staticMembers, instanceMembers)
    }

    private fun collectClassMembers(
        members: List<ClassElement>,
        staticMembers: MutableSet<String>,
        instanceMembers: MutableSet<String>,
    ) {
        for (member in members) {
            when (member) {
                is PropertyDeclaration -> {
                    val memberName = (member.name as? Identifier)?.text ?: continue
                    if (ModifierFlag.Static in member.modifiers) staticMembers.add(memberName)
                    else instanceMembers.add(memberName)
                }
                is MethodDeclaration -> {
                    val memberName = (member.name as? Identifier)?.text ?: continue
                    if (ModifierFlag.Static in member.modifiers) staticMembers.add(memberName)
                    else instanceMembers.add(memberName)
                }
                is GetAccessor -> {
                    val memberName = (member.name as? Identifier)?.text ?: continue
                    if (ModifierFlag.Static in member.modifiers) staticMembers.add(memberName)
                    else instanceMembers.add(memberName)
                }
                is SetAccessor -> {
                    val memberName = (member.name as? Identifier)?.text ?: continue
                    if (ModifierFlag.Static in member.modifiers) staticMembers.add(memberName)
                    else instanceMembers.add(memberName)
                }
                is Constructor -> {
                    // Constructor parameter properties (public/private/protected/readonly params)
                    // become instance fields on the class
                    for (param in member.parameters) {
                        val hasModifier = ModifierFlag.Public in param.modifiers ||
                            ModifierFlag.Private in param.modifiers ||
                            ModifierFlag.Protected in param.modifiers ||
                            ModifierFlag.Readonly in param.modifiers
                        if (hasModifier) {
                            val paramName = (param.name as? Identifier)?.text
                            if (paramName != null) instanceMembers.add(paramName)
                        }
                    }
                }
                else -> {}
            }
        }
    }

    private fun collectBaseClassMembers(
        baseName: String,
        scope: NameScope,
        fileName: String,
        staticMembers: MutableSet<String>,
        instanceMembers: MutableSet<String>,
        visited: MutableSet<String> = mutableSetOf(),
    ) {
        if (!visited.add(baseName)) return // circular inheritance
        // Try to find the base class in the binder
        val result = fileResults[fileName] ?: return
        val sym = result.locals[baseName] ?: return
        if (!sym.flags.hasAny(SymbolFlags.Class)) return
        // Find the class declaration node
        val classDecl = sym.declarations?.filterIsInstance<ClassDeclaration>()?.firstOrNull() ?: return
        collectClassMembers(classDecl.members, staticMembers, instanceMembers)
        // Recurse into base's heritage
        classDecl.heritageClauses?.forEach { clause ->
            if (clause.token == SyntaxKind.ExtendsKeyword) {
                for (type in clause.types) {
                    val nextBaseName = (type.expression as? Identifier)?.text
                    if (nextBaseName != null) {
                        collectBaseClassMembers(nextBaseName, scope, fileName, staticMembers, instanceMembers, visited)
                    }
                }
            }
        }
    }

    /**
     * Check if an identifier name can be resolved in the current scope chain.
     * If not, emit TS2662/TS2663 (did-you-mean) or TS2304.
     * @param inTypePosition When true, suppress TS2662/TS2663 suggestions (type positions use TS2304)
     */
    private fun checkIdentifierResolved(
        name: String,
        node: Node,
        scope: NameScope,
        source: String,
        fileName: String,
        inTypePosition: Boolean = false,
        suppressClassSuggestion: Boolean = false,
    ) {
        // Skip empty/synthetic names or non-identifier text from parser recovery
        if (name.isEmpty()) return
        if (name[0] !in 'A'..'Z' && name[0] !in 'a'..'z' && name[0] != '_' && name[0] != '$') return
        // Skip keywords that parse as identifiers in our AST
        if (name in KEYWORD_IDENTIFIERS) return
        // Skip well-known globals that don't need declaration
        if (scope.has(name)) return

        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        // Check for did-you-mean static/instance member suggestion
        // In type positions and typeof contexts, suppress TS2662/TS2663
        val classCtx = if (inTypePosition || suppressClassSuggestion) null else scope.classContext
        if (classCtx != null) {
            if (name in classCtx.staticMembers) {
                diagnostics.add(Diagnostic(
                    message = "Cannot find name '$name'. Did you mean the static member '${classCtx.className}.$name'?",
                    category = DiagnosticCategory.Error,
                    code = 2662,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                return
            }
            // Only suggest instance members when NOT in static context
            if (!classCtx.inStaticContext && name in classCtx.instanceMembers) {
                diagnostics.add(Diagnostic(
                    message = "Cannot find name '$name'. Did you mean the instance member 'this.$name'?",
                    category = DiagnosticCategory.Error,
                    code = 2663,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                return
            }
        }

        // Try to find a spelling suggestion (TS2552)
        // TypeScript limits to 10 suggestions per unique name per file (max10SpellingSuggestions)
        val countKey = "$fileName:$name"
        val currentCount = spellingSuggestionCounts[countKey] ?: 0
        if (currentCount < 10) {
            val suggestion = getSpellingSuggestion(name, scope, fileName, forTypePosition = inTypePosition)
            if (suggestion != null) {
                spellingSuggestionCounts[countKey] = currentCount + 1
                // Try to find the declaration position of the suggestion for TS2728 related info.
                // TypeScript omits TS2728 when the suggestion is a pure type alias — `findDeclarationRelatedInfo`
                // returns null for TypeAliasDeclaration.
                val relatedInfo = findDeclarationRelatedInfo(suggestion, fileName, source)
                diagnostics.add(Diagnostic(
                    message = "Cannot find name '$name'. Did you mean '$suggestion'?",
                    category = DiagnosticCategory.Error,
                    code = 2552,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    relatedInformation = if (relatedInfo != null) listOf(relatedInfo) else emptyList(),
                ))
                return
            }
        }

        diagnostics.add(Diagnostic(
            message = "Cannot find name '$name'.",
            category = DiagnosticCategory.Error,
            code = 2304,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Finds a spelling suggestion for an unresolved name.
     * Returns the closest name from scope if within edit-distance threshold.
     * Mirrors TypeScript's getSpellingSuggestion algorithm with weighted costs:
     * case-diff = 0.1, substitution = 2, insert/delete = 1.
     * Only suggests value-producing names (not type-alias/interface-only declarations).
     */
    private fun getSpellingSuggestion(
        name: String,
        scope: NameScope,
        fileName: String,
        forTypePosition: Boolean = false,
    ): String? {
        // Classify binder locals: pure-type (Class/Interface/TypeAlias/Enum/TypeParam without Value/Module)
        // vs pure-value (Variable/Function/etc. without any Type flag).
        val typeOnlyNames = mutableSetOf<String>()
        val typeEligibleLocalNames = mutableSetOf<String>()
        val binderResult = fileResults[fileName]
        if (binderResult != null) {
            for ((symName, sym) in binderResult.locals) {
                val hasValue = sym.flags.hasAny(SymbolFlags.Value or SymbolFlags.Module)
                val hasType = sym.flags.hasAny(SymbolFlags.Type)
                if (!hasValue) typeOnlyNames.add(symName)
                if (hasType) typeEligibleLocalNames.add(symName)
            }
        }

        // Collect candidate names. In value position, use the broad set (KNOWN_GLOBALS + scope chain).
        // In type position, restrict to type-eligible sources: KNOWN_GLOBALS (most lib entries are
        // interfaces/classes usable as types; pure value-only globals are filtered below), local types
        // from the binder, and type parameters in scope. Function parameters and block-scoped variables
        // in general scope.names are NOT included — they leak values like `x` as suggestions for type `X`.
        // Primitive type keywords (`string`, `unknown`, etc.) are intentionally omitted: TypeScript's
        // `getSuggestedSymbolForNonexistentType` looks up symbols, and primitive keywords have no symbol.
        val candidates = LinkedHashSet<String>()
        candidates.addAll(KNOWN_GLOBALS)
        if (forTypePosition) {
            candidates.addAll(typeEligibleLocalNames)
            var s: NameScope? = scope
            while (s != null) {
                candidates.addAll(s.typeParamNames)
                candidates.addAll(s.typeNames)
                s = s.parent
            }
        } else {
            var s: NameScope? = scope
            while (s != null) {
                candidates.addAll(s.names)
                s = s.parent
            }
        }

        // TypeScript's threshold: floor(name.length * 0.4) + 1
        // bestDistance starts at this value; candidates must have distance STRICTLY LESS THAN bestDistance
        // We use 10x integer scale throughout: 0.1 → 1, 1 → 10, 2 → 20
        val maximumLengthDifference = maxOf(2, (name.length * 0.34).toInt())
        var bestDistance10 = (name.length * 0.4).toInt() * 10 + 10  // (floor(n*0.4) + 1) * 10
        var bestSuggestion: String? = null

        for (candidate in candidates) {
            if (candidate == name) continue  // exact match already handled by scope.has()
            if (candidate.isEmpty()) continue  // skip empty candidates
            if (forTypePosition) {
                // Skip value-only globals like `parseInt`, `console`, `Math` — not usable as types
                if (candidate in VALUE_ONLY_GLOBALS) continue
            } else {
                // Don't suggest type-only declarations (type aliases, interfaces) in value position
                if (candidate in typeOnlyNames) continue
                // Don't suggest type parameters as replacements for value-position names
                if (scope.isTypeParam(candidate)) continue
            }
            // Skip candidates shorter than 3 unless case-insensitive match
            if (candidate.length < 3 && candidate.lowercase() != name.lowercase()) continue
            // Quick filter: skip if length difference is too large
            val lenDiff = kotlin.math.abs(candidate.length - name.length)
            if (lenDiff > maximumLengthDifference) continue

            val dist10 = weightedLevenshteinDistance10(name, candidate, bestDistance10)
            if (dist10 < bestDistance10) {
                bestDistance10 = dist10
                bestSuggestion = candidate
            }
        }
        return bestSuggestion
    }

    /**
     * Simple spelling suggestion among a set of names.
     * Uses Damerau-Levenshtein distance (same as TS2552) with TypeScript's threshold.
     */
    private fun getSpellingSuggestionFromNames(name: String, candidates: Set<String>): String? {
        var bestDistance10 = (name.length * 0.4).toInt() * 10 + 10
        var bestSuggestion: String? = null
        val maximumLengthDifference = maxOf(2, (name.length * 0.34).toInt())
        for (candidate in candidates) {
            if (candidate == name) continue
            if (candidate.isEmpty()) continue
            val lenDiff = kotlin.math.abs(candidate.length - name.length)
            if (lenDiff > maximumLengthDifference) continue
            val dist10 = weightedLevenshteinDistance10(name, candidate, bestDistance10)
            if (dist10 < bestDistance10) {
                bestDistance10 = dist10
                bestSuggestion = candidate
            }
        }
        return bestSuggestion
    }

    /**
     * Find the declaration position of [name] in the current file's binder locals,
     * or by scanning the AST for block-scoped let/const declarations not in the top-level locals.
     * Returns a TS2728 related diagnostic ("'name' is declared here.") if found, null otherwise.
     */
    private fun findDeclarationRelatedInfo(name: String, fileName: String, source: String): Diagnostic? {
        val result = fileResults[fileName]
        val localSym = result?.locals?.get(name)
            ?: result?.let { findSymbolInNestedNamespaces(name, it.locals.values) }
        // 16.4: fall back to globals for lib-declared names (e.g. `Function`, `Array`) so
        // that TS2552 "did you mean 'Function'" suggestions also get the TS2728 related info.
        // The lib path is rendered as `lib.es5.d.ts:--:--` per the BaselineFormatter convention.
        val symbol = localSym ?: globals[name]
        val declPos = if (symbol != null) {
            val decl = symbol.declarations?.firstOrNull() ?: symbol.valueDeclaration ?: return null
            when (decl) {
                is VariableDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                is FunctionDeclaration -> decl.name?.pos ?: decl.pos
                is ClassDeclaration -> decl.name?.pos ?: decl.pos
                is InterfaceDeclaration -> decl.name.pos
                // TypeScript omits TS2728 "declared here" when the suggestion is a pure type alias.
                is TypeAliasDeclaration -> return null
                is EnumDeclaration -> decl.name.pos
                is ModuleDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                is ImportSpecifier -> decl.name.pos
                is NamespaceImport -> decl.name.pos
                else -> decl.pos
            }
        } else {
            // Not in file-level locals — search AST for block-scoped let/const declaration
            if (result == null) return null
            findBlockScopedDeclPos(name, result.sourceFile.statements) ?: return null
        }
        val (resolvedFile, resolvedSource) = resolveDeclarationSourceFile(declPos)
        val declFile = resolvedFile ?: fileName
        val declSource = resolvedSource ?: source
        val isLib = isLibFileName(declFile)
        val (declLine, declChar) = if (isLib) {
            Pair(null as Int?, null as Int?)
        } else {
            val p = getLineAndCharacterOfPosition(declSource, declPos)
            Pair(p.first, p.second)
        }
        return Diagnostic(
            message = "'$name' is declared here.",
            category = DiagnosticCategory.Message,
            code = 2728,
            fileName = declFile,
            line = declLine,
            character = declChar,
            start = declPos,
            length = name.length,
        )
    }

    /**
     * Search nested namespace exports (BFS) for a symbol with [name]. Used to find
     * TS2728 "declared here" targets for classes/interfaces/enums declared inside namespaces.
     */
    private fun findSymbolInNestedNamespaces(name: String, topLevel: Collection<Symbol>): Symbol? {
        val queue = ArrayDeque<Symbol>()
        val visited = HashSet<Int>()
        queue.addAll(topLevel)
        while (queue.isNotEmpty()) {
            val sym = queue.removeFirst()
            if (!visited.add(sym.id)) continue
            val exports = sym.exports ?: continue
            exports[name]?.let { return it }
            for (child in exports.values) queue.addLast(child)
        }
        return null
    }

    /**
     * Recursively search [stmts] for the first `let`/`const` declaration of [name].
     * Returns the position of the identifier in the declaration, or null if not found.
     */
    private fun findBlockScopedDeclPos(name: String, stmts: List<Statement>): Int? {
        for (stmt in stmts) {
            val pos = findBlockScopedDeclPosInStmt(name, stmt)
            if (pos != null) return pos
        }
        return null
    }

    private fun findBlockScopedDeclPosInStmt(name: String, stmt: Statement): Int? {
        return when (stmt) {
            is VariableStatement -> {
                val kind = stmt.declarationList.flags
                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                    for (d in stmt.declarationList.declarations) {
                        val id = d.name as? Identifier
                        if (id != null && id.text == name) return id.pos
                    }
                }
                null
            }
            is Block -> findBlockScopedDeclPos(name, stmt.statements)
            is IfStatement -> {
                findBlockScopedDeclPosInStmt(name, stmt.thenStatement)
                    ?: stmt.elseStatement?.let { findBlockScopedDeclPosInStmt(name, it) }
            }
            is ForStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            is ForInStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            is ForOfStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            is WhileStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            is DoStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            is TryStatement -> {
                findBlockScopedDeclPos(name, stmt.tryBlock.statements)
                    ?: stmt.catchClause?.let { findBlockScopedDeclPos(name, it.block.statements) }
                    ?: stmt.finallyBlock?.let { findBlockScopedDeclPos(name, it.statements) }
            }
            is LabeledStatement -> findBlockScopedDeclPosInStmt(name, stmt.statement)
            else -> null
        }
    }

    /**
     * Compute weighted Levenshtein distance matching TypeScript's getSpellingSuggestion.
     * Cost model: case-only difference = 0.1, insert/delete = 1, other substitution = 2.
     * Uses 10x integer scaling to avoid floating point (so 0.1 → 1, 1 → 10, 2 → 20).
     * Returns the distance in 10x scale; callers use the same scale for thresholds.
     * [cutoff10] is the maximum acceptable distance in 10x scale (for early termination).
     */
    private fun weightedLevenshteinDistance10(a: String, b: String, cutoff10: Int): Int {
        if (a == b) return 0
        if (a.isEmpty()) return b.length * 10
        if (b.isEmpty()) return a.length * 10
        val m = a.length
        val n = b.length
        // dp[j] = distance(a[0..i-1], b[0..j-1]) in 10x scale
        var prev = IntArray(n + 1) { j -> j * 10 } // insert cost = 10 per char
        var curr = IntArray(n + 1)
        for (i in 1..m) {
            curr[0] = i * 10  // delete cost = 10 per char
            var rowMin = curr[0]
            for (j in 1..n) {
                val cost10 = when {
                    a[i - 1] == b[j - 1] -> 0                          // exact match
                    a[i - 1].lowercaseChar() == b[j - 1].lowercaseChar() -> 1  // case-only diff = 0.1 → 1
                    else -> 20                                          // substitution = 2 → 20
                }
                curr[j] = minOf(
                    prev[j] + 10,         // deletion (cost 1 → 10)
                    curr[j - 1] + 10,     // insertion (cost 1 → 10)
                    prev[j - 1] + cost10  // substitution
                )
                if (curr[j] < rowMin) rowMin = curr[j]
            }
            // Early termination: if entire row exceeds cutoff, no solution possible
            if (rowMin >= cutoff10) return cutoff10
            val tmp = prev
            prev = curr
            curr = tmp
        }
        return prev[n]
    }

    /**
     * Checks shorthand property assignment names. When the name is not in scope,
     * emits TS18004 instead of TS2304.
     */
    private fun checkShorthandPropertyResolved(
        prop: ShorthandPropertyAssignment,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val name = prop.name.text
        if (name.isEmpty()) return
        if (name[0] !in 'A'..'Z' && name[0] !in 'a'..'z' && name[0] != '_' && name[0] != '$') return
        if (name in KEYWORD_IDENTIFIERS) return
        if (scope.has(name)) return

        val start = prop.name.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        diagnostics.add(Diagnostic(
            message = "No value exists in scope for the shorthand property '$name'. Either declare one or provide an initializer.",
            category = DiagnosticCategory.Error,
            code = 18004,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // JSX implicit any checking (TS7026)
    // -----------------------------------------------------------------------

    /**
     * Check for JSX elements when no JSX.IntrinsicElements interface is defined.
     * Since we don't have lib.d.ts JSX type definitions, this fires for all JSX
     * elements when JSX is configured.
     * Emits TS7026 at both opening and closing tag names.
     */
    private fun checkJsxImplicitAny() {
        // Skip when jsxFactory/reactNamespace is explicitly set or jsx is preserve/react-native
        // (TypeScript doesn't check implicit any in these cases)
        if (options.jsxFactory != null) return
        if (options.reactNamespace != null) return
        val jsxMode = options.jsx?.lowercase()
        if (jsxMode == "preserve" || jsxMode == "react-native") return
        for (result in binderResults) {
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            // Only check .tsx/.jsx files
            if (!fileName.endsWith(".tsx") && !fileName.endsWith(".jsx")) continue
            checkJsxInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkJsxInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            checkJsxInStatement(stmt, source, fileName)
        }
    }

    private fun checkJsxInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkJsxInExpr(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkJsxInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkJsxInExpr(it, source, fileName) }
            is FunctionDeclaration -> {
                stmt.body?.let { checkJsxInStatements(it.statements, source, fileName) }
                for (param in stmt.parameters) {
                    param.initializer?.let { checkJsxInExpr(it, source, fileName) }
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            member.body?.let { checkJsxInStatements(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            member.body?.let { checkJsxInStatements(it.statements, source, fileName) }
                        }
                        is PropertyDeclaration -> {
                            member.initializer?.let { checkJsxInExpr(it, source, fileName) }
                        }
                        is GetAccessor -> {
                            member.body?.let { checkJsxInStatements(it.statements, source, fileName) }
                        }
                        is SetAccessor -> {
                            member.body?.let { checkJsxInStatements(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is Block -> checkJsxInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkJsxInExpr(stmt.expression, source, fileName)
                checkJsxInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkJsxInStatement(it, source, fileName) }
            }
            is ForStatement -> {
                stmt.condition?.let { checkJsxInExpr(it, source, fileName) }
                checkJsxInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> checkJsxInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkJsxInStatement(stmt.statement, source, fileName)
            is WhileStatement -> {
                checkJsxInExpr(stmt.expression, source, fileName)
                checkJsxInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkJsxInStatement(stmt.statement, source, fileName)
                checkJsxInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkJsxInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkJsxInExpr(clause.expression, source, fileName)
                            checkJsxInStatements(clause.statements, source, fileName)
                        }
                        is DefaultClause -> checkJsxInStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkJsxInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkJsxInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkJsxInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkJsxInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> checkJsxInStatements(body.statements, source, fileName)
                    else -> {}
                }
            }
            is ExportAssignment -> checkJsxInExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun checkJsxInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is JsxElement -> {
                emitJsx7026(expr.openingElement.tagName, source, fileName)
                // Check children for nested JSX
                for (child in expr.children) {
                    when (child) {
                        is Expression -> checkJsxInExpr(child, source, fileName)
                        is JsxExpressionContainer -> child.expression?.let { checkJsxInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
                emitJsx7026(expr.closingElement.tagName, source, fileName)
            }
            is JsxSelfClosingElement -> {
                emitJsx7026(expr.tagName, source, fileName)
            }
            is JsxFragment -> {
                for (child in expr.children) {
                    when (child) {
                        is Expression -> checkJsxInExpr(child, source, fileName)
                        is JsxExpressionContainer -> child.expression?.let { checkJsxInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkJsxInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkJsxInExpr(expr.condition, source, fileName)
                checkJsxInExpr(expr.whenTrue, source, fileName)
                checkJsxInExpr(expr.whenFalse, source, fileName)
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkJsxInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkJsxInExpr(current, source, fileName)
            }
            is CallExpression -> {
                checkJsxInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { checkJsxInExpr(it, source, fileName) }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkJsxInStatements(body.statements, source, fileName)
                    is Expression -> checkJsxInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkJsxInStatements(expr.body.statements, source, fileName)
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkJsxInExpr(it, source, fileName) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkJsxInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> checkJsxInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is AsExpression -> checkJsxInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkJsxInExpr(expr.expression, source, fileName)
            is CommaListExpression -> {
                expr.elements.forEach { checkJsxInExpr(it, source, fileName) }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkJsxInExpr(span.expression, source, fileName)
                }
            }
            is TaggedTemplateExpression -> {
                checkJsxInExpr(expr.tag, source, fileName)
            }
            is SpreadElement -> checkJsxInExpr(expr.expression, source, fileName)
            is AwaitExpression -> expr.expression?.let { checkJsxInExpr(it, source, fileName) }
            is YieldExpression -> expr.expression?.let { checkJsxInExpr(it, source, fileName) }
            else -> {}
        }
    }

    private fun emitJsx7026(tagName: Expression, source: String, fileName: String) {
        // TS7026 only fires for intrinsic (lowercase) element names like <div>, <span>.
        // Component references (uppercase) like <Comp> get TS2304 instead.
        // Namespace components like <Foo.Bar> skip TS7026 entirely.
        val intrinsicName = when (tagName) {
            is Identifier -> if (tagName.text.firstOrNull()?.isLowerCase() == true) tagName.text else null
            else -> null  // PropertyAccessExpression (Foo.Bar) or other — skip
        } ?: return
        val start = tagName.pos
        val length = intrinsicName.length
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "JSX element implicitly has type 'any' because no interface 'JSX.IntrinsicElements' exists.",
            category = DiagnosticCategory.Error,
            code = 7026,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // -----------------------------------------------------------------------
    // TS2403: Subsequent variable declarations must have the same type
    // -----------------------------------------------------------------------

    /**
     * Check that when `var` is declared multiple times in the same scope,
     * all declarations have compatible types.
     */
    private fun checkSubsequentVarTypes() {
        // Check file-level vars (in globals, which merges across files)
        checkSubsequentVarTypesInGlobals()
        // Check file-level and function-level vars per file
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Check top-level vars in this file
            val topLevelVars = mutableMapOf<String, MutableList<VariableDeclaration>>()
            collectVarDecls(result.sourceFile.statements, topLevelVars)
            for ((name, decls) in topLevelVars) {
                if (decls.size >= 2) checkVarDeclTypeConsistency(decls, name, source, fileName)
            }
            // Check function-level and namespace-level vars
            checkSubsequentVarTypesInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkSubsequentVarTypesInGlobals() {
        // Cross-file duplicate var type checking is deferred — too many FPs from
        // imports, path mapping, and module resolution creating merged variable symbols.
        // The function-level check handles single-file vars.
    }

    private fun checkSubsequentVarTypesInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    stmt.body?.let { body ->
                        // Collect all var declarations in this function
                        val localVars = mutableMapOf<String, MutableList<VariableDeclaration>>()
                        collectVarDecls(body.statements, localVars)
                        for ((name, decls) in localVars) {
                            if (decls.size >= 2) checkVarDeclTypeConsistency(decls, name, source, fileName)
                        }
                        // Recurse into nested functions
                        checkSubsequentVarTypesInStatements(body.statements, source, fileName)
                    }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        val body = when (member) {
                            is Constructor -> member.body
                            is MethodDeclaration -> member.body
                            else -> null
                        }
                        if (body != null) {
                            // Collect var declarations including parameters
                            val localVars = mutableMapOf<String, MutableList<VariableDeclaration>>()
                            // Add constructor/method parameters as pseudo-first-declarations
                            val params = when (member) {
                                is Constructor -> member.parameters
                                is MethodDeclaration -> member.parameters
                                else -> emptyList()
                            }
                            collectVarDecls(body.statements, localVars)
                            // For params that match var names, prepend param as first decl
                            for (param in params) {
                                val paramName = (param.name as? Identifier)?.text ?: continue
                                val varDecls = localVars[paramName] ?: continue
                                // Create a pseudo VariableDeclaration for the parameter to serve as "first"
                                // We'll handle this in checkVarDeclTypeConsistency by checking the first decl
                                // has the param's type annotation
                            }
                            for ((name, decls) in localVars) {
                                if (decls.size >= 2) checkVarDeclTypeConsistency(decls, name, source, fileName)
                            }
                            checkSubsequentVarTypesInStatements(body.statements, source, fileName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val localVars = mutableMapOf<String, MutableList<VariableDeclaration>>()
                        collectVarDecls(body.statements, localVars)
                        for ((name, decls) in localVars) {
                            if (decls.size >= 2) checkVarDeclTypeConsistency(decls, name, source, fileName)
                        }
                        checkSubsequentVarTypesInStatements(body.statements, source, fileName)
                    }
                }
                is Block -> checkSubsequentVarTypesInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkSubsequentVarTypesInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkSubsequentVarTypesInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                is TryStatement -> {
                    checkSubsequentVarTypesInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkSubsequentVarTypesInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkSubsequentVarTypesInStatements(it.statements, source, fileName) }
                }
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkSubsequentVarTypesInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkSubsequentVarTypesInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is LabeledStatement -> checkSubsequentVarTypesInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    /** Collect all `var` declarations from statements into a map by name. */
    private fun collectVarDecls(stmts: List<Statement>, result: MutableMap<String, MutableList<VariableDeclaration>>) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    // Only check `var` declarations, not let/const
                    if (stmt.declarationList.flags != SyntaxKind.VarKeyword) continue
                    for (decl in stmt.declarationList.declarations) {
                        val name = (decl.name as? Identifier)?.text ?: continue
                        result.getOrPut(name) { mutableListOf() }.add(decl)
                    }
                }
                // var declarations inside blocks are hoisted
                is Block -> collectVarDecls(stmt.statements, result)
                is IfStatement -> {
                    collectVarDecls(listOf(stmt.thenStatement), result)
                    stmt.elseStatement?.let { collectVarDecls(listOf(it), result) }
                }
                is ForStatement -> collectVarDecls(listOf(stmt.statement), result)
                is ForInStatement -> collectVarDecls(listOf(stmt.statement), result)
                is ForOfStatement -> collectVarDecls(listOf(stmt.statement), result)
                is WhileStatement -> collectVarDecls(listOf(stmt.statement), result)
                is DoStatement -> collectVarDecls(listOf(stmt.statement), result)
                is TryStatement -> {
                    collectVarDecls(stmt.tryBlock.statements, result)
                    stmt.catchClause?.block?.let { collectVarDecls(it.statements, result) }
                    stmt.finallyBlock?.let { collectVarDecls(it.statements, result) }
                }
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> collectVarDecls(clause.statements, result)
                            is DefaultClause -> collectVarDecls(clause.statements, result)
                            else -> {}
                        }
                    }
                }
                is LabeledStatement -> collectVarDecls(listOf(stmt.statement), result)
                else -> {}
            }
        }
    }

    /** Check that multiple var declarations for the same name have compatible types. */
    private fun checkVarDeclTypeConsistency(
        decls: List<VariableDeclaration>, varName: String,
        source: String, fileName: String,
    ) {
        val firstDecl = decls[0]
        val firstType = getVarDeclType(firstDecl) ?: return
        // Only check when the first type is simple (intrinsic, literal) — complex types
        // need structural comparison which we can't do reliably via string comparison
        if (!isSimpleTypeForTs2403(firstType)) return
        val firstTypeName = typeToString(firstType)
        val firstIsExported = isVarDeclExported(firstDecl)

        for (i in 1 until decls.size) {
            val decl = decls[i]
            // Skip when export status differs (TS2395 handles that case)
            if (isVarDeclExported(decl) != firstIsExported) continue
            val declType = getVarDeclType(decl) ?: continue
            if (!isSimpleTypeForTs2403(declType)) continue
            if (firstType === declType) continue
            val declTypeName = typeToString(declType)
            if (firstTypeName == declTypeName) continue
            val nameNode = decl.name as? Identifier ?: continue
            val start = nameNode.pos
            val length = nameNode.text.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            // Build TS6203 related info pointing to first declaration
            val firstNameNode = firstDecl.name as? Identifier
            val relatedInfo = if (firstNameNode != null) {
                val firstStart = firstNameNode.pos
                val firstLen = firstNameNode.text.length
                val (firstLine, firstChar) = getLineAndCharacterOfPosition(source, firstStart)
                listOf(Diagnostic(
                    message = "'$varName' was also declared here.",
                    category = DiagnosticCategory.Message,
                    code = 6203,
                    fileName = fileName,
                    line = firstLine,
                    character = firstChar,
                    start = firstStart,
                    length = firstLen,
                ))
            } else emptyList()
            diagnostics.add(Diagnostic(
                message = "Subsequent variable declarations must have the same type.  Variable '$varName' must be of type '$firstTypeName', but here has type '$declTypeName'.",
                category = DiagnosticCategory.Error,
                code = 2403,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
                relatedInformation = relatedInfo,
            ))
        }
    }

    /** Get the type of a var declaration from its type annotation or initializer, widened. */
    private fun getVarDeclType(decl: VariableDeclaration): Type? {
        // Type annotation takes priority
        decl.type?.let { return getTypeFromTypeNode(it) }
        // Infer from initializer — widen literal types to base types
        val init = decl.initializer ?: return anyType
        return widenType(getTypeOfExpression(init))
    }

    /** Widen a literal type to its base type (e.g., true → boolean, "hello" → string). */
    private fun widenType(type: Type): Type {
        return when (type) {
            is Type.StringLiteral -> stringType
            is Type.NumberLiteral -> numberType
            is Type.BigIntLiteral -> bigintType
            trueType, falseType -> booleanType
            else -> type
        }
    }

    /**
     * Infer the type of a variable from its initializer expression, with widening.
     * Returns `anyType` for expressions that can't be reliably inferred.
     * Skips null/undefined initializers (declare-then-assign patterns).
     */
    private fun inferTypeFromInitializer(init: Expression): Type {
        // Skip null/undefined — "declare then assign" pattern
        if (init is Identifier && (init.text == "null" || init.text == "undefined")) return anyType
        return try {
            val raw = getTypeOfExpression(init)
            if (raw === anyType || raw === errorType) anyType
            // Skip null/undefined/void inferred types
            else if (raw.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) anyType
            else widenType(raw)
        } catch (_: StackOverflowError) {
            anyType
        }
    }

    /** Check if a type is simple enough for reliable TS2403 string-based comparison. */
    private fun isSimpleTypeForTs2403(type: Type): Boolean {
        return when (type) {
            is Type.Intrinsic -> true  // number, string, boolean, void, null, undefined, any, etc.
            is Type.Object -> {
                // Function types (with call/construct signatures) are reliably comparable
                !type.callSignatures.isNullOrEmpty() || !type.constructSignatures.isNullOrEmpty()
            }
            else -> false
        }
    }

    /** Check if a var declaration is inside an export statement. */
    private fun isVarDeclExported(decl: VariableDeclaration): Boolean {
        // Check if the parent VariableStatement has export modifier
        // Since we don't have parent pointers, we search the surrounding file
        for (result in binderResults) {
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && decl in stmt.declarationList.declarations) {
                    return ModifierFlag.Export in stmt.modifiers
                }
                // Also check inside module/namespace blocks
                if (stmt is ModuleDeclaration) {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        for (innerStmt in body.statements) {
                            if (innerStmt is VariableStatement && decl in innerStmt.declarationList.declarations) {
                                return ModifierFlag.Export in innerStmt.modifiers
                            }
                        }
                    }
                }
            }
        }
        return false
    }

    // Duplicate identifier checking (TS2300)
    // -----------------------------------------------------------------------

    /**
     * Check for duplicate identifiers: duplicate type parameters,
     * duplicate function parameters, and duplicate declarations in the same scope.
     */
    private fun checkDuplicateIdentifiers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkDuplicatesInStatements(result.sourceFile.statements, source, fileName)
            // Check file-level duplicate declarations
            checkDuplicateDeclarations(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkDuplicatesInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            checkDuplicatesInStatement(stmt, source, fileName)
        }
    }

    private fun checkDuplicatesInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkDuplicateTypeParams(stmt.typeParameters, source, fileName)
                checkDuplicateParams(stmt.parameters, source, fileName)
                checkDuplicatesInType(stmt.type, source, fileName)
                for (param in stmt.parameters) checkDuplicatesInType(param.type, source, fileName)
                stmt.body?.let {
                    checkDuplicatesInStatements(it.statements, source, fileName)
                    // Check for duplicate declarations within function body
                    checkDuplicateDeclarations(it.statements, source, fileName)
                }
            }
            is ClassDeclaration -> {
                checkDuplicateTypeParams(stmt.typeParameters, source, fileName)
                for (member in stmt.members) {
                    checkDuplicatesInClassElement(member, source, fileName)
                }
                checkDuplicateClassMembers(stmt.members, source, fileName)
            }
            is InterfaceDeclaration -> {
                checkDuplicateTypeParams(stmt.typeParameters, source, fileName)
                checkDuplicateInterfaceMembers(stmt.members, source, fileName)
                for (member in stmt.members) {
                    checkDuplicatesInTypeMember(member, source, fileName)
                }
            }
            is TypeAliasDeclaration -> {
                checkDuplicateTypeParams(stmt.typeParameters, source, fileName)
                checkDuplicatesInType(stmt.type, source, fileName)
            }
            is EnumDeclaration -> {
                checkDuplicateEnumMembers(stmt, source, fileName)
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkDuplicatesInType(decl.type, source, fileName)
                    decl.initializer?.let { checkDuplicatesInExpr(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkDuplicatesInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkDuplicatesInExpr(it, source, fileName) }
            is Block -> checkDuplicatesInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkDuplicatesInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkDuplicatesInStatement(it, source, fileName) }
            }
            is ForStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkDuplicatesInStatements(clause.statements, source, fileName)
                        is DefaultClause -> checkDuplicatesInStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkDuplicatesInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkDuplicatesInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkDuplicatesInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> {
                        val ambient = ModifierFlag.Declare in stmt.modifiers
                        checkDuplicatesInStatements(body.statements, source, fileName)
                        checkDuplicateDeclarations(body.statements, source, fileName, isAmbientContext = ambient)
                    }
                    else -> {}
                }
            }
            is ExportDeclaration -> {
                val exportClause = stmt.exportClause
                if (exportClause is NamedExports) {
                    checkDuplicateExportSpecifiers(exportClause.elements, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun checkDuplicateExportSpecifiers(
        specifiers: List<ExportSpecifier>,
        source: String,
        fileName: String,
    ) {
        data class SpecInfo(val name: String, val nameNode: Identifier)
        val specs = mutableListOf<SpecInfo>()
        for (spec in specifiers) {
            specs.add(SpecInfo(spec.name.text, spec.name))
        }
        val byName = specs.groupBy { it.name }
        for ((_, group) in byName) {
            if (group.size >= 2) {
                for (spec in group) {
                    emitDuplicate2300(spec.name, spec.nameNode, source, fileName)
                }
            }
        }
    }

    private fun checkDuplicatesInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
    ) {
        when (element) {
            is MethodDeclaration -> {
                checkDuplicateTypeParams(element.typeParameters, source, fileName)
                checkDuplicateParams(element.parameters, source, fileName)
                element.body?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
            }
            is Constructor -> {
                checkDuplicateParams(element.parameters, source, fileName)
                element.body?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
            }
            is GetAccessor -> {
                element.body?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
            }
            is SetAccessor -> {
                checkDuplicateParams(element.parameters, source, fileName)
                element.body?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkDuplicatesInExpr(
        expr: Expression,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is ArrowFunction -> {
                checkDuplicateTypeParams(expr.typeParameters, source, fileName)
                checkDuplicateParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkDuplicatesInStatements(body.statements, source, fileName)
                    is Expression -> checkDuplicatesInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkDuplicateTypeParams(expr.typeParameters, source, fileName)
                checkDuplicateParams(expr.parameters, source, fileName)
                checkDuplicatesInStatements(expr.body.statements, source, fileName)
            }
            is ClassExpression -> {
                checkDuplicateTypeParams(expr.typeParameters, source, fileName)
                for (member in expr.members) {
                    checkDuplicatesInClassElement(member, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            checkDuplicateTypeParams(prop.typeParameters, source, fileName)
                            checkDuplicateParams(prop.parameters, source, fileName)
                            prop.body?.let { checkDuplicatesInStatements(it.statements, source, fileName) }
                        }
                        is PropertyAssignment -> {
                            checkDuplicatesInExpr(prop.initializer, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Check for duplicate type parameter names in a type parameter list.
     */
    private fun checkDuplicateTypeParams(
        typeParams: List<TypeParameter>?,
        source: String,
        fileName: String,
    ) {
        if (typeParams == null || typeParams.size < 2) return
        val seen = mutableSetOf<String>()
        for (tp in typeParams) {
            val name = tp.name.text
            if (!seen.add(name)) {
                emitDuplicate2300(name, tp.name, source, fileName)
            }
        }
    }

    /**
     * Check for duplicate parameter names in a parameter list.
     */
    private fun checkDuplicateParams(
        params: List<Parameter>,
        source: String,
        fileName: String,
    ) {
        val seen = mutableMapOf<String, Node>() // name → first occurrence
        val duplicates = mutableListOf<Pair<String, Node>>()
        for (param in params) {
            collectBindingNames(param.name, seen, duplicates)
        }
        // Report duplicates
        for ((name, node) in duplicates) {
            emitDuplicate2300(name, node, source, fileName)
        }
    }

    private fun collectBindingNames(
        name: Node,
        seen: MutableMap<String, Node>,
        duplicates: MutableList<Pair<String, Node>>,
    ) {
        when (name) {
            is Identifier -> {
                val prev = seen[name.text]
                if (prev != null) {
                    // Report both the first occurrence and this one
                    if (prev !== name) {
                        duplicates.add(name.text to prev)
                    }
                    duplicates.add(name.text to name)
                } else {
                    seen[name.text] = name
                }
            }
            is ObjectBindingPattern -> {
                for (element in name.elements) {
                    collectBindingNames(element.name, seen, duplicates)
                }
            }
            is ArrayBindingPattern -> {
                for (element in name.elements) {
                    if (element is BindingElement) {
                        collectBindingNames(element.name, seen, duplicates)
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Check for duplicate declarations at the same scope level.
     * Walks statements and tracks declaration names to detect incompatible duplicates.
     */
    private fun checkDuplicateDeclarations(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isAmbientContext: Boolean = false,
    ) {
        // Collect all declaration names with their kind and node
        data class DeclInfo(val name: String, val kind: String, val nameNode: Node, val stmt: Statement? = null)
        val decls = mutableListOf<DeclInfo>()

        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    val varKind = when (stmt.declarationList.flags) {
                        SyntaxKind.LetKeyword -> "let"
                        SyntaxKind.ConstKeyword -> "const"
                        else -> "var"
                    }
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier) {
                            decls.add(DeclInfo(name.text, varKind, name, stmt))
                        }
                    }
                }
                is FunctionDeclaration -> {
                    val name = stmt.name ?: continue
                    decls.add(DeclInfo(name.text, "function", name, stmt))
                }
                is ClassDeclaration -> {
                    val name = stmt.name ?: continue
                    decls.add(DeclInfo(name.text, "class", name, stmt))
                }
                is EnumDeclaration -> {
                    decls.add(DeclInfo(stmt.name.text, "enum", stmt.name, stmt))
                }
                is ExportAssignment -> {
                    if (stmt.isExportEquals) {
                        decls.add(DeclInfo("export=", "export=", stmt.expression))
                    }
                }
                is ModuleDeclaration -> {
                    val name = stmt.name
                    if (name is Identifier) {
                        decls.add(DeclInfo(name.text, "namespace", name, stmt))
                    }
                }
                is InterfaceDeclaration -> {
                    decls.add(DeclInfo(stmt.name.text, "interface", stmt.name, stmt))
                }
                is ImportEqualsDeclaration -> {
                    val name = stmt.name
                    decls.add(DeclInfo(name.text, "import=", name))
                }
                is ImportDeclaration -> {
                    val clause = stmt.importClause ?: continue
                    // Default binding: import X from "..."
                    clause.name?.let { decls.add(DeclInfo(it.text, "import", it)) }
                    // Named bindings
                    val nb = clause.namedBindings
                    when (nb) {
                        is NamespaceImport -> decls.add(DeclInfo(nb.name.text, "import", nb.name))
                        is NamedImports -> for (element in nb.elements) {
                            decls.add(DeclInfo(element.name.text, "import", element.name))
                        }
                        else -> {}
                    }
                }
                // Collect hoisted var declarations from for-loop initializers.
                // var is function-scoped, so `for (var x; ;)` creates a declaration at this level.
                is ForStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) {
                            val name = decl.name
                            if (name is Identifier) {
                                decls.add(DeclInfo(name.text, "var", name))
                            }
                        }
                    }
                }
                is ForInStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) {
                            val name = decl.name
                            if (name is Identifier) {
                                decls.add(DeclInfo(name.text, "var", name))
                            }
                        }
                    }
                }
                is ForOfStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) {
                            val name = decl.name
                            if (name is Identifier) {
                                decls.add(DeclInfo(name.text, "var", name))
                            }
                        }
                    }
                }
                else -> {}
            }
        }

        // Check for duplicate export= assignments
        val exportEquals = decls.filter { it.kind == "export=" }
        if (exportEquals.size >= 2) {
            for (decl in exportEquals) {
                val expr = decl.nameNode
                val len = if (expr is Identifier) expr.text.length else (expr.end - expr.pos)
                emitDuplicate2300("export=", expr, source, fileName, spanLength = len)
            }
        }

        // Group by name and check for incompatible declarations
        val byName = decls.groupBy { it.name }
        for ((_, group) in byName) {
            if (group.size < 2) continue
            val kinds = group.map { it.kind }.toSet()

            // Duplicate declarations → TS2300
            // Allowed: function overloads (multiple function declarations)
            // Allowed: namespace + namespace, namespace + class, namespace + function, namespace + enum
            // Allowed: interface + interface (declaration merging)
            // Error: class + class, class + function, class + enum, class + var
            // Error: var + class, var + function, var + enum
            // Error: enum + class, enum + var
            val hasVar = "var" in kinds
            val hasClass = "class" in kinds
            val hasEnum = "enum" in kinds
            val hasFunc = "function" in kinds
            val classCount = group.count { it.kind == "class" }

            // Check for duplicate import= declarations
            val hasImportEq = "import=" in kinds
            val importEqCount = group.count { it.kind == "import=" }
            if (hasImportEq && importEqCount >= 2) {
                for (decl in group.filter { it.kind == "import=" }) {
                    emitDuplicate2300(decl.name, decl.nameNode, source, fileName)
                }
            }

            // Check for duplicate import bindings (import X + import X → TS2300 on both)
            // Allowed: import + interface (value+type merge OK)
            val importCount = group.count { it.kind == "import" }
            if (importCount >= 2) {
                for (decl in group.filter { it.kind == "import" }) {
                    emitDuplicate2300(decl.name, decl.nameNode, source, fileName)
                }
            }

            // TS2432: In merged enums, only one declaration can omit initializer for first element.
            // Also check TS2300 for duplicate member names across merged enum declarations.
            if (hasEnum) {
                val enumDecls = group.filter { it.kind == "enum" }.mapNotNull { it.stmt as? EnumDeclaration }
                if (enumDecls.size >= 2) {
                    // TS2432: count how many declarations have their first member without an initializer
                    val declsWithUninitFirst = enumDecls.filter { decl ->
                        decl.members.isNotEmpty() && decl.members.first().initializer == null
                    }
                    if (declsWithUninitFirst.size >= 2) {
                        // Fire TS2432 on all but the first one that omits the initializer
                        for (decl in declsWithUninitFirst.drop(1)) {
                            val firstMember = decl.members.first()
                            val memberName = firstMember.name
                            val start = memberName.pos
                            val nameLen = when (memberName) {
                                is Identifier -> memberName.text.length
                                is StringLiteralNode -> memberName.text.length + 2
                                else -> memberName.end - memberName.pos
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "In an enum with multiple declarations, only one declaration can omit an initializer for its first enum element.",
                                category = DiagnosticCategory.Error,
                                code = 2432,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = nameLen,
                            ))
                        }
                    }
                    // TS2300 for duplicate member names across merged enum declarations
                    val allMemberNames = mutableMapOf<String, MutableList<Node>>()
                    for (decl in enumDecls) {
                        for (m in decl.members) {
                            val text = when (val n = m.name) {
                                is Identifier -> n.text
                                is StringLiteralNode -> n.text
                                else -> continue
                            }
                            allMemberNames.getOrPut(text) { mutableListOf() }.add(m.name)
                        }
                    }
                    for ((name, nodes) in allMemberNames) {
                        if (nodes.size >= 2) {
                            for (node in nodes) {
                                emitDuplicate2300(name, node, source, fileName)
                            }
                        }
                    }
                }
            }

            // TS2428: All declarations of interface must have identical type parameters.
            val hasInterface = "interface" in kinds
            if (hasInterface) {
                val ifaceDecls = group.filter { it.kind == "interface" }.mapNotNull { it.stmt as? InterfaceDeclaration }
                if (ifaceDecls.size >= 2) {
                    // Compare type parameter signatures: count and names
                    val firstDecl = ifaceDecls.first()
                    val firstSig = firstDecl.typeParameters?.map { it.name.text } ?: emptyList()
                    val mismatch = ifaceDecls.drop(1).any { decl ->
                        val sig = decl.typeParameters?.map { it.name.text } ?: emptyList()
                        sig.size != firstSig.size || sig != firstSig
                    }
                    if (mismatch) {
                        // Fire TS2428 on ALL declarations
                        for (decl in ifaceDecls) {
                            val start = decl.name.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "All declarations of '${decl.name.text}' must have identical type parameters.",
                                category = DiagnosticCategory.Error,
                                code = 2428,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.text.length,
                            ))
                        }
                    }
                }
            }

            // TS2567: Enum declarations can only merge with namespace or other enum declarations
            if (hasEnum && (hasClass || hasFunc || hasVar || hasInterface)) {
                for (decl in group) {
                    if (decl.kind == "namespace") continue // namespace+enum is allowed
                    val start = decl.nameNode.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Enum declarations can only merge with namespace or other enum declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2567,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = decl.name.length,
                    ))
                }
            } else {
                val hasNamespace = "namespace" in kinds

                // Check if namespace+var should be allowed:
                // A namespace can merge with a var when:
                // - The namespace is `declare` (ambient), OR
                // - The namespace only contains type declarations (interfaces, types) and no value exports
                // A `declare var` can merge with any namespace
                val namespaceVarAllowed = if (hasVar && hasNamespace) {
                    val allNamespacesValueFree = group.filter { it.kind == "namespace" }.all { decl ->
                        val modDecl = decl.stmt as? ModuleDeclaration ?: return@all true
                        !isNamespaceInstantiated(modDecl)
                    }
                    val allVarsDeclare = group.filter { it.kind == "var" }.all { decl ->
                        val varStmt = decl.stmt as? VariableStatement ?: return@all false
                        ModifierFlag.Declare in varStmt.modifiers
                    }
                    allNamespacesValueFree || allVarsDeclare
                } else false

                // TS2395: All declarations in a merged name must be uniformly exported or local.
                // Check per "declaration space": Type (interface/class), Value (class/function/var),
                // Namespace. Each space independently must have consistent export status.
                // TypeScript models: interface→Type, class→Type+Value, function→Value,
                // var→Value, namespace→Namespace. Only spaces with 2+ members are checked.
                // Type aliases (not tracked here) are Type-only and transparent.
                fun isExported(decl: DeclInfo): Boolean {
                    return when (val s = decl.stmt) {
                        is FunctionDeclaration -> ModifierFlag.Export in s.modifiers
                        is VariableStatement -> ModifierFlag.Export in s.modifiers
                        is ClassDeclaration -> ModifierFlag.Export in s.modifiers
                        is ModuleDeclaration -> ModifierFlag.Export in s.modifiers
                        is InterfaceDeclaration -> ModifierFlag.Export in s.modifiers
                        else -> false
                    }
                }
                // Classify each declaration into spaces
                val typeSpaceDecls = group.filter { it.kind == "interface" || it.kind == "class" }
                // For value space: exclude pure function overloads (handled by TS2383/TS2384/TS2385)
                val valueSpaceDecls = if (group.all { it.kind == "function" }) emptyList()
                    else group.filter { it.kind == "class" || it.kind == "function" || it.kind == "var" }
                val namespaceSpaceDecls = group.filter { it.kind == "namespace" }
                var emitted2395 = false
                for (spaceDecls in listOf(typeSpaceDecls, valueSpaceDecls, namespaceSpaceDecls)) {
                    if (spaceDecls.size < 2) continue
                    val exported = spaceDecls.filter { isExported(it) }
                    val nonExported = spaceDecls.filter { !isExported(it) }
                    if (exported.isNotEmpty() && nonExported.isNotEmpty()) {
                        // Emit TS2395 on all declarations in this group (both exported and not)
                        // Deduplicate: only emit once per declaration node
                        val all2395 = (exported + nonExported).distinctBy { it.nameNode.pos }
                        for (decl in all2395) {
                            val start = decl.nameNode.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Individual declarations in merged declaration '${decl.name}' must be all exported or all local.",
                                category = DiagnosticCategory.Error,
                                code = 2395,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.length,
                            ))
                        }
                        emitted2395 = true
                    }
                }
                if (emitted2395) continue // Don't also check for TS2300 etc.

                // TS2434: A namespace declaration cannot be located prior to a class or function
                // with which it is merged. Only fires for instantiated namespaces.
                if (hasNamespace && (hasClass || hasFunc) && !isAmbientContext) {
                    val namespaceDecls = group.filter { it.kind == "namespace" }
                    // Only non-declare class/function declarations trigger TS2434
                    val classFuncDecls = group.filter { decl ->
                        (decl.kind == "class" || decl.kind == "function") &&
                        when (val s = decl.stmt) {
                            is ClassDeclaration -> ModifierFlag.Declare !in s.modifiers
                            is FunctionDeclaration -> ModifierFlag.Declare !in s.modifiers
                            else -> true
                        }
                    }
                    if (classFuncDecls.isEmpty()) {} else {
                    // Find instantiated namespace decls that appear before any non-declare class/function decl
                    val firstClassFuncIdx = statements.indexOfFirst { s ->
                        classFuncDecls.any { it.stmt === s }
                    }
                    if (firstClassFuncIdx >= 0) {
                        for (nsDecl in namespaceDecls) {
                            val modDecl = nsDecl.stmt as? ModuleDeclaration ?: continue
                            // Only instantiated namespaces trigger TS2434
                            if (!isNamespaceInstantiated(modDecl)) continue
                            val nsIdx = statements.indexOfFirst { it === modDecl }
                            if (nsIdx >= 0 && nsIdx < firstClassFuncIdx) {
                                val start = nsDecl.nameNode.pos
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "A namespace declaration cannot be located prior to a class or function with which it is merged.",
                                    category = DiagnosticCategory.Error,
                                    code = 2434,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = nsDecl.name.length,
                                ))
                            }
                        }
                    }
                    }
                }

                // TS2393: Duplicate function implementation — two functions both with bodies
                // Fires regardless of other declaration kinds (alongside TS2300 if var/class also present)
                if (hasFunc) {
                    val funcDecls = group.filter { it.kind == "function" }
                    val funcBodies = funcDecls.filter { decl ->
                        val funcStmt = decl.stmt as? FunctionDeclaration ?: return@filter false
                        funcStmt.body != null
                    }
                    if (funcBodies.size >= 2) {
                        for (decl in funcBodies) {
                            val start = decl.nameNode.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Duplicate function implementation.",
                                category = DiagnosticCategory.Error,
                                code = 2393,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.length,
                            ))
                        }
                        // Only skip TS2300 check if ONLY functions are involved (pure overload scenario)
                        if (!hasClass && !hasVar && !hasNamespace) continue
                    }
                }

                // TS2813/TS2814: function + non-ambient class conflict
                if (hasClass && hasFunc) {
                    val funcDecls = group.filter { it.kind == "function" }
                    val classDecls = group.filter { it.kind == "class" }
                    val nonDeclFuncs = funcDecls.filter { decl ->
                        val funcStmt = decl.stmt as? FunctionDeclaration ?: return@filter false
                        ModifierFlag.Declare !in funcStmt.modifiers
                    }
                    val nonAmbientClasses = classDecls.filter { decl ->
                        val classStmt = decl.stmt as? ClassDeclaration ?: return@filter false
                        ModifierFlag.Declare !in classStmt.modifiers
                    }
                    if (nonDeclFuncs.isNotEmpty() && nonAmbientClasses.isNotEmpty()) {
                        // Any non-declare function (with or without body) + non-ambient class
                        // → TS2813 for class, TS2814 for function
                        // Related info points to the first non-ambient class
                        val relatedClass = nonAmbientClasses.first()
                        val classStart = relatedClass.nameNode.pos
                        val (classLine, classChar) = getLineAndCharacterOfPosition(source, classStart)
                        val relatedInfo = Diagnostic(
                            message = "Consider adding a 'declare' modifier to this class.",
                            category = DiagnosticCategory.Message,
                            code = 6506,
                            fileName = fileName,
                            line = classLine,
                            character = classChar,
                            start = classStart,
                            length = relatedClass.name.length,
                        )
                        // TS2814 for all non-declare functions
                        for (decl in nonDeclFuncs) {
                            val start = decl.nameNode.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Function with bodies can only merge with classes that are ambient.",
                                category = DiagnosticCategory.Error,
                                code = 2814,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.length,
                                relatedInformation = listOf(relatedInfo),
                            ))
                        }
                        // TS2813 for non-ambient classes
                        for (decl in nonAmbientClasses) {
                            val start = decl.nameNode.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Class declaration cannot implement overload list for '${decl.name}'.",
                                category = DiagnosticCategory.Error,
                                code = 2813,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.length,
                                relatedInformation = listOf(relatedInfo),
                            ))
                        }
                        // When there's also a var declaration, TS2300 fires for ALL (class+function+var)
                        // When it's only class+function (no var), skip TS2300 (only TS2813/TS2814)
                        if (!hasVar) continue
                        // Fall through to emit TS2300 below (isDuplicate check)
                    }

                    // Otherwise: declare function + declare class is a legal merge.
                    // declare class + non-declare function is ALSO legal (class provides type shape,
                    // function provides implementation — e.g. targetTypeTest1.ts).
                    // Only emit TS2300 for non-declare class + non-declare function (handled above via
                    // nonAmbientClasses check) or non-declare class + non-declare function without body.
                    val allClassesDeclare = classDecls.all { decl ->
                        val classStmt = decl.stmt as? ClassDeclaration ?: return@all false
                        ModifierFlag.Declare in classStmt.modifiers
                    }
                    // If all classes are ambient (declare), the function implements them — legal merge
                    if (!allClassesDeclare) {
                        // Non-ambient class + functions (without body triggers TS2813/TS2814 above)
                        // Non-ambient class + declare function → TS2300
                        for (decl in group) {
                            emitDuplicate2300(decl.name, decl.nameNode, source, fileName)
                        }
                    }
                    continue
                }

                // TS2323: Cannot redeclare exported variable 'X' — fires when multiple
                // exported var declarations have the same name (var+var is normally legal via
                // hoisting, but exported vars occupy a fixed binding slot)
                val varCount = group.count { it.kind == "var" }
                if (!hasClass && !hasFunc && !hasEnum && !hasNamespace && varCount >= 2) {
                    val allVarsExported = group.filter { it.kind == "var" }.all { decl ->
                        val varStmt = decl.stmt as? VariableStatement ?: return@all false
                        ModifierFlag.Export in varStmt.modifiers
                    }
                    if (allVarsExported) {
                        for (decl in group.filter { it.kind == "var" }) {
                            val start = decl.nameNode.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Cannot redeclare exported variable '${decl.name}'.",
                                category = DiagnosticCategory.Error,
                                code = 2323,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = decl.name.length,
                            ))
                        }
                        continue
                    }
                }

                // TS2451: Cannot redeclare block-scoped variable — fires when ALL
                // declarations are block-scoped (let or const). When there's a mix of
                // var and let/const, TS2300 fires instead (handled below).
                val hasLet = "let" in kinds
                val hasConst = "const" in kinds
                val hasBlockScoped = hasLet || hasConst
                val hasNamespace2 = "namespace" in kinds
                val allBlockScoped = hasBlockScoped && !hasVar && !hasFunc && !hasClass && !hasEnum && !hasInterface && !hasNamespace2
                if (allBlockScoped && group.size >= 2) {
                    for (decl in group) {
                        val start = decl.nameNode.pos
                        val nameLen = if (decl.nameNode is Identifier) (decl.nameNode as Identifier).text.length
                            else (decl.nameNode.end - decl.nameNode.pos)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Cannot redeclare block-scoped variable '${decl.name}'.",
                            category = DiagnosticCategory.Error,
                            code = 2451,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = nameLen,
                        ))
                    }
                    continue
                }
                // When block-scoped (let/const) mixes with var/class/func (not interface/namespace
                // which are legal merges), emit TS2451 for const/class conflicts, TS2300 for others
                if (hasBlockScoped && (hasVar || hasFunc || hasClass || hasEnum)) {
                    // TS2451 when block-scoped conflicts with class (TypeScript uses TS2451 for this)
                    val useTs2451 = hasBlockScoped && hasClass && !hasVar && !hasFunc && !hasEnum
                    for (decl in group) {
                        if (decl.kind == "interface" || decl.kind == "namespace") continue
                        if (useTs2451) {
                            val start = decl.nameNode.pos
                            val nameLen = if (decl.nameNode is Identifier) (decl.nameNode as Identifier).text.length
                                else (decl.nameNode.end - decl.nameNode.pos)
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Cannot redeclare block-scoped variable '${decl.name}'.",
                                category = DiagnosticCategory.Error,
                                code = 2451,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = nameLen,
                            ))
                        } else {
                            emitDuplicate2300(decl.name, decl.nameNode, source, fileName)
                        }
                    }
                    continue
                }

                val isDuplicate = (hasClass && classCount >= 2) ||
                        (hasVar && (hasClass || hasFunc)) ||
                        (hasVar && hasNamespace && !namespaceVarAllowed)

                if (isDuplicate) {
                    for (decl in group) {
                        emitDuplicate2300(decl.name, decl.nameNode, source, fileName)
                    }
                }
            }
        }
    }

    /**
     * Check for duplicate enum members: members with the same name.
     */
    private fun checkDuplicateEnumMembers(
        decl: EnumDeclaration,
        source: String,
        fileName: String,
    ) {
        data class MemberInfo(val name: String, val nameNode: Node)
        val members = mutableListOf<MemberInfo>()
        for (m in decl.members) {
            val name = m.name
            val text = when (name) {
                is Identifier -> name.text
                is StringLiteralNode -> name.text
                else -> continue
            }
            members.add(MemberInfo(text, name))
        }
        val byName = members.groupBy { it.name }
        for ((_, group) in byName) {
            if (group.size >= 2) {
                for (info in group) {
                    emitDuplicate2300(info.name, info.nameNode, source, fileName)
                }
            }
        }
        checkEnumMemberInitializers(decl, source, fileName)
    }

    /**
     * TS1061: "Enum member must have initializer."
     * Fires for a member with no initializer when the previous member's value
     * cannot be evaluated as a numeric constant (auto-increment impossible).
     * Matches TypeScript's behavior: skip `declare enum` (ambient, all members
     * must have initializers separately enforced).
     */
    private fun checkEnumMemberInitializers(
        decl: EnumDeclaration,
        source: String,
        fileName: String,
    ) {
        if (ModifierFlag.Declare in decl.modifiers) return
        // Track computed values from earlier members for reference resolution.
        val syntheticSymbol = Symbol(SymbolFlags.RegularEnum, decl.name.text)
        val localValues = mutableMapOf<String, ConstantValue>()
        var canAutoIncrement = true
        for (member in decl.members) {
            val memberName = when (val n = member.name) {
                is Identifier -> n.text
                is StringLiteralNode -> n.text
                is NumericLiteralNode -> n.text
                else -> null
            }
            if (member.initializer != null) {
                val v = evaluateEnumInitializer(member.initializer, localValues, syntheticSymbol)
                canAutoIncrement = v is ConstantValue.NumberValue
                if (v != null && memberName != null) localValues[memberName] = v
            } else {
                if (!canAutoIncrement) {
                    val nameNode = member.name
                    val (pos, length) = when (nameNode) {
                        is Identifier -> nameNode.pos to nameNode.text.length
                        is StringLiteralNode -> nameNode.pos to ((nameNode.rawText?.length ?: nameNode.text.length) + 2)
                        is NumericLiteralNode -> nameNode.pos to nameNode.text.length
                        else -> nameNode.pos to 1
                    }
                    val (line, character) = getLineAndCharacterOfPosition(source, pos)
                    diagnostics.add(Diagnostic(
                        message = "Enum member must have initializer.",
                        category = DiagnosticCategory.Error, code = 1061,
                        fileName = fileName, line = line, character = character,
                        start = pos, length = length,
                    ))
                } else if (memberName != null) {
                    // Record the implicit auto-increment value for downstream references.
                    val last = localValues.values.lastOrNull()
                    val base = if (last is ConstantValue.NumberValue) last.value + 1 else 0.0
                    localValues[memberName] = ConstantValue.NumberValue(base)
                }
            }
        }
    }

    /**
     * Check for duplicate interface members: properties with the same name.
     * Unlike classes, interfaces can have method overloads (same name, different params).
     * Only same-name properties are flagged.
     */
    private fun checkDuplicateInterfaceMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        data class PropInfo(val name: String, val nameNode: Node)
        val props = mutableListOf<PropInfo>()
        for (member in members) {
            if (member is PropertyDeclaration) {
                val name = member.name
                val text = getMemberNameText(name) ?: continue
                props.add(PropInfo(text, name))
            }
        }
        val byName = props.groupBy { it.name }
        for ((_, group) in byName) {
            if (group.size >= 2) {
                for (prop in group) {
                    emitDuplicate2300(prop.name, prop.nameNode, source, fileName)
                }
            }
        }
    }

    /**
     * Check for duplicate class members: method + getter/setter, method + property, etc.
     */
    private fun checkDuplicateClassMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // displayName is used in the message (string literals get extra quotes in TS: ''0'' for '0')
        // groupKey is used for duplicate comparison (only numeric literals are normalized)
        data class MemberInfo(val displayName: String, val groupKey: String, val kind: String, val nameNode: Node, val memberNode: Node? = null)

        fun memberKey(nameNode: Node): Pair<String, String>? {
            return when (nameNode) {
                is Identifier -> {
                    // Skip modifier keywords used as member names (error recovery artifacts)
                    // e.g., `public private p4` parses as member named "private" — don't flag as duplicate
                    if (nameNode.text in MODIFIER_KEYWORDS_SET) return null
                    nameNode.text.let { it to it }
                }
                is NumericLiteralNode -> {
                    // Numeric literals are normalized: 0.0 → "0"
                    val normalized = normalizeNumericKey(nameNode.text)
                    nameNode.text to normalized
                }
                is StringLiteralNode -> {
                    // String literals are NOT normalized for comparison — '0.0' ≠ '0'
                    // But TypeScript DOES compare string literals numerically against numeric literals:
                    // class { 0.0: ..., '0': ... } → duplicate (numeric 0.0 key = "0", string '0' = "0")
                    // class { '0.0': ..., '0': ... } → NOT duplicate (strings compared as-is)
                    // String names are wrapped in quotes in messages: ''0'' for '0'
                    val quotedDisplay = "'${nameNode.text}'"
                    quotedDisplay to nameNode.text
                }
                else -> null
            }
        }

        val memberInfos = mutableListOf<MemberInfo>()
        for (member in members) {
            val isStatic = when (member) {
                is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                is GetAccessor -> ModifierFlag.Static in member.modifiers
                is SetAccessor -> ModifierFlag.Static in member.modifiers
                else -> false
            }
            val staticPrefix = if (isStatic) "static:" else ""
            when (member) {
                is MethodDeclaration -> {
                    val (display, key) = memberKey(member.name) ?: continue
                    memberInfos.add(MemberInfo(display, "$staticPrefix$key", "method", member.name, member))
                }
                is PropertyDeclaration -> {
                    val (display, key) = memberKey(member.name) ?: continue
                    memberInfos.add(MemberInfo(display, "$staticPrefix$key", "property", member.name, member))
                }
                is GetAccessor -> {
                    val (display, key) = memberKey(member.name) ?: continue
                    memberInfos.add(MemberInfo(display, "$staticPrefix$key", "getter", member.name))
                }
                is SetAccessor -> {
                    val (display, key) = memberKey(member.name) ?: continue
                    memberInfos.add(MemberInfo(display, "$staticPrefix$key", "setter", member.name))
                }
                else -> {}
            }
        }

        val byName = memberInfos.groupBy { it.groupKey }
        for ((_, group) in byName) {
            if (group.size < 2) continue
            val kinds = group.map { it.kind }.toSet()
            // method + getter or method + setter → TS2300
            // method + property → TS2300
            // getter + setter → ALLOWED (single pair only)
            // property + property → TS2300 (unless overloads)
            val hasMethod = "method" in kinds
            val hasGetter = "getter" in kinds
            val hasSetter = "setter" in kinds
            val hasProperty = "property" in kinds
            val getterCount = group.count { it.kind == "getter" }
            val setterCount = group.count { it.kind == "setter" }

            // Determine which members to flag with TS2300.
            // TypeScript's rules (derived from test baselines):
            // - getter + setter (complete pair) → ALLOWED
            // - complete accessor pair (get+set) + property → only flag the property
            // - duplicate getters (2+) or setters (2+) → flag ALL in the group
            // - method + property (method first) → only flag the property
            // - property + method (property first) → flag ALL (both property and method)
            // - property + property → only flag the second and subsequent properties (not the first)
            // - method + getter/setter → flag ALL
            val hasCompleteAccessorPair = hasGetter && hasSetter && getterCount == 1 && setterCount == 1
            val membersToFlag: List<MemberInfo> = when {
                getterCount >= 2 || setterCount >= 2 -> group // all conflict when either accessor is duplicated
                hasMethod && (hasGetter || hasSetter) -> group // method + accessor → all
                hasProperty && hasCompleteAccessorPair ->
                    // Complete get+set pair plus property: only the property is the duplicate
                    group.filter { it.kind == "property" }
                hasProperty && (hasGetter || hasSetter) ->
                    // Incomplete accessor + property: both conflict
                    group
                hasMethod && hasProperty -> {
                    // method + property: if method comes FIRST, only flag the property;
                    // if property comes FIRST, flag ALL
                    val firstMember = group.first()
                    if (firstMember.kind == "method") {
                        group.filter { it.kind != "method" }
                    } else {
                        group // property first → both flagged
                    }
                }
                hasProperty && group.count { it.kind == "property" } >= 2 ->
                    // property + property: only flag the 2nd and subsequent, not the first
                    group.drop(1)
                else -> emptyList()
            }

            for (info in membersToFlag) {
                emitDuplicate2300(info.displayName, info.nameNode, source, fileName)
            }

            // TS2717: Subsequent property declarations must have the same type
            // Fires when a property is subsequent to any first declaration with a different type
            if (hasProperty && group.size >= 2) {
                val firstMember = group[0]
                val firstType = getMemberTypeString(firstMember.memberNode)
                if (firstType != null) {
                    // Check all subsequent properties (not methods — TS2717 only fires on properties)
                    for (i in 1 until group.size) {
                        val info = group[i]
                        if (info.kind != "property") continue
                        val laterProp = info.memberNode as? PropertyDeclaration ?: continue
                        val laterType = getPropertyTypeString(laterProp)
                        if (laterType != null && laterType != firstType) {
                            val name = info.displayName
                            val start = info.nameNode.pos
                            val length = when (val n = info.nameNode) {
                                is StringLiteralNode -> n.text.length + 2
                                is NumericLiteralNode -> n.text.length
                                else -> name.length
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            val firstStart = firstMember.nameNode.pos
                            val (firstLine, firstChar) = getLineAndCharacterOfPosition(source, firstStart)
                            diagnostics.add(Diagnostic(
                                message = "Subsequent property declarations must have the same type.  Property '$name' must be of type '$firstType', but here has type '$laterType'.",
                                category = DiagnosticCategory.Error,
                                code = 2717,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                                relatedInformation = listOf(Diagnostic(
                                    message = "'$name' was also declared here.",
                                    category = DiagnosticCategory.Message,
                                    code = 6203,
                                    fileName = fileName,
                                    line = firstLine,
                                    character = firstChar,
                                    start = firstStart,
                                    length = when (val n = firstMember.nameNode) {
                                        is StringLiteralNode -> n.text.length + 2
                                        is NumericLiteralNode -> n.text.length
                                        else -> firstMember.displayName.length
                                    },
                                )),
                            ))
                        }
                    }
                }
            }
        }
    }

    /** Get a type string from a MemberInfo's member node. */
    private fun getMemberTypeString(memberNode: Node?): String? {
        return when (memberNode) {
            is PropertyDeclaration -> getPropertyTypeString(memberNode)
            is MethodDeclaration -> getMethodTypeString(memberNode)
            else -> null
        }
    }

    /** Get a method type string formatted as '() => returnType'. */
    private fun getMethodTypeString(method: MethodDeclaration): String? {
        val returnType = method.type
        val returnTypeStr = if (returnType != null) {
            when (returnType) {
                is KeywordTypeNode -> returnType.kind.name.lowercase().removeSuffix("keyword")
                is TypeReference -> (returnType.typeName as? Identifier)?.text
                else -> formatTypeForDisplay(returnType)
            }
        } else {
            "void"
        }
        if (returnTypeStr == null) return null
        val params = method.parameters
        if (params.isNullOrEmpty()) return "() => $returnTypeStr"
        // Build parameter list
        val paramStrs = params.map { p ->
            val pName = (p.name as? Identifier)?.text ?: "arg"
            val pType = if (p.type != null) {
                when (p.type) {
                    is KeywordTypeNode -> (p.type as KeywordTypeNode).kind.name.lowercase().removeSuffix("keyword")
                    is TypeReference -> ((p.type as TypeReference).typeName as? Identifier)?.text
                    else -> formatTypeForDisplay(p.type!!)
                }
            } else "any"
            "$pName: ${pType ?: "any"}"
        }
        return "(${paramStrs.joinToString(", ")}) => $returnTypeStr"
    }

    /** Get a simple type string from a property declaration for TS2717 comparison. */
    private fun getPropertyTypeString(prop: PropertyDeclaration): String? {
        // Check type annotation first
        val typeNode = prop.type
        if (typeNode != null) {
            return when (typeNode) {
                is TypeReference -> (typeNode.typeName as? Identifier)?.text
                is KeywordTypeNode -> typeNode.kind.name.lowercase()
                    .removeSuffix("keyword")
                else -> formatTypeForDisplay(typeNode)
            }
        }
        // Infer from initializer
        val init = prop.initializer ?: return null
        return when (init) {
            is NumericLiteralNode -> "number"
            is StringLiteralNode -> "string"
            is TemplateExpression -> "string"
            is NoSubstitutionTemplateLiteralNode -> "string"
            is PrefixUnaryExpression -> if (init.operator == SyntaxKind.Minus) "number" else null
            else -> null
        }
    }

    /**
     * Recursively walk type annotations checking for duplicates.
     */
    private fun checkDuplicatesInType(
        type: TypeNode?,
        source: String,
        fileName: String,
    ) {
        if (type == null) return
        when (type) {
            is TypeLiteral -> {
                checkDuplicateInterfaceMembers(type.members, source, fileName)
                for (member in type.members) {
                    checkDuplicatesInTypeMember(member, source, fileName)
                }
            }
            is FunctionType -> {
                checkDuplicateTypeParams(type.typeParameters, source, fileName)
                checkDuplicatesInType(type.type, source, fileName)
            }
            is ConstructorType -> {
                checkDuplicateTypeParams(type.typeParameters, source, fileName)
                checkDuplicatesInType(type.type, source, fileName)
            }
            is UnionType -> for (t in type.types) checkDuplicatesInType(t, source, fileName)
            is IntersectionType -> for (t in type.types) checkDuplicatesInType(t, source, fileName)
            is ParenthesizedType -> checkDuplicatesInType(type.type, source, fileName)
            is ArrayType -> checkDuplicatesInType(type.elementType, source, fileName)
            is TypePredicate -> checkDuplicatesInType(type.type, source, fileName)
            else -> {}
        }
    }

    private fun checkDuplicatesInTypeMember(
        member: ClassElement,
        source: String,
        fileName: String,
    ) {
        when (member) {
            is PropertyDeclaration -> checkDuplicatesInType(member.type, source, fileName)
            is MethodDeclaration -> {
                checkDuplicateTypeParams(member.typeParameters, source, fileName)
                checkDuplicatesInType(member.type, source, fileName)
            }
            else -> {}
        }
    }

    /** Extract the effective property name from a member name node. */
    private fun getMemberNameText(name: Node): String? = when (name) {
        is Identifier -> name.text
        is StringLiteralNode -> name.text
        is NumericLiteralNode -> name.text
        else -> null
    }

    /** Normalize numeric string to canonical form for duplicate comparison. */
    private fun normalizeNumericKey(text: String): String {
        val num = when {
            text.startsWith("0b", ignoreCase = true) || text.startsWith("0B") ->
                text.substring(2).toLongOrNull(2)?.toDouble()
            text.startsWith("0o", ignoreCase = true) || text.startsWith("0O") ->
                text.substring(2).toLongOrNull(8)?.toDouble()
            text.startsWith("0x", ignoreCase = true) || text.startsWith("0X") ->
                text.substring(2).toLongOrNull(16)?.toDouble()
            else -> text.toDoubleOrNull()
        } ?: return text
        // 0.0 → "0", 1.0 → "1", etc.
        return if (num == num.toLong().toDouble()) num.toLong().toString() else text
    }

    private fun emitDuplicate2300(
        name: String,
        node: Node,
        source: String,
        fileName: String,
        spanLength: Int = when (node) {
            is StringLiteralNode -> node.text.length + 2 // inner text + 2 quotes
            is NumericLiteralNode -> node.text.length
            else -> name.length
        },
    ) {
        val start = node.pos
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Duplicate identifier '$name'.",
            category = DiagnosticCategory.Error,
            code = 2300,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = spanLength,
        ))
    }

    // -----------------------------------------------------------------------
    // Catch clause redeclaration checking (TS2492)
    // -----------------------------------------------------------------------

    /**
     * TS2492: "Cannot redeclare identifier 'X' in catch clause."
     * Fires when a let/const declaration in a catch block shadows the catch variable name.
     * Also checks catch clause destructuring patterns for duplicate names (TS2451).
     */
    private fun checkCatchClauseRedeclarations() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkStatementsForCatchRedecl(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkStatementsForCatchRedecl(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is TryStatement -> {
                    walkStatementsForCatchRedecl(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { catchClause ->
                        // Collect catch variable names
                        val catchNames = mutableSetOf<String>()
                        catchClause.variableDeclaration?.let { collectBindingNames(it.name, catchNames) }

                        // Check for duplicate names within catch destructuring pattern (TS2451)
                        val seenNames = mutableMapOf<String, Node>()
                        catchClause.variableDeclaration?.let { checkDuplicateBindingNames(it.name, seenNames, source, fileName) }

                        // Check catch block body for let/const redeclarations of catch names (TS2492)
                        if (catchNames.isNotEmpty()) {
                            checkBlockForCatchRedecl(catchClause.block.statements, catchNames, source, fileName)
                        }
                        walkStatementsForCatchRedecl(catchClause.block.statements, source, fileName)
                    }
                    stmt.finallyBlock?.let { walkStatementsForCatchRedecl(it.statements, source, fileName) }
                }
                is FunctionDeclaration -> stmt.body?.let { walkStatementsForCatchRedecl(it.statements, source, fileName) }
                is ClassDeclaration -> {} // class methods don't need this check
                is Block -> walkStatementsForCatchRedecl(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkStatementForCatchRedecl(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { walkStatementForCatchRedecl(it, source, fileName) }
                }
                is ForStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is ForInStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is ForOfStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is WhileStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is DoStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        val stmts2 = when (clause) { is CaseClause -> clause.statements; is DefaultClause -> clause.statements; else -> emptyList() }
                        walkStatementsForCatchRedecl(stmts2, source, fileName)
                    }
                }
                is LabeledStatement -> walkStatementForCatchRedecl(stmt.statement, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkStatementsForCatchRedecl(body.statements, source, fileName)
                }
                else -> {}
            }
        }
    }

    private fun walkStatementForCatchRedecl(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is Block -> walkStatementsForCatchRedecl(stmt.statements, source, fileName)
            else -> walkStatementsForCatchRedecl(listOf(stmt), source, fileName)
        }
    }

    private fun checkBlockForCatchRedecl(
        stmts: List<Statement>,
        catchNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    // Only let/const trigger TS2492 (var doesn't — it's function-scoped)
                    val flags = stmt.declarationList.flags
                    if (flags == SyntaxKind.LetKeyword || flags == SyntaxKind.ConstKeyword) {
                        for (decl in stmt.declarationList.declarations) {
                            checkBindingForCatchRedecl(decl.name, catchNames, source, fileName)
                        }
                    }
                }
                // Don't descend into function declarations — they create new scope
                else -> {}
            }
        }
    }

    private fun checkBindingForCatchRedecl(
        name: Node,
        catchNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (name) {
            is Identifier -> {
                if (name.text in catchNames) {
                    val start = name.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot redeclare identifier '${name.text}' in catch clause.",
                        category = DiagnosticCategory.Error,
                        code = 2492,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = name.text.length,
                    ))
                }
            }
            is ArrayBindingPattern -> {
                for (elem in name.elements) {
                    if (elem is BindingElement) checkBindingForCatchRedecl(elem.name, catchNames, source, fileName)
                }
            }
            is ObjectBindingPattern -> {
                for (elem in name.elements) {
                    checkBindingForCatchRedecl(elem.name, catchNames, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun collectBindingNames(name: Node, result: MutableSet<String>) {
        when (name) {
            is Identifier -> result.add(name.text)
            is ArrayBindingPattern -> {
                for (elem in name.elements) {
                    if (elem is BindingElement) collectBindingNames(elem.name, result)
                }
            }
            is ObjectBindingPattern -> {
                for (elem in name.elements) {
                    collectBindingNames(elem.name, result)
                }
            }
            else -> {}
        }
    }

    private fun checkDuplicateBindingNames(
        name: Node,
        seen: MutableMap<String, Node>,
        source: String,
        fileName: String,
    ) {
        when (name) {
            is Identifier -> {
                if (name.text in seen) {
                    // TS2451 for both the first and current occurrence
                    val first = seen[name.text]!!
                    val firstStart = first.pos
                    val (firstLine, firstChar) = getLineAndCharacterOfPosition(source, firstStart)
                    diagnostics.add(Diagnostic(
                        message = "Cannot redeclare block-scoped variable '${name.text}'.",
                        category = DiagnosticCategory.Error,
                        code = 2451,
                        fileName = fileName,
                        line = firstLine,
                        character = firstChar,
                        start = firstStart,
                        length = name.text.length,
                    ))
                    val start = name.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot redeclare block-scoped variable '${name.text}'.",
                        category = DiagnosticCategory.Error,
                        code = 2451,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = name.text.length,
                    ))
                } else {
                    seen[name.text] = name
                }
            }
            is ArrayBindingPattern -> {
                for (elem in name.elements) {
                    if (elem is BindingElement) checkDuplicateBindingNames(elem.name, seen, source, fileName)
                }
            }
            is ObjectBindingPattern -> {
                for (elem in name.elements) {
                    checkDuplicateBindingNames(elem.name, seen, source, fileName)
                }
            }
            else -> {}
        }
    }

    /**
     * Checks if a namespace/module declaration is "instantiated" — meaning it
     * contributes a runtime value. A namespace is instantiated when it is NOT
     * `declare` and its body contains value-producing statements.
     * Value-free namespaces (empty, or only containing interfaces/types) can
     * merge with var declarations without conflict.
     */
    private fun isNamespaceInstantiated(decl: ModuleDeclaration): Boolean {
        if (ModifierFlag.Declare in decl.modifiers) return false
        val body = decl.body as? ModuleBlock ?: return false
        return body.statements.any { s ->
            when (s) {
                is VariableStatement -> true
                is FunctionDeclaration -> true
                is ClassDeclaration -> true
                is EnumDeclaration -> true
                is ModuleDeclaration -> isNamespaceInstantiated(s)
                is ExportDeclaration -> {
                    // export { ... } from "..." or export { ... } — check if there's an actual re-export
                    // of values (not just types). For simplicity, assume value export.
                    true
                }
                else -> false
            }
        }
    }

    // -----------------------------------------------------------------------
    // Export= in ES module checking (TS1203)
    // -----------------------------------------------------------------------

    /**
     * Check for TS1203/TS1202: export=/import= cannot be used with ES modules.
     */
    private fun checkExportAssignmentInEsModule() {
        val effectiveModule = options.effectiveModule
        // ES module kinds: ES2015, ES2020, ES2022, ESNext
        // Node16/Node18/Node20/NodeNext support import= require() via createRequire, so exclude them
        // Preserve mode defers module format decision per-file, so exclude it too
        val isEsModule = effectiveModule >= ModuleKind.ES2015 && !effectiveModule.isNodeNext && effectiveModule != ModuleKind.Preserve
        if (!isEsModule) return

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — TS1203 doesn't apply to JS
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text

            for (stmt in result.sourceFile.statements) {
                when {
                    stmt is ExportAssignment && stmt.isExportEquals -> {
                        emitStatementLineDiagnostic(
                            stmt, source, fileName, 1203,
                            "Export assignment cannot be used when targeting ECMAScript modules. Consider using 'export default' or another module format instead.",
                        )
                    }
                    stmt is ImportEqualsDeclaration && stmt.moduleReference is ExternalModuleReference -> {
                        emitStatementLineDiagnostic(
                            stmt, source, fileName, 1202,
                            "Import assignment cannot be used when targeting ECMAScript modules. Consider using 'import * as ns from \"mod\"', 'import {a} from \"mod\"', 'import d from \"mod\"', or another module format instead.",
                        )
                    }
                }
            }
        }
    }

    /** Emit a diagnostic for a statement, spanning the statement text (excluding comments). */
    private fun emitStatementLineDiagnostic(
        stmt: Statement, source: String, fileName: String, code: Int, message: String,
    ) {
        var start = stmt.pos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) start++
        // Use the statement's end but find the last non-whitespace before it
        // Also find the semicolon if present to end the span there
        val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
        // Find the semicolon position (statement end) or trim trailing comment
        var end = start
        var i = start
        while (i < lineEnd) {
            val ch = source[i]
            if (ch == ';') {
                end = i + 1 // include the semicolon
                break
            }
            if (ch == '/' && i + 1 < lineEnd && (source[i + 1] == '/' || source[i + 1] == '*')) {
                // Comment starts — end before it
                while (end > start && source[end - 1].let { it == ' ' || it == '\t' }) end--
                break
            }
            end = i + 1
            i++
        }
        if (end <= start) end = start + 1
        val length = end - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Unresolved module checking (TS2307)
    // -----------------------------------------------------------------------

    /**
     * Check for TS2307: "Cannot find module 'X' or its corresponding type declarations."
     * Emitted when an import module specifier doesn't resolve to a known file.
     */
    private fun checkUnresolvedModules() {
        val isMultiFile = binderResults.size > 1 || isMultiFileSource

        // Collect ambient module names (declare module "X") from all files including .d.ts
        // so that side-effect imports like `import "Map"` don't get TS2882 when "Map" is
        // declared as an ambient module in a referenced .d.ts file.
        val ambientModuleNames = mutableSetOf<String>()
        // Also collect .d.ts filenames (without extension) as module names — e.g., "foo" for foo.d.ts.
        // A bare specifier import of "foo" is valid if foo.d.ts is in the compilation.
        val dtsFileBaseNames = mutableSetOf<String>()
        if (isMultiFile) {
            for (result in binderResults) {
                val fn = result.sourceFile.fileName
                if (isDtsFile(fn)) {
                    // Extract base name without .d.ts extension
                    val base = fn.substringAfterLast("/").substringAfterLast("\\")
                        .removeSuffix(".d.ts")
                    dtsFileBaseNames.add(base)
                }
                for (stmt in result.sourceFile.statements) {
                    if (stmt is ModuleDeclaration) {
                        val name = stmt.name
                        if (name is StringLiteralNode) {
                            ambientModuleNames.add(name.text)
                        }
                    }
                }
            }
        }

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            for (stmt in flattenImportLikeStatements(result.sourceFile.statements)) {
                val isSideEffectImport = stmt is ImportDeclaration && stmt.importClause == null
                val specifier = when (stmt) {
                    is ImportDeclaration -> stmt.moduleSpecifier
                    is ExportDeclaration -> stmt.moduleSpecifier
                    is ImportEqualsDeclaration -> {
                        val ref = stmt.moduleReference
                        if (ref is ExternalModuleReference) ref.expression else null
                    }
                    else -> null
                }
                if (specifier == null) continue
                val moduleName = when (specifier) {
                    is StringLiteralNode -> specifier.text
                    else -> continue
                }
                if (isMultiFile) {
                    val isRelative = moduleName.startsWith("./") || moduleName.startsWith("../")
                    // Determine effective module resolution to distinguish node vs classic
                    val moduleRes = options.moduleResolution?.lowercase()
                    val effectiveModuleRes = moduleRes ?: run {
                        when (options.module) {
                            ModuleKind.CommonJS -> "node10"
                            ModuleKind.Node16, ModuleKind.Node18, ModuleKind.Node20 -> "node16"
                            ModuleKind.NodeNext -> "nodenext"
                            ModuleKind.System, ModuleKind.AMD, ModuleKind.UMD -> "classic"
                            else -> "node10"
                        }
                    }
                    val isClassicResolution = effectiveModuleRes !in setOf("node", "node10", "node16", "nodenext", "bundler")
                    if (isSideEffectImport) {
                        // Side-effect imports: TS2882
                        if (isRelative) {
                            if (resolveModuleSpecifier(moduleName) == null) {
                                emitTS2882(specifier, moduleName, source, fileName)
                            }
                        } else if (moduleName !in ambientModuleNames
                            && moduleName !in dtsFileBaseNames
                            && !hasNodeModulesPackage(moduleName)
                        ) {
                            val mod = options.module
                            if (mod != ModuleKind.AMD && mod != ModuleKind.System && mod != ModuleKind.UMD) {
                                emitTS2882(specifier, moduleName, source, fileName)
                            }
                        }
                    } else if (isClassicResolution && options.paths.isNullOrEmpty() && options.baseUrl == null) {
                        // For classic/AMD/System/UMD module resolution, emit TS2792 in multi-file
                        // when the module can't be resolved. Skip when paths/baseUrl are configured
                        // since those require complex path remapping that our simple resolver can't handle.
                        // Skip .json imports (handled by TS5070 resolveJsonModule+classic incompatibility).
                        if (!moduleName.endsWith(".json")) {
                            val resolved = if (isRelative) {
                                // For relative specifiers, resolve strictly relative to the importing file's dir
                                // (no fallback to global resolution that ignores directory context)
                                resolveModuleSpecifierStrictRelative(moduleName, fileName)
                            } else {
                                resolveModuleSpecifier(moduleName, null)
                            }
                            if (resolved == null && moduleName !in ambientModuleNames && moduleName !in dtsFileBaseNames) {
                                emitTS2307(specifier, moduleName, source, fileName)
                            }
                        }
                    } else if (!options.moduleSuffixes.isNullOrEmpty() && isRelative && !moduleName.endsWith(".json")) {
                        // Node resolution with moduleSuffixes: relative imports only resolve to a
                        // file whose name matches one of the configured suffixes. If none match,
                        // emit TS2307 even though an unsuffixed file with the same base name exists.
                        if (resolveWithModuleSuffixes(moduleName, fileName, options.moduleSuffixes!!) == null) {
                            emitTS2307(specifier, moduleName, source, fileName)
                        }
                    } else if (moduleName.endsWith(".json") && !options.resolveJsonModule && !isRelative) {
                        // Non-relative .json imports (resolved via node_modules or path mapping)
                        // require `resolveJsonModule: true`; without it, TypeScript emits TS2732.
                        // Relative .json imports still fall back to direct-file parsing in the test
                        // layout, so we leave their handling to downstream type checking.
                        emitTS2732(specifier, moduleName, source, fileName)
                    }
                    // Skip TS2307 in multi-file with node resolution — resolveModuleSpecifier is too
                    // simplified for paths, symlinks, json, index resolution; causes FPs.
                } else {
                    if (isSideEffectImport) {
                        emitTS2882(specifier, moduleName, source, fileName)
                    } else {
                        emitTS2307(specifier, moduleName, source, fileName)
                    }
                }
            }
        }
    }

    /**
     * Resolve a relative specifier using `moduleSuffixes`: for each suffix, look for a file
     * matching `{path}{suffix}.ts|.tsx|.d.ts|.json`. Suffixes of "" fall back to the plain name.
     * Returns the first match or null.
     */
    private fun resolveWithModuleSuffixes(specifier: String, contextFileName: String, suffixes: List<String>): String? {
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) return null
        val dir = contextFileName.substringBeforeLast('/', "")
        val basePath = if (dir.isEmpty()) specifier else "$dir/${specifier.removePrefix("./")}"
        val normalized = normalizePath(basePath)
        // Strip explicit .js/.jsx extension — TypeScript resolves these to .ts/.tsx/.d.ts
        // (or .js/.jsx under allowJs), so the base used for suffix-matching is without ext.
        val withoutJs = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            else -> normalized
        }
        // Try with and without a leading "/" prefix to match how fileResults keys are stored
        // (root-file layouts like "@filename: /foo.ts" produce keys starting with "/").
        val bases = buildList {
            add(withoutJs)
            add(withoutJs.removePrefix("./"))
            if (!withoutJs.startsWith("/")) add("/$withoutJs")
        }
        val allowJs = options.allowJs == true || options.checkJs == true
        for (suffix in suffixes) {
            for (base in bases) {
                val candidates = buildList {
                    add("$base$suffix.ts")
                    add("$base$suffix.tsx")
                    add("$base$suffix.d.ts")
                    add("$base$suffix.json")
                    add("$base/index$suffix.ts")
                    add("$base/index$suffix.tsx")
                    add("$base/index$suffix.d.ts")
                    if (allowJs) {
                        add("$base$suffix.js")
                        add("$base$suffix.jsx")
                        add("$base/index$suffix.js")
                        add("$base/index$suffix.jsx")
                    }
                }
                for (c in candidates) {
                    if (c in fileResults) return c
                }
            }
        }
        return null
    }

    /**
     * TS2439: "Import or export declaration in an ambient module declaration cannot reference
     * module through relative module name." — fires for `import Y = require("./Z")` or
     * `import ... from "./Z"` / `export ... from "./Z"` nested inside `declare module "X" { }`.
     */
    private fun checkRelativeImportsInAmbientModules() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            val hostIsModule = isModuleFile(result.sourceFile.statements)
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode) {
                    // A `declare module "X"` with a RELATIVE specifier inside a module file
                    // is always a module augmentation — any external-module import/export
                    // inside it gets TS2667. Non-relative names are ambient module
                    // definitions (or bare-name augmentations of imported modules, which
                    // we don't currently distinguish); imports inside those are allowed
                    // at this level — TS2307/TS2664 handle those separately.
                    val outerName = (stmt.name as StringLiteralNode).text
                    val isRelativeAugmentation = hostIsModule &&
                        (outerName.startsWith("./") || outerName.startsWith("../"))
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        for (innerStmt in body.statements) {
                            val specifier: Expression? = when (innerStmt) {
                                is ImportDeclaration -> innerStmt.moduleSpecifier
                                is ExportDeclaration -> innerStmt.moduleSpecifier
                                is ImportEqualsDeclaration -> {
                                    val ref = innerStmt.moduleReference
                                    if (ref is ExternalModuleReference) ref.expression else null
                                }
                                else -> null
                            }
                            val moduleName = (specifier as? StringLiteralNode)?.text ?: continue
                            if (isRelativeAugmentation) {
                                // Squiggle only the `import` / `export` keyword (6 chars).
                                var kwStart = innerStmt.pos
                                while (kwStart < source.length && source[kwStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) kwStart++
                                val kwLength = when (innerStmt) {
                                    is ExportDeclaration -> 6
                                    else -> 6
                                }
                                val (kwLine, kwChar) = getLineAndCharacterOfPosition(source, kwStart)
                                diagnostics.add(Diagnostic(
                                    message = "Imports are not permitted in module augmentations. Consider moving them to the enclosing external module.",
                                    category = DiagnosticCategory.Error,
                                    code = 2667,
                                    fileName = fileName,
                                    line = kwLine,
                                    character = kwChar,
                                    start = kwStart,
                                    length = kwLength,
                                ))
                                // TypeScript ALSO emits TS2307 for relative specifiers inside
                                // augmentations — the augmented module's scope doesn't offer
                                // normal relative resolution. checkUnresolvedModules won't flag
                                // this (the file exists on disk in the multi-file layout), so
                                // emit it here on the specifier.
                                if (moduleName.startsWith("./") || moduleName.startsWith("../")) {
                                    val specStart = specifier.pos
                                    val specLen = moduleName.length + 2 // +2 for quotes
                                    val (specLine, specChar) = getLineAndCharacterOfPosition(source, specStart)
                                    diagnostics.add(Diagnostic(
                                        message = "Cannot find module '$moduleName' or its corresponding type declarations.",
                                        category = DiagnosticCategory.Error,
                                        code = 2307,
                                        fileName = fileName,
                                        line = specLine,
                                        character = specChar,
                                        start = specStart,
                                        length = specLen,
                                    ))
                                }
                            } else if (moduleName.startsWith("./") || moduleName.startsWith("../")) {
                                emitStatementLineDiagnostic(
                                    innerStmt, source, fileName, 2439,
                                    "Import or export declaration in an ambient module declaration cannot reference module through relative module name.",
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Flatten top-level import/export/import-equals statements plus those nested inside
     * `declare module "X" { ... }` augmentations (ModuleDeclaration with StringLiteralNode name).
     * Identifier-named namespaces (`namespace N { ... }`, `declare global { ... }`) are NOT
     * recursed into because imports there use different diagnostics (TS1147/TS2667/TS1194).
     */
    private fun flattenImportLikeStatements(statements: List<Statement>): List<Statement> {
        val out = mutableListOf<Statement>()
        for (s in statements) {
            when (s) {
                is ImportDeclaration, is ExportDeclaration, is ImportEqualsDeclaration -> out.add(s)
                is ModuleDeclaration -> {
                    if (s.name is StringLiteralNode) {
                        val body = s.body
                        if (body is ModuleBlock) {
                            out.addAll(flattenImportLikeStatements(body.statements))
                        }
                    }
                }
                else -> {}
            }
        }
        return out
    }

    private fun emitTS2307(specifier: Expression, moduleName: String, source: String, fileName: String) {
        val start = specifier.pos
        val length = moduleName.length + 2 // +2 for quotes
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        // TS2792 fires when moduleResolution is not node-based (classic, or default for
        // system/amd/es2015/esnext modules) — suggests switching to nodenext
        val moduleRes = options.moduleResolution?.lowercase()
        val effectiveModuleRes = moduleRes ?: run {
            // Default moduleResolution based on module option
            when (options.module) {
                ModuleKind.CommonJS -> "node10"
                ModuleKind.Node16, ModuleKind.Node18, ModuleKind.Node20 -> "node16"
                ModuleKind.NodeNext -> "nodenext"
                // System and AMD use classic resolution
                ModuleKind.System, ModuleKind.AMD, ModuleKind.UMD -> "classic"
                // ES module kinds (es2015, es2020, esnext) and null/none: default to node10 in TS6+
                else -> "node10"
            }
        }
        val isNodeResolution = effectiveModuleRes in setOf("node", "node10", "node16", "nodenext", "bundler")
        val code: Int
        val message: String
        if (isNodeResolution) {
            code = 2307
            message = "Cannot find module '$moduleName' or its corresponding type declarations."
        } else {
            code = 2792
            message = "Cannot find module '$moduleName'. Did you mean to set the 'moduleResolution' option to 'nodenext', or to add aliases to the 'paths' option?"
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Checks whether the test-file layout contains a package matching [pkgName]
     * under a node_modules directory — i.e. any file in `fileResults.keys` whose
     * path contains `/node_modules/<pkgName>/` (with any depth of nesting before
     * `node_modules`). Used to suppress TS2307/TS2882 for bare specifiers that
     * TypeScript would resolve via node_modules.
     */
    private fun hasNodeModulesPackage(pkgName: String): Boolean {
        val needle = "/node_modules/$pkgName/"
        for (fn in fileResults.keys) {
            if (needle in fn || fn.startsWith("node_modules/$pkgName/")) return true
        }
        return false
    }

    private fun emitTS2882(specifier: Expression, moduleName: String, source: String, fileName: String) {
        val start = specifier.pos
        val length = moduleName.length + 2 // +2 for quotes
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Cannot find module or type declarations for side-effect import of '$moduleName'.",
            category = DiagnosticCategory.Error,
            code = 2882,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * TS2732: "Cannot find module 'X.json'. Consider using '--resolveJsonModule' to import
     * module with '.json' extension." — fires when a `.json` specifier is imported while
     * `resolveJsonModule` is disabled, regardless of whether the file exists.
     */
    private fun emitTS2732(specifier: Expression, moduleName: String, source: String, fileName: String) {
        val start = specifier.pos
        val length = moduleName.length + 2 // +2 for quotes
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Cannot find module '$moduleName'. Consider using '--resolveJsonModule' to import module with '.json' extension.",
            category = DiagnosticCategory.Error,
            code = 2732,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Invalid module augmentation check (TS2664)
    // -----------------------------------------------------------------------

    /**
     * TS2664: Invalid module name in augmentation.
     * A `declare module "X"` in a MODULE file (has imports/exports) is an augmentation.
     * The augmented module must be defined elsewhere — either by resolving to a file
     * or by another `declare module "X"` in a script (non-module) file or a .d.ts file.
     */
    private fun checkAmbientModuleAugmentations() {
        // Collect module-definition names: `declare module "X"` in script (non-module)
        // files and .d.ts files (which may contain ambient module definitions).
        val moduleDefinitions = mutableSetOf<String>()
        for (result in binderResults) {
            val fn = result.sourceFile.fileName
            val isDts = isDtsFile(fn)
            val isScript = !isModuleFile(result.sourceFile.statements)
            if (!isDts && !isScript) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration) {
                    val name = stmt.name
                    if (name is StringLiteralNode) {
                        moduleDefinitions.add(name.text)
                    }
                }
            }
        }

        // Check each `declare module "X"` in non-.d.ts module files as an augmentation.
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (!isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text

            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val name = stmt.name
                if (name !is StringLiteralNode) continue
                val moduleName = name.text

                val resolvesToFile = resolveModuleSpecifier(moduleName) != null ||
                    resolvesAsJsOrJsx(moduleName)
                val definedElsewhere = moduleName in moduleDefinitions

                if (!resolvesToFile && !definedElsewhere) {
                    val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Invalid module name in augmentation, module '$moduleName' cannot be found.",
                        category = DiagnosticCategory.Error,
                        code = 2664,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = name.pos,
                        length = moduleName.length + 2, // +2 for quotes
                    ))
                }
            }
        }
    }

    /**
     * Scoped helper for [checkAmbientModuleAugmentations]: checks whether [specifier] resolves to
     * a `.js`/`.jsx`/`.mjs`/`.cjs` sibling file under `allowJs`/`checkJs`. The main
     * [resolveModuleSpecifier] intentionally does not try JS extensions (they would change the
     * behavior of TS2307 and cross-file type lookups elsewhere in non-desirable ways).
     */
    private fun resolvesAsJsOrJsx(specifier: String): Boolean {
        if (!options.allowJs && !options.checkJs) return false
        val baseName = specifier.removePrefix("./").removePrefix("../")
        val isRelative = specifier.startsWith("./") || specifier.startsWith("../")
        val candidates = mutableListOf(
            "$baseName.js", "$baseName.jsx",
            "./$baseName.js", "./$baseName.jsx",
        )
        if (isRelative) {
            candidates.add("$baseName.mjs")
            candidates.add("$baseName.cjs")
            candidates.add("./$baseName.mjs")
            candidates.add("./$baseName.cjs")
        }
        for (candidate in candidates) {
            if (candidate in fileResults) return true
        }
        // Last-resort base match for flat-directory absolute-path layouts (@Filename: /test.js)
        for (fileName in fileResults.keys) {
            val fileBase = fileName.removePrefix("./")
                .removeSuffix(".js").removeSuffix(".jsx").removeSuffix(".mjs").removeSuffix(".cjs")
            if (fileBase == baseName || fileBase == "/$baseName" ||
                (!isRelative && fileBase.endsWith("/$baseName"))) return true
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS1046: Top-level declarations in .d.ts files must be declare/export
    // -----------------------------------------------------------------------

    /**
     * Emit TS1046 at the first top-level declaration statement in a .d.ts file that doesn't
     * have a `declare` or `export` modifier. Only the FIRST offender is reported — subsequent
     * statements are left to other diagnostics.
     * Interface/TypeAlias are implicitly type-only and don't need the modifier.
     * Import/ExportDeclaration/ExportAssignment inherently imply module context and are skipped.
     */
    private fun checkDtsTopLevelDeclarations() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (!isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Only check the FIRST declaration in the file. TypeScript's actual rule is broader
            // (every bare declaration is flagged until module-mode is established), but our parser
            // sometimes splits malformed constructs like `export as namespace Foo;` into multiple
            // statements, and checking every statement produces false positives. Restricting to
            // the very first statement matches all currently-broken baselines.
            val firstStmt = result.sourceFile.statements.firstOrNull { it !is NotEmittedStatement } ?: continue
            val (offenderKeywordStart, keywordLength) = dtsOffenderKeyword(firstStmt, source) ?: continue
            val (line, character) = getLineAndCharacterOfPosition(source, offenderKeywordStart)
            diagnostics.add(Diagnostic(
                message = "Top-level declarations in .d.ts files must start with either a 'declare' or 'export' modifier.",
                category = DiagnosticCategory.Error,
                code = 1046,
                fileName = fileName,
                line = line,
                character = character,
                start = offenderKeywordStart,
                length = keywordLength,
            ))
        }
    }

    /**
     * Returns (keyword start, keyword length) for statements that are top-level declarations
     * in a .d.ts file which lack `declare`/`export` modifier, or null if the statement is OK
     * or should be skipped.
     */
    private fun dtsOffenderKeyword(stmt: Statement, source: String): Pair<Int, Int>? {
        val (mods, keyword) = when (stmt) {
            is ModuleDeclaration -> {
                if (stmt.name is StringLiteralNode) return null // `declare module "X"` form handled via modifier
                stmt.modifiers to extractModuleKeyword(stmt, source)
            }
            is FunctionDeclaration -> stmt.modifiers to "function"
            is ClassDeclaration -> stmt.modifiers to "class"
            is EnumDeclaration -> stmt.modifiers to if (ModifierFlag.Const in stmt.modifiers) "const" else "enum"
            is VariableStatement -> stmt.modifiers to variableStatementKeyword(stmt)
            else -> return null // InterfaceDeclaration, TypeAliasDeclaration, ImportDeclaration, etc. are fine
        }
        if (ModifierFlag.Declare in mods || ModifierFlag.Export in mods) return null
        val keywordStart = source.indexOf(keyword, startIndex = stmt.pos).takeIf { it >= 0 && it < stmt.end } ?: return null
        return keywordStart to keyword.length
    }

    private fun extractModuleKeyword(decl: ModuleDeclaration, source: String): String {
        // `namespace X` → "namespace", `module X` → "module". Check the source text.
        val nsIdx = source.indexOf("namespace", startIndex = decl.pos)
        val modIdx = source.indexOf("module", startIndex = decl.pos)
        return if (nsIdx >= 0 && nsIdx < decl.end && (modIdx < 0 || nsIdx < modIdx)) "namespace" else "module"
    }

    private fun variableStatementKeyword(stmt: VariableStatement): String = when (stmt.declarationList.flags) {
        SyntaxKind.LetKeyword -> "let"
        SyntaxKind.ConstKeyword -> "const"
        else -> "var"
    }

    // -----------------------------------------------------------------------
    // Default import checking (TS1192)
    // -----------------------------------------------------------------------

    /**
     * Check for TS1192: "Module '...' has no default export."
     * Emitted when a default import binding is used against a module that doesn't
     * export a default value. Suppressed when allowSyntheticDefaultImports is true.
     *
     * Also checks for TS2614: "Module '...' has no exported member 'X'. Did you mean
     * to use 'import X from ...' instead?" — fires when a named import specifier
     * doesn't exist in the module's exports but the module does have a default export.
     */
    private fun checkDefaultImports() {
        // allowSyntheticDefaultImports suppresses TS1192 check.
        // Explicit false overrides all implicit true conditions.
        // It is implicitly true when:
        //   1. Explicitly set to true
        //   2. module is System (System.js includes synthetic default support)
        //
        // Note: esModuleInterop does NOT generally suppress TS1192 for normal modules.
        // For 'export =' modules with esModuleInterop=true, TS1259 fires instead (handled separately).
        val effectiveSyntheticDefaults = if (options.allowSyntheticDefaultImportsExplicitlyFalse) {
            false // Explicit false always wins
        } else {
            options.allowSyntheticDefaultImports ||
            options.effectiveModule == ModuleKind.System
        }
        if (effectiveSyntheticDefaults) return

        val isMultiFile = binderResults.size > 1 || isMultiFileSource
        if (!isMultiFile) return

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            for (stmt in result.sourceFile.statements) {
                if (stmt !is ImportDeclaration) continue
                val importClause = stmt.importClause ?: continue
                // Type-only imports don't need a runtime default export
                if (importClause.isTypeOnly) continue

                // Resolve the module specifier
                val specifier = stmt.moduleSpecifier
                val moduleName = (specifier as? StringLiteralNode)?.text ?: continue
                val resolvedFile = resolveModuleSpecifier(moduleName) ?: continue
                val targetResult = fileResults[resolvedFile] ?: continue
                val targetFile = targetResult.sourceFile

                val hasDefaultExport = moduleHasDefaultExport(targetFile)

                // TS1192: default binding used but module has no default export
                // Suppress for 'export =' modules when esModuleInterop=true (TS1259 would fire instead)
                val hasExportEquals = targetFile.statements.any { it is ExportAssignment && it.isExportEquals }
                val esModuleInteropActive = options.esModuleInterop && !options.esModuleInteropExplicitlyFalse &&
                    !options.allowSyntheticDefaultImportsExplicitlyFalse
                // Suppress for JS CJS files (no ESM exports) when esModuleInterop=true —
                // module.exports becomes a synthetic default export under esModuleInterop.
                val targetIsJsCjs = esModuleInteropActive &&
                    (resolvedFile.endsWith(".js") || resolvedFile.endsWith(".jsx") ||
                     resolvedFile.endsWith(".cjs") || resolvedFile.endsWith(".mjs")) &&
                    targetFile.statements.none { it is ExportAssignment || it is ExportDeclaration ||
                        (it is FunctionDeclaration && ModifierFlag.Export in it.modifiers) ||
                        (it is ClassDeclaration && ModifierFlag.Export in it.modifiers) ||
                        (it is VariableStatement && ModifierFlag.Export in it.modifiers) }
                val defaultBinding = importClause.name
                if (defaultBinding != null && !hasDefaultExport && !(hasExportEquals && esModuleInteropActive) && !targetIsJsCjs) {
                    // Compute display module name: strip leading "./" from relative specifiers
                    val displayName = when {
                        moduleName.startsWith("./") -> moduleName.removePrefix("./")
                        moduleName.startsWith("../") -> moduleName
                        else -> {
                            // For bare specifiers, use the resolved file path without extension
                            resolvedFile.removeSuffix(".d.ts").removeSuffix(".ts").removeSuffix(".tsx")
                        }
                    }
                    val nameStart = defaultBinding.pos
                    val nameLength = defaultBinding.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
                    // TS1259: fires when the target module has `export = X` and neither
                    // esModuleInterop nor allowSyntheticDefaultImports allow a default import.
                    // TypeScript emits TS1259 (not TS1192) with a TS2594 related-info pointing
                    // to the `export =` statement.
                    if (hasExportEquals && !esModuleInteropActive) {
                        val exportEqStmt = targetFile.statements
                            .firstOrNull { it is ExportAssignment && it.isExportEquals }
                        val relatedInfos: List<Diagnostic> = if (exportEqStmt != null) {
                            val (rLine, rChar) = getLineAndCharacterOfPosition(targetFile.text, exportEqStmt.pos)
                            listOf(
                                Diagnostic(
                                    message = "This module is declared with 'export =', and can only be used with a default import when using the 'esModuleInterop' flag.",
                                    category = DiagnosticCategory.Message,
                                    code = 2594,
                                    fileName = resolvedFile,
                                    line = rLine,
                                    character = rChar,
                                    start = exportEqStmt.pos,
                                    length = 1,
                                )
                            )
                        } else emptyList()
                        diagnostics.add(Diagnostic(
                            message = "Module '\"$displayName\"' can only be default-imported using the 'esModuleInterop' flag",
                            category = DiagnosticCategory.Error,
                            code = 1259,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameStart,
                            length = nameLength,
                            relatedInformation = relatedInfos,
                        ))
                    } else {
                        // TS2613: Module has no default export. Did you mean to use named import?
                        // Fires when the default binding name matches a named export of the module.
                        val importName = defaultBinding.text
                        val moduleNamedExports = getModuleNamedExports(targetFile)
                        if (importName in moduleNamedExports) {
                            diagnostics.add(Diagnostic(
                                message = "Module '\"$displayName\"' has no default export. Did you mean to use 'import { $importName } from \"$displayName\"' instead?",
                                category = DiagnosticCategory.Error,
                                code = 2613,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = nameStart,
                                length = nameLength,
                            ))
                        } else {
                            diagnostics.add(Diagnostic(
                                message = "Module '\"$displayName\"' has no default export.",
                                category = DiagnosticCategory.Error,
                                code = 1192,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = nameStart,
                                length = nameLength,
                            ))
                        }
                    }
                }

                // TS2614: named import specifier not found in module exports, but
                // module has a default export — suggest using default import instead.
                // Only fires when module HAS a default export (otherwise TS1192 is enough).
                if (hasDefaultExport) {
                    val namedBindings = importClause.namedBindings
                    if (namedBindings is NamedImports) {
                        val moduleNamedExports = getModuleNamedExports(targetFile)
                        for (importSpecifier in namedBindings.elements) {
                            if (importSpecifier.isTypeOnly) continue
                            // The "property name" is what's imported; the "name" is the local binding
                            val importedName = (importSpecifier.propertyName ?: importSpecifier.name).text
                            // import { default as X } is a valid way to import the default export — skip
                            if (importedName == "default") continue
                            if (importedName !in moduleNamedExports) {
                                // Squiggle on the propertyName if present, else on the name
                                val nameNode = importSpecifier.propertyName ?: importSpecifier.name
                                val nameStart = nameNode.pos
                                val nameLength = nameNode.text.length
                                val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
                                diagnostics.add(Diagnostic(
                                    message = "Module '\"$moduleName\"' has no exported member '$importedName'. Did you mean to use 'import $importedName from \"$moduleName\"' instead?",
                                    category = DiagnosticCategory.Error,
                                    code = 2614,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = nameStart,
                                    length = nameLength,
                                ))
                            }
                        }
                    }
                }

                // TS2617/TS2596/TS2598 + TS2497: `import { X } from "./a"` where "./a" uses
                // `export =` and esModuleInterop is explicitly false. TypeScript cannot synthesize
                // named bindings without esModuleInterop, so the named import is invalid.
                // The specific code + TS2497 message depend on the importer's file kind and module
                // output target.
                val namedBindingsEM = importClause.namedBindings
                if (hasExportEquals && options.esModuleInteropExplicitlyFalse &&
                    namedBindingsEM is NamedImports) {
                    val importerIsJs = fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                        fileName.endsWith(".mjs") || fileName.endsWith(".cjs")
                    val isEsmTarget = isESModuleFormat(options.effectiveModule, fileName)
                    for (importSpecifier in namedBindingsEM.elements) {
                        if (importSpecifier.isTypeOnly) continue
                        val nameNode = importSpecifier.propertyName ?: importSpecifier.name
                        val importedName = nameNode.text
                        if (importedName == "default") continue
                        val nameStart = nameNode.pos
                        val nameLength = importedName.length
                        val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
                        val (code, message) = when {
                            isEsmTarget -> 2596 to
                                "'$importedName' can only be imported by turning on the 'esModuleInterop' flag and using a default import."
                            importerIsJs -> 2598 to
                                "'$importedName' can only be imported by using a 'require' call or by turning on the 'esModuleInterop' flag and using a default import."
                            else -> 2617 to
                                "'$importedName' can only be imported by using 'import $importedName = require(\"$moduleName\")' or by turning on the 'esModuleInterop' flag and using a default import."
                        }
                        diagnostics.add(Diagnostic(
                            message = message,
                            category = DiagnosticCategory.Error,
                            code = code,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameStart,
                            length = nameLength,
                        ))
                    }
                    val specStart = specifier.pos
                    val specLength = moduleName.length + 2
                    val (line, character) = getLineAndCharacterOfPosition(source, specStart)
                    val ts2497Message = if (isEsmTarget) {
                        "This module can only be referenced with ECMAScript imports/exports by turning on the 'allowSyntheticDefaultImports' flag and referencing its default export."
                    } else {
                        "This module can only be referenced with ECMAScript imports/exports by turning on the 'esModuleInterop' flag and referencing its default export."
                    }
                    diagnostics.add(Diagnostic(
                        message = ts2497Message,
                        category = DiagnosticCategory.Error,
                        code = 2497,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = specStart,
                        length = specLength,
                    ))
                }

                // TS2497: `import * as X from` against an `export =` module in an ESM
                // output format (ES2015+, ESNext, Preserve) requires
                // allowSyntheticDefaultImports (already guarded at the top of this
                // function). Only fires when the namespace alias is actually referenced
                // as a value — plain `import * as X from "./a"` without any use of X
                // compiles away cleanly.
                val isEsmOutput = isESModuleFormat(options.effectiveModule, fileName)
                val nsBinding = importClause.namedBindings
                if (isEsmOutput && hasExportEquals && nsBinding is NamespaceImport) {
                    val aliasName = nsBinding.name.text
                    if (aliasName.isNotEmpty() && isIdentifierReferencedAsValue(aliasName, result.sourceFile.statements, stmt)) {
                        val specStart = specifier.pos
                        val specLength = moduleName.length + 2 // +2 for quotes
                        val (line, character) = getLineAndCharacterOfPosition(source, specStart)
                        diagnostics.add(Diagnostic(
                            message = "This module can only be referenced with ECMAScript imports/exports by turning on the 'allowSyntheticDefaultImports' flag and referencing its default export.",
                            category = DiagnosticCategory.Error,
                            code = 2497,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = specStart,
                            length = specLength,
                        ))
                    }
                }
            }
        }
    }

    /**
     * Returns true if [name] appears as a value-position Identifier anywhere in the
     * file's [statements], excluding [skipStmt] (the import declaration that introduces
     * the alias). Used by TS2497 to avoid emitting the diagnostic for unused namespace
     * imports.
     */
    private fun isIdentifierReferencedAsValue(
        name: String,
        statements: List<Statement>,
        skipStmt: Statement,
    ): Boolean {
        fun exprContains(e: Expression?): Boolean {
            if (e == null) return false
            return when (e) {
                is Identifier -> e.text == name
                is PropertyAccessExpression -> exprContains(e.expression)
                is ElementAccessExpression -> exprContains(e.expression) || exprContains(e.argumentExpression)
                is CallExpression -> exprContains(e.expression) || e.arguments.any { exprContains(it) }
                is NewExpression -> exprContains(e.expression) || (e.arguments?.any { exprContains(it) } == true)
                is BinaryExpression -> exprContains(e.left) || exprContains(e.right)
                is PrefixUnaryExpression -> exprContains(e.operand)
                is PostfixUnaryExpression -> exprContains(e.operand)
                is ParenthesizedExpression -> exprContains(e.expression)
                is ConditionalExpression -> exprContains(e.condition) || exprContains(e.whenTrue) || exprContains(e.whenFalse)
                is TypeOfExpression -> exprContains(e.expression)
                is SpreadElement -> exprContains(e.expression)
                is ArrayLiteralExpression -> e.elements.any { exprContains(it) }
                is ObjectLiteralExpression -> e.properties.any { p ->
                    when (p) {
                        is PropertyAssignment -> exprContains(p.initializer)
                        is ShorthandPropertyAssignment -> p.name.text == name
                        is SpreadAssignment -> exprContains(p.expression)
                        else -> false
                    }
                }
                else -> false
            }
        }
        fun stmtContains(s: Statement): Boolean {
            if (s === skipStmt) return false
            return when (s) {
                is ExpressionStatement -> exprContains(s.expression)
                is VariableStatement -> s.declarationList.declarations.any { exprContains(it.initializer) }
                is ReturnStatement -> exprContains(s.expression)
                is IfStatement -> exprContains(s.expression) || stmtContains(s.thenStatement) ||
                    (s.elseStatement?.let { stmtContains(it) } == true)
                is Block -> s.statements.any { stmtContains(it) }
                is ExportAssignment -> exprContains(s.expression)
                else -> false
            }
        }
        return statements.any { stmtContains(it) }
    }

    // -----------------------------------------------------------------------
    // TS2305: Module has no exported member 'X'
    // -----------------------------------------------------------------------

    /**
     * Check named imports and named re-exports against the target module's actual exports.
     * Emits TS2305 when importing a name that the module doesn't export.
     *
     * Note: TS2614 (similar but with "Did you mean to use default import?") is handled
     * in checkDefaultImports() for the case where the module HAS a default export.
     */
    private fun checkNamedImportExistence() {
        val isMultiFile = binderResults.size > 1 || isMultiFileSource
        if (!isMultiFile) return

        // Skip when moduleSuffixes is set — module resolution is suffix-aware and we can't
        // resolve to the correct suffixed file (e.g. ./foo → ./foo.ios.ts with suffix ".ios")
        if (!options.moduleSuffixes.isNullOrEmpty()) return

        // For re-exports of 'default': suppress TS2305 only for System module format,
        // unless allowSyntheticDefaultImports is explicitly set to false.
        // System format handles default re-exports dynamically.
        // Note: allowSyntheticDefaultImports=true alone does NOT suppress TS2305 for re-exports.
        val suppressDefaultReexportError = options.effectiveModule == ModuleKind.System &&
            !options.allowSyntheticDefaultImportsExplicitlyFalse

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            // Check both .ts and .d.ts files (d.ts files can import from other modules)
            val source = result.sourceFile.text

            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ImportDeclaration -> {
                        val clause = stmt.importClause ?: continue
                        if (clause.isTypeOnly) continue
                        val namedBindings = clause.namedBindings as? NamedImports ?: continue

                        val specifier = stmt.moduleSpecifier
                        val moduleName = (specifier as? StringLiteralNode)?.text ?: continue
                        // Only check relative imports — non-relative imports might resolve incorrectly
                        // (e.g. npm packages with complex node_modules resolution)
                        if (!moduleName.startsWith("./") && !moduleName.startsWith("../")) continue
                        val resolvedFile = resolveModuleSpecifierRelative(moduleName, fileName) ?: continue
                        val targetResult = fileResults[resolvedFile] ?: continue
                        val targetFile = targetResult.sourceFile

                        // If target has export=, it cannot be named-imported
                        val hasExportEquals = targetFile.statements.any { it is ExportAssignment && it.isExportEquals }
                        // Get all available exports (named + default)
                        val allExports = getModuleAllExports(targetFile)
                        val hasDefaultExport = moduleHasDefaultExport(targetFile)

                        for (specEl in namedBindings.elements) {
                            if (specEl.isTypeOnly) continue
                            val importedName = (specEl.propertyName ?: specEl.name).text
                            // Skip parse-error artifacts (e.g. `*`, `from` as import names)
                            if (!importedName[0].isLetter() && importedName[0] != '_' && importedName[0] != '$') continue
                            // 'default' as name: checked by checkDefaultImports (TS1192) or TS2305
                            // Skip 'default' here only if checked already via hasDefaultExport
                            if (importedName == "default") {
                                // 'import { default as X }' — check if module has default
                                // This is not covered by checkDefaultImports (which only checks importClause.name)
                                // TS2305 fires if no default export and allowSyntheticDefaultImports is false
                                if (!hasDefaultExport && !hasExportEquals && !suppressDefaultReexportError) {
                                    val nameNode = specEl.propertyName ?: specEl.name
                                    emitTs2305(source, fileName, moduleName, importedName, nameNode)
                                }
                                continue
                            }
                            // For non-default names: check against module exports
                            // Skip if we already emit TS2614 for this case (module has default export)
                            // TS2614 is emitted in checkDefaultImports for this pattern
                            if (hasDefaultExport) continue  // TS2614 handled in checkDefaultImports
                            // Skip TS2305 for export= modules — we'd need to check namespace members
                            // and type members of the exported value, which requires full type resolution
                            if (hasExportEquals) continue
                            if (importedName !in allExports) {
                                val nameNode = specEl.propertyName ?: specEl.name
                                // Check if name is declared locally but not exported → TS2459
                                // or declared locally but exported under a different name → TS2460
                                val localNames = getModuleLocalNames(targetFile)
                                val exportAlias = getModuleExportAlias(targetFile, importedName)
                                when {
                                    exportAlias != null -> {
                                        // TS2460: name declared locally, exported as 'exportAlias'
                                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                                        // Add TS2728 related info pointing to the declaration in the target file
                                        val declPos2460 = getLocalDeclarationPos(targetFile, importedName)
                                        val targetSource2460 = targetResult.sourceFile.text
                                        val relatedInfo2460 = if (declPos2460 != null) {
                                            val (declLine, declChar) = getLineAndCharacterOfPosition(targetSource2460, declPos2460.first)
                                            listOf(Diagnostic(
                                                message = "'$importedName' is declared here.",
                                                category = DiagnosticCategory.Message,
                                                code = 2728,
                                                fileName = resolvedFile,
                                                line = declLine,
                                                character = declChar,
                                                start = declPos2460.first,
                                                length = declPos2460.second,
                                            ))
                                        } else emptyList()
                                        diagnostics.add(Diagnostic(
                                            message = "Module '\"$moduleName\"' declares '$importedName' locally, but it is exported as '$exportAlias'.",
                                            category = DiagnosticCategory.Error,
                                            code = 2460,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = nameNode.pos,
                                            length = nameNode.text.length,
                                            relatedInformation = relatedInfo2460,
                                        ))
                                    }
                                    importedName in localNames -> {
                                        // TS2459: name declared locally but not exported
                                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                                        // Add TS2728 related info for first declaration + TS6204 "and here" for additional
                                        val allDeclPositions = getAllLocalDeclarationPositions(targetFile, importedName)
                                        val targetSource = targetResult.sourceFile.text
                                        val relatedInfo = buildList {
                                            allDeclPositions.forEachIndexed { idx, declPos ->
                                                val (declLine, declChar) = getLineAndCharacterOfPosition(targetSource, declPos.first)
                                                if (idx == 0) {
                                                    add(Diagnostic(
                                                        message = "'$importedName' is declared here.",
                                                        category = DiagnosticCategory.Message,
                                                        code = 2728,
                                                        fileName = resolvedFile,
                                                        line = declLine,
                                                        character = declChar,
                                                        start = declPos.first,
                                                        length = declPos.second,
                                                    ))
                                                } else {
                                                    add(Diagnostic(
                                                        message = "and here.",
                                                        category = DiagnosticCategory.Message,
                                                        code = 6204,
                                                        fileName = resolvedFile,
                                                        line = declLine,
                                                        character = declChar,
                                                        start = declPos.first,
                                                        length = declPos.second,
                                                    ))
                                                }
                                            }
                                        }
                                        diagnostics.add(Diagnostic(
                                            message = "Module '\"$moduleName\"' declares '$importedName' locally, but it is not exported.",
                                            category = DiagnosticCategory.Error,
                                            code = 2459,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = nameNode.pos,
                                            length = nameNode.text.length,
                                            relatedInformation = relatedInfo,
                                        ))
                                    }
                                    else -> emitTs2305(source, fileName, moduleName, importedName, nameNode)
                                }
                            }
                        }
                    }
                    is ExportDeclaration -> {
                        // export { X } from "./module" — check X against module exports
                        val moduleName = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                        // Only check relative imports — non-relative imports might resolve incorrectly
                        if (!moduleName.startsWith("./") && !moduleName.startsWith("../")) continue
                        if (stmt.isTypeOnly) continue
                        val clause = stmt.exportClause as? NamedExports ?: continue

                        val resolvedFile = resolveModuleSpecifierRelative(moduleName, fileName) ?: continue
                        val targetResult = fileResults[resolvedFile] ?: continue
                        val targetFile = targetResult.sourceFile

                        val allExports = getModuleAllExports(targetFile)
                        val hasDefaultExport = moduleHasDefaultExport(targetFile)
                        val hasExportEqualsInTarget = targetFile.statements.any { it is ExportAssignment && it.isExportEquals }

                        for (specEl in clause.elements) {
                            if (specEl.isTypeOnly) continue
                            // For re-exports: the "source name" in the source module
                            // is either propertyName (for `export { X as Y } from ...`) or name
                            val sourceName = (specEl.propertyName ?: specEl.name).text
                            if (sourceName == "default") {
                                if (!hasDefaultExport && !hasExportEqualsInTarget && !suppressDefaultReexportError) {
                                    val nameNode = specEl.propertyName ?: specEl.name
                                    emitTs2305(source, fileName, moduleName, "default", nameNode)
                                }
                                continue
                            }
                            // Skip named member checks for export= modules (requires type resolution)
                            if (hasExportEqualsInTarget) continue
                            if (sourceName !in allExports) {
                                // Only emit if TS2614 wouldn't cover this case
                                // (TS2614 fires for named imports where module has default)
                                // For re-exports, TS2305 always fires for missing names
                                val nameNode = specEl.propertyName ?: specEl.name
                                emitTs2305(source, fileName, moduleName, sourceName, nameNode)
                            }
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    private fun emitTs2305(
        source: String, fileName: String, moduleName: String,
        importedName: String, nameNode: Identifier
    ) {
        val displayName = when {
            moduleName.startsWith("./") || moduleName.startsWith("../") -> moduleName
            else -> {
                val resolved = resolveModuleSpecifier(moduleName)
                    ?.removeSuffix(".d.ts")?.removeSuffix(".ts")?.removeSuffix(".tsx")
                    ?: moduleName
                resolved
            }
        }
        val nameStart = nameNode.pos
        val nameLength = nameNode.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
        diagnostics.add(Diagnostic(
            message = "Module '\"$displayName\"' has no exported member '$importedName'.",
            category = DiagnosticCategory.Error,
            code = 2305,
            fileName = fileName,
            line = line,
            character = character,
            start = nameStart,
            length = nameLength,
        ))
    }

    /**
     * Returns ALL exports from a source file including 'default'.
     * Used for TS2305 checking.
     */
    private fun getModuleAllExports(file: SourceFile): Set<String> {
        val exports = getModuleNamedExports(file).toMutableSet()
        if (moduleHasDefaultExport(file)) {
            exports.add("default")
        }
        return exports
    }

    /**
     * Returns all locally-declared names in the source file (exported or not).
     * Used to distinguish TS2459 (declared but not exported) from TS2305 (not declared).
     */
    private fun getModuleLocalNames(file: SourceFile): Set<String> {
        val names = mutableSetOf<String>()
        for (stmt in file.statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier) names.add(name.text)
                    }
                }
                is FunctionDeclaration -> stmt.name?.let { names.add(it.text) }
                is ClassDeclaration -> stmt.name?.let { names.add(it.text) }
                is InterfaceDeclaration -> names.add(stmt.name.text)
                is TypeAliasDeclaration -> names.add(stmt.name.text)
                is EnumDeclaration -> names.add(stmt.name.text)
                is ModuleDeclaration -> {
                    val name = stmt.name
                    if (name is Identifier) names.add(name.text)
                }
                else -> {}
            }
        }
        return names
    }

    /**
     * Returns the exported name for a local name that is exported under a different name.
     * E.g. for `export { bar as baz }`, getModuleExportAlias(file, "bar") returns "baz".
     * Returns null if bar is not locally declared and re-exported under a different alias.
     */
    private fun getModuleExportAlias(file: SourceFile, localName: String): String? {
        for (stmt in file.statements) {
            if (stmt !is ExportDeclaration) continue
            if (stmt.moduleSpecifier != null) continue  // skip re-exports from other modules
            val clause = stmt.exportClause as? NamedExports ?: continue
            for (specifier in clause.elements) {
                val propName = specifier.propertyName?.text
                val exportedName = specifier.name.text
                // `export { localName as exportedName }` — propName = localName, name = exportedName
                if (propName == localName && exportedName != localName) {
                    return exportedName
                }
            }
        }
        return null
    }

    /**
     * Returns the position (start, length) of the declaration of [name] in [file],
     * for use as TS2728 related info in TS2459 diagnostics.
     */
    private fun getLocalDeclarationPos(file: SourceFile, name: String): Pair<Int, Int>? =
        getAllLocalDeclarationPositions(file, name).firstOrNull()

    /**
     * Returns ALL positions where [name] is declared in [file], for use as TS2728/TS6204 related info.
     */
    private fun getAllLocalDeclarationPositions(file: SourceFile, name: String): List<Pair<Int, Int>> {
        val result = mutableListOf<Pair<Int, Int>>()
        for (stmt in file.statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val ident = decl.name as? Identifier ?: continue
                        if (ident.text == name) result.add(Pair(ident.pos, ident.text.length))
                    }
                }
                is FunctionDeclaration -> {
                    val ident = stmt.name ?: continue
                    if (ident.text == name) result.add(Pair(ident.pos, ident.text.length))
                }
                is ClassDeclaration -> {
                    val ident = stmt.name ?: continue
                    if (ident.text == name) result.add(Pair(ident.pos, ident.text.length))
                }
                is InterfaceDeclaration -> {
                    if (stmt.name.text == name) result.add(Pair(stmt.name.pos, stmt.name.text.length))
                }
                is TypeAliasDeclaration -> {
                    if (stmt.name.text == name) result.add(Pair(stmt.name.pos, stmt.name.text.length))
                }
                is EnumDeclaration -> {
                    if (stmt.name.text == name) result.add(Pair(stmt.name.pos, stmt.name.text.length))
                }
                is ModuleDeclaration -> {
                    val ident = stmt.name as? Identifier ?: continue
                    if (ident.text == name) result.add(Pair(ident.pos, ident.text.length))
                }
                else -> {}
            }
        }
        return result
    }

    /**
     * Returns the set of named exports from a source file (excluding 'default').
     * Used by TS2614 checking to determine if named imports exist in the module.
     */
    private fun getModuleNamedExports(file: SourceFile): Set<String> {
        val exports = mutableSetOf<String>()
        for (stmt in file.statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        for (decl in stmt.declarationList.declarations) {
                            val name = decl.name
                            if (name is Identifier) exports.add(name.text)
                        }
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default !in stmt.modifiers) {
                        stmt.name?.let { exports.add(it.text) }
                    }
                }
                is ClassDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default !in stmt.modifiers) {
                        stmt.name?.let { exports.add(it.text) }
                    }
                }
                is InterfaceDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        exports.add(stmt.name.text)
                    }
                }
                is TypeAliasDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        exports.add(stmt.name.text)
                    }
                }
                is EnumDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        exports.add(stmt.name.text)
                    }
                }
                is ModuleDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        val name = stmt.name
                        if (name is Identifier) exports.add(name.text)
                    }
                }
                is ExportDeclaration -> {
                    // export { A, B, C as D } — add each specifier's exported name
                    val clause = stmt.exportClause
                    if (clause is NamedExports) {
                        for (specifier in clause.elements) {
                            val exportedName = specifier.name.text
                            if (exportedName != "default") exports.add(exportedName)
                        }
                    }
                }
                else -> {}
            }
        }
        return exports
    }

    /**
     * Returns true if the given source file has a default export via:
     * - `export default <expr>` (ExportAssignment with isExportEquals=false)
     * - `export default function/class` (declaration with Default modifier)
     * - `export { X as default }` (ExportDeclaration with a specifier named "default")
     */
    private fun moduleHasDefaultExport(file: SourceFile): Boolean {
        for (stmt in file.statements) {
            when (stmt) {
                is ExportAssignment -> {
                    if (!stmt.isExportEquals) return true
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Default in stmt.modifiers) return true
                }
                is ClassDeclaration -> {
                    if (ModifierFlag.Default in stmt.modifiers) return true
                }
                is InterfaceDeclaration -> {
                    if (ModifierFlag.Default in stmt.modifiers) return true
                }
                is ExportDeclaration -> {
                    val clause = stmt.exportClause
                    if (clause is NamedExports) {
                        for (specifier in clause.elements) {
                            if (specifier.name.text == "default") return true
                        }
                    }
                }
                else -> {}
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Jump target checking (TS1107)
    // -----------------------------------------------------------------------

    /**
     * Check for TS1107: "Jump target cannot cross function boundary."
     * break/continue inside a nested function/arrow that targets an outer loop/label.
     */
    private fun checkJumpTargets() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkJumpInStatements(result.sourceFile.statements, source, fileName,
                inIteration = false, inSwitch = false, labelNames = emptyMap(),
                crossedFunctionBoundary = false)
        }
    }

    private fun checkJumpInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        inIteration: Boolean,
        inSwitch: Boolean,
        labelNames: Map<String, Boolean>,
        crossedFunctionBoundary: Boolean,
    ) {
        for (stmt in statements) {
            checkJumpInStatement(stmt, source, fileName, inIteration, inSwitch, labelNames, crossedFunctionBoundary)
        }
    }

    private fun checkJumpInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        inIteration: Boolean,
        inSwitch: Boolean,
        labelNames: Map<String, Boolean>,
        crossedFunctionBoundary: Boolean,
    ) {
        when (stmt) {
            is BreakStatement -> {
                val label = stmt.label?.text
                if (label != null) {
                    // Labeled break — check if label is in scope
                    if (label !in labelNames) {
                        if (crossedFunctionBoundary) {
                            emitJumpDiagnostic(stmt, source, fileName, 1107,
                                "Jump target cannot cross function boundary.")
                        } else {
                            emitJumpDiagnostic(stmt, source, fileName, 1116,
                                "A 'break' statement can only jump to a label of an enclosing statement.")
                        }
                    }
                } else {
                    // Unlabeled break — needs to be in a loop or switch
                    if (!inIteration && !inSwitch) {
                        if (crossedFunctionBoundary) {
                            emitJumpDiagnostic(stmt, source, fileName, 1107,
                                "Jump target cannot cross function boundary.")
                        } else {
                            emitJumpDiagnostic(stmt, source, fileName, 1105,
                                "A 'break' statement can only be used within an enclosing iteration or switch statement.")
                        }
                    }
                }
            }
            is ContinueStatement -> {
                val label = stmt.label?.text
                if (label != null) {
                    // continue can only jump to labels of iteration statements
                    if (label !in labelNames || labelNames[label] != true) {
                        if (crossedFunctionBoundary) {
                            emitJumpDiagnostic(stmt, source, fileName, 1107,
                                "Jump target cannot cross function boundary.")
                        } else {
                            emitJumpDiagnostic(stmt, source, fileName, 1115,
                                "A 'continue' statement can only jump to a label of an enclosing iteration statement.")
                        }
                    }
                } else {
                    if (!inIteration) {
                        if (crossedFunctionBoundary) {
                            emitJumpDiagnostic(stmt, source, fileName, 1107,
                                "Jump target cannot cross function boundary.")
                        } else {
                            emitJumpDiagnostic(stmt, source, fileName, 1104,
                                "A 'continue' statement can only be used within an enclosing iteration statement.")
                        }
                    }
                }
            }
            // Loop statements: set inIteration = true
            is ForStatement -> {
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration = true, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is ForInStatement -> {
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration = true, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is ForOfStatement -> {
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration = true, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is WhileStatement -> {
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration = true, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is DoStatement -> {
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration = true, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val stmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkJumpInStatements(stmts, source, fileName,
                        inIteration, inSwitch = true, labelNames, crossedFunctionBoundary)
                }
            }
            is LabeledStatement -> {
                // TS1344: A label is not allowed on declaration statements (strict mode only)
                val isStrict = options.alwaysStrict != false
                if (isStrict && isDeclarationStatement(stmt.statement)) {
                    val labelStart = stmt.label.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, labelStart)
                    diagnostics.add(Diagnostic(
                        message = "A label is not allowed here.",
                        category = DiagnosticCategory.Error,
                        code = 1344,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = labelStart,
                        length = stmt.label.text.length,
                    ))
                }
                val isIterationLabel = stmt.statement is ForStatement || stmt.statement is ForInStatement ||
                    stmt.statement is ForOfStatement || stmt.statement is WhileStatement ||
                    stmt.statement is DoStatement
                val newLabels = labelNames + (stmt.label.text to isIterationLabel)
                checkJumpInStatement(stmt.statement, source, fileName,
                    inIteration, inSwitch, newLabels, crossedFunctionBoundary)
            }
            is Block -> {
                checkJumpInStatements(stmt.statements, source, fileName,
                    inIteration, inSwitch, labelNames, crossedFunctionBoundary)
            }
            is IfStatement -> {
                checkJumpInStatement(stmt.thenStatement, source, fileName,
                    inIteration, inSwitch, labelNames, crossedFunctionBoundary)
                stmt.elseStatement?.let {
                    checkJumpInStatement(it, source, fileName, inIteration, inSwitch, labelNames, crossedFunctionBoundary)
                }
            }
            is TryStatement -> {
                checkJumpInStatements(stmt.tryBlock.statements, source, fileName,
                    inIteration, inSwitch, labelNames, crossedFunctionBoundary)
                stmt.catchClause?.block?.let {
                    checkJumpInStatements(it.statements, source, fileName,
                        inIteration, inSwitch, labelNames, crossedFunctionBoundary)
                }
                stmt.finallyBlock?.let {
                    checkJumpInStatements(it.statements, source, fileName,
                        inIteration, inSwitch, labelNames, crossedFunctionBoundary)
                }
            }
            // Function boundaries: reset iteration/switch/label state, mark boundary crossed
            is FunctionDeclaration -> {
                stmt.body?.let {
                    checkJumpInStatements(it.statements, source, fileName,
                        inIteration = false, inSwitch = false, labelNames = emptyMap(),
                        crossedFunctionBoundary = true)
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let {
                        checkJumpInStatements(it.statements, source, fileName,
                            inIteration = false, inSwitch = false, labelNames = emptyMap(),
                            crossedFunctionBoundary = true)
                    }
                }
            }
            is ModuleDeclaration -> {
                // Recurse into namespace bodies with same iteration/switch context.
                // Note: TypeScript fires TS1104 (continue not in iteration) and TS1108 (return
                // outside function) inside namespaces, but does NOT fire TS1105 (break not in
                // iteration/switch) because TS1036 (ambient statement) covers break statements.
                // We suppress TS1105 for break inside namespace by noting the namespace context.
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkJumpInStatements(body.statements, source, fileName,
                        inIteration, inSwitch = true /* suppress TS1105 for break */,
                        labelNames, crossedFunctionBoundary)
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkJumpInExpr(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkJumpInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkJumpInExpr(it, source, fileName) }
            else -> {}
        }
    }

    private fun checkJumpInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkJumpInStatements(body.statements, source, fileName,
                        inIteration = false, inSwitch = false, labelNames = emptyMap(),
                        crossedFunctionBoundary = true)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkJumpInStatements(expr.body.statements, source, fileName,
                    inIteration = false, inSwitch = false, labelNames = emptyMap(),
                    crossedFunctionBoundary = true)
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let {
                        checkJumpInStatements(it.statements, source, fileName,
                            inIteration = false, inSwitch = false, labelNames = emptyMap(),
                            crossedFunctionBoundary = true)
                    }
                }
            }
            is CallExpression -> {
                expr.arguments.forEach { checkJumpInExpr(it, source, fileName) }
            }
            is ParenthesizedExpression -> checkJumpInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkJumpInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkJumpInExpr(current, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Returns true if this statement is a "declaration statement" that cannot be the body
     * of a labeled statement. TS1344 fires for labels on these statement types.
     */
    private fun isDeclarationStatement(stmt: Statement): Boolean = stmt is VariableStatement ||
        stmt is FunctionDeclaration || stmt is ClassDeclaration || stmt is EnumDeclaration ||
        stmt is ModuleDeclaration || stmt is InterfaceDeclaration || stmt is TypeAliasDeclaration ||
        stmt is ImportDeclaration || stmt is ExportDeclaration || stmt is ExportAssignment

    private fun emitJumpDiagnostic(stmt: Statement, source: String, fileName: String, code: Int, message: String) {
        var start = stmt.pos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) start++
        val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
        var end = lineEnd
        while (end > start && source[end - 1].let { it == ' ' || it == '\t' || it == '\r' }) end--
        val length = end - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Strict mode identifier checking (TS1100)
    // -----------------------------------------------------------------------

    /**
     * Check for TS1100: "Invalid use of 'arguments'/'eval' in strict mode."
     * In strict mode, `arguments` and `eval` cannot be used as variable/parameter/function names.
     */
    private fun checkStrictModeIdentifiers() {
        val restricted = setOf("arguments", "eval")
        // Global strict mode from compiler options
        val globalStrict = options.alwaysStrict == true || options.strict
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Per-file strict mode: options + "use strict" prologue + module file
            val hasUseStrict = result.sourceFile.statements.firstOrNull()?.let { stmt ->
                stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                    (stmt.expression as StringLiteralNode).text == "use strict"
            } == true
            val isModule = isModuleFile(result.sourceFile.statements)
            // Module files get TS1215 instead of TS1100
            if (isModule) {
                checkModuleStrictModeInStatements(result.sourceFile.statements, source, fileName, restricted)
            } else if (globalStrict || hasUseStrict) {
                checkStrictModeInStatements(result.sourceFile.statements, source, fileName, restricted)
            } else {
                // Even when the file isn't globally strict, function bodies with their own
                // "use strict" prologue directives are locally strict and must be checked.
                checkFunctionLocalStrictMode(result.sourceFile.statements, source, fileName, restricted)
            }
        }
    }

    /**
     * Like checkStrictModeInStatements but uses TS1215 (module-specific) instead of TS1100
     * for top-level statements. This covers variable declarations and function/class parameters.
     */
    private fun checkModuleStrictModeInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkModuleStrictModeName(decl.name, source, fileName, restricted)
                        decl.initializer?.let { checkStrictModeInExpr(it, source, fileName, restricted) }
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        stmt.name?.let { checkModuleStrictModeName(it, source, fileName, restricted) }
                        // Don't check function parameters here — checkArgumentsCollision already handles those
                        // Nested function bodies are just strict (TS1100), not module-specific
                        stmt.body?.let { checkStrictModeInStatements(it.statements, source, fileName, restricted) }
                    }
                }
                else -> {
                    // For other statements (class declarations, etc.), use regular strict mode checking (TS1100)
                    checkStrictModeInStatement(stmt, source, fileName, restricted)
                }
            }
        }
    }

    private fun checkModuleStrictModeName(name: Node, source: String, fileName: String, restricted: Set<String>) {
        when (name) {
            is Identifier -> {
                if (name.text in restricted) {
                    val start = name.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val word = name.text
                    val msg = "Invalid use of '$word'. Modules are automatically in strict mode."
                    diagnostics.add(Diagnostic(
                        message = msg,
                        category = DiagnosticCategory.Error,
                        code = 1215,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = word.length,
                    ))
                }
            }
            else -> {}
        }
    }

    /**
     * Traverses statements looking for function declarations/expressions whose bodies
     * start with a "use strict" prologue directive, then checks those bodies for TS1100.
     * Called when the enclosing scope is NOT globally strict.
     */
    private fun checkFunctionLocalStrictMode(
        statements: List<Statement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        val body = stmt.body
                        if (body != null) {
                            if (hasPrologueUseStrict(body.statements)) {
                                // This function is locally strict — check its body
                                checkStrictModeInStatements(body.statements, source, fileName, restricted)
                            } else {
                                // Not strict, but recurse to find nested strictly-strict functions
                                checkFunctionLocalStrictMode(body.statements, source, fileName, restricted)
                            }
                        }
                    }
                }
                is ExpressionStatement -> {
                    checkFunctionLocalStrictModeInExpr(stmt.expression, source, fileName, restricted)
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let {
                            checkFunctionLocalStrictModeInExpr(it, source, fileName, restricted)
                        }
                    }
                }
                is Block -> checkFunctionLocalStrictMode(stmt.statements, source, fileName, restricted)
                is IfStatement -> {
                    checkFunctionLocalStrictModeStmt(stmt.thenStatement, source, fileName, restricted)
                    stmt.elseStatement?.let {
                        checkFunctionLocalStrictModeStmt(it, source, fileName, restricted)
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkFunctionLocalStrictMode(body.statements, source, fileName, restricted)
                    }
                }
                else -> {}
            }
        }
    }

    private fun checkFunctionLocalStrictModeStmt(
        stmt: Statement,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (stmt) {
            is Block -> checkFunctionLocalStrictMode(stmt.statements, source, fileName, restricted)
            else -> checkFunctionLocalStrictMode(listOf(stmt), source, fileName, restricted)
        }
    }

    private fun checkFunctionLocalStrictModeInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (expr) {
            is FunctionExpression -> {
                val body = expr.body
                if (hasPrologueUseStrict(body.statements)) {
                    checkStrictModeInStatements(body.statements, source, fileName, restricted)
                } else {
                    checkFunctionLocalStrictMode(body.statements, source, fileName, restricted)
                }
            }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) {
                    if (hasPrologueUseStrict(body.statements)) {
                        checkStrictModeInStatements(body.statements, source, fileName, restricted)
                    } else {
                        checkFunctionLocalStrictMode(body.statements, source, fileName, restricted)
                    }
                }
            }
            else -> {}
        }
    }

    private fun hasPrologueUseStrict(statements: List<Statement>): Boolean =
        statements.firstOrNull()?.let { stmt ->
            stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                (stmt.expression as StringLiteralNode).text == "use strict"
        } == true

    // -----------------------------------------------------------------------
    // TS1042: modifier cannot be used here (object literal members)
    // -----------------------------------------------------------------------

    private fun checkObjectLiteralModifiers() {
        val accessModifiers = setOf(ModifierFlag.Public, ModifierFlag.Private, ModifierFlag.Protected)
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForObjectLiteralModifiers(result.sourceFile.statements, source, fileName, accessModifiers)
        }
    }

    private fun walkForObjectLiteralModifiers(stmts: List<Statement>, source: String, fileName: String, accessModifiers: Set<ModifierFlag>) {
        for (stmt in stmts) walkExprForObjectLiteralModifiers(stmt, source, fileName, accessModifiers)
    }

    private fun walkExprForObjectLiteralModifiers(startNode: Node, source: String, fileName: String, accessModifiers: Set<ModifierFlag>) {
        // Iterative traversal using an explicit stack to avoid StackOverflow on deeply nested
        // BinaryExpression trees (e.g. binderBinaryExpressionStress.ts with 4971-level nesting).
        val stack = ArrayDeque<Node>()
        stack.addLast(startNode)
        while (stack.isNotEmpty()) {
            val node = stack.removeLast()
            when (node) {
                is ObjectLiteralExpression -> {
                    for (prop in node.properties) {
                        val modifiers = when (prop) {
                            is MethodDeclaration -> prop.modifiers
                            is GetAccessor -> prop.modifiers
                            is SetAccessor -> prop.modifiers
                            is PropertyAssignment -> emptySet()
                            else -> emptySet()
                        }
                        for (mod in accessModifiers) {
                            if (mod in modifiers) {
                                val modName = when (mod) {
                                    ModifierFlag.Public -> "public"
                                    ModifierFlag.Private -> "private"
                                    ModifierFlag.Protected -> "protected"
                                    else -> continue
                                }
                                // Find the modifier keyword position in source
                                val memberPos = prop.pos
                                val modIdx = source.indexOf(modName, memberPos)
                                if (modIdx >= 0 && modIdx < (prop.end.coerceAtMost(source.length))) {
                                    val (line, character) = getLineAndCharacterOfPosition(source, modIdx)
                                    diagnostics.add(Diagnostic(
                                        message = "'$modName' modifier cannot be used here.",
                                        category = DiagnosticCategory.Error,
                                        code = 1042,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = modIdx,
                                        length = modName.length,
                                    ))
                                    // TS1184: Modifiers cannot appear here. (TypeScript emits both
                                    // for methods, but NOT for get/set accessors)
                                    if (prop is MethodDeclaration) {
                                        diagnostics.add(Diagnostic(
                                            message = "Modifiers cannot appear here.",
                                            category = DiagnosticCategory.Error,
                                            code = 1184,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = modIdx,
                                            length = modName.length,
                                        ))
                                    }
                                }
                            }
                        }
                        // Push children for continued traversal
                        when (prop) {
                            is MethodDeclaration -> prop.body?.statements?.let { stmts -> stmts.forEach { stack.addLast(it) } }
                            is GetAccessor -> prop.body?.statements?.let { stmts -> stmts.forEach { stack.addLast(it) } }
                            is SetAccessor -> prop.body?.statements?.let { stmts -> stmts.forEach { stack.addLast(it) } }
                            is PropertyAssignment -> stack.addLast(prop.initializer)
                            else -> {}
                        }
                    }
                }
                // Push children onto stack instead of recursing
                is VariableStatement -> for (decl in node.declarationList.declarations) {
                    decl.initializer?.let { stack.addLast(it) }
                }
                is ExpressionStatement -> stack.addLast(node.expression)
                is ReturnStatement -> node.expression?.let { stack.addLast(it) }
                is Block -> node.statements.forEach { stack.addLast(it) }
                is FunctionDeclaration -> node.body?.statements?.forEach { stack.addLast(it) }
                is ClassDeclaration -> node.members.forEach { stack.addLast(it) }
                is MethodDeclaration -> node.body?.statements?.forEach { stack.addLast(it) }
                is GetAccessor -> node.body?.statements?.forEach { stack.addLast(it) }
                is SetAccessor -> node.body?.statements?.forEach { stack.addLast(it) }
                is Constructor -> node.body?.statements?.forEach { stack.addLast(it) }
                is IfStatement -> {
                    stack.addLast(node.thenStatement)
                    node.elseStatement?.let { stack.addLast(it) }
                }
                is ForStatement -> stack.addLast(node.statement)
                is WhileStatement -> stack.addLast(node.statement)
                is ArrowFunction -> {
                    val body = node.body
                    if (body is Block) body.statements.forEach { stack.addLast(it) }
                    else stack.addLast(body)
                }
                is FunctionExpression -> node.body?.statements?.forEach { stack.addLast(it) }
                is ParenthesizedExpression -> stack.addLast(node.expression)
                is BinaryExpression -> {
                    // Push both sides — iterative instead of recursive to handle deep nesting
                    stack.addLast(node.left)
                    stack.addLast(node.right)
                }
                is CallExpression -> {
                    stack.addLast(node.expression)
                    node.arguments.forEach { stack.addLast(it) }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Class body strict mode checking (TS1210)
    // -----------------------------------------------------------------------

    /**
     * TS1210: "Code contained in a class is evaluated in JavaScript's strict mode
     * which does not allow this use of '{0}'."
     * Class bodies are always strict — regardless of alwaysStrict/strict options.
     * Fires for `arguments` and `eval` as parameter names or variable declaration
     * names inside class constructors, methods, and accessors.
     */
    private fun checkClassStrictModeIdentifiers() {
        val restricted = setOf("arguments", "eval")
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            findClassesInStatements(result.sourceFile.statements, source, fileName, restricted)
        }
    }

    private fun findClassesInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    checkClassMembersForTS1210(stmt.members, source, fileName, restricted)
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        findClassesInStatements(body.statements, source, fileName, restricted)
                    }
                }
                is Block -> findClassesInStatements(stmt.statements, source, fileName, restricted)
                is IfStatement -> {
                    findClassesInStatement(stmt.thenStatement, source, fileName, restricted)
                    stmt.elseStatement?.let { findClassesInStatement(it, source, fileName, restricted) }
                }
                else -> {}
            }
        }
    }

    private fun findClassesInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (stmt) {
            is Block -> findClassesInStatements(stmt.statements, source, fileName, restricted)
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                checkClassMembersForTS1210(stmt.members, source, fileName, restricted)
            }
            else -> {}
        }
    }

    private fun checkClassMembersForTS1210(
        members: List<ClassElement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (member in members) {
            when (member) {
                is Constructor -> {
                    for (param in member.parameters) {
                        checkNameForTS1210(param.name, source, fileName, restricted)
                    }
                    member.body?.let { checkStatementsForTS1210(it.statements, source, fileName, restricted) }
                }
                is MethodDeclaration -> {
                    for (param in member.parameters) {
                        checkNameForTS1210(param.name, source, fileName, restricted)
                    }
                    member.body?.let { checkStatementsForTS1210(it.statements, source, fileName, restricted) }
                }
                is GetAccessor -> {
                    member.body?.let { checkStatementsForTS1210(it.statements, source, fileName, restricted) }
                }
                is SetAccessor -> {
                    for (param in member.parameters) {
                        checkNameForTS1210(param.name, source, fileName, restricted)
                    }
                    member.body?.let { checkStatementsForTS1210(it.statements, source, fileName, restricted) }
                }
                else -> {}
            }
        }
    }

    private fun checkStatementsForTS1210(
        statements: List<Statement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkNameForTS1210(decl.name, source, fileName, restricted)
                    }
                }
                is Block -> checkStatementsForTS1210(stmt.statements, source, fileName, restricted)
                is IfStatement -> {
                    checkStatementForTS1210(stmt.thenStatement, source, fileName, restricted)
                    stmt.elseStatement?.let { checkStatementForTS1210(it, source, fileName, restricted) }
                }
                is ForStatement -> {
                    when (val init = stmt.initializer) {
                        is VariableDeclarationList -> {
                            for (decl in init.declarations) {
                                checkNameForTS1210(decl.name, source, fileName, restricted)
                            }
                        }
                        else -> {}
                    }
                    checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                }
                is ForInStatement -> checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                is ForOfStatement -> checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                is WhileStatement -> checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                is DoStatement -> checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkStatementsForTS1210(clause.statements, source, fileName, restricted)
                            is DefaultClause -> checkStatementsForTS1210(clause.statements, source, fileName, restricted)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkStatementsForTS1210(stmt.tryBlock.statements, source, fileName, restricted)
                    stmt.catchClause?.let {
                        it.variableDeclaration?.let { v -> checkNameForTS1210(v.name, source, fileName, restricted) }
                        checkStatementsForTS1210(it.block.statements, source, fileName, restricted)
                    }
                    stmt.finallyBlock?.let { checkStatementsForTS1210(it.statements, source, fileName, restricted) }
                }
                is LabeledStatement -> checkStatementForTS1210(stmt.statement, source, fileName, restricted)
                // Nested function declarations DON'T get TS1210 — they have their own scope
                // Class expressions inside class bodies DO get checked
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        checkClassMembersForTS1210(stmt.members, source, fileName, restricted)
                    }
                }
                else -> {}
            }
        }
    }

    private fun checkStatementForTS1210(
        stmt: Statement,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (stmt) {
            is Block -> checkStatementsForTS1210(stmt.statements, source, fileName, restricted)
            else -> checkStatementsForTS1210(listOf(stmt), source, fileName, restricted)
        }
    }

    private fun checkNameForTS1210(
        name: Node,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        if (name is Identifier && name.text in restricted) {
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Code contained in a class is evaluated in JavaScript's strict mode which does not allow this use of '${name.text}'. For more information, see https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Strict_mode.",
                category = DiagnosticCategory.Error,
                code = 1210,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = name.text.length,
            ))
        }
    }

    private fun checkStrictModeInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        for (stmt in statements) {
            checkStrictModeInStatement(stmt, source, fileName, restricted)
        }
    }

    private fun checkStrictModeInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkStrictModeBindingName(decl.name, source, fileName, restricted)
                    // Recurse into function/arrow initializers to check nested declarations
                    decl.initializer?.let { checkStrictModeInExpr(it, source, fileName, restricted) }
                    // Check type annotations for function type parameter names
                    decl.type?.let { checkStrictModeInTypeNode(it, source, fileName, restricted) }
                }
            }
            is FunctionDeclaration -> {
                // Skip declare functions — no code gen, so no TS1100
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    stmt.name?.let { checkStrictModeName(it, source, fileName, restricted) }
                    for (param in stmt.parameters) {
                        checkStrictModeBindingName(param.name, source, fileName, restricted)
                    }
                    stmt.body?.let { checkStrictModeInStatements(it.statements, source, fileName, restricted) }
                }
            }
            is ClassDeclaration -> {
                // Skip declare classes — no code gen, so no TS1100
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    for (member in stmt.members) {
                        checkStrictModeInClassElement(member, source, fileName, restricted)
                    }
                }
            }
            is InterfaceDeclaration -> {
                // Check interface method/property parameter names for restricted identifiers
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is Constructor -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is IndexSignature -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is PropertyDeclaration -> {
                            val name = member.name
                            if (name is Identifier) checkStrictModeName(name, source, fileName, restricted)
                        }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> checkStrictModeInExpr(stmt.expression, source, fileName, restricted)
            is ReturnStatement -> stmt.expression?.let { checkStrictModeInExpr(it, source, fileName, restricted) }
            is Block -> checkStrictModeInStatements(stmt.statements, source, fileName, restricted)
            is IfStatement -> {
                checkStrictModeInStatement(stmt.thenStatement, source, fileName, restricted)
                stmt.elseStatement?.let { checkStrictModeInStatement(it, source, fileName, restricted) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            checkStrictModeBindingName(decl.name, source, fileName, restricted)
                        }
                    }
                    else -> {}
                }
                checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            }
            is ForInStatement -> checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            is ForOfStatement -> checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            is WhileStatement -> checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            is DoStatement -> checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkStrictModeInStatements(clause.statements, source, fileName, restricted)
                        is DefaultClause -> checkStrictModeInStatements(clause.statements, source, fileName, restricted)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkStrictModeInStatements(stmt.tryBlock.statements, source, fileName, restricted)
                stmt.catchClause?.let {
                    it.variableDeclaration?.let { v ->
                        checkStrictModeBindingName(v.name, source, fileName, restricted)
                    }
                    checkStrictModeInStatements(it.block.statements, source, fileName, restricted)
                }
                stmt.finallyBlock?.let { checkStrictModeInStatements(it.statements, source, fileName, restricted) }
            }
            is LabeledStatement -> checkStrictModeInStatement(stmt.statement, source, fileName, restricted)
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> checkStrictModeInStatements(body.statements, source, fileName, restricted)
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun checkStrictModeInClassElement(
        member: ClassElement,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        // TS1210 handles arguments/eval in class bodies — only check non-arguments/eval
        // names for TS1100 here to avoid duplicate diagnostics.
        val nonClassRestricted = restricted - setOf("arguments", "eval")
        when (member) {
            is MethodDeclaration -> {
                for (param in member.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, nonClassRestricted)
                }
                member.body?.let { checkStrictModeInStatements(it.statements, source, fileName, nonClassRestricted) }
            }
            is Constructor -> {
                for (param in member.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, nonClassRestricted)
                }
                member.body?.let { checkStrictModeInStatements(it.statements, source, fileName, nonClassRestricted) }
            }
            is GetAccessor -> {
                member.body?.let { checkStrictModeInStatements(it.statements, source, fileName, nonClassRestricted) }
            }
            is SetAccessor -> {
                for (param in member.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, nonClassRestricted)
                }
                member.body?.let { checkStrictModeInStatements(it.statements, source, fileName, nonClassRestricted) }
            }
            else -> {}
        }
    }

    private fun checkStrictModeInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (expr) {
            is FunctionExpression -> {
                expr.name?.let { checkStrictModeName(it, source, fileName, restricted) }
                for (param in expr.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, restricted)
                }
                checkStrictModeInStatements(expr.body.statements, source, fileName, restricted)
            }
            is ArrowFunction -> {
                for (param in expr.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, restricted)
                }
                when (val body = expr.body) {
                    is Block -> checkStrictModeInStatements(body.statements, source, fileName, restricted)
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun checkStrictModeBindingName(
        name: Node,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (name) {
            is Identifier -> checkStrictModeName(name, source, fileName, restricted)
            // Could recurse into destructuring patterns if needed
            else -> {}
        }
    }

    private fun checkStrictModeName(
        name: Identifier,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        if (name.text in restricted) {
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Invalid use of '${name.text}' in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1100,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = name.text.length,
            ))
        }
    }

    /**
     * Walk a type annotation to find function type parameter names for TS1100.
     * Checks FunctionType, ConstructorType, TypeLiteral members.
     */
    private fun checkStrictModeInTypeNode(
        type: TypeNode,
        source: String,
        fileName: String,
        restricted: Set<String>,
    ) {
        when (type) {
            is FunctionType -> {
                for (param in type.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, restricted)
                }
                checkStrictModeInTypeNode(type.type, source, fileName, restricted)
            }
            is ConstructorType -> {
                for (param in type.parameters) {
                    checkStrictModeBindingName(param.name, source, fileName, restricted)
                }
                checkStrictModeInTypeNode(type.type, source, fileName, restricted)
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is Constructor -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is IndexSignature -> {
                            for (param in member.parameters) {
                                checkStrictModeBindingName(param.name, source, fileName, restricted)
                            }
                        }
                        is PropertyDeclaration -> {
                            // Walk property type annotations (e.g., prop: (arguments) => void)
                            member.type?.let { checkStrictModeInTypeNode(it, source, fileName, restricted) }
                        }
                        else -> {}
                    }
                }
            }
            is UnionType -> for (t in type.types) checkStrictModeInTypeNode(t, source, fileName, restricted)
            is IntersectionType -> for (t in type.types) checkStrictModeInTypeNode(t, source, fileName, restricted)
            is ParenthesizedType -> checkStrictModeInTypeNode(type.type, source, fileName, restricted)
            is ArrayType -> checkStrictModeInTypeNode(type.elementType, source, fileName, restricted)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Export assignment conflict checking (TS2309)
    // -----------------------------------------------------------------------

    /**
     * Check for TS2309: "An export assignment cannot be used in a module with other exported elements."
     * Fires when a file has both `export = X` and other exported declarations.
     */
    private fun checkExportAssignmentConflicts() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkExportAssignmentConflictsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkExportAssignmentConflictsInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        // Find export assignments (export = X)
        val exportAssignments = statements.filterIsInstance<ExportAssignment>()
            .filter { it.isExportEquals }
        if (exportAssignments.isEmpty()) {
            // Still recurse into module declaration bodies
            for (stmt in statements) {
                if (stmt is ModuleDeclaration) {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkExportAssignmentConflictsInStatements(body.statements, source, fileName)
                    }
                }
            }
            return
        }

        // Check for other exported elements
        val hasOtherExports = statements.any { stmt ->
            when (stmt) {
                is ExportDeclaration -> true
                is ImportEqualsDeclaration -> ModifierFlag.Export in stmt.modifiers
                is FunctionDeclaration -> ModifierFlag.Export in stmt.modifiers
                is ClassDeclaration -> ModifierFlag.Export in stmt.modifiers
                is VariableStatement -> ModifierFlag.Export in stmt.modifiers
                is EnumDeclaration -> ModifierFlag.Export in stmt.modifiers
                is InterfaceDeclaration -> ModifierFlag.Export in stmt.modifiers
                is TypeAliasDeclaration -> ModifierFlag.Export in stmt.modifiers
                is ModuleDeclaration -> ModifierFlag.Export in stmt.modifiers
                else -> false
            }
        }

        if (hasOtherExports) {
            for (ea in exportAssignments) {
                // Find the start of the actual statement text (skip leading trivia)
                var start = ea.pos
                while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
                    start++
                }
                // Compute length from start to end of current line (or semicolon)
                val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
                var end = lineEnd
                // Trim trailing whitespace/CR
                while (end > start && source[end - 1].let { it == ' ' || it == '\t' || it == '\r' }) {
                    end--
                }
                val length = end - start
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "An export assignment cannot be used in a module with other exported elements.",
                    category = DiagnosticCategory.Error,
                    code = 2309,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }

        // Recurse into module declarations
        for (stmt in statements) {
            if (stmt is ModuleDeclaration) {
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkExportAssignmentConflictsInStatements(body.statements, source, fileName)
                }
            }
        }
    }

